window.MT_DATA = window.MT_DATA || {};
window.MT_DATA['ja'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours au Japon, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Premiers mots à Shinjuku","phrases":[{"fr":"Bonjour !","tgt":"こんにちは！","ro":"Konnichiwa!","lit":"bonjour (littéralement : quant à aujourd'hui)","note":{"lit":"bonjour","text":"Bonjour se dit « konnichiwa ». On l'utilise surtout dans la journée. Le matin, on emploie un autre mot.","say":{"konnichiwa":"こんにちは"},"words":[["bonjour","こんにちは"]]}},{"fr":"Enchanté.","tgt":"はじめまして。","ro":"Hajimemashite.","lit":"pour la première fois","note":{"lit":"enchanté","text":"Quand on rencontre quelqu'un pour la première fois, on dit « hajimemashite ». Mot à mot, cela veut dire pour la première fois. C'est la toute première phrase d'une présentation.","say":{"hajimemashite":"はじめまして"},"words":[["enchanté","はじめまして"]]}},{"fr":"Je m'appelle Léa.","tgt":"レアです。","ro":"Rea desu.","lit":"Léa · être (poli)","note":{"lit":"Léa, être","text":"En japonais, on n'a pas besoin de dire je. Pour se présenter, on donne son nom suivi de « desu ». Ce petit mot poli veut dire c'est, ou je suis.","say":{"desu":"です"},"words":[["Léa","レア"],["être","です"]]}},{"fr":"Je suis français.","tgt":"フランス人です。","ro":"Furansujin desu.","lit":"France-personne · être (poli)","note":{"lit":"Français, être","text":"Après le nom du pays, on ajoute un petit mot qui veut dire personne. Ce mot se dit « jin ». Un Français, c'est donc une personne de France.","say":{"jin":"人"},"words":[["Français","フランス人"],["être","です"]]}},{"fr":"Ravi de faire votre connaissance.","tgt":"よろしくお願いします。","ro":"Yoroshiku onegaishimasu.","lit":"bien · je vous le demande humblement","note":{"lit":"bien, je vous le demande","text":"Cette formule figée termine toute présentation. Elle demande poliment à l'autre de bien nous accueillir. Le premier mot se dit « yoroshiku ».","say":{"yoroshiku":"よろしく"},"words":[["bien","よろしく"],["je vous le demande","お願いします"]]}},{"fr":"J'ai sommeil.","tgt":"眠いです。","ro":"Nemui desu.","lit":"avoir sommeil · être (poli)","note":{"lit":"avoir sommeil, être","text":"En japonais, avoir sommeil se dit avec un seul adjectif. Cet adjectif se dit « nemui ». On ajoute ensuite le petit mot poli de la fin.","say":{"nemui":"眠い"},"words":[["avoir sommeil","眠い"],["être","です"]]}},{"fr":"J'ai faim.","tgt":"お腹がすきました。","ro":"Onaka ga sukimashita.","lit":"honorable-ventre · [sujet] · s'est vidé (poli)","note":{"lit":"ventre, petit mot du sujet, se vider","text":"Pour dire j'ai faim, on dit que le ventre s'est vidé. Ventre se dit « onaka ». Le verbe est au passé, car la faim est déjà là.","say":{"onaka":"お腹"},"words":[["ventre","お腹"],["petit mot du sujet","が"],["se vider","すきました"]]}},{"fr":"Je suis fatiguée.","tgt":"疲れました。","ro":"Tsukaremashita.","lit":"s'être fatigué (poli)","note":{"lit":"se fatiguer","text":"Pour dire je suis fatigué, le japonais emploie un verbe au passé. On dit en fait je me suis fatigué, « tsukaremashita ». C'est la phrase classique en fin de journée.","say":{"tsukaremashita":"疲れました"},"words":[["se fatiguer","疲れました"]]}},{"fr":"Je suis tellement content !","tgt":"とてもうれしいです！","ro":"Totemo ureshii desu!","lit":"très · content · être (poli)","note":{"lit":"très, content, être","text":"Très se dit « totemo ». Il se place juste avant l'adjectif, comme en français. Ici, l'adjectif veut dire heureux, content.","say":{"totemo":"とても"},"words":[["très","とても"],["content","うれしい"],["être","です"]]}},{"fr":"Shinjuku, c'est immense !","tgt":"新宿は大きいですね！","ro":"Shinjuku wa ōkii desu ne!","lit":"Shinjuku · [thème] · grand · être (poli) · [n'est-ce pas]","note":{"lit":"Shinjuku, petit mot du thème, grand, être, petit mot d'accord","text":"À la fin de la phrase, on ajoute « ne ». Ce petit mot cherche l'accord de l'autre, comme n'est-ce pas. On l'entend partout dans les conversations.","say":{"ne":"ね"},"words":[["Shinjuku","新宿"],["petit mot du thème","は"],["grand","大きい"],["être","です"],["petit mot d'accord","ね"]]}}],"tip":{"title":"Pas besoin de « je » : le japonais omet le sujet","example":"Je suis français. — <b>フランス人です</b>。","body":"En français, une phrase a presque toujours un sujet : je, tu, il. En japonais, c'est différent : quand on comprend de qui on parle, on ne le dit tout simplement pas. « Furansujin desu » se dit littéralement : France-personne, être. Pas de « je », et pourtant tout le monde comprend que vous parlez de vous. De la même façon, « Nemui desu », c'est : avoir sommeil, être, donc j'ai sommeil. Et « Tsukaremashita », un seul mot, veut dire : je suis fatigué. Le mot « watashi », qui veut dire moi, existe bien, mais si on le répète à chaque phrase, on paraît insistant, un peu comme si on disait moi, moi, moi. Retenez cette astuce : en japonais, c'est le contexte qui fait le sujet, et quand il est clair, on l'efface.","exampleRo":"Furansujin desu.","lit":"France-personne · être (poli)","say":{"Furansujin desu":"フランス人です","Nemui desu":"眠いです","Tsukaremashita":"疲れました","watashi":"私"}}},{"title":"Au konbini du quartier","phrases":[{"fr":"Le konbini est juste là.","tgt":"コンビニはそこです。","ro":"Konbini wa soko desu.","lit":"konbini · [thème] · là · être (poli)","note":{"lit":"konbini, petit mot du thème, là, être","text":"On parle ici du konbini. On le dit suivi du petit mot du thème, « konbini wa ». Ce petit mot veut dire un peu quant à.","say":{"konbini wa":"コンビニは"},"words":[["konbini","コンビニ"],["petit mot du thème","は"],["là","そこ"],["être","です"]]}},{"fr":"Le konbini est pratique.","tgt":"コンビニは便利です。","ro":"Konbini wa benri desu.","lit":"konbini · [thème] · pratique · être (poli)","note":{"lit":"konbini, petit mot du thème, pratique, être","text":"Pratique se dit « benri ». Cet adjectif ne change pas de forme. On ajoute simplement le petit mot poli de la fin.","say":{"benri":"便利"},"words":[["konbini","コンビニ"],["petit mot du thème","は"],["pratique","便利"],["être","です"]]}},{"fr":"C'est un onigiri au thon.","tgt":"ツナのおにぎりです。","ro":"Tsuna no onigiri desu.","lit":"thon · [de] · onigiri · être (poli)","note":{"lit":"thon, petit mot de liaison, onigiri, être","text":"En japonais, le complément du nom se place avant le nom. On dit thon, puis le petit mot « no ». Ensuite seulement vient l'onigiri.","say":{"no":"の"},"words":[["thon","ツナ"],["petit mot de liaison","の"],["onigiri","おにぎり"],["être","です"]]}},{"fr":"Le thé vert, c'est cent cinquante yens.","tgt":"お茶は百五十円です。","ro":"Ocha wa hyakugojū en desu.","lit":"honorable-thé · [thème] · cent-cinquante yens · être (poli)","note":{"lit":"thé, petit mot du thème, cent cinquante, yen, être","text":"Le yen se dit en réalité « en ». On le place juste après le nombre, sans rien changer.","say":{"en":"円"},"words":[["thé","お茶"],["petit mot du thème","は"],["cent cinquante","百五十"],["yen","円"],["être","です"]]}},{"fr":"Mademoiselle Tanaka est vendeuse.","tgt":"田中さんは店員です。","ro":"Tanaka-san wa ten'in desu.","lit":"Tanaka-mademoiselle · [thème] · employée de magasin · être (poli)","note":{"lit":"Tanaka, mademoiselle, petit mot du thème, vendeuse, être","text":"Après le nom de quelqu'un, on ajoute « san ». Il veut dire monsieur, madame ou mademoiselle. On ne le dit jamais pour soi-même.","say":{"san":"さん"},"words":[["Tanaka","田中"],["mademoiselle","さん"],["petit mot du thème","は"],["vendeuse","店員"],["être","です"]]}},{"fr":"Le bentō, c'est cinq cents yens.","tgt":"お弁当は五百円です。","ro":"Obentō wa gohyaku en desu.","lit":"honorable-bentō · [thème] · cinq-cents yens · être (poli)","note":{"lit":"bentō, petit mot du thème, cinq cents, yen, être","text":"Devant certains mots, on ajoute un petit son de politesse. Ainsi, le repas en boîte se dit « obentō ». Cela rend le mot plus doux.","say":{"obentō":"お弁当"},"words":[["bentō","お弁当"],["petit mot du thème","は"],["cinq cents","五百"],["yen","円"],["être","です"]]}},{"fr":"L'onigiri est délicieux.","tgt":"おにぎりはおいしいです。","ro":"Onigiri wa oishii desu.","lit":"onigiri · [thème] · délicieux · être (poli)","note":{"lit":"onigiri, petit mot du thème, délicieux, être","text":"Délicieux se dit « oishii ». C'est un mot qu'on entend très souvent au Japon. On le dit en goûtant un plat.","say":{"oishii":"おいしい"},"words":[["onigiri","おにぎり"],["petit mot du thème","は"],["délicieux","おいしい"],["être","です"]]}},{"fr":"Aujourd'hui, c'est lundi.","tgt":"今日は月曜日です。","ro":"Kyō wa getsuyōbi desu.","lit":"aujourd'hui · [thème] · lundi · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, lundi, être","text":"Aujourd'hui se dit « kyō ». On le place en tête de phrase, suivi du petit mot du thème. Tous les jours de la semaine finissent par le même son.","say":{"kyō":"今日"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["lundi","月曜日"],["être","です"]]}},{"fr":"Il est sept heures.","tgt":"七時です。","ro":"Shichiji desu.","lit":"sept-heure · être (poli)","note":{"lit":"sept heures, être","text":"Pour dire l'heure, on ajoute un petit mot après le nombre. Heure se dit « ji ». Sept heures, c'est donc sept suivi de ce petit mot.","say":{"ji":"時"},"words":[["sept heures","七時"],["être","です"]]}},{"fr":"Ce konbini est tout neuf.","tgt":"このコンビニは新しいです。","ro":"Kono konbini wa atarashii desu.","lit":"ce · konbini · [thème] · neuf · être (poli)","note":{"lit":"ce, konbini, petit mot du thème, neuf, être","text":"Devant un nom, ce se dit « kono ». Il se place juste avant le nom qu'il montre. Neuf, ici, veut dire nouveau.","say":{"kono":"この"},"words":[["ce","この"],["konbini","コンビニ"],["petit mot du thème","は"],["neuf","新しい"],["être","です"]]}}],"tip":{"title":"« Desu » : le verbe être poli","example":"Le konbini est pratique. — コンビニは便利<b>です</b>。","body":"« Desu » joue le rôle de notre verbe être, avec une touche de politesse. Il se place toujours à la fin de la phrase, comme un point final poli. Le schéma de base est : X wa Y desu, c'est-à-dire, quant à X, c'est Y. « Konbini wa benri desu » se dit littéralement : konbini, quant à lui, pratique, être. Avec ce seul modèle, vous pouvez déjà dire beaucoup : « Shichiji desu », il est sept heures, ou « Obentō wa gohyaku en desu », le bentō fait cinq cents yens. Notez aussi que « desu » ne change pas selon la personne : je suis, tu es, ils sont, tout se dit « desu ». Petite astuce de prononciation : le « u » final s'entend à peine, on dit presque « dess ». Pensez-y comme à un sourire poli posé en fin de phrase.","exampleRo":"Konbini wa benri desu.","lit":"konbini · [thème] · pratique · être (poli)","say":{"Desu":"です","Konbini wa benri desu":"コンビニは便利です","Shichiji desu":"七時です","Obentō wa gohyaku en desu":"お弁当は五百円です","desu":"です"}}},{"title":"Le carrefour de Shibuya","phrases":[{"fr":"Ici, c'est Shibuya.","tgt":"ここは渋谷です。","ro":"Koko wa Shibuya desu.","lit":"ici · [thème] · Shibuya · être (poli)","note":{"lit":"ici, petit mot du thème, Shibuya, être","text":"Ici se dit « koko ». On le met en thème au début de la phrase. Puis on dit le nom du lieu et le petit mot poli.","say":{"koko":"ここ"},"words":[["ici","ここ"],["petit mot du thème","は"],["Shibuya","渋谷"],["être","です"]]}},{"fr":"Ce carrefour est très célèbre.","tgt":"この交差点はとても有名です。","ro":"Kono kōsaten wa totemo yūmei desu.","lit":"ce · carrefour · [thème] · très · célèbre · être (poli)","note":{"lit":"ce, carrefour, petit mot du thème, très, célèbre, être","text":"Célèbre se dit « yūmei ». C'est un adjectif qui ne change pas de forme. Le carrefour de Shibuya est connu dans le monde entier.","say":{"yūmei":"有名"},"words":[["ce","この"],["carrefour","交差点"],["petit mot du thème","は"],["très","とても"],["célèbre","有名"],["être","です"]]}},{"fr":"Hachikō est un chien.","tgt":"ハチ公は犬です。","ro":"Hachikō wa inu desu.","lit":"Hachikō · [thème] · chien · être (poli)","note":{"lit":"Hachikō, petit mot du thème, chien, être","text":"Chien se dit « inu ». En japonais, il n'y a pas d'article. On ne dit ni un ni le, seulement chien.","say":{"inu":"犬"},"words":[["Hachikō","ハチ公"],["petit mot du thème","は"],["chien","犬"],["être","です"]]}},{"fr":"La statue de Hachikō est par là.","tgt":"ハチ公の像はあちらです。","ro":"Hachikō no zō wa achira desu.","lit":"Hachikō · [de] · statue · [thème] · par là-bas · être (poli)","note":{"lit":"Hachikō, petit mot de liaison, statue, petit mot du thème, par là-bas, être","text":"Pour indiquer poliment un endroit loin de nous, on dit « achira ». C'est une façon polie de dire par là-bas. On l'entend souvent quand on demande son chemin.","say":{"achira":"あちら"},"words":[["Hachikō","ハチ公"],["petit mot de liaison","の"],["statue","像"],["petit mot du thème","は"],["par là-bas","あちら"],["être","です"]]}},{"fr":"Moi, je suis Marc.","tgt":"私はマルクです。","ro":"Watashi wa Maruku desu.","lit":"moi · [thème] · Marc · être (poli)","note":{"lit":"moi, petit mot du thème, Marc, être","text":"Je ou moi se dit « watashi ». On le dit surtout pour insister sur soi. Le plus souvent, les Japonais le laissent tomber.","say":{"watashi":"私"},"words":[["moi","私"],["petit mot du thème","は"],["Marc","マルク"],["être","です"]]}},{"fr":"Pour moi, ce sera un café.","tgt":"私はコーヒーです。","ro":"Watashi wa kōhī desu.","lit":"moi · [thème] · café · être (poli)","note":{"lit":"moi, petit mot du thème, café, être","text":"Au café, on peut dire mot à mot moi, c'est café. Le petit mot du thème veut dire ici quant à moi. Café se dit « kōhī ».","say":{"kōhī":"コーヒー"},"words":[["moi","私"],["petit mot du thème","は"],["café","コーヒー"],["être","です"]]}},{"fr":"Aujourd'hui, il fait beau.","tgt":"今日はいい天気です。","ro":"Kyō wa ii tenki desu.","lit":"aujourd'hui · [thème] · bon · temps · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, bon, temps, être","text":"Pour dire il fait beau, on dit c'est un bon temps. Le temps qu'il fait se dit « tenki ». Bon se place juste devant.","say":{"tenki":"天気"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["bon","いい"],["temps","天気"],["être","です"]]}},{"fr":"Shibuya est très animé.","tgt":"渋谷はとてもにぎやかです。","ro":"Shibuya wa totemo nigiyaka desu.","lit":"Shibuya · [thème] · très · animé · être (poli)","note":{"lit":"Shibuya, petit mot du thème, très, animé, être","text":"Animé se dit « nigiyaka ». On l'emploie pour un quartier plein de monde et de bruit. C'est le contraire de calme.","say":{"nigiyaka":"にぎやか"},"words":[["Shibuya","渋谷"],["petit mot du thème","は"],["très","とても"],["animé","にぎやか"],["être","です"]]}},{"fr":"Mon ami, c'est Kenji.","tgt":"友達は健二さんです。","ro":"Tomodachi wa Kenji-san desu.","lit":"ami · [thème] · Kenji-monsieur · être (poli)","note":{"lit":"ami, petit mot du thème, Kenji, monsieur, être","text":"Ami se dit « tomodachi ». Pour dire mon ami, on n'a pas besoin du possessif. On comprend tout seul qu'on parle de son ami.","say":{"tomodachi":"友達"},"words":[["ami","友達"],["petit mot du thème","は"],["Kenji","健二"],["monsieur","さん"],["être","です"]]}},{"fr":"Kenji est étudiant.","tgt":"健二さんは学生です。","ro":"Kenji-san wa gakusei desu.","lit":"Kenji-monsieur · [thème] · étudiant · être (poli)","note":{"lit":"Kenji, monsieur, petit mot du thème, étudiant, être","text":"Étudiant se dit « gakusei ». Il n'y a ni article, ni masculin, ni féminin. Étudiant ou étudiante, c'est le même mot.","say":{"gakusei":"学生"},"words":[["Kenji","健二"],["monsieur","さん"],["petit mot du thème","は"],["étudiant","学生"],["être","です"]]}}],"tip":{"title":"« Wa » : la particule du thème, de quoi on parle","example":"Pour moi, ce sera un café. — 私<b>は</b>コーヒーです。","body":"Les particules sont de petits mots qui se placent après un mot pour indiquer son rôle dans la phrase. « Wa » annonce le thème, c'est-à-dire ce dont on parle, un peu comme quant à, ou pour ce qui est de, en français. « Watashi wa kōhī desu » se dit littéralement : moi, quant à moi, café, être. Cela ne veut pas dire je suis un café, mais tout simplement : pour moi, ce sera un café. Autre exemple : « Kyō wa ii tenki desu », aujourd'hui, quant à lui, beau temps, donc il fait beau aujourd'hui. Et « Koko wa Shibuya desu » : ici, c'est Shibuya. Curiosité amusante : à l'écrit, cette particule utilise le signe qui se lit d'habitude « ha », mais on la prononce bien « wa ». Pour retenir, imaginez que « wa » pose un projecteur sur le mot qui le précède : voilà le sujet de la conversation.","exampleRo":"Watashi wa kōhī desu.","lit":"moi · [thème] · café · être (poli)","say":{"Wa":"わ","Watashi wa kōhī desu":"私はコーヒーです","Kyō wa ii tenki desu":"今日はいい天気です","Koko wa Shibuya desu":"ここは渋谷です","ha":"は","wa":"わ"}}},{"title":"Une promenade à Ueno","phrases":[{"fr":"Vous allez bien ?","tgt":"お元気ですか？","ro":"Ogenki desu ka?","lit":"honorable-santé · être (poli) · [question]","note":{"lit":"en forme, être, petit mot de question","text":"Pour poser une question, on ajoute à la fin le petit mot « ka ». Pas besoin de changer l'ordre des mots. C'est comme un point d'interrogation qu'on prononce.","say":{"ka":"か"},"words":[["en forme","お元気"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, je vais très bien.","tgt":"はい、とても元気です。","ro":"Hai, totemo genki desu.","lit":"oui · très · en forme · être (poli)","note":{"lit":"oui, très, en forme, être","text":"Oui se dit « hai ». On le dit aussi pour montrer qu'on écoute. Pour parler de soi, on enlève le petit son poli du début de en forme.","say":{"hai":"はい"},"words":[["oui","はい"],["très","とても"],["en forme","元気"],["être","です"]]}},{"fr":"C'est bien ici, le parc d'Ueno ?","tgt":"ここは上野公園ですか？","ro":"Koko wa Ueno kōen desu ka?","lit":"ici · [thème] · Ueno-parc · être (poli) · [question]","note":{"lit":"ici, petit mot du thème, Ueno, parc, être, petit mot de question","text":"Parc se dit « kōen ». Le nom du lieu se place devant, comme Ueno parc. On fait la question en ajoutant le petit mot final.","say":{"kōen":"公園"},"words":[["ici","ここ"],["petit mot du thème","は"],["Ueno","上野"],["parc","公園"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, c'est ça.","tgt":"はい、そうです。","ro":"Hai, sō desu.","lit":"oui · ainsi · être (poli)","note":{"lit":"oui, ainsi, être","text":"Pour confirmer, on dit « sō desu ». Mot à mot, c'est ainsi. C'est la façon la plus simple de dire c'est ça.","say":{"sō desu":"そうです"},"words":[["oui","はい"],["ainsi","そう"],["être","です"]]}},{"fr":"Où est le musée d'art ?","tgt":"美術館はどこですか？","ro":"Bijutsukan wa doko desu ka?","lit":"musée d'art · [thème] · où · être (poli) · [question]","note":{"lit":"musée d'art, petit mot du thème, où, être, petit mot de question","text":"Où se dit « doko ». Il prend la place de la réponse, avant le petit mot poli. On garde le même ordre que dans la réponse.","say":{"doko":"どこ"},"words":[["musée d'art","美術館"],["petit mot du thème","は"],["où","どこ"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est loin ?","tgt":"遠いですか？","ro":"Tōi desu ka?","lit":"loin · être (poli) · [question]","note":{"lit":"loin, être, petit mot de question","text":"Loin se dit « tōi ». C'est un adjectif, suivi du petit mot poli. Le sujet n'est pas dit, on le devine.","say":{"tōi":"遠い"},"words":[["loin","遠い"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, c'est tout près.","tgt":"いいえ、すぐそこです。","ro":"Iie, sugu soko desu.","lit":"non · tout de suite · là · être (poli)","note":{"lit":"non, tout de suite, là, être","text":"Non se dit « iie ». Les Japonais l'emploient avec prudence, car il peut paraître sec. Ici, il sert juste à corriger gentiment.","say":{"iie":"いいえ"},"words":[["non","いいえ"],["tout de suite","すぐ"],["là","そこ"],["être","です"]]}},{"fr":"Vous êtes étudiant ?","tgt":"学生ですか？","ro":"Gakusei desu ka?","lit":"étudiant · être (poli) · [question]","note":{"lit":"étudiant, être, petit mot de question","text":"Sans sujet, la question vise la personne en face. On ne dit pas vous, ce serait même un peu direct. On dit juste étudiant, puis « desu ka ».","say":{"desu ka":"ですか"},"words":[["étudiant","学生"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, je suis employé de bureau.","tgt":"いいえ、会社員です。","ro":"Iie, kaishain desu.","lit":"non · employé d'entreprise · être (poli)","note":{"lit":"non, employé de bureau, être","text":"Employé de bureau se dit « kaishain ». Mot à mot, c'est une personne de l'entreprise. C'est la réponse la plus courante au Japon.","say":{"kaishain":"会社員"},"words":[["non","いいえ"],["employé de bureau","会社員"],["être","です"]]}},{"fr":"L'entrée du parc est gratuite ?","tgt":"公園は無料ですか？","ro":"Kōen wa muryō desu ka?","lit":"parc · [thème] · gratuit · être (poli) · [question]","note":{"lit":"parc, petit mot du thème, gratuit, être, petit mot de question","text":"Gratuit se dit « muryō ». On l'entend souvent à l'entrée des musées et des parcs.","say":{"muryō":"無料"},"words":[["parc","公園"],["petit mot du thème","は"],["gratuit","無料"],["être","です"],["petit mot de question","か"]]}}],"tip":{"title":"« Ka » : transformer une phrase en question","example":"Vous allez bien ? — お元気です<b>か</b>？","body":"Pour poser une question en japonais, rien de plus simple : on prend une phrase affirmative et on ajoute « ka » à la fin. Pas besoin d'inverser les mots comme en français, ni d'ajouter est-ce que. « Ogenki desu ka » se dit littéralement : honorable santé, être, question ? Le « o » du début est une marque de politesse envers la personne à qui l'on parle. Comparez : « Gakusei desu », je suis étudiant, et « Gakusei desu ka », vous êtes étudiant ? De même, « Tōi desu », c'est loin, devient « Tōi desu ka », c'est loin ? Pour répondre, on dit « hai », oui, ou « iie », non. Astuce : voyez « ka » comme un point d'interrogation que l'on prononce à voix haute.","exampleRo":"Ogenki desu ka?","lit":"honorable-santé · être (poli) · [question]","say":{"Ka":"か","ka":"か","Ogenki desu ka":"お元気ですか","Gakusei desu":"学生です","Gakusei desu ka":"学生ですか","Tōi desu":"遠いです","Tōi desu ka":"遠いですか","hai":"はい","iie":"いいえ"}}},{"title":"Sur la ligne Yamanote","phrases":[{"fr":"Je prends la ligne Yamanote.","tgt":"山手線に乗ります。","ro":"Yamanotesen ni norimasu.","lit":"ligne Yamanote · [dans] · monter (poli)","note":{"lit":"ligne Yamanote, dans, monter","text":"En japonais, le verbe est toujours à la fin. Monter dans un train se dit « norimasu ». Le train se place avant, avec un petit mot qui veut dire dans.","say":{"norimasu":"乗ります"},"words":[["ligne Yamanote","山手線"],["dans","に"],["monter","乗ります"]]}},{"fr":"Le train arrive.","tgt":"電車が来ます。","ro":"Densha ga kimasu.","lit":"train · [sujet] · venir (poli)","note":{"lit":"train, petit mot du sujet, venir","text":"Pour un fait qu'on remarque, on marque le sujet avec « ga ». Ici, on annonce ce qui se passe, le train arrive. Le verbe venir vient en dernier.","say":{"ga":"が"},"words":[["train","電車"],["petit mot du sujet","が"],["venir","来ます"]]}},{"fr":"Je vais à Akihabara.","tgt":"秋葉原に行きます。","ro":"Akihabara ni ikimasu.","lit":"Akihabara · [direction] · aller (poli)","note":{"lit":"Akihabara, vers, aller","text":"Aller se dit « ikimasu ». La destination vient d'abord, avec un petit mot qui veut dire vers. Le verbe ferme la phrase.","say":{"ikimasu":"行きます"},"words":[["Akihabara","秋葉原"],["vers","に"],["aller","行きます"]]}},{"fr":"Je descends à Shinjuku.","tgt":"新宿で降ります。","ro":"Shinjuku de orimasu.","lit":"Shinjuku · [lieu] · descendre (poli)","note":{"lit":"Shinjuku, petit mot du lieu, descendre","text":"Descendre du train se dit « orimasu ». C'est le contraire de monter. Le lieu vient avant, comme toujours.","say":{"orimasu":"降ります"},"words":[["Shinjuku","新宿"],["petit mot du lieu","で"],["descendre","降ります"]]}},{"fr":"Je lis un livre dans le train.","tgt":"電車で本を読みます。","ro":"Densha de hon o yomimasu.","lit":"train · [lieu] · livre · [objet] · lire (poli)","note":{"lit":"train, petit mot du lieu, livre, petit mot du complément, lire","text":"Le verbe arrive en dernier. L'ordre est dans le train, un livre, lire. Livre se dit « hon ».","say":{"hon":"本"},"words":[["train","電車"],["petit mot du lieu","で"],["livre","本"],["petit mot du complément","を"],["lire","読みます"]]}},{"fr":"J'écoute de la musique.","tgt":"音楽を聞きます。","ro":"Ongaku o kikimasu.","lit":"musique · [objet] · écouter (poli)","note":{"lit":"musique, petit mot du complément, écouter","text":"Musique se dit « ongaku ». On dit musique d'abord, puis écouter. C'est l'inverse du français.","say":{"ongaku":"音楽"},"words":[["musique","音楽"],["petit mot du complément","を"],["écouter","聞きます"]]}},{"fr":"Je regarde par la fenêtre.","tgt":"窓の外を見ます。","ro":"Mado no soto o mimasu.","lit":"fenêtre · [de] · extérieur · [objet] · regarder (poli)","note":{"lit":"fenêtre, petit mot de liaison, dehors, petit mot du complément, regarder","text":"Regarder se dit « mimasu ». Le japonais dit regarder le dehors de la fenêtre. Le verbe court reste à la fin.","say":{"mimasu":"見ます"},"words":[["fenêtre","窓"],["petit mot de liaison","の"],["dehors","外"],["petit mot du complément","を"],["regarder","見ます"]]}},{"fr":"J'attends le prochain train.","tgt":"次の電車を待ちます。","ro":"Tsugi no densha o machimasu.","lit":"suivant · [de] · train · [objet] · attendre (poli)","note":{"lit":"suivant, petit mot de liaison, train, petit mot du complément, attendre","text":"Attendre se dit « machimasu ». Le mot suivant se place devant le train, avec le petit mot de liaison. Puis le verbe vient en dernier.","say":{"machimasu":"待ちます"},"words":[["suivant","次"],["petit mot de liaison","の"],["train","電車"],["petit mot du complément","を"],["attendre","待ちます"]]}},{"fr":"Je rentre à la maison.","tgt":"家に帰ります。","ro":"Ie ni kaerimasu.","lit":"maison · [direction] · rentrer (poli)","note":{"lit":"maison, vers, rentrer","text":"Rentrer chez soi se dit « kaerimasu ». C'est un verbe à part, différent d'aller. Maison se met devant, avec le petit mot vers.","say":{"kaerimasu":"帰ります"},"words":[["maison","家"],["vers","に"],["rentrer","帰ります"]]}},{"fr":"Demain, je vais à Ueno en train.","tgt":"明日、電車で上野に行きます。","ro":"Ashita, densha de Ueno ni ikimasu.","lit":"demain · train · [moyen] · Ueno · [direction] · aller (poli)","note":{"lit":"demain, train, petit mot du moyen, Ueno, vers, aller","text":"Demain se dit « ashita ». Le moment se place en tout début de phrase. Le verbe, lui, reste à la fin.","say":{"ashita":"明日"},"words":[["demain","明日"],["train","電車"],["petit mot du moyen","で"],["Ueno","上野"],["vers","に"],["aller","行きます"]]}}],"tip":{"title":"Le verbe à la fin : l'ordre des mots japonais","example":"Je lis un livre dans le train. — 電車で本を<b>読みます</b>。","body":"En français, on dit : je lis un livre, avec le verbe au milieu. En japonais, le verbe arrive toujours en dernier, comme la chute d'une histoire. « Densha de hon o yomimasu » se dit littéralement : train, dans, livre, objet, lire. On pose d'abord le décor, puis ce qui est concerné, et l'action vient tout à la fin. C'est pour cela que les particules sont si utiles : elles disent le rôle de chaque mot, alors le début de la phrase reste assez souple. Autres exemples : « Ongaku o kikimasu », musique, objet, écouter, et « Akihabara ni ikimasu », Akihabara, vers, aller. Pour un Français, c'est un peu comme écouter quelqu'un qui garde le suspense jusqu'au bout. Astuce : quand vous construisez une phrase, gardez le verbe en réserve et posez-le en tout dernier.","exampleRo":"Densha de hon o yomimasu.","lit":"train · [lieu] · livre · [objet] · lire (poli)","say":{"Densha de hon o yomimasu":"電車で本を読みます","Ongaku o kikimasu":"音楽を聞きます","Akihabara ni ikimasu":"秋葉原に行きます"}}},{"title":"Les boutiques d'Akihabara","phrases":[{"fr":"Qu'est-ce que c'est, ceci ?","tgt":"これは何ですか？","ro":"Kore wa nan desu ka?","lit":"ceci · [thème] · quoi · être (poli) · [question]","note":{"lit":"ceci, petit mot du thème, quoi, être, petit mot de question","text":"Ceci, tout près de moi, se dit « kore ». On montre l'objet en le disant. Quoi se place juste avant le petit mot poli.","say":{"kore":"これ"},"words":[["ceci","これ"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"Cela, c'est un appareil photo.","tgt":"それはカメラです。","ro":"Sore wa kamera desu.","lit":"cela · [thème] · appareil photo · être (poli)","note":{"lit":"cela, petit mot du thème, appareil photo, être","text":"Cela, près de la personne en face, se dit « sore ». C'est l'objet que l'autre tient ou montre. Appareil photo vient de l'anglais.","say":{"sore":"それ"},"words":[["cela","それ"],["petit mot du thème","は"],["appareil photo","カメラ"],["être","です"]]}},{"fr":"Combien coûte ceci ?","tgt":"これはいくらですか？","ro":"Kore wa ikura desu ka?","lit":"ceci · [thème] · combien · être (poli) · [question]","note":{"lit":"ceci, petit mot du thème, combien, être, petit mot de question","text":"Combien ça coûte se dit « ikura ». C'est la question la plus utile dans un magasin. On la dit avec ceci devant.","say":{"ikura":"いくら"},"words":[["ceci","これ"],["petit mot du thème","は"],["combien","いくら"],["être","です"],["petit mot de question","か"]]}},{"fr":"Ça fait trente mille yens.","tgt":"三万円です。","ro":"Sanman en desu.","lit":"trois-dix-mille yens · être (poli)","note":{"lit":"trente mille, yen, être","text":"En japonais, on compte par dix mille. Dix mille se dit « man ». Trente mille, c'est trois fois dix mille.","say":{"man":"万"},"words":[["trente mille","三万"],["yen","円"],["être","です"]]}},{"fr":"C'est cher, dites donc !","tgt":"高いですね！","ro":"Takai desu ne!","lit":"cher · être (poli) · [n'est-ce pas]","note":{"lit":"cher, être, petit mot d'accord","text":"Cher se dit « takai ». Ce même mot veut aussi dire haut. Le petit mot final cherche l'accord du vendeur.","say":{"takai":"高い"},"words":[["cher","高い"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Et là-bas, qu'est-ce que c'est ?","tgt":"あれは何ですか？","ro":"Are wa nan desu ka?","lit":"ce là-bas · [thème] · quoi · être (poli) · [question]","note":{"lit":"ce là-bas, petit mot du thème, quoi, être, petit mot de question","text":"Pour un objet loin de nous deux, on dit « are ». Il y a donc trois mots là où le français en a deux. Tout dépend de la distance.","say":{"are":"あれ"},"words":[["ce là-bas","あれ"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"Là-bas, c'est un robot.","tgt":"あれはロボットです。","ro":"Are wa robotto desu.","lit":"ce là-bas · [thème] · robot · être (poli)","note":{"lit":"ce là-bas, petit mot du thème, robot, être","text":"Robot se dit « robotto ». Beaucoup de mots étrangers sont adaptés aux sons japonais. On ajoute souvent une voyelle à la fin.","say":{"robotto":"ロボット"},"words":[["ce là-bas","あれ"],["petit mot du thème","は"],["robot","ロボット"],["être","です"]]}},{"fr":"Ce jeu est amusant.","tgt":"このゲームはおもしろいです。","ro":"Kono gēmu wa omoshiroi desu.","lit":"ce · jeu · [thème] · amusant · être (poli)","note":{"lit":"ce, jeu, petit mot du thème, amusant, être","text":"Amusant ou intéressant se dit « omoshiroi ». C'est un adjectif très courant. On l'utilise pour un jeu, un film ou une histoire.","say":{"omoshiroi":"おもしろい"},"words":[["ce","この"],["jeu","ゲーム"],["petit mot du thème","は"],["amusant","おもしろい"],["être","です"]]}},{"fr":"Celui-ci, s'il vous plaît.","tgt":"これをください。","ro":"Kore o kudasai.","lit":"ceci · [objet] · donnez-moi (poli)","note":{"lit":"ceci, petit mot du complément, donnez-moi","text":"Pour acheter, on montre l'objet et on dit « kudasai ». Ce mot veut dire donnez-moi, poliment. Ceci vient avant, avec le petit mot du complément.","say":{"kudasai":"ください"},"words":[["ceci","これ"],["petit mot du complément","を"],["donnez-moi","ください"]]}},{"fr":"Akihabara est le quartier de l'électronique.","tgt":"秋葉原は電気の町です。","ro":"Akihabara wa denki no machi desu.","lit":"Akihabara · [thème] · électricité · [de] · quartier · être (poli)","note":{"lit":"Akihabara, petit mot du thème, électricité, petit mot de liaison, quartier, être","text":"Le quartier de l'électronique se dit mot à mot le quartier de l'électricité. Électricité se dit « denki ». Ce mot se place avant quartier, relié par le petit mot de liaison.","say":{"denki":"電気"},"words":[["Akihabara","秋葉原"],["petit mot du thème","は"],["électricité","電気"],["petit mot de liaison","の"],["quartier","町"],["être","です"]]}}],"tip":{"title":"« Kore, sore, are » : ceci, cela, ce là-bas","example":"Qu'est-ce que c'est, ceci ? — <b>これ</b>は何ですか？","body":"Le japonais a trois mots pour montrer les choses, selon la distance. « Kore », c'est ceci, près de moi. « Sore », c'est cela, près de vous. « Are », c'est ce truc là-bas, loin de nous deux. « Kore wa nan desu ka » se dit littéralement : ceci, quant à lui, quoi, être, question ? Et la réponse peut être : « Sore wa kamera desu », cela, c'est un appareil photo. Les mêmes sons reviennent partout : « koko », « soko », « asoko » veulent dire ici, là, là-bas. Devant un nom, on utilise « kono », « sono », « ano » : « kono gēmu », ce jeu-ci. Astuce : « ko » est près de moi, « so » est près de toi, « a » est au loin, il suffit de retenir ces trois petits sons.","exampleRo":"Kore wa nan desu ka?","lit":"ceci · [thème] · quoi · être (poli) · [question]","say":{"Kore, sore, are":"これ、それ、あれ","Kore":"これ","Sore":"それ","Are":"あれ","Kore wa nan desu ka":"これは何ですか","Sore wa kamera desu":"それはカメラです","koko":"ここ","soko":"そこ","asoko":"あそこ","kono":"この","sono":"その","ano":"あの","kono gēmu":"このゲーム"}}},{"title":"Mon petit appartement","phrases":[{"fr":"Voici mon appartement.","tgt":"ここは私のアパートです。","ro":"Koko wa watashi no apāto desu.","lit":"ici · [thème] · moi · [possessif] · appartement · être (poli)","note":{"lit":"ici, petit mot du thème, moi, petit mot du possessif, appartement, être","text":"Pour dire mon, on dit moi, suivi de « no ». Ce petit mot crée le possessif. Mon appartement, c'est l'appartement de moi.","say":{"no":"の"},"words":[["ici","ここ"],["petit mot du thème","は"],["moi","私"],["petit mot du possessif","の"],["appartement","アパート"],["être","です"]]}},{"fr":"C'est ma clé.","tgt":"これは私の鍵です。","ro":"Kore wa watashi no kagi desu.","lit":"ceci · [thème] · moi · [possessif] · clé · être (poli)","note":{"lit":"ceci, petit mot du thème, moi, petit mot du possessif, clé, être","text":"Clé se dit « kagi ». Ma clé se dit moi, puis le petit mot du possessif, puis clé. L'ordre est le même pour toutes les choses à soi.","say":{"kagi":"鍵"},"words":[["ceci","これ"],["petit mot du thème","は"],["moi","私"],["petit mot du possessif","の"],["clé","鍵"],["être","です"]]}},{"fr":"Ma chambre est petite.","tgt":"私の部屋は小さいです。","ro":"Watashi no heya wa chiisai desu.","lit":"moi · [possessif] · chambre · [thème] · petit · être (poli)","note":{"lit":"moi, petit mot du possessif, chambre, petit mot du thème, petit, être","text":"Petit se dit « chiisai ». C'est un adjectif qui finit par le son i. Il se place à la fin, avant le petit mot poli.","say":{"chiisai":"小さい"},"words":[["moi","私"],["petit mot du possessif","の"],["chambre","部屋"],["petit mot du thème","は"],["petit","小さい"],["être","です"]]}},{"fr":"C'est le vélo de Monsieur Satō.","tgt":"それは佐藤さんの自転車です。","ro":"Sore wa Satō-san no jitensha desu.","lit":"cela · [thème] · Satō-monsieur · [possessif] · vélo · être (poli)","note":{"lit":"cela, petit mot du thème, Satō, monsieur, petit mot du possessif, vélo, être","text":"Vélo se dit « jitensha ». Le propriétaire vient en premier, puis le possessif, puis l'objet. C'est l'inverse du français.","say":{"jitensha":"自転車"},"words":[["cela","それ"],["petit mot du thème","は"],["Satō","佐藤"],["monsieur","さん"],["petit mot du possessif","の"],["vélo","自転車"],["être","です"]]}},{"fr":"Mon appartement est près de la gare.","tgt":"私のアパートは駅の近くです。","ro":"Watashi no apāto wa eki no chikaku desu.","lit":"moi · [possessif] · appartement · [thème] · gare · [de] · proximité · être (poli)","note":{"lit":"moi, petit mot du possessif, appartement, petit mot du thème, gare, petit mot de liaison, proximité, être","text":"Près de la gare se dit mot à mot la proximité de la gare. Gare se dit « eki ». Ce mot sert tous les jours au Japon.","say":{"eki":"駅"},"words":[["moi","私"],["petit mot du possessif","の"],["appartement","アパート"],["petit mot du thème","は"],["gare","駅"],["petit mot de liaison","の"],["proximité","近く"],["être","です"]]}},{"fr":"La salle de bain est neuve.","tgt":"お風呂は新しいです。","ro":"Ofuro wa atarashii desu.","lit":"honorable-bain · [thème] · neuf · être (poli)","note":{"lit":"bain, petit mot du thème, neuf, être","text":"Le bain se dit « ofuro ». Le petit son du début est une marque de politesse. Au Japon, le bain du soir est un vrai moment de détente.","say":{"ofuro":"お風呂"},"words":[["bain","お風呂"],["petit mot du thème","は"],["neuf","新しい"],["être","です"]]}},{"fr":"C'est le parapluie de qui ?","tgt":"これはだれの傘ですか？","ro":"Kore wa dare no kasa desu ka?","lit":"ceci · [thème] · qui · [possessif] · parapluie · être (poli) · [question]","note":{"lit":"ceci, petit mot du thème, qui, petit mot du possessif, parapluie, être, petit mot de question","text":"Pour demander à qui, on dit qui, suivi du possessif. Qui se dit « dare ». Le parapluie vient après, comme pour un nom.","say":{"dare":"だれ"},"words":[["ceci","これ"],["petit mot du thème","は"],["qui","だれ"],["petit mot du possessif","の"],["parapluie","傘"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est le mien.","tgt":"私のです。","ro":"Watashi no desu.","lit":"moi · [possessif] · être (poli)","note":{"lit":"moi, petit mot du possessif, être","text":"Pour dire le mien, on dit simplement « watashi no ». L'objet n'est pas répété. On comprend de quoi on parle.","say":{"watashi no":"私の"},"words":[["moi","私"],["petit mot du possessif","の"],["être","です"]]}},{"fr":"Le loyer est de quatre-vingt mille yens.","tgt":"家賃は八万円です。","ro":"Yachin wa hachiman en desu.","lit":"loyer · [thème] · huit-dix-mille yens · être (poli)","note":{"lit":"loyer, petit mot du thème, quatre-vingt mille, yen, être","text":"Loyer se dit « yachin ». Quatre-vingt mille, c'est huit fois dix mille. On compte toujours par paquets de dix mille.","say":{"yachin":"家賃"},"words":[["loyer","家賃"],["petit mot du thème","は"],["quatre-vingt mille","八万"],["yen","円"],["être","です"]]}},{"fr":"La propriétaire est gentille.","tgt":"大家さんは優しいです。","ro":"Ōya-san wa yasashii desu.","lit":"propriétaire-madame · [thème] · gentil · être (poli)","note":{"lit":"propriétaire, madame, petit mot du thème, gentil, être","text":"Gentil ou doux se dit « yasashii ». Le petit mot de politesse s'ajoute même après un métier. On parle ainsi poliment de la propriétaire.","say":{"yasashii":"優しい"},"words":[["propriétaire","大家"],["madame","さん"],["petit mot du thème","は"],["gentil","優しい"],["être","です"]]}}],"tip":{"title":"« No » : de, à moi, le possessif","example":"Voici mon appartement. — ここは私<b>の</b>アパートです。","body":"« No » relie deux noms, un peu comme notre « de », mais à l'envers. En français, on dit le vélo de Monsieur Satō ; en japonais, on dit « Satō-san no jitensha », Satō, de, vélo. Le possesseur vient en premier, puis la chose possédée. « Koko wa watashi no apāto desu » se dit littéralement : ici, quant à lui, moi de, appartement, être. Donc « watashi no » veut dire mon, ma, ou à moi. On peut même laisser tomber l'objet : « Watashi no desu », c'est le mien. « No » sert aussi à préciser : « Tōkyō no fuyu », l'hiver de Tokyo, ou « eki no chikaku », près de la gare. Astuce : retenez l'ordre propriétaire, puis « no », puis objet, comme si vous disiez à moi, l'appartement.","exampleRo":"Koko wa watashi no apāto desu.","lit":"ici · [thème] · moi · [possessif] · appartement · être (poli)","say":{"No":"の","Satō-san no jitensha":"佐藤さんの自転車","Koko wa watashi no apāto desu":"ここは私のアパートです","watashi no":"私の","Watashi no desu":"私のです","Tōkyō no fuyu":"東京の冬","eki no chikaku":"駅の近く","no":"の"}}},{"title":"Un bol de ramen","phrases":[{"fr":"Ce restaurant de ramen est célèbre.","tgt":"このラーメン屋は有名です。","ro":"Kono rāmen-ya wa yūmei desu.","lit":"ce · ramen-boutique · [thème] · célèbre · être (poli)","note":{"lit":"ce, ramen, boutique, petit mot du thème, célèbre, être","text":"Après le nom d'un produit, boutique se dit « ya ». Une boutique de ramen, c'est donc ramen suivi de ce mot. Le même mot sert pour le boulanger ou le fleuriste.","say":{"ya":"屋"},"words":[["ce","この"],["ramen","ラーメン"],["boutique","屋"],["petit mot du thème","は"],["célèbre","有名"],["être","です"]]}},{"fr":"Mais ce n'est pas un restaurant cher.","tgt":"でも、高い店じゃありません。","ro":"Demo, takai mise ja arimasen.","lit":"mais · cher · restaurant · ne pas être (poli)","note":{"lit":"mais, cher, restaurant, ne pas être","text":"Pour dire ce n'est pas, on remplace le petit mot poli par « ja arimasen ». Le reste de la phrase ne change pas. Mais se place en tout début de phrase.","say":{"ja arimasen":"じゃありません"},"words":[["mais","でも"],["cher","高い"],["restaurant","店"],["ne pas être","じゃありません"]]}},{"fr":"C'est du ramen au miso, ça ?","tgt":"これは味噌ラーメンですか？","ro":"Kore wa miso rāmen desu ka?","lit":"ceci · [thème] · miso-ramen · être (poli) · [question]","note":{"lit":"ceci, petit mot du thème, miso, ramen, être, petit mot de question","text":"Ramen se prononce avec un a long, « rāmen ». Les voyelles longues comptent en japonais. Le type de soupe se place devant.","say":{"rāmen":"ラーメン"},"words":[["ceci","これ"],["petit mot du thème","は"],["miso","味噌"],["ramen","ラーメン"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, ce n'est pas du miso.","tgt":"いいえ、味噌じゃありません。","ro":"Iie, miso ja arimasen.","lit":"non · miso · ne pas être (poli)","note":{"lit":"non, miso, ne pas être","text":"Ici, on répète le mot de la question, puis on le nie. C'est la réponse la plus naturelle. Non se dit « iie ».","say":{"iie":"いいえ"},"words":[["non","いいえ"],["miso","味噌"],["ne pas être","じゃありません"]]}},{"fr":"C'est du ramen à la sauce soja.","tgt":"醤油ラーメンです。","ro":"Shōyu rāmen desu.","lit":"sauce soja-ramen · être (poli)","note":{"lit":"sauce soja, ramen, être","text":"Sauce soja se dit « shōyu ». On la met avant ramen pour dire le goût. Le sujet n'est pas dit, on le devine.","say":{"shōyu":"醤油"},"words":[["sauce soja","醤油"],["ramen","ラーメン"],["être","です"]]}},{"fr":"Ce n'est pas ma commande.","tgt":"それは私の注文じゃありません。","ro":"Sore wa watashi no chūmon ja arimasen.","lit":"cela · [thème] · moi · [possessif] · commande · ne pas être (poli)","note":{"lit":"cela, petit mot du thème, moi, petit mot du possessif, commande, ne pas être","text":"Commande se dit « chūmon ». Ma commande, c'est moi, le possessif, puis commande. La négation polie vient en dernier.","say":{"chūmon":"注文"},"words":[["cela","それ"],["petit mot du thème","は"],["moi","私"],["petit mot du possessif","の"],["commande","注文"],["ne pas être","じゃありません"]]}},{"fr":"Pardon, ma commande, ce sont les gyōza.","tgt":"すみません、私のは餃子です。","ro":"Sumimasen, watashi no wa gyōza desu.","lit":"pardon · moi · [possessif] · [thème] · gyōza · être (poli)","note":{"lit":"pardon, moi, petit mot du possessif, petit mot du thème, gyōza, être","text":"Pour s'excuser ou interpeller, on dit « sumimasen ». C'est le mot le plus utile au restaurant. Il sert aussi à appeler le serveur.","say":{"sumimasen":"すみません"},"words":[["pardon","すみません"],["moi","私"],["petit mot du possessif","の"],["petit mot du thème","は"],["gyōza","餃子"],["être","です"]]}},{"fr":"Ce n'est pas un plat épicé.","tgt":"辛い料理じゃありません。","ro":"Karai ryōri ja arimasen.","lit":"épicé · plat · ne pas être (poli)","note":{"lit":"épicé, plat, ne pas être","text":"Épicé se dit « karai ». L'adjectif se place devant le nom. On dit donc épicé plat.","say":{"karai":"辛い"},"words":[["épicé","辛い"],["plat","料理"],["ne pas être","じゃありません"]]}},{"fr":"Ce n'est pas la première fois.","tgt":"初めてじゃありません。","ro":"Hajimete ja arimasen.","lit":"première fois · ne pas être (poli)","note":{"lit":"première fois, ne pas être","text":"Première fois se dit « hajimete ». On reconnaît le début du mot enchanté. Ici, on le nie avec la forme polie.","say":{"hajimete":"初めて"},"words":[["première fois","初めて"],["ne pas être","じゃありません"]]}},{"fr":"Ça fait neuf cents yens.","tgt":"九百円です。","ro":"Kyūhyaku en desu.","lit":"neuf-cents yens · être (poli)","note":{"lit":"neuf cents, yen, être","text":"Neuf cents se dit « kyūhyaku ». Le mot cent change un peu de son selon le chiffre devant. Le prix vient toujours avant yen.","say":{"kyūhyaku":"九百"},"words":[["neuf cents","九百"],["yen","円"],["être","です"]]}}],"tip":{"title":"« Ja arimasen » : dire « ce n'est pas »","example":"Non, ce n'est pas du miso. — いいえ、味噌<b>じゃありません</b>。","body":"Pour dire ce n'est pas, on remplace « desu » par « ja arimasen ». « Miso desu », c'est du miso, devient « Miso ja arimasen », ce n'est pas du miso. Littéralement, « ja arimasen » signifie à peu près : en tant que cela, ça n'existe pas. Comme toujours, la négation se place à la fin de la phrase, là où se trouve le verbe. Il faut donc attendre le dernier mot pour savoir si une phrase est positive ou négative. Autres exemples : « Gakusei ja arimasen », je ne suis pas étudiant, et « Hajimete ja arimasen », ce n'est pas la première fois. Dans un registre un peu plus soigné, vous entendrez aussi « dewa arimasen », qui veut dire exactement la même chose. Astuce : en japonais, écoutez toujours jusqu'au bout, c'est la fin qui dit oui ou non.","exampleRo":"Iie, miso ja arimasen.","lit":"non · miso · ne pas être (poli)","say":{"Ja arimasen":"じゃありません","desu":"です","ja arimasen":"じゃありません","Miso desu":"味噌です","Miso ja arimasen":"味噌じゃありません","Gakusei ja arimasen":"学生じゃありません","Hajimete ja arimasen":"初めてじゃありません","dewa arimasen":"ではありません"}}},{"title":"La routine du matin","phrases":[{"fr":"Je me lève à six heures.","tgt":"六時に起きます。","ro":"Rokuji ni okimasu.","lit":"six-heure · [à : moment] · se lever (poli)","note":{"lit":"six heures, petit mot du moment, se lever","text":"Les verbes polis finissent tous par le même son. Ce son se dit « masu ». Il sert pour le présent comme pour le futur.","say":{"masu":"ます"},"words":[["six heures","六時"],["petit mot du moment","に"],["se lever","起きます"]]}},{"fr":"Je me brosse les dents.","tgt":"歯を磨きます。","ro":"Ha o migakimasu.","lit":"dents · [objet] · brosser (poli)","note":{"lit":"dents, petit mot du complément, brosser","text":"Dent se dit « ha ». Il n'y a pas de pluriel, une dent ou des dents, c'est pareil. Le verbe brosser vient à la fin.","say":{"ha":"歯"},"words":[["dents","歯"],["petit mot du complément","を"],["brosser","磨きます"]]}},{"fr":"Je prends une douche.","tgt":"シャワーを浴びます。","ro":"Shawā o abimasu.","lit":"douche · [objet] · recevoir sur soi (poli)","note":{"lit":"douche, petit mot du complément, recevoir sur soi","text":"Pour une douche, on dit qu'on la reçoit sur soi. Ce verbe se dit « abimasu ». Douche vient de l'anglais.","say":{"abimasu":"浴びます"},"words":[["douche","シャワー"],["petit mot du complément","を"],["recevoir sur soi","浴びます"]]}},{"fr":"Je prends mon petit-déjeuner.","tgt":"朝ごはんを食べます。","ro":"Asagohan o tabemasu.","lit":"matin-repas · [objet] · manger (poli)","note":{"lit":"petit-déjeuner, petit mot du complément, manger","text":"Le petit-déjeuner se dit mot à mot le repas du matin. Manger se dit « tabemasu ». C'est un verbe de tous les jours.","say":{"tabemasu":"食べます"},"words":[["petit-déjeuner","朝ごはん"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"Je bois du thé vert.","tgt":"お茶を飲みます。","ro":"Ocha o nomimasu.","lit":"honorable-thé · [objet] · boire (poli)","note":{"lit":"thé, petit mot du complément, boire","text":"Boire se dit « nomimasu ». Thé vert se dit simplement thé, avec le petit son poli devant. Au Japon, le thé est vert par défaut.","say":{"nomimasu":"飲みます"},"words":[["thé","お茶"],["petit mot du complément","を"],["boire","飲みます"]]}},{"fr":"Je sors à huit heures.","tgt":"八時に出かけます。","ro":"Hachiji ni dekakemasu.","lit":"huit-heure · [à : moment] · sortir (poli)","note":{"lit":"huit heures, petit mot du moment, sortir","text":"Après une heure, on ajoute le petit mot « ni ». C'est comme à en français, à huit heures. Le verbe sortir vient ensuite.","say":{"ni":"に"},"words":[["huit heures","八時"],["petit mot du moment","に"],["sortir","出かけます"]]}},{"fr":"Demain, je vais à Asakusa.","tgt":"明日、浅草に行きます。","ro":"Ashita, Asakusa ni ikimasu.","lit":"demain · Asakusa · [direction] · aller (poli)","note":{"lit":"demain, Asakusa, vers, aller","text":"Le même verbe sert pour le présent et le futur. Avec demain, on comprend que c'est le futur. Je vais se dit donc « ikimasu ».","say":{"ikimasu":"行きます"},"words":[["demain","明日"],["Asakusa","浅草"],["vers","に"],["aller","行きます"]]}},{"fr":"Le week-end, je fais le ménage.","tgt":"週末、掃除をします。","ro":"Shūmatsu, sōji o shimasu.","lit":"week-end · ménage · [objet] · faire (poli)","note":{"lit":"week-end, ménage, petit mot du complément, faire","text":"Faire se dit « shimasu ». On le combine avec beaucoup de noms. Ménage plus faire, c'est faire le ménage.","say":{"shimasu":"します"},"words":[["week-end","週末"],["ménage","掃除"],["petit mot du complément","を"],["faire","します"]]}},{"fr":"Ce soir, je regarde la télé.","tgt":"今晩、テレビを見ます。","ro":"Konban, terebi o mimasu.","lit":"ce soir · télé · [objet] · regarder (poli)","note":{"lit":"ce soir, télé, petit mot du complément, regarder","text":"Ce soir se dit « konban ». On le retrouve dans bonsoir, qui se dit presque pareil. Le moment vient en premier.","say":{"konban":"今晩"},"words":[["ce soir","今晩"],["télé","テレビ"],["petit mot du complément","を"],["regarder","見ます"]]}},{"fr":"Je me couche à onze heures.","tgt":"十一時に寝ます。","ro":"Jūichiji ni nemasu.","lit":"onze-heure · [à : moment] · dormir (poli)","note":{"lit":"onze heures, petit mot du moment, dormir","text":"Se coucher et dormir, c'est le même verbe, « nemasu ». Onze, c'est dix et un. C'est très régulier.","say":{"nemasu":"寝ます"},"words":[["onze heures","十一時"],["petit mot du moment","に"],["dormir","寝ます"]]}}],"tip":{"title":"Les verbes polis en « -masu » : présent et futur","example":"Demain, je vais à Asakusa. — 明日、浅草に<b>行きます</b>。","body":"Les verbes polis japonais se terminent par « masu ». « Ikimasu » veut dire aller, « tabemasu » manger, « nomimasu » boire. Bonne nouvelle : ils ne changent pas selon la personne, je mange, tu manges et ils mangent se disent tous « tabemasu ». Encore mieux, la même forme sert pour le présent et pour le futur. « Ashita, Asakusa ni ikimasu » se dit littéralement : demain, Asakusa, vers, aller. C'est le mot « ashita », demain, qui indique le futur. Sans lui, « Asakusa ni ikimasu » peut vouloir dire je vais à Asakusa, en général ou bientôt. Comme « desu », la terminaison « masu » se prononce presque « mass ». Astuce : imaginez « masu » comme le costume poli que les verbes enfilent pour sortir.","exampleRo":"Ashita, Asakusa ni ikimasu.","lit":"demain · Asakusa · [direction] · aller (poli)","say":{"masu":"ます","Ikimasu":"行きます","tabemasu":"食べます","nomimasu":"飲みます","Ashita, Asakusa ni ikimasu":"明日、浅草に行きます","ashita":"明日","Asakusa ni ikimasu":"浅草に行きます","desu":"です","-masu":"ます"}}},{"title":"Un bentō pour midi","phrases":[{"fr":"J'achète un bentō.","tgt":"お弁当を買います。","ro":"Obentō o kaimasu.","lit":"honorable-bentō · [objet] · acheter (poli)","note":{"lit":"bentō, petit mot du complément, acheter","text":"Le complément est suivi de « o ». Ce petit mot marque ce qu'on achète, mange ou boit. Il se place ici juste avant le verbe.","say":{"o":"を"},"words":[["bentō","お弁当"],["petit mot du complément","を"],["acheter","買います"]]}},{"fr":"Je mange un onigiri.","tgt":"おにぎりを食べます。","ro":"Onigiri o tabemasu.","lit":"onigiri · [objet] · manger (poli)","note":{"lit":"onigiri, petit mot du complément, manger","text":"Une boule de riz se dit « onigiri ». On en trouve dans tous les konbinis. Elle est souvent garnie de thon ou de saumon.","say":{"onigiri":"おにぎり"},"words":[["onigiri","おにぎり"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"Je bois de l'eau.","tgt":"水を飲みます。","ro":"Mizu o nomimasu.","lit":"eau · [objet] · boire (poli)","note":{"lit":"eau, petit mot du complément, boire","text":"Eau se dit « mizu ». On ne dit pas de l'eau, juste eau. Le japonais n'a pas d'article.","say":{"mizu":"水"},"words":[["eau","水"],["petit mot du complément","を"],["boire","飲みます"]]}},{"fr":"Je vous réchauffe le bentō ?","tgt":"お弁当を温めますか？","ro":"Obentō o atatamemasu ka?","lit":"honorable-bentō · [objet] · réchauffer (poli) · [question]","note":{"lit":"bentō, petit mot du complément, réchauffer, petit mot de question","text":"C'est la question qu'on entend toujours au konbini. Réchauffer se dit « atatamemasu ». Le petit mot de question vient en dernier.","say":{"atatamemasu":"温めます"},"words":[["bentō","お弁当"],["petit mot du complément","を"],["réchauffer","温めます"],["petit mot de question","か"]]}},{"fr":"Oui, s'il vous plaît.","tgt":"はい、お願いします。","ro":"Hai, onegaishimasu.","lit":"oui · je vous le demande (poli)","note":{"lit":"oui, je vous le demande","text":"S'il vous plaît, pour accepter, se dit « onegaishimasu ». Mot à mot, c'est je vous le demande. C'est la réponse polie à une offre.","say":{"onegaishimasu":"お願いします"},"words":[["oui","はい"],["je vous le demande","お願いします"]]}},{"fr":"Je choisis un bentō au poulet frit.","tgt":"唐揚げ弁当を選びます。","ro":"Karaage bentō o erabimasu.","lit":"poulet frit-bentō · [objet] · choisir (poli)","note":{"lit":"poulet frit, bentō, petit mot du complément, choisir","text":"Le poulet frit japonais se dit « karaage ». C'est un des bentōs préférés des Japonais. Choisir vient à la fin.","say":{"karaage":"唐揚げ"},"words":[["poulet frit","唐揚げ"],["bentō","弁当"],["petit mot du complément","を"],["choisir","選びます"]]}},{"fr":"Je sors mon porte-monnaie.","tgt":"財布を出します。","ro":"Saifu o dashimasu.","lit":"porte-monnaie · [objet] · sortir (poli)","note":{"lit":"porte-monnaie, petit mot du complément, sortir","text":"Porte-monnaie se dit « saifu ». Sortir, ici, veut dire sortir quelque chose. C'est un autre verbe que sortir de chez soi.","say":{"saifu":"財布"},"words":[["porte-monnaie","財布"],["petit mot du complément","を"],["sortir","出します"]]}},{"fr":"Je regarde les prix.","tgt":"値段を見ます。","ro":"Nedan o mimasu.","lit":"prix · [objet] · regarder (poli)","note":{"lit":"prix, petit mot du complément, regarder","text":"Prix se dit « nedan ». Le complément vient avant le verbe regarder. On dit juste prix, sans article.","say":{"nedan":"値段"},"words":[["prix","値段"],["petit mot du complément","を"],["regarder","見ます"]]}},{"fr":"Je prends le bentō en photo.","tgt":"お弁当の写真を撮ります。","ro":"Obentō no shashin o torimasu.","lit":"honorable-bentō · [de] · photo · [objet] · prendre (poli)","note":{"lit":"bentō, petit mot de liaison, photo, petit mot du complément, prendre","text":"Photo se dit « shashin ». Prendre en photo se dit mot à mot prendre la photo du bentō. Le bentō vient avant, avec le petit mot de liaison.","say":{"shashin":"写真"},"words":[["bentō","お弁当"],["petit mot de liaison","の"],["photo","写真"],["petit mot du complément","を"],["prendre","撮ります"]]}},{"fr":"Qu'est-ce que vous mangez ?","tgt":"何を食べますか？","ro":"Nani o tabemasu ka?","lit":"quoi · [objet] · manger (poli) · [question]","note":{"lit":"quoi, petit mot du complément, manger, petit mot de question","text":"Quoi, comme complément, se dit « nani ». Il prend simplement la place de la chose mangée. L'ordre de la phrase reste le même.","say":{"nani":"何"},"words":[["quoi","何"],["petit mot du complément","を"],["manger","食べます"],["petit mot de question","か"]]}}],"tip":{"title":"« O » : la particule du complément d'objet","example":"J'achète un bentō. — お弁当<b>を</b>買います。","body":"La particule « o » marque le complément d'objet, c'est-à-dire la chose sur laquelle porte l'action. On la place juste après cette chose, et juste avant le verbe. « Obentō o kaimasu » se dit littéralement : honorable bentō, objet, acheter. En français, on dirait simplement : j'achète un bentō. Autres exemples : « Mizu o nomimasu », eau, objet, boire, et « Onigiri o tabemasu », onigiri, objet, manger. Pour poser une question, remplacez la chose par « nani », quoi : « Nani o tabemasu ka », qu'est-ce que vous mangez ? À l'écrit, cette particule a son propre signe, qui ne sert presque qu'à cela, mais elle se prononce simplement « o ». Astuce : « o » est comme une flèche qui désigne la cible de l'action.","exampleRo":"Obentō o kaimasu.","lit":"honorable-bentō · [objet] · acheter (poli)","say":{"O":"を","o":"を","Obentō o kaimasu":"お弁当を買います","Mizu o nomimasu":"水を飲みます","Onigiri o tabemasu":"おにぎりを食べます","nani":"なに","Nani o tabemasu ka":"何を食べますか"}}},{"title":"Rendez-vous à Asakusa","phrases":[{"fr":"Nous allons au temple Sensō-ji.","tgt":"浅草寺へ行きます。","ro":"Sensōji e ikimasu.","lit":"temple Sensō-ji · [direction] · aller (poli)","note":{"lit":"temple Sensō-ji, vers, aller","text":"Le Sensō-ji est le plus vieux temple de Tokyo. Aller se dit « ikimasu ». La destination vient avant, avec le petit mot vers.","say":{"ikimasu":"行きます"},"words":[["temple Sensō-ji","浅草寺"],["vers","へ"],["aller","行きます"]]}},{"fr":"Je pars à dix heures.","tgt":"十時に出ます。","ro":"Jūji ni demasu.","lit":"dix-heure · [à : moment] · partir (poli)","note":{"lit":"dix heures, petit mot du moment, partir","text":"Partir se dit « demasu ». Mot à mot, c'est sortir. Avec une heure précise, on ajoute le petit mot du moment.","say":{"demasu":"出ます"},"words":[["dix heures","十時"],["petit mot du moment","に"],["partir","出ます"]]}},{"fr":"J'arrive à Asakusa à dix heures et demie.","tgt":"十時半に浅草に着きます。","ro":"Jūji han ni Asakusa ni tsukimasu.","lit":"dix-heure · demie · [à : moment] · Asakusa · [direction] · arriver (poli)","note":{"lit":"dix heures, et demie, petit mot du moment, Asakusa, vers, arriver","text":"Et demie se dit « han ». Il se place juste après l'heure. Le même petit mot sert ensuite pour l'heure et pour le lieu d'arrivée.","say":{"han":"半"},"words":[["dix heures","十時"],["et demie","半"],["petit mot du moment","に"],["Asakusa","浅草"],["vers","に"],["arriver","着きます"]]}},{"fr":"Mon ami arrive à onze heures.","tgt":"友達は十一時に来ます。","ro":"Tomodachi wa jūichiji ni kimasu.","lit":"ami · [thème] · onze-heure · [à : moment] · venir (poli)","note":{"lit":"ami, petit mot du thème, onze heures, petit mot du moment, venir","text":"Venir se dit « kimasu ». On dit le thème, puis l'heure, puis le verbe. L'heure a besoin du petit mot du moment.","say":{"kimasu":"来ます"},"words":[["ami","友達"],["petit mot du thème","は"],["onze heures","十一時"],["petit mot du moment","に"],["venir","来ます"]]}},{"fr":"Où allez-vous ?","tgt":"どこへ行きますか？","ro":"Doko e ikimasu ka?","lit":"où · [direction] · aller (poli) · [question]","note":{"lit":"où, vers, aller, petit mot de question","text":"Pour demander où l'on va, on dit « doko e ». Le second son veut dire vers. On termine par aller et le petit mot de question.","say":{"doko e":"どこへ"},"words":[["où","どこ"],["vers","へ"],["aller","行きます"],["petit mot de question","か"]]}},{"fr":"Je vais à la porte Kaminarimon.","tgt":"雷門へ行きます。","ro":"Kaminarimon e ikimasu.","lit":"porte du Tonnerre · [direction] · aller (poli)","note":{"lit":"porte du Tonnerre, vers, aller","text":"Le nom de cette porte veut dire porte du tonnerre. Tonnerre se dit « kaminari ». C'est l'entrée la plus célèbre d'Asakusa.","say":{"kaminari":"雷"},"words":[["porte du Tonnerre","雷門"],["vers","へ"],["aller","行きます"]]}},{"fr":"Ensuite, nous allons à la Skytree.","tgt":"それから、スカイツリーに行きます。","ro":"Sorekara, Sukaitsurī ni ikimasu.","lit":"ensuite · Skytree · [direction] · aller (poli)","note":{"lit":"ensuite, Skytree, vers, aller","text":"Ensuite se dit « sorekara ». On le place en tête de phrase, suivi d'une petite pause. Il sert à raconter les étapes d'une journée.","say":{"sorekara":"それから"},"words":[["ensuite","それから"],["Skytree","スカイツリー"],["vers","に"],["aller","行きます"]]}},{"fr":"Je rentre chez moi à six heures.","tgt":"六時に家へ帰ります。","ro":"Rokuji ni ie e kaerimasu.","lit":"six-heure · [à : moment] · maison · [direction] · rentrer (poli)","note":{"lit":"six heures, petit mot du moment, maison, vers, rentrer","text":"L'heure vient souvent en premier, puis le lieu. Chaque élément a son petit mot. Rentrer se dit « kaerimasu ».","say":{"kaerimasu":"帰ります"},"words":[["six heures","六時"],["petit mot du moment","に"],["maison","家"],["vers","へ"],["rentrer","帰ります"]]}},{"fr":"Le samedi, je vais à la piscine.","tgt":"土曜日にプールへ行きます。","ro":"Doyōbi ni pūru e ikimasu.","lit":"samedi · [à : moment] · piscine · [direction] · aller (poli)","note":{"lit":"samedi, petit mot du moment, piscine, vers, aller","text":"Samedi se dit « doyōbi ». Avec un jour de la semaine, on ajoute le petit mot du moment. Piscine est un mot venu de l'anglais.","say":{"doyōbi":"土曜日"},"words":[["samedi","土曜日"],["petit mot du moment","に"],["piscine","プール"],["vers","へ"],["aller","行きます"]]}},{"fr":"Les boutiques de Nakamise ouvrent à dix heures.","tgt":"仲見世のお店は十時に開きます。","ro":"Nakamise no omise wa jūji ni akimasu.","lit":"Nakamise · [de] · honorables-boutiques · [thème] · dix-heure · [à : moment] · ouvrir (poli)","note":{"lit":"Nakamise, petit mot de liaison, boutiques, petit mot du thème, dix heures, petit mot du moment, ouvrir","text":"Ouvrir, pour un magasin, se dit « akimasu ». Le magasin s'ouvre tout seul, sans complément. Les boutiques de Nakamise mènent au temple.","say":{"akimasu":"開きます"},"words":[["Nakamise","仲見世"],["petit mot de liaison","の"],["boutiques","お店"],["petit mot du thème","は"],["dix heures","十時"],["petit mot du moment","に"],["ouvrir","開きます"]]}}],"tip":{"title":"« Ni » et « e » : aller vers un lieu, à une heure","example":"J'arrive à Asakusa à dix heures et demie. — 十時半<b>に</b>浅草<b>に</b>着きます。","body":"La particule « ni » a deux usages très fréquents. Après un lieu, elle indique la destination : « Asakusa ni ikimasu », Asakusa, vers, aller. Après une heure précise, elle indique le moment : « Jūji ni demasu », dix heures, à, partir. « Jūji han ni Asakusa ni tsukimasu » se dit donc : dix heures et demie, à, Asakusa, vers, arriver. La particule « e » ressemble beaucoup à « ni » pour les déplacements : « Sensōji e ikimasu », nous allons au temple Sensō-ji. « E » insiste sur la direction, le mouvement vers quelque part, alors que « ni » insiste plutôt sur le point d'arrivée. Pour aller quelque part, les deux sont donc presque toujours possibles, mais pour une heure, seul « ni » fonctionne. Astuce : « e », c'est la flèche du trajet, « ni », c'est la cible.","exampleRo":"Jūji han ni Asakusa ni tsukimasu.","lit":"dix-heure · demie · [à : moment] · Asakusa · [direction] · arriver (poli)","say":{"Ni":"に","e":"え","ni":"に","Asakusa ni ikimasu":"浅草に行きます","Jūji ni demasu":"十時に出ます","Jūji han ni Asakusa ni tsukimasu":"十時半に浅草に着きます","Sensōji e ikimasu":"浅草寺へ行きます","E":"え"}}},{"title":"Le métro de Tokyo","phrases":[{"fr":"Je vais au travail en métro.","tgt":"地下鉄で会社に行きます。","ro":"Chikatetsu de kaisha ni ikimasu.","lit":"métro · [moyen] · entreprise · [direction] · aller (poli)","note":{"lit":"métro, petit mot du moyen, entreprise, vers, aller","text":"Après un moyen de transport, on ajoute le petit mot « de ». Métro suivi de ce mot, c'est en métro. Le travail se dit ici l'entreprise.","say":{"de":"で"},"words":[["métro","地下鉄"],["petit mot du moyen","で"],["entreprise","会社"],["vers","に"],["aller","行きます"]]}},{"fr":"Je change à Ueno.","tgt":"上野で乗り換えます。","ro":"Ueno de norikaemasu.","lit":"Ueno · [lieu] · changer de train (poli)","note":{"lit":"Ueno, petit mot du lieu, changer de train","text":"Changer de train se dit « norikaemasu ». Mot à mot, c'est monter en changeant. Le lieu du changement prend le petit mot du lieu.","say":{"norikaemasu":"乗り換えます"},"words":[["Ueno","上野"],["petit mot du lieu","で"],["changer de train","乗り換えます"]]}},{"fr":"J'achète un ticket au distributeur.","tgt":"券売機で切符を買います。","ro":"Kenbaiki de kippu o kaimasu.","lit":"distributeur de tickets · [lieu] · ticket · [objet] · acheter (poli)","note":{"lit":"distributeur, petit mot du lieu, ticket, petit mot du complément, acheter","text":"Ticket se dit « kippu ». Le distributeur est l'endroit où l'on achète, avec le petit mot du lieu. Puis vient le ticket, et enfin acheter.","say":{"kippu":"切符"},"words":[["distributeur","券売機"],["petit mot du lieu","で"],["ticket","切符"],["petit mot du complément","を"],["acheter","買います"]]}},{"fr":"Je paie avec mon téléphone.","tgt":"スマホで払います。","ro":"Sumaho de haraimasu.","lit":"smartphone · [moyen] · payer (poli)","note":{"lit":"smartphone, petit mot du moyen, payer","text":"Smartphone se dit « sumaho ». C'est un mot anglais raccourci à la japonaise. Le même petit mot sert ici pour le moyen.","say":{"sumaho":"スマホ"},"words":[["smartphone","スマホ"],["petit mot du moyen","で"],["payer","払います"]]}},{"fr":"Je dors dans le métro.","tgt":"地下鉄で寝ます。","ro":"Chikatetsu de nemasu.","lit":"métro · [lieu] · dormir (poli)","note":{"lit":"métro, petit mot du lieu, dormir","text":"Dormir se dit « nemasu ». Dans le métro, on met le petit mot du lieu. Beaucoup de Japonais font la sieste dans les transports.","say":{"nemasu":"寝ます"},"words":[["métro","地下鉄"],["petit mot du lieu","で"],["dormir","寝ます"]]}},{"fr":"Je vais à Ginza en taxi.","tgt":"タクシーで銀座に行きます。","ro":"Takushī de Ginza ni ikimasu.","lit":"taxi · [moyen] · Ginza · [direction] · aller (poli)","note":{"lit":"taxi, petit mot du moyen, Ginza, vers, aller","text":"Taxi se dit « takushī ». On ajoute un son i long à la fin, à la japonaise. Le moyen vient avant la destination.","say":{"takushī":"タクシー"},"words":[["taxi","タクシー"],["petit mot du moyen","で"],["Ginza","銀座"],["vers","に"],["aller","行きます"]]}},{"fr":"Je déjeune à la gare de Tokyo.","tgt":"東京駅で昼ごはんを食べます。","ro":"Tōkyō-eki de hirugohan o tabemasu.","lit":"Tokyo-gare · [lieu] · midi-repas · [objet] · manger (poli)","note":{"lit":"gare de Tokyo, petit mot du lieu, déjeuner, petit mot du complément, manger","text":"Le déjeuner se dit « hirugohan ». C'est mot à mot le repas de midi. Le petit-déjeuner suit la même logique avec le matin.","say":{"hirugohan":"昼ごはん"},"words":[["gare de Tokyo","東京駅"],["petit mot du lieu","で"],["déjeuner","昼ごはん"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"Je fais les courses à Ikebukuro.","tgt":"池袋で買い物をします。","ro":"Ikebukuro de kaimono o shimasu.","lit":"Ikebukuro · [lieu] · courses · [objet] · faire (poli)","note":{"lit":"Ikebukuro, petit mot du lieu, courses, petit mot du complément, faire","text":"Les courses se disent « kaimono ». Mot à mot, c'est la chose achetée. On ajoute faire pour en faire un verbe.","say":{"kaimono":"買い物"},"words":[["Ikebukuro","池袋"],["petit mot du lieu","で"],["courses","買い物"],["petit mot du complément","を"],["faire","します"]]}},{"fr":"Où est-ce qu'on change ?","tgt":"どこで乗り換えますか？","ro":"Doko de norikaemasu ka?","lit":"où · [lieu] · changer de train (poli) · [question]","note":{"lit":"où, petit mot du lieu, changer de train, petit mot de question","text":"Où, pour le lieu d'une action, se dit « doko de ». Pour la destination, on dit où avec le petit mot vers. Le verbe et la question viennent à la fin.","say":{"doko de":"どこで"},"words":[["où","どこ"],["petit mot du lieu","で"],["changer de train","乗り換えます"],["petit mot de question","か"]]}},{"fr":"Je vais au konbini à vélo.","tgt":"自転車でコンビニに行きます。","ro":"Jitensha de konbini ni ikimasu.","lit":"vélo · [moyen] · konbini · [direction] · aller (poli)","note":{"lit":"vélo, petit mot du moyen, konbini, vers, aller","text":"On marque le moyen et la destination avec deux petits mots différents. Vers, après la destination, se dit « ni ». Le verbe aller ferme la phrase.","say":{"ni":"に"},"words":[["vélo","自転車"],["petit mot du moyen","で"],["konbini","コンビニ"],["vers","に"],["aller","行きます"]]}}],"tip":{"title":"« De » : le lieu où l'on fait quelque chose, et le moyen","example":"Je vais au travail en métro. — 地下鉄<b>で</b>会社に行きます。","body":"« De » est une particule très pratique qui a deux grands sens. D'abord, elle indique le lieu où l'on fait une action : « Ikebukuro de kaimono o shimasu », Ikebukuro, à, courses, faire, donc je fais les courses à Ikebukuro. Ensuite, elle indique le moyen, avec quoi on fait quelque chose. « Chikatetsu de kaisha ni ikimasu » se dit littéralement : métro, avec, entreprise, vers, aller. Autrement dit : je vais au travail en métro. On l'utilise aussi pour payer : « Sumaho de haraimasu », je paie avec mon téléphone. Attention à ne pas la confondre avec « ni » : « ni » indique où l'on va, « de » indique où l'action se passe. Astuce : si vous pouvez dire en ou avec en français, ou si quelqu'un agit à un endroit, pensez à « de ».","exampleRo":"Chikatetsu de kaisha ni ikimasu.","lit":"métro · [moyen] · entreprise · [direction] · aller (poli)","say":{"De":"で","Ikebukuro de kaimono o shimasu":"池袋で買い物をします","Chikatetsu de kaisha ni ikimasu":"地下鉄で会社に行きます","Sumaho de haraimasu":"スマホで払います","ni":"に","de":"で"}}},{"title":"Un dimanche tranquille","phrases":[{"fr":"Aujourd'hui, je ne vais pas au travail.","tgt":"今日は仕事に行きません。","ro":"Kyō wa shigoto ni ikimasen.","lit":"aujourd'hui · [thème] · travail · [direction] · ne pas aller (poli)","note":{"lit":"aujourd'hui, petit mot du thème, travail, vers, ne pas aller","text":"Pour la négation, on remplace la fin du verbe par « masen ». Je vais devient ainsi je ne vais pas. Le reste de la phrase ne bouge pas.","say":{"masen":"ません"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["travail","仕事"],["vers","に"],["ne pas aller","行きません"]]}},{"fr":"Je ne me lève pas tôt.","tgt":"早く起きません。","ro":"Hayaku okimasen.","lit":"tôt · ne pas se lever (poli)","note":{"lit":"tôt, ne pas se lever","text":"Tôt se dit « hayaku ». Il se place juste avant le verbe. Comme d'habitude, je n'est pas dit.","say":{"hayaku":"早く"},"words":[["tôt","早く"],["ne pas se lever","起きません"]]}},{"fr":"Je ne prends pas le train.","tgt":"電車に乗りません。","ro":"Densha ni norimasen.","lit":"train · [dans] · ne pas monter (poli)","note":{"lit":"train, dans, ne pas monter","text":"Prendre le train se dit monter dans le train. La négation se dit « norimasen ». Le train garde son petit mot dans.","say":{"norimasen":"乗りません"},"words":[["train","電車"],["dans","に"],["ne pas monter","乗りません"]]}},{"fr":"Je ne bois pas d'alcool.","tgt":"お酒を飲みません。","ro":"Osake o nomimasen.","lit":"honorable-alcool · [objet] · ne pas boire (poli)","note":{"lit":"alcool, petit mot du complément, ne pas boire","text":"Alcool se dit « osake ». Ce mot désigne l'alcool en général, pas seulement le saké. On le dit avec le petit son poli.","say":{"osake":"お酒"},"words":[["alcool","お酒"],["petit mot du complément","を"],["ne pas boire","飲みません"]]}},{"fr":"Ce soir, je ne fais pas la cuisine.","tgt":"今晩は料理をしません。","ro":"Konban wa ryōri o shimasen.","lit":"ce soir · [thème] · cuisine · [objet] · ne pas faire (poli)","note":{"lit":"ce soir, petit mot du thème, cuisine, petit mot du complément, ne pas faire","text":"Faire la cuisine se dit cuisine plus faire. Ne pas faire se dit « shimasen ». Ce soir est mis en thème pour marquer le contraste.","say":{"shimasen":"しません"},"words":[["ce soir","今晩"],["petit mot du thème","は"],["cuisine","料理"],["petit mot du complément","を"],["ne pas faire","しません"]]}},{"fr":"Je regarde un film à la maison.","tgt":"家で映画を見ます。","ro":"Ie de eiga o mimasu.","lit":"maison · [lieu] · film · [objet] · regarder (poli)","note":{"lit":"maison, petit mot du lieu, film, petit mot du complément, regarder","text":"Film se dit « eiga ». Ici, la phrase est positive, avec la fin habituelle. À la maison prend le petit mot du lieu.","say":{"eiga":"映画"},"words":[["maison","家"],["petit mot du lieu","で"],["film","映画"],["petit mot du complément","を"],["regarder","見ます"]]}},{"fr":"Je ne regarde pas la télé.","tgt":"テレビは見ません。","ro":"Terebi wa mimasen.","lit":"télé · [thème] · ne pas regarder (poli)","note":{"lit":"télé, petit mot du thème, ne pas regarder","text":"Dans une phrase négative, on remplace souvent le petit mot du complément par celui du thème. Cela veut dire la télé, en tout cas, non. Le verbe se dit « mimasen ».","say":{"mimasen":"見ません"},"words":[["télé","テレビ"],["petit mot du thème","は"],["ne pas regarder","見ません"]]}},{"fr":"Je ne comprends pas très bien.","tgt":"よくわかりません。","ro":"Yoku wakarimasen.","lit":"bien · ne pas comprendre (poli)","note":{"lit":"bien, ne pas comprendre","text":"Je ne comprends pas se dit « wakarimasen ». C'est une phrase très utile pour un débutant. Bien, juste avant, adoucit la phrase.","say":{"wakarimasen":"わかりません"},"words":[["bien","よく"],["ne pas comprendre","わかりません"]]}},{"fr":"Demain, il ne pleuvra pas.","tgt":"明日は雨が降りません。","ro":"Ashita wa ame ga furimasen.","lit":"demain · [thème] · pluie · [sujet] · ne pas tomber (poli)","note":{"lit":"demain, petit mot du thème, pluie, petit mot du sujet, ne pas tomber","text":"Pour la pluie, on dit que la pluie tombe. Pluie se dit « ame ». Ici, le verbe tomber est à la négation.","say":{"ame":"雨"},"words":[["demain","明日"],["petit mot du thème","は"],["pluie","雨"],["petit mot du sujet","が"],["ne pas tomber","降りません"]]}},{"fr":"Je ne vais nulle part.","tgt":"どこへも行きません。","ro":"Doko e mo ikimasen.","lit":"où · [direction] · [même] · ne pas aller (poli)","note":{"lit":"où, vers, même, ne pas aller","text":"Nulle part se dit où, vers, même, puis un verbe négatif. Ce petit mot même se dit « mo ». Le verbe doit être à la négation.","say":{"mo":"も"},"words":[["où","どこ"],["vers","へ"],["même","も"],["ne pas aller","行きません"]]}}],"tip":{"title":"La négation des verbes : « -masen »","example":"Aujourd'hui, je ne vais pas au travail. — 今日は仕事に<b>行きません</b>。","body":"Pour mettre un verbe poli à la forme négative, c'est très régulier : on remplace « masu » par « masen ». « Ikimasu », je vais, devient « ikimasen », je ne vais pas. « Tabemasu », je mange, devient « tabemasen », je ne mange pas. « Kyō wa shigoto ni ikimasen » se dit littéralement : aujourd'hui, quant à lui, travail, vers, ne pas aller. Comme le verbe est à la fin, la négation arrive aussi en dernier, il faut donc écouter jusqu'au bout. Et comme pour « masu », la forme « masen » vaut aussi pour le futur : « Ashita wa ame ga furimasen », il ne pleuvra pas demain. Une phrase très utile à connaître : « Wakarimasen », je ne comprends pas. Astuce : « masu » dit oui, « masen » dit non, une seule syllabe change tout.","exampleRo":"Kyō wa shigoto ni ikimasen.","lit":"aujourd'hui · [thème] · travail · [direction] · ne pas aller (poli)","say":{"masu":"ます","masen":"ません","Ikimasu":"行きます","ikimasen":"行きません","Tabemasu":"食べます","tabemasen":"食べません","Kyō wa shigoto ni ikimasen":"今日は仕事に行きません","Ashita wa ame ga furimasen":"明日は雨が降りません","Wakarimasen":"分かりません","-masen":"ません"}}},{"title":"L'heure et les nombres","phrases":[{"fr":"Un, deux, trois !","tgt":"いち、に、さん！","ro":"Ichi, ni, san!","lit":"un · deux · trois","note":{"lit":"un, deux, trois","text":"Un, deux, trois se dit « ichi, ni, san ». Ces trois nombres servent de base à tous les autres. On les entend aussi pour prendre une photo.","say":{"ichi, ni, san":"いち、に、さん"},"words":[["un","いち"],["deux","に"],["trois","さん"]]}},{"fr":"Quelle heure est-il maintenant ?","tgt":"今、何時ですか？","ro":"Ima, nanji desu ka?","lit":"maintenant · quelle-heure · être (poli) · [question]","note":{"lit":"maintenant, quelle heure, être, petit mot de question","text":"Quelle heure se dit « nanji ». C'est quoi suivi du mot heure. Maintenant se place au début.","say":{"nanji":"何時"},"words":[["maintenant","今"],["quelle heure","何時"],["être","です"],["petit mot de question","か"]]}},{"fr":"Il est quatre heures.","tgt":"四時です。","ro":"Yoji desu.","lit":"quatre-heure · être (poli)","note":{"lit":"quatre heures, être","text":"Attention, quatre heures se dit « yoji ». Le nombre quatre change de son devant heure. C'est une exception à retenir.","say":{"yoji":"四時"},"words":[["quatre heures","四時"],["être","です"]]}},{"fr":"Il est neuf heures et demie.","tgt":"九時半です。","ro":"Kuji han desu.","lit":"neuf-heure · demie · être (poli)","note":{"lit":"neuf heures, et demie, être","text":"Neuf heures se dit « kuji ». Le nombre neuf prend ici un son court. Et demie s'ajoute juste après.","say":{"kuji":"九時"},"words":[["neuf heures","九時"],["et demie","半"],["être","です"]]}},{"fr":"Le train part à sept heures.","tgt":"電車は七時に出ます。","ro":"Densha wa shichiji ni demasu.","lit":"train · [thème] · sept-heure · [à : moment] · partir (poli)","note":{"lit":"train, petit mot du thème, sept heures, petit mot du moment, partir","text":"Sept heures se dit « shichiji ». Le train est le thème, puis vient l'heure. Le verbe partir ferme la phrase.","say":{"shichiji":"七時"},"words":[["train","電車"],["petit mot du thème","は"],["sept heures","七時"],["petit mot du moment","に"],["partir","出ます"]]}},{"fr":"Quel est votre numéro de téléphone ?","tgt":"電話番号は何番ですか？","ro":"Denwa bangō wa nanban desu ka?","lit":"téléphone-numéro · [thème] · quel-numéro · être (poli) · [question]","note":{"lit":"téléphone, numéro, petit mot du thème, quel numéro, être, petit mot de question","text":"Pour demander un numéro, on dit « nanban ». C'est quoi suivi du mot numéro. Le numéro de téléphone est mis en thème.","say":{"nanban":"何番"},"words":[["téléphone","電話"],["numéro","番号"],["petit mot du thème","は"],["quel numéro","何番"],["être","です"],["petit mot de question","か"]]}},{"fr":"Un ramen, c'est huit cents yens.","tgt":"ラーメンは八百円です。","ro":"Rāmen wa happyaku en desu.","lit":"ramen · [thème] · huit-cents yens · être (poli)","note":{"lit":"ramen, petit mot du thème, huit cents, yen, être","text":"Huit cents se dit « happyaku ». Le son change un peu quand huit rencontre cent. Le prix se termine par yen et le petit mot poli.","say":{"happyaku":"八百"},"words":[["ramen","ラーメン"],["petit mot du thème","は"],["huit cents","八百"],["yen","円"],["être","です"]]}},{"fr":"Le cours commence à une heure.","tgt":"授業は一時に始まります。","ro":"Jugyō wa ichiji ni hajimarimasu.","lit":"cours · [thème] · une-heure · [à : moment] · commencer (poli)","note":{"lit":"cours, petit mot du thème, une heure, petit mot du moment, commencer","text":"Une heure se dit « ichiji ». Le cours est le thème de la phrase. Commencer vient à la fin.","say":{"ichiji":"一時"},"words":[["cours","授業"],["petit mot du thème","は"],["une heure","一時"],["petit mot du moment","に"],["commencer","始まります"]]}},{"fr":"Dix, onze, douze.","tgt":"十、十一、十二。","ro":"Jū, jūichi, jūni.","lit":"dix · dix-un · dix-deux","note":{"lit":"dix, onze, douze","text":"Dix se dit « jū ». Onze, c'est dix et un. Douze, c'est dix et deux.","say":{"jū":"十"},"words":[["dix","十"],["onze","十一"],["douze","十二"]]}},{"fr":"Il est midi pile.","tgt":"ちょうど十二時です。","ro":"Chōdo jūniji desu.","lit":"pile · douze-heure · être (poli)","note":{"lit":"pile, midi, être","text":"Pile, pour l'heure, se dit « chōdo ». Il se place avant l'heure. Midi, c'est tout simplement douze heures.","say":{"chōdo":"ちょうど"},"words":[["pile","ちょうど"],["midi","十二時"],["être","です"]]}}],"tip":{"title":"Compter en japonais : « ichi, ni, san », et les heures en « -ji »","example":"Il est quatre heures. — <b>四時</b>です。","body":"Les nombres japonais sont très logiques. De un à dix : « ichi, ni, san, yon, go, roku, nana, hachi, kyū, jū ». Ensuite, on assemble comme des briques : onze, c'est « jūichi », dix-un, et douze, « jūni », dix-deux. Vingt, c'est « nijū », deux-dix, et trente, « sanjū », trois-dix. Pour l'heure, on ajoute simplement « ji » : « ichiji », une heure, « sanji », trois heures. « Yoji desu » se dit littéralement : quatre-heure, être. Attention à trois exceptions : quatre heures se dit « yoji », sept heures « shichiji », et neuf heures « kuji ». Pour la demie, on ajoute « han » : « kuji han », neuf heures et demie. Astuce : pour demander l'heure, remplacez le nombre par « nan », quoi : « Nanji desu ka », quelle heure est-il ?","exampleRo":"Yoji desu.","lit":"quatre-heure · être (poli)","say":{"jūichi":"じゅういち","jūni":"じゅうに","nijū":"にじゅう","sanjū":"さんじゅう","ichiji":"いちじ","sanji":"さんじ","Yoji desu":"四時です","yoji":"よじ","shichiji":"しちじ","kuji":"くじ","han":"はん","kuji han":"くじはん","nan":"なん","Nanji desu ka":"何時ですか","ichi, ni, san":"いち、に、さん","ichi, ni, san, yon, go, roku, nana, hachi, kyū, jū":"いち、に、さん、よん、ご、ろく、なな、はち、きゅう、じゅう"}}},{"title":"Autour de chez moi","phrases":[{"fr":"Il y a un konbini près de chez moi.","tgt":"家の近くにコンビニがあります。","ro":"Ie no chikaku ni konbini ga arimasu.","lit":"maison · [de] · proximité · [lieu] · konbini · [sujet] · il y a, objet (poli)","note":{"lit":"maison, petit mot de liaison, proximité, petit mot du lieu, konbini, petit mot du sujet, il y a","text":"Pour un objet ou un lieu, il y a se dit « arimasu ». La chose qui existe prend le petit mot du sujet. Le verbe vient en dernier.","say":{"arimasu":"あります"},"words":[["maison","家"],["petit mot de liaison","の"],["proximité","近く"],["petit mot du lieu","に"],["konbini","コンビニ"],["petit mot du sujet","が"],["il y a","あります"]]}},{"fr":"Il y a aussi un petit parc.","tgt":"小さい公園もあります。","ro":"Chiisai kōen mo arimasu.","lit":"petit · parc · [aussi] · il y a, objet (poli)","note":{"lit":"petit, parc, aussi, il y a","text":"Aussi se dit « mo ». Il remplace le petit mot du sujet. Il se place juste après le mot concerné.","say":{"mo":"も"},"words":[["petit","小さい"],["parc","公園"],["aussi","も"],["il y a","あります"]]}},{"fr":"Il y a un chat dans le parc.","tgt":"公園に猫がいます。","ro":"Kōen ni neko ga imasu.","lit":"parc · [lieu] · chat · [sujet] · il y a, être vivant (poli)","note":{"lit":"parc, petit mot du lieu, chat, petit mot du sujet, il y a","text":"Pour un être vivant, il y a se dit « imasu ». Un chat bouge tout seul, donc on change de verbe. C'est un point très important en japonais.","say":{"imasu":"います"},"words":[["parc","公園"],["petit mot du lieu","に"],["chat","猫"],["petit mot du sujet","が"],["il y a","います"]]}},{"fr":"Il y a beaucoup de monde à la gare.","tgt":"駅に人がたくさんいます。","ro":"Eki ni hito ga takusan imasu.","lit":"gare · [lieu] · gens · [sujet] · beaucoup · il y a, être vivant (poli)","note":{"lit":"gare, petit mot du lieu, gens, petit mot du sujet, beaucoup, il y a","text":"Beaucoup se dit « takusan ». Il se place juste avant le verbe. Les gens sont vivants, donc on prend le verbe des êtres vivants.","say":{"takusan":"たくさん"},"words":[["gare","駅"],["petit mot du lieu","に"],["gens","人"],["petit mot du sujet","が"],["beaucoup","たくさん"],["il y a","います"]]}},{"fr":"Est-ce qu'il y a une banque ?","tgt":"銀行はありますか？","ro":"Ginkō wa arimasu ka?","lit":"banque · [thème] · il y a, objet (poli) · [question]","note":{"lit":"banque, petit mot du thème, il y a, petit mot de question","text":"Banque se dit « ginkō ». Pour demander s'il y en a une, on ajoute le petit mot de question. Le thème montre ce qu'on cherche.","say":{"ginkō":"銀行"},"words":[["banque","銀行"],["petit mot du thème","は"],["il y a","あります"],["petit mot de question","か"]]}},{"fr":"Il n'y a pas de supermarché.","tgt":"スーパーはありません。","ro":"Sūpā wa arimasen.","lit":"supermarché · [thème] · il n'y a pas, objet (poli)","note":{"lit":"supermarché, petit mot du thème, il n'y a pas","text":"Il n'y a pas se dit « arimasen ». C'est la négation du verbe il y a. Supermarché se dit avec un mot raccourci de l'anglais.","say":{"arimasen":"ありません"},"words":[["supermarché","スーパー"],["petit mot du thème","は"],["il n'y a pas","ありません"]]}},{"fr":"Mon grand frère est à la maison.","tgt":"兄は家にいます。","ro":"Ani wa ie ni imasu.","lit":"grand frère · [thème] · maison · [lieu] · être là, être vivant (poli)","note":{"lit":"grand frère, petit mot du thème, maison, petit mot du lieu, être là","text":"Mon grand frère se dit « ani ». Pour sa propre famille, on utilise des mots simples. Le verbe des êtres vivants sert aussi pour être à la maison.","say":{"ani":"兄"},"words":[["grand frère","兄"],["petit mot du thème","は"],["maison","家"],["petit mot du lieu","に"],["être là","います"]]}},{"fr":"Il y a une télé dans ma chambre.","tgt":"部屋にテレビがあります。","ro":"Heya ni terebi ga arimasu.","lit":"chambre · [lieu] · télé · [sujet] · il y a, objet (poli)","note":{"lit":"chambre, petit mot du lieu, télé, petit mot du sujet, il y a","text":"On dit d'abord le lieu, puis la chose. Télé se dit « terebi ». La télé est un objet, donc le verbe est celui des objets.","say":{"terebi":"テレビ"},"words":[["chambre","部屋"],["petit mot du lieu","に"],["télé","テレビ"],["petit mot du sujet","が"],["il y a","あります"]]}},{"fr":"Il y a un policier au petit poste de police.","tgt":"交番に警察官がいます。","ro":"Kōban ni keisatsukan ga imasu.","lit":"poste de police · [lieu] · policier · [sujet] · il y a, être vivant (poli)","note":{"lit":"poste de police, petit mot du lieu, policier, petit mot du sujet, il y a","text":"Le petit poste de police du quartier se dit « kōban ». On en trouve partout à Tokyo. Le policier est vivant, d'où le verbe des êtres vivants.","say":{"kōban":"交番"},"words":[["poste de police","交番"],["petit mot du lieu","に"],["policier","警察官"],["petit mot du sujet","が"],["il y a","います"]]}},{"fr":"Il y a du lait dans le frigo.","tgt":"冷蔵庫に牛乳があります。","ro":"Reizōko ni gyūnyū ga arimasu.","lit":"frigo · [lieu] · lait · [sujet] · il y a, objet (poli)","note":{"lit":"frigo, petit mot du lieu, lait, petit mot du sujet, il y a","text":"Lait se dit « gyūnyū ». Le lieu se place en premier, avec son petit mot. Le lait est une chose, donc on garde le verbe des objets.","say":{"gyūnyū":"牛乳"},"words":[["frigo","冷蔵庫"],["petit mot du lieu","に"],["lait","牛乳"],["petit mot du sujet","が"],["il y a","あります"]]}}],"tip":{"title":"« Arimasu » et « imasu » : il y a, pour les objets et pour les êtres vivants","example":"Il y a un chat dans le parc. — 公園に猫が<b>います</b>。","body":"Le japonais a deux verbes pour dire il y a. « Arimasu » s'utilise pour les objets, les plantes et les lieux : « Konbini ga arimasu », il y a un konbini. « Imasu » s'utilise pour les êtres vivants qui bougent, les personnes et les animaux. « Kōen ni neko ga imasu » se dit littéralement : parc, dans, chat, sujet, il y a. Le schéma est toujours le même : le lieu avec « ni », puis la chose avec « ga », et le verbe à la fin. À la forme négative, on obtient « arimasen » et « imasen » : « Sūpā wa arimasen », il n'y a pas de supermarché. Ces mêmes verbes servent aussi à dire où se trouve quelqu'un : « Ani wa ie ni imasu », mon grand frère est à la maison. Astuce : si ça respire et bouge tout seul, c'est « imasu », sinon, c'est « arimasu ».","exampleRo":"Kōen ni neko ga imasu.","lit":"parc · [lieu] · chat · [sujet] · il y a, être vivant (poli)","say":{"Arimasu":"あります","imasu":"います","Konbini ga arimasu":"コンビニがあります","Imasu":"います","Kōen ni neko ga imasu":"公園に猫がいます","ni":"に","ga":"が","arimasen":"ありません","imasen":"いません","Sūpā wa arimasen":"スーパーはありません","Ani wa ie ni imasu":"兄は家にいます","arimasu":"あります"}}},{"title":"Il fait chaud, il fait froid","phrases":[{"fr":"Aujourd'hui, il fait très chaud.","tgt":"今日はとても暑いです。","ro":"Kyō wa totemo atsui desu.","lit":"aujourd'hui · [thème] · très · chaud · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, très, chaud, être","text":"Il fait chaud se dit « atsui ». Pas besoin de il fait, l'adjectif suffit. On ajoute le petit mot poli.","say":{"atsui":"暑い"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["très","とても"],["chaud","暑い"],["être","です"]]}},{"fr":"L'hiver à Tokyo est froid.","tgt":"東京の冬は寒いです。","ro":"Tōkyō no fuyu wa samui desu.","lit":"Tokyo · [de] · hiver · [thème] · froid · être (poli)","note":{"lit":"Tokyo, petit mot de liaison, hiver, petit mot du thème, froid, être","text":"Froid, pour le temps, se dit « samui ». Comme beaucoup d'adjectifs, il finit par le son i. L'hiver de Tokyo se dit Tokyo, liaison, hiver.","say":{"samui":"寒い"},"words":[["Tokyo","東京"],["petit mot de liaison","の"],["hiver","冬"],["petit mot du thème","は"],["froid","寒い"],["être","です"]]}},{"fr":"Le ciel est bleu.","tgt":"空が青いです。","ro":"Sora ga aoi desu.","lit":"ciel · [sujet] · bleu · être (poli)","note":{"lit":"ciel, petit mot du sujet, bleu, être","text":"Bleu se dit « aoi ». Au Japon, ce mot désigne aussi le vert des feux de circulation. Ciel se place avant, avec le petit mot du sujet.","say":{"aoi":"青い"},"words":[["ciel","空"],["petit mot du sujet","が"],["bleu","青い"],["être","です"]]}},{"fr":"Le vent est fort.","tgt":"風が強いです。","ro":"Kaze ga tsuyoi desu.","lit":"vent · [sujet] · fort · être (poli)","note":{"lit":"vent, petit mot du sujet, fort, être","text":"Fort se dit « tsuyoi ». Le vent prend le petit mot du sujet, car on décrit ce qu'on sent. Le petit mot poli ferme la phrase.","say":{"tsuyoi":"強い"},"words":[["vent","風"],["petit mot du sujet","が"],["fort","強い"],["être","です"]]}},{"fr":"Une glace bien froide, c'est délicieux.","tgt":"冷たいアイスはおいしいです。","ro":"Tsumetai aisu wa oishii desu.","lit":"froid · glace · [thème] · délicieux · être (poli)","note":{"lit":"froid, glace, petit mot du thème, délicieux, être","text":"Pour un objet froid au toucher, on dit « tsumetai ». Pour le temps qu'il fait, on dit un autre mot. Le japonais distingue bien les deux.","say":{"tsumetai":"冷たい"},"words":[["froid","冷たい"],["glace","アイス"],["petit mot du thème","は"],["délicieux","おいしい"],["être","です"]]}},{"fr":"Ce parapluie est cher.","tgt":"この傘は高いです。","ro":"Kono kasa wa takai desu.","lit":"ce · parapluie · [thème] · cher · être (poli)","note":{"lit":"ce, parapluie, petit mot du thème, cher, être","text":"Parapluie se dit « kasa ». Au Japon, on en achète souvent au konbini quand il pleut. Cher finit la phrase, avant le petit mot poli.","say":{"kasa":"傘"},"words":[["ce","この"],["parapluie","傘"],["petit mot du thème","は"],["cher","高い"],["être","です"]]}},{"fr":"Ce parapluie-là est bon marché.","tgt":"あの傘は安いです。","ro":"Ano kasa wa yasui desu.","lit":"ce là-bas · parapluie · [thème] · bon marché · être (poli)","note":{"lit":"ce là-bas, parapluie, petit mot du thème, bon marché, être","text":"Bon marché se dit « yasui ». C'est le contraire de cher. Ce là-bas, devant un nom, montre un objet éloigné.","say":{"yasui":"安い"},"words":[["ce là-bas","あの"],["parapluie","傘"],["petit mot du thème","は"],["bon marché","安い"],["être","です"]]}},{"fr":"Aujourd'hui, il ne fait pas froid.","tgt":"今日は寒くないです。","ro":"Kyō wa samukunai desu.","lit":"aujourd'hui · [thème] · pas froid · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, pas froid, être","text":"Pour nier un adjectif en i, on change la fin en « kunai ». Froid devient ainsi pas froid. On garde le petit mot poli à la fin.","say":{"kunai":"くない"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["pas froid","寒くない"],["être","です"]]}},{"fr":"En été, les journées sont longues.","tgt":"夏は日が長いです。","ro":"Natsu wa hi ga nagai desu.","lit":"été · [thème] · jour · [sujet] · long · être (poli)","note":{"lit":"été, petit mot du thème, jour, petit mot du sujet, long, être","text":"Cette phrase a un thème et un sujet. L'été est le thème, les journées sont le sujet. Long se dit « nagai ».","say":{"nagai":"長い"},"words":[["été","夏"],["petit mot du thème","は"],["jour","日"],["petit mot du sujet","が"],["long","長い"],["être","です"]]}},{"fr":"Qu'il fait lourd !","tgt":"蒸し暑いですね！","ro":"Mushiatsui desu ne!","lit":"chaud et humide · être (poli) · [n'est-ce pas]","note":{"lit":"lourd, être, petit mot d'accord","text":"Chaud et humide se dit « mushiatsui ». C'est le mot de l'été japonais. Le petit mot final invite l'autre à être d'accord.","say":{"mushiatsui":"蒸し暑い"},"words":[["lourd","蒸し暑い"],["être","です"],["petit mot d'accord","ね"]]}}],"tip":{"title":"Les adjectifs en « -i » : « takai, oishii »","example":"Une glace bien froide, c'est délicieux. — <b>冷たい</b>アイスは<b>おいしい</b>です。","body":"Beaucoup d'adjectifs japonais se terminent par « i » : « takai », cher, « yasui », bon marché, « oishii », délicieux, « samui », froid. On peut les placer devant un nom : « tsumetai aisu », une glace froide. On peut aussi les placer en fin de phrase, suivis de « desu » : « Kono kasa wa takai desu », ce parapluie est cher. « Tsumetai aisu wa oishii desu » se dit littéralement : froide glace, quant à elle, délicieuse, être. Leur particularité, c'est qu'ils se conjuguent un peu comme des verbes. Pour la négation, on remplace le « i » final par « kunai » : « samui » devient « samukunai », pas froid. Ainsi, « Kyō wa samukunai desu » veut dire : aujourd'hui, il ne fait pas froid. Astuce : un « i » à la fin, c'est le signe d'un adjectif qui sait se conjuguer tout seul.","exampleRo":"Tsumetai aisu wa oishii desu.","lit":"froid · glace · [thème] · délicieux · être (poli)","say":{"takai":"高い","yasui":"安い","oishii":"おいしい","samui":"寒い","tsumetai aisu":"冷たいアイス","desu":"です","Kono kasa wa takai desu":"この傘は高いです","Tsumetai aisu wa oishii desu":"冷たいアイスはおいしいです","samukunai":"寒くない","Kyō wa samukunai desu":"今日は寒くないです","takai, oishii":"高い、おいしい","kunai":"くない"}}},{"title":"Le jardin de Shinjuku","phrases":[{"fr":"Le jardin de Shinjuku est beau.","tgt":"新宿御苑はきれいです。","ro":"Shinjuku Gyoen wa kirei desu.","lit":"Shinjuku-jardin impérial · [thème] · beau · être (poli)","note":{"lit":"Shinjuku, jardin impérial, petit mot du thème, beau, être","text":"Beau ou propre se dit « kirei ». Il finit par un i, mais ce n'est pas un adjectif en i. Il ne change donc pas à la négation.","say":{"kirei":"きれい"},"words":[["Shinjuku","新宿"],["jardin impérial","御苑"],["petit mot du thème","は"],["beau","きれい"],["être","です"]]}},{"fr":"C'est un endroit calme.","tgt":"静かな所です。","ro":"Shizuka na tokoro desu.","lit":"calme-na · endroit · être (poli)","note":{"lit":"calme, petit mot de l'adjectif, endroit, être","text":"Devant un nom, certains adjectifs prennent le petit mot « na ». Il se place entre l'adjectif et le nom. À la fin d'une phrase, il disparaît.","say":{"na":"な"},"words":[["calme","静か"],["petit mot de l'adjectif","な"],["endroit","所"],["être","です"]]}},{"fr":"C'est un jardin très célèbre.","tgt":"とても有名な庭園です。","ro":"Totemo yūmei na teien desu.","lit":"très · célèbre-na · jardin · être (poli)","note":{"lit":"très, célèbre, petit mot de l'adjectif, jardin, être","text":"Jardin se dit « teien ». Célèbre prend le même petit mot que calme devant un nom. Très se place tout au début.","say":{"teien":"庭園"},"words":[["très","とても"],["célèbre","有名"],["petit mot de l'adjectif","な"],["jardin","庭園"],["être","です"]]}},{"fr":"Ici, ce n'est pas animé.","tgt":"ここはにぎやかじゃありません。","ro":"Koko wa nigiyaka ja arimasen.","lit":"ici · [thème] · animé · ne pas être (poli)","note":{"lit":"ici, petit mot du thème, animé, ne pas être","text":"Pour nier ces adjectifs, on fait comme avec un nom. On ajoute simplement « ja arimasen ».","say":{"ja arimasen":"じゃありません"},"words":[["ici","ここ"],["petit mot du thème","は"],["animé","にぎやか"],["ne pas être","じゃありません"]]}},{"fr":"Les allées sont très propres.","tgt":"道がとてもきれいです。","ro":"Michi ga totemo kirei desu.","lit":"chemin · [sujet] · très · propre · être (poli)","note":{"lit":"chemin, petit mot du sujet, très, propre, être","text":"Chemin ou rue se dit « michi ». Ici, propre et beau sont le même mot. Le contexte suffit pour comprendre.","say":{"michi":"道"},"words":[["chemin","道"],["petit mot du sujet","が"],["très","とても"],["propre","きれい"],["être","です"]]}},{"fr":"Aujourd'hui, je suis libre.","tgt":"今日は暇です。","ro":"Kyō wa hima desu.","lit":"aujourd'hui · [thème] · libre · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, libre, être","text":"Libre, sans rien à faire, se dit « hima ». On l'emploie pour dire qu'on a du temps. Il ne change pas de forme devant le petit mot poli.","say":{"hima":"暇"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["libre","暇"],["être","です"]]}},{"fr":"Le métro de Tokyo est pratique.","tgt":"東京の地下鉄は便利です。","ro":"Tōkyō no chikatetsu wa benri desu.","lit":"Tokyo · [de] · métro · [thème] · pratique · être (poli)","note":{"lit":"Tokyo, petit mot de liaison, métro, petit mot du thème, pratique, être","text":"Métro se dit « chikatetsu ». Mot à mot, c'est le fer sous la terre. Le métro de Tokyo est réputé pour sa ponctualité.","say":{"chikatetsu":"地下鉄"},"words":[["Tokyo","東京"],["petit mot de liaison","の"],["métro","地下鉄"],["petit mot du thème","は"],["pratique","便利"],["être","です"]]}},{"fr":"Mademoiselle Yamada est une personne gentille.","tgt":"山田さんは親切な人です。","ro":"Yamada-san wa shinsetsu na hito desu.","lit":"Yamada-mademoiselle · [thème] · gentil-na · personne · être (poli)","note":{"lit":"Yamada, mademoiselle, petit mot du thème, gentil, petit mot de l'adjectif, personne, être","text":"Gentil, serviable, se dit « shinsetsu ». Devant personne, il prend le petit mot des adjectifs. Une personne gentille, c'est gentil, petit mot, puis personne.","say":{"shinsetsu":"親切"},"words":[["Yamada","山田"],["mademoiselle","さん"],["petit mot du thème","は"],["gentil","親切"],["petit mot de l'adjectif","な"],["personne","人"],["être","です"]]}},{"fr":"Quel endroit magnifique !","tgt":"すてきな所ですね！","ro":"Suteki na tokoro desu ne!","lit":"magnifique-na · endroit · être (poli) · [n'est-ce pas]","note":{"lit":"magnifique, petit mot de l'adjectif, endroit, être, petit mot d'accord","text":"Magnifique ou charmant se dit « suteki ». Le petit mot final exprime l'émotion partagée. On l'entend souvent en visitant un beau lieu.","say":{"suteki":"すてき"},"words":[["magnifique","すてき"],["petit mot de l'adjectif","な"],["endroit","所"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Le japonais, c'est facile ?","tgt":"日本語は簡単ですか？","ro":"Nihongo wa kantan desu ka?","lit":"japonais · [thème] · facile · être (poli) · [question]","note":{"lit":"japonais, petit mot du thème, facile, être, petit mot de question","text":"La langue japonaise se dit « nihongo ». C'est le Japon suivi d'un mot qui veut dire langue. Facile vient ensuite, puis la question.","say":{"nihongo":"日本語"},"words":[["japonais","日本語"],["petit mot du thème","は"],["facile","簡単"],["être","です"],["petit mot de question","か"]]}}],"tip":{"title":"Les adjectifs en « -na » : « kirei, shizuka »","example":"C'est un endroit calme. — <b>静かな</b>所です。","body":"Il existe une deuxième famille d'adjectifs, les adjectifs en « na ». Devant un nom, ils prennent « na » : « Shizuka na tokoro desu » se dit littéralement : calme-na, endroit, être, donc c'est un endroit calme. En fin de phrase, on enlève le « na » et on met simplement « desu » : « Shinjuku Gyoen wa kirei desu », le jardin de Shinjuku est beau. Pour la négation, ils se comportent comme des noms, avec « ja arimasen » : « Koko wa nigiyaka ja arimasen », ici, ce n'est pas animé. Parmi les plus utiles : « kirei », beau ou propre, « shizuka », calme, « benri », pratique, « yūmei », célèbre, et « kantan », facile. Attention au piège : « kirei » se termine par un « i », mais c'est bien un adjectif en « na ». Astuce : traitez ces adjectifs comme des noms, avec juste un petit « na » quand ils se collent devant un autre nom.","exampleRo":"Shizuka na tokoro desu.","lit":"calme-na · endroit · être (poli)","say":{"na":"な","Shizuka na tokoro desu":"静かな所です","desu":"です","Shinjuku Gyoen wa kirei desu":"新宿御苑はきれいです","ja arimasen":"じゃありません","Koko wa nigiyaka ja arimasen":"ここはにぎやかじゃありません","kirei":"きれい","shizuka":"静か","benri":"便利","yūmei":"有名","kantan":"簡単","kirei, shizuka":"きれい、静か"}}},{"title":"Des vêtements à Shibuya","phrases":[{"fr":"Cette jupe est mignonne.","tgt":"このスカートはかわいいです。","ro":"Kono sukāto wa kawaii desu.","lit":"ce · jupe · [thème] · mignon · être (poli)","note":{"lit":"ce, jupe, petit mot du thème, mignon, être","text":"Mignon se dit « kawaii ». C'est l'un des mots les plus utilisés au Japon. On le dit pour les vêtements, les animaux ou les gens.","say":{"kawaii":"かわいい"},"words":[["ce","この"],["jupe","スカート"],["petit mot du thème","は"],["mignon","かわいい"],["être","です"]]}},{"fr":"Cette veste aussi est mignonne.","tgt":"このジャケットもかわいいです。","ro":"Kono jaketto mo kawaii desu.","lit":"ce · veste · [aussi] · mignon · être (poli)","note":{"lit":"ce, veste, aussi, mignon, être","text":"Aussi se dit « mo ». Il remplace le petit mot du thème. Cette veste aussi, c'est veste, puis ce petit mot.","say":{"mo":"も"},"words":[["ce","この"],["veste","ジャケット"],["aussi","も"],["mignon","かわいい"],["être","です"]]}},{"fr":"J'achète un pull.","tgt":"セーターを買います。","ro":"Sētā o kaimasu.","lit":"pull · [objet] · acheter (poli)","note":{"lit":"pull, petit mot du complément, acheter","text":"Pull se dit « sētā ». Il vient de l'anglais, avec des voyelles longues. Le verbe acheter vient à la fin.","say":{"sētā":"セーター"},"words":[["pull","セーター"],["petit mot du complément","を"],["acheter","買います"]]}},{"fr":"Moi aussi, j'en achète un.","tgt":"私も買います。","ro":"Watashi mo kaimasu.","lit":"moi · [aussi] · acheter (poli)","note":{"lit":"moi, aussi, acheter","text":"Moi aussi se dit « watashi mo ». Le petit mot aussi suit directement moi. Pas besoin de répéter le pull.","say":{"watashi mo":"私も"},"words":[["moi","私"],["aussi","も"],["acheter","買います"]]}},{"fr":"Je regarde aussi les chaussures.","tgt":"靴も見ます。","ro":"Kutsu mo mimasu.","lit":"chaussures · [aussi] · regarder (poli)","note":{"lit":"chaussures, aussi, regarder","text":"Chaussures se dit « kutsu ». Ici, aussi porte sur l'objet regardé. Il remplace le petit mot du complément.","say":{"kutsu":"靴"},"words":[["chaussures","靴"],["aussi","も"],["regarder","見ます"]]}},{"fr":"Vous l'avez aussi en bleu ?","tgt":"青もありますか？","ro":"Ao mo arimasu ka?","lit":"bleu · [aussi] · il y a, objet (poli) · [question]","note":{"lit":"bleu, aussi, il y a, petit mot de question","text":"Pour demander une couleur en magasin, on demande s'il y en a. On utilise le verbe des objets, « arimasu ». Bleu se dit ici sans le son i final, comme un nom.","say":{"arimasu":"あります"},"words":[["bleu","青"],["aussi","も"],["il y a","あります"],["petit mot de question","か"]]}},{"fr":"Oui, et aussi en noir.","tgt":"はい、黒もあります。","ro":"Hai, kuro mo arimasu.","lit":"oui · noir · [aussi] · il y a, objet (poli)","note":{"lit":"oui, noir, aussi, il y a","text":"Noir se dit « kuro ». Comme bleu, il s'emploie ici comme un nom. Le petit mot aussi le suit directement.","say":{"kuro":"黒"},"words":[["oui","はい"],["noir","黒"],["aussi","も"],["il y a","あります"]]}},{"fr":"Le manteau aussi est cher.","tgt":"コートも高いです。","ro":"Kōto mo takai desu.","lit":"manteau · [aussi] · cher · être (poli)","note":{"lit":"manteau, aussi, cher, être","text":"Manteau se dit « kōto ». Il vient de l'anglais. Le petit mot aussi remplace ici le thème.","say":{"kōto":"コート"},"words":[["manteau","コート"],["aussi","も"],["cher","高い"],["être","です"]]}},{"fr":"Où est la cabine d'essayage ?","tgt":"試着室はどこですか？","ro":"Shichakushitsu wa doko desu ka?","lit":"cabine d'essayage · [thème] · où · être (poli) · [question]","note":{"lit":"cabine d'essayage, petit mot du thème, où, être, petit mot de question","text":"La cabine d'essayage se dit « shichakushitsu ». C'est un long mot, mais très utile. On le dit avec où et le petit mot de question.","say":{"shichakushitsu":"試着室"},"words":[["cabine d'essayage","試着室"],["petit mot du thème","は"],["où","どこ"],["être","です"],["petit mot de question","か"]]}},{"fr":"Aujourd'hui aussi, il y a foule à Shibuya.","tgt":"今日も渋谷は人が多いです。","ro":"Kyō mo Shibuya wa hito ga ōi desu.","lit":"aujourd'hui · [aussi] · Shibuya · [thème] · gens · [sujet] · nombreux · être (poli)","note":{"lit":"aujourd'hui, aussi, Shibuya, petit mot du thème, gens, petit mot du sujet, nombreux, être","text":"Il y a foule se dit les gens sont nombreux. Nombreux se dit « ōi ». Aujourd'hui aussi, c'est aujourd'hui suivi du petit mot aussi.","say":{"ōi":"多い"},"words":[["aujourd'hui","今日"],["aussi","も"],["Shibuya","渋谷"],["petit mot du thème","は"],["gens","人"],["petit mot du sujet","が"],["nombreux","多い"],["être","です"]]}}],"tip":{"title":"« Mo » : aussi, moi aussi","example":"Cette veste aussi est mignonne. — このジャケット<b>も</b>かわいいです。","body":"La particule « mo » veut dire aussi. Elle se place juste après le mot concerné, et elle prend la place de « wa », de « ga » ou de « o ». « Kono sukāto wa kawaii desu », cette jupe est mignonne, devient pour la veste : « Kono jaketto mo kawaii desu », littéralement cette veste, aussi, mignonne, être. Pour dire moi aussi, il suffit de dire « watashi mo » : « Watashi mo kaimasu », moi aussi, j'achète. Et avec un objet : « Kutsu mo mimasu », je regarde aussi les chaussures. Attention à la place : en français, aussi peut voyager dans la phrase, mais en japonais, « mo » reste collé au mot qu'il concerne. Dans une phrase négative, il prend le sens de non plus. Astuce : « mo », c'est comme un petit et moi aussi qu'on accroche derrière un mot.","exampleRo":"Kono jaketto mo kawaii desu.","lit":"ce · veste · [aussi] · mignon · être (poli)","say":{"Mo":"も","mo":"も","wa":"わ","ga":"が","o":"を","Kono sukāto wa kawaii desu":"このスカートはかわいいです","Kono jaketto mo kawaii desu":"このジャケットもかわいいです","watashi mo":"私も","Watashi mo kaimasu":"私も買います","Kutsu mo mimasu":"靴も見ます"}}},{"title":"Une soirée à Shinjuku","phrases":[{"fr":"On mange des ramen ensemble ?","tgt":"一緒にラーメンを食べませんか？","ro":"Issho ni rāmen o tabemasen ka?","lit":"ensemble · ramen · [objet] · ne pas manger (poli) · [question]","note":{"lit":"ensemble, ramen, petit mot du complément, ne pas manger, petit mot de question","text":"Pour inviter, on pose une question négative. On ne mange pas ensemble, c'est en fait une proposition. La fin se dit « masen ka ».","say":{"masen ka":"ませんか"},"words":[["ensemble","一緒に"],["ramen","ラーメン"],["petit mot du complément","を"],["ne pas manger","食べません"],["petit mot de question","か"]]}},{"fr":"Bonne idée, allons-y !","tgt":"いいですね、行きましょう！","ro":"Ii desu ne, ikimashō!","lit":"bon · être (poli) · [n'est-ce pas] · allons-y (poli)","note":{"lit":"bon, être, petit mot d'accord, aller","text":"Pour dire allons, on change la fin du verbe en « mashō ». Allons-y se dit donc aller avec cette fin. Avant, bonne idée se dit mot à mot c'est bien.","say":{"mashō":"ましょう"},"words":[["bon","いい"],["être","です"],["petit mot d'accord","ね"],["aller","行きましょう"]]}},{"fr":"On se retrouve où ?","tgt":"どこで会いましょうか？","ro":"Doko de aimashō ka?","lit":"où · [lieu] · retrouvons-nous (poli) · [question]","note":{"lit":"où, petit mot du lieu, se retrouver, petit mot de question","text":"Avec la question, on demande l'avis de l'autre. Se retrouver se dit « aimashō ka ». C'est la manière douce de demander où.","say":{"aimashō ka":"会いましょうか"},"words":[["où","どこ"],["petit mot du lieu","で"],["se retrouver","会いましょう"],["petit mot de question","か"]]}},{"fr":"Retrouvons-nous à la sortie est de la gare de Shinjuku.","tgt":"新宿駅の東口で会いましょう。","ro":"Shinjuku-eki no higashiguchi de aimashō.","lit":"Shinjuku-gare · [de] · est-sortie · [lieu] · retrouvons-nous (poli)","note":{"lit":"gare de Shinjuku, petit mot de liaison, sortie est, petit mot du lieu, se retrouver","text":"Sortie est se dit « higashiguchi ». C'est est suivi de sortie. Les grandes gares ont toujours plusieurs sorties.","say":{"higashiguchi":"東口"},"words":[["gare de Shinjuku","新宿駅"],["petit mot de liaison","の"],["sortie est","東口"],["petit mot du lieu","で"],["se retrouver","会いましょう"]]}},{"fr":"Sept heures, ça vous va ?","tgt":"七時はどうですか？","ro":"Shichiji wa dō desu ka?","lit":"sept-heure · [thème] · comment · être (poli) · [question]","note":{"lit":"sept heures, petit mot du thème, comment, être, petit mot de question","text":"Pour proposer, on dit « dō desu ka ». Mot à mot, c'est comment est-ce. On met l'heure proposée en thème juste avant.","say":{"dō desu ka":"どうですか"},"words":[["sept heures","七時"],["petit mot du thème","は"],["comment","どう"],["être","です"],["petit mot de question","か"]]}},{"fr":"Ensuite, on va à l'observatoire de la mairie ?","tgt":"それから、都庁の展望台に行きませんか？","ro":"Sorekara, Tochō no tenbōdai ni ikimasen ka?","lit":"ensuite · mairie de Tokyo · [de] · observatoire · [direction] · ne pas aller (poli) · [question]","note":{"lit":"ensuite, mairie de Tokyo, petit mot de liaison, observatoire, vers, ne pas aller, petit mot de question","text":"Observatoire se dit « tenbōdai ». Celui de la mairie de Tokyo est gratuit. Encore une fois, on invite avec une question négative.","say":{"tenbōdai":"展望台"},"words":[["ensuite","それから"],["mairie de Tokyo","都庁"],["petit mot de liaison","の"],["observatoire","展望台"],["vers","に"],["ne pas aller","行きません"],["petit mot de question","か"]]}},{"fr":"Prenons un taxi.","tgt":"タクシーに乗りましょう。","ro":"Takushī ni norimashō.","lit":"taxi · [dans] · montons (poli)","note":{"lit":"taxi, dans, monter","text":"Prenons se dit ici montons. La fin du verbe propose de faire ensemble. Monter devient « norimashō ».","say":{"norimashō":"乗りましょう"},"words":[["taxi","タクシー"],["dans","に"],["monter","乗りましょう"]]}},{"fr":"On fait une photo ensemble ?","tgt":"一緒に写真を撮りませんか？","ro":"Issho ni shashin o torimasen ka?","lit":"ensemble · photo · [objet] · ne pas prendre (poli) · [question]","note":{"lit":"ensemble, photo, petit mot du complément, ne pas prendre, petit mot de question","text":"Ensemble se dit « issho ni ». Il se place en tout début de phrase. On propose ensuite la photo avec une question négative.","say":{"issho ni":"一緒に"},"words":[["ensemble","一緒に"],["photo","写真"],["petit mot du complément","を"],["ne pas prendre","撮りません"],["petit mot de question","か"]]}},{"fr":"Bon, on rentre ?","tgt":"そろそろ帰りましょうか？","ro":"Sorosoro kaerimashō ka?","lit":"bientôt · rentrons (poli) · [question]","note":{"lit":"bientôt, rentrer, petit mot de question","text":"Il est temps se dit « sorosoro ». On l'emploie pour proposer de partir sans brusquer. C'est très japonais.","say":{"sorosoro":"そろそろ"},"words":[["bientôt","そろそろ"],["rentrer","帰りましょう"],["petit mot de question","か"]]}},{"fr":"Retournons-y la semaine prochaine.","tgt":"来週もまた行きましょう。","ro":"Raishū mo mata ikimashō.","lit":"semaine prochaine · [aussi] · encore · allons-y (poli)","note":{"lit":"semaine prochaine, aussi, encore, aller","text":"La semaine prochaine se dit « raishū ». Encore se dit juste après. Le verbe propose d'y aller ensemble.","say":{"raishū":"来週"},"words":[["semaine prochaine","来週"],["aussi","も"],["encore","また"],["aller","行きましょう"]]}}],"tip":{"title":"« -mashō » et « -masen ka » : proposer et inviter","example":"On mange des ramen ensemble ? — 一緒にラーメンを<b>食べませんか</b>？","body":"Pour inviter quelqu'un poliment, le japonais utilise une question négative : « tabemasen ka », littéralement, ne mangez-vous pas ? « Issho ni rāmen o tabemasen ka » se dit mot à mot : ensemble, ramen, objet, ne pas manger, question ? C'est une manière douce de proposer, qui laisse à l'autre la liberté de refuser. Pour répondre avec enthousiasme, ou pour proposer directement, on utilise « mashō », qui veut dire faisons, ou allons-y : « Ikimashō », allons-y, « Tabemashō », mangeons. On peut aussi y ajouter « ka » : « Kaerimashō ka », et si on rentrait ? En résumé, « masen ka » invite l'autre, et « mashō » lance l'action ensemble. Astuce : pour accepter une invitation, « Ii desu ne, ikimashō », bonne idée, allons-y, marche presque toujours.","exampleRo":"Issho ni rāmen o tabemasen ka?","lit":"ensemble · ramen · [objet] · ne pas manger (poli) · [question]","say":{"tabemasen ka":"食べませんか","Issho ni rāmen o tabemasen ka":"一緒にラーメンを食べませんか","mashō":"ましょう","Ikimashō":"行きましょう","Tabemashō":"食べましょう","ka":"か","Kaerimashō ka":"帰りましょうか","masen ka":"ませんか","Ii desu ne, ikimashō":"いいですね、行きましょう","-mashō":"ましょう","-masen ka":"ませんか"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Merci beaucoup !","tgt":"ありがとうございます！","ro":"Arigatō gozaimasu!","lit":"merci (poli)","note":{"lit":"merci, poliment","text":"Merci, poliment, se dit « arigatō gozaimasu ». Entre amis, on dit juste le premier mot. Avec un inconnu, on dit les deux.","say":{"arigatō gozaimasu":"ありがとうございます"},"words":[["merci","ありがとう"],["poliment","ございます"]]}},{"fr":"Le premier module se termine.","tgt":"最初のモジュールはこれで終わりです。","ro":"Saisho no mojūru wa kore de owari desu.","lit":"premier · [de] · module · [thème] · ceci · [moyen] · fin · être (poli)","note":{"lit":"premier, petit mot de liaison, module, petit mot du thème, ceci, petit mot du moyen, fin, être","text":"Fin se dit « owari ». Avec ceci et le petit mot du moyen, on dit avec ceci, c'est fini. C'est une formule pour terminer.","say":{"owari":"終わり"},"words":[["premier","最初"],["petit mot de liaison","の"],["module","モジュール"],["petit mot du thème","は"],["ceci","これ"],["petit mot du moyen","で"],["fin","終わり"],["être","です"]]}},{"fr":"Le japonais est difficile, mais amusant.","tgt":"日本語は難しいですが、楽しいです。","ro":"Nihongo wa muzukashii desu ga, tanoshii desu.","lit":"japonais · [thème] · difficile · être (poli) · mais · amusant · être (poli)","note":{"lit":"japonais, petit mot du thème, difficile, être, mais, amusant, être","text":"Pour relier deux idées opposées, on dit après la première « ga ». Ce mot veut dire mais. Attention, il ressemble au petit mot du sujet.","say":{"ga":"が"},"words":[["japonais","日本語"],["petit mot du thème","は"],["difficile","難しい"],["être","です"],["mais","が"],["amusant","楽しい"],["être","です"]]}},{"fr":"Excusez-moi, encore une fois, s'il vous plaît.","tgt":"すみません、もう一度お願いします。","ro":"Sumimasen, mō ichido onegaishimasu.","lit":"excusez-moi · encore · une fois · je vous le demande (poli)","note":{"lit":"excusez-moi, encore, une fois, je vous le demande","text":"Encore une fois se dit « mō ichido ». C'est la phrase à connaître quand on n'a pas compris. On ajoute s'il vous plaît à la fin.","say":{"mō ichido":"もう一度"},"words":[["excusez-moi","すみません"],["encore","もう"],["une fois","一度"],["je vous le demande","お願いします"]]}},{"fr":"Je comprends un peu le japonais.","tgt":"日本語が少しわかります。","ro":"Nihongo ga sukoshi wakarimasu.","lit":"japonais · [sujet] · un peu · comprendre (poli)","note":{"lit":"japonais, petit mot du sujet, un peu, comprendre","text":"Avec comprendre, ce qu'on comprend prend le petit mot du sujet. Un peu se dit « sukoshi ». C'est la phrase modeste idéale.","say":{"sukoshi":"少し"},"words":[["japonais","日本語"],["petit mot du sujet","が"],["un peu","少し"],["comprendre","わかります"]]}},{"fr":"Les particules sont importantes.","tgt":"助詞は大切です。","ro":"Joshi wa taisetsu desu.","lit":"particules · [thème] · important · être (poli)","note":{"lit":"particules, petit mot du thème, important, être","text":"Important se dit « taisetsu ». Les particules sont ces petits mots après les noms. Ils indiquent le rôle de chaque mot.","say":{"taisetsu":"大切"},"words":[["particules","助詞"],["petit mot du thème","は"],["important","大切"],["être","です"]]}},{"fr":"« Sumimasen » est un mot très pratique.","tgt":"「すみません」はとても便利な言葉です。","ro":"« Sumimasen » wa totemo benri na kotoba desu.","lit":"« sumimasen » · [thème] · très · pratique-na · mot · être (poli)","note":{"lit":"pardon, petit mot du thème, très, pratique, petit mot de l'adjectif, mot, être","text":"Mot se dit « kotoba ». Le mot pardon sert à s'excuser, à remercier et à appeler. C'est vraiment pratique.","say":{"kotoba":"言葉"},"words":[["pardon","すみません"],["petit mot du thème","は"],["très","とても"],["pratique","便利"],["petit mot de l'adjectif","な"],["mot","言葉"],["être","です"]]}},{"fr":"Un café, s'il vous plaît.","tgt":"コーヒーをお願いします。","ro":"Kōhī o onegaishimasu.","lit":"café · [objet] · je vous le demande (poli)","note":{"lit":"café, petit mot du complément, je vous le demande","text":"Pour commander, on dit la chose, puis « onegaishimasu ». Le café prend le petit mot du complément. C'est simple et poli.","say":{"onegaishimasu":"お願いします"},"words":[["café","コーヒー"],["petit mot du complément","を"],["je vous le demande","お願いします"]]}},{"fr":"Le prochain module, c'est le voyage.","tgt":"次のモジュールは旅行です。","ro":"Tsugi no mojūru wa ryokō desu.","lit":"suivant · [de] · module · [thème] · voyage · être (poli)","note":{"lit":"suivant, petit mot de liaison, module, petit mot du thème, voyage, être","text":"Voyage se dit « ryokō ». Suivant se place devant le nom, avec le petit mot de liaison. On l'a déjà entendu avec le train.","say":{"ryokō":"旅行"},"words":[["suivant","次"],["petit mot de liaison","の"],["module","モジュール"],["petit mot du thème","は"],["voyage","旅行"],["être","です"]]}},{"fr":"Merci pour tout, et à la prochaine !","tgt":"どうもありがとうございました。また会いましょう！","ro":"Dōmo arigatō gozaimashita. Mata aimashō!","lit":"vraiment · merci (poli, pour ce qui a été fait) · encore · retrouvons-nous (poli)","note":{"lit":"vraiment, merci, poliment, encore, se retrouver","text":"Pour remercier de ce qui est fini, on met le merci au passé. On dit alors « arigatō gozaimashita ». À la prochaine se dit mot à mot retrouvons-nous encore.","say":{"arigatō gozaimashita":"ありがとうございました"},"words":[["vraiment","どうも"],["merci","ありがとう"],["poliment","ございました"],["encore","また"],["se retrouver","会いましょう"]]}}],"tip":{"title":"Les mots magiques : « sumimasen, onegaishimasu, arigatō gozaimasu »","example":"Excusez-moi, encore une fois, s'il vous plaît. — <b>すみません</b>、もう一度<b>お願いします</b>。","body":"Trois expressions vous ouvriront presque toutes les portes au Japon. « Sumimasen » veut dire excusez-moi, mais aussi pardon, et même merci quand on a dérangé quelqu'un. On l'utilise pour appeler un serveur ou pour se frayer un chemin dans le métro. « Onegaishimasu » veut dire littéralement : je vous fais humblement une demande. On le place après ce qu'on souhaite : « Kōhī o onegaishimasu », un café, s'il vous plaît. « Sumimasen, mō ichido onegaishimasu » se dit mot à mot : excusez-moi, encore, une fois, je vous le demande. Enfin, « arigatō gozaimasu » est le merci poli, souvent accompagné d'une petite inclinaison de la tête. Avec ces trois expressions et tout ce que vous avez appris dans ce module, vous pouvez déjà vous débrouiller à Tokyo, bravo ! Astuce : dans le doute, commencez par « sumimasen », vous ne vous tromperez presque jamais.","exampleRo":"Sumimasen, mō ichido onegaishimasu.","lit":"excusez-moi · encore · une fois · je vous le demande (poli)","say":{"Sumimasen":"すみません","Onegaishimasu":"お願いします","Kōhī o onegaishimasu":"コーヒーをお願いします","Sumimasen, mō ichido onegaishimasu":"すみません、もう一度お願いします","arigatō gozaimasu":"ありがとうございます","sumimasen":"すみません","sumimasen, onegaishimasu, arigatō gozaimasu":"すみません、お願いします、ありがとうございます"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus au Japon.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport du Kansai","phrases":[{"fr":"Votre passeport, s'il vous plaît.","tgt":"パスポートをお願いします。","ro":"Pasupōto o onegaishimasu.","lit":"passeport · [objet] · s'il vous plaît (poli)","note":{"lit":"passeport, petit mot du complément, je vous le demande","text":"Passeport se dit « pasupōto ». C'est l'anglais adapté aux sons japonais. Au contrôle, on entend cette phrase en premier.","say":{"pasupōto":"パスポート"},"words":[["passeport","パスポート"],["petit mot du complément","を"],["je vous le demande","お願いします"]]}},{"fr":"Oui, le voici.","tgt":"はい、どうぞ。","ro":"Hai, dōzo.","lit":"oui · je vous en prie","note":{"lit":"oui, je vous en prie","text":"Pour tendre quelque chose, on dit « dōzo ». Ce mot veut dire tenez, ou je vous en prie. On l'entend aussi pour laisser passer quelqu'un.","say":{"dōzo":"どうぞ"},"words":[["oui","はい"],["je vous en prie","どうぞ"]]}},{"fr":"Vous venez pour du tourisme ?","tgt":"観光ですか？","ro":"Kankō desu ka?","lit":"tourisme · être (poli) · [question]","note":{"lit":"tourisme, être, petit mot de question","text":"Tourisme se dit « kankō ». Pas besoin de dire vous venez pour. Le mot seul, avec la question, suffit.","say":{"kankō":"観光"},"words":[["tourisme","観光"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, c'est pour du tourisme.","tgt":"はい、観光です。","ro":"Hai, kankō desu.","lit":"oui · tourisme · être (poli)","note":{"lit":"oui, tourisme, être","text":"Pour répondre, on reprend simplement le mot de la question. On enlève seulement le petit mot de question. La réponse se termine par « desu ».","say":{"desu":"です"},"words":[["oui","はい"],["tourisme","観光"],["être","です"]]}},{"fr":"Je reste dix jours au Japon.","tgt":"日本に十日間います。","ro":"Nihon ni tōkakan imasu.","lit":"Japon · [lieu] · dix-jours (durée) · être (vivants, poli)","note":{"lit":"Japon, petit mot du lieu, dix jours, rester","text":"Japon se dit « nihon ». Pour rester quelque part, on emploie le verbe des êtres vivants. La durée se place juste avant le verbe.","say":{"nihon":"日本"},"words":[["Japon","日本"],["petit mot du lieu","に"],["dix jours","十日間"],["rester","います"]]}},{"fr":"Les bagages sont là-bas.","tgt":"荷物はあそこです。","ro":"Nimotsu wa asoko desu.","lit":"bagages · [thème] · là-bas · être (poli)","note":{"lit":"bagages, petit mot du thème, là-bas, être","text":"Là-bas, loin de nous deux, se dit « asoko ». Il va avec ici et là, qu'on a déjà entendus. On l'emploie pour montrer un endroit.","say":{"asoko":"あそこ"},"words":[["bagages","荷物"],["petit mot du thème","は"],["là-bas","あそこ"],["être","です"]]}},{"fr":"Ma valise est rouge.","tgt":"私のスーツケースは赤いです。","ro":"Watashi no sūtsukēsu wa akai desu.","lit":"moi · [possessif] · valise · [thème] · rouge · être (poli)","note":{"lit":"moi, petit mot du possessif, valise, petit mot du thème, rouge, être","text":"Rouge se dit « akai ». C'est un adjectif en i, comme bleu. Il se place à la fin, avant le petit mot poli.","say":{"akai":"赤い"},"words":[["moi","私"],["petit mot du possessif","の"],["valise","スーツケース"],["petit mot du thème","は"],["rouge","赤い"],["être","です"]]}},{"fr":"Je vais à Kyoto en train.","tgt":"電車で京都へ行きます。","ro":"Densha de Kyōto e ikimasu.","lit":"train · [moyen] · Kyoto · [direction] · aller (poli)","note":{"lit":"train, petit mot du moyen, Kyoto, vers, aller","text":"Le moyen vient d'abord, puis la destination. Vers Kyoto se dit « Kyōto e ». Le verbe aller ferme la phrase.","say":{"Kyōto e":"京都へ"},"words":[["train","電車"],["petit mot du moyen","で"],["Kyoto","京都"],["vers","へ"],["aller","行きます"]]}},{"fr":"Le train part à trois heures.","tgt":"電車は三時に出ます。","ro":"Densha wa sanji ni demasu.","lit":"train · [thème] · trois-heures · [moment] · partir (poli)","note":{"lit":"train, petit mot du thème, trois heures, petit mot du moment, partir","text":"Trois heures se dit « sanji ». Le train est le thème de la phrase. Partir vient à la fin.","say":{"sanji":"三時"},"words":[["train","電車"],["petit mot du thème","は"],["trois heures","三時"],["petit mot du moment","に"],["partir","出ます"]]}},{"fr":"Bienvenue au Japon !","tgt":"日本へようこそ！","ro":"Nihon e yōkoso!","lit":"Japon · [direction] · bienvenue","note":{"lit":"Japon, vers, bienvenue","text":"Bienvenue se dit « yōkoso ». On dit d'abord le lieu, avec le petit mot vers. Mot à mot, c'est vers le Japon, bienvenue.","say":{"yōkoso":"ようこそ"},"words":[["Japon","日本"],["vers","へ"],["bienvenue","ようこそ"]]}}]},{"title":"Dans le train pour Kyoto","phrases":[{"fr":"Ce train va à Kyoto ?","tgt":"この電車は京都へ行きますか？","ro":"Kono densha wa Kyōto e ikimasu ka?","lit":"ce · train · [thème] · Kyoto · [direction] · aller (poli) · [question]","note":{"lit":"ce, train, petit mot du thème, Kyoto, vers, aller, petit mot de question","text":"Pour vérifier la destination, on ajoute juste le petit mot de question. Ce train se dit « kono densha ».","say":{"kono densha":"この電車"},"words":[["ce","この"],["train","電車"],["petit mot du thème","は"],["Kyoto","京都"],["vers","へ"],["aller","行きます"],["petit mot de question","か"]]}},{"fr":"Oui, il y va.","tgt":"はい、行きます。","ro":"Hai, ikimasu.","lit":"oui · aller (poli)","note":{"lit":"oui, aller","text":"Pour répondre oui, on répète simplement le verbe. On ne dit pas il y va. Le verbe seul suffit, « ikimasu ».","say":{"ikimasu":"行きます"},"words":[["oui","はい"],["aller","行きます"]]}},{"fr":"Je peux m'asseoir ici ?","tgt":"この席、いいですか？","ro":"Kono seki, ii desu ka?","lit":"ce · siège · bien · être (poli) · [question]","note":{"lit":"ce, siège, bien, être, petit mot de question","text":"Pour demander la permission, on dit « ii desu ka ». Mot à mot, c'est c'est bien. On montre le siège en le disant juste avant.","say":{"ii desu ka":"いいですか"},"words":[["ce","この"],["siège","席"],["bien","いい"],["être","です"],["petit mot de question","か"]]}},{"fr":"Bien sûr, allez-y.","tgt":"ええ、どうぞ。","ro":"Ee, dōzo.","lit":"oui · je vous en prie","note":{"lit":"oui, je vous en prie","text":"À l'oral, oui se dit aussi « ee ». C'est un peu moins formel que l'autre mot. Puis on ajoute je vous en prie.","say":{"ee":"ええ"},"words":[["oui","ええ"],["je vous en prie","どうぞ"]]}},{"fr":"Le café est à trois cents yens.","tgt":"コーヒーは三百円です。","ro":"Kōhī wa sanbyaku en desu.","lit":"café · [thème] · trois-cents-yens · être (poli)","note":{"lit":"café, petit mot du thème, trois cents, yen, être","text":"Trois cents se dit « sanbyaku ». Le mot cent change de son après trois. C'est une petite irrégularité à retenir.","say":{"sanbyaku":"三百"},"words":[["café","コーヒー"],["petit mot du thème","は"],["trois cents","三百"],["yen","円"],["être","です"]]}},{"fr":"Un thé vert, s'il vous plaît.","tgt":"お茶をお願いします。","ro":"Ocha o onegaishimasu.","lit":"honorable-thé · [objet] · s'il vous plaît (poli)","note":{"lit":"thé, petit mot du complément, je vous le demande","text":"Pour le thé vert, on dit simplement « ocha ». Le petit son du début le rend plus poli. On commande avec je vous le demande.","say":{"ocha":"お茶"},"words":[["thé","お茶"],["petit mot du complément","を"],["je vous le demande","お願いします"]]}},{"fr":"Les kanji sont difficiles.","tgt":"漢字は難しいです。","ro":"Kanji wa muzukashii desu.","lit":"kanji · [thème] · difficile · être (poli)","note":{"lit":"kanji, petit mot du thème, difficile, être","text":"Difficile se dit « muzukashii ». C'est un adjectif en i. Il se termine par le petit mot poli.","say":{"muzukashii":"難しい"},"words":[["kanji","漢字"],["petit mot du thème","は"],["difficile","難しい"],["être","です"]]}},{"fr":"Mais les hiragana sont faciles.","tgt":"でも、ひらがなは易しいです。","ro":"Demo, hiragana wa yasashii desu.","lit":"mais · hiragana · [thème] · facile · être (poli)","note":{"lit":"mais, hiragana, petit mot du thème, facile, être","text":"Mais, en début de phrase, se dit « demo ». Il marque une opposition avec la phrase d'avant. Ici, on oppose difficile et facile.","say":{"demo":"でも"},"words":[["mais","でも"],["hiragana","ひらがな"],["petit mot du thème","は"],["facile","易しい"],["être","です"]]}},{"fr":"La prochaine gare, c'est Kyoto.","tgt":"次は京都です。","ro":"Tsugi wa Kyōto desu.","lit":"prochain · [thème] · Kyoto · être (poli)","note":{"lit":"prochain, petit mot du thème, Kyoto, être","text":"Dans le train, on entend souvent cette annonce. Prochain se dit « tsugi ». Ici, il suffit à dire la prochaine gare.","say":{"tsugi":"次"},"words":[["prochain","次"],["petit mot du thème","は"],["Kyoto","京都"],["être","です"]]}},{"fr":"On descend ici ?","tgt":"ここで降りますか？","ro":"Koko de orimasu ka?","lit":"ici · [lieu] · descendre (poli) · [question]","note":{"lit":"ici, petit mot du lieu, descendre, petit mot de question","text":"Ici, comme lieu d'une action, se dit « koko de ». Descendre vient juste après. Puis le petit mot de question.","say":{"koko de":"ここで"},"words":[["ici","ここ"],["petit mot du lieu","で"],["descendre","降ります"],["petit mot de question","か"]]}}],"tip":{"title":"Trois écritures : hiragana, katakana et kanji","example":"Le café est à trois cents yens. — <b>コーヒー</b>は<b>三百円</b>です。","body":"Le japonais mélange trois écritures dans une même phrase, et c'est moins effrayant qu'il n'y paraît. Les hiragana, aux formes arrondies, notent des syllabes et servent surtout aux petits mots de grammaire, comme « wa » (thème) ou « desu » (être, poli). Les katakana, plus anguleux, notent les mêmes sons mais servent aux mots venus de l'étranger, comme « kōhī » (café), « basu » (bus) ou « pasupōto » (passeport). Les kanji, eux, sont des caractères qui portent un sens : un seul signe peut vouloir dire montagne, gare ou argent. Dans « Kōhī wa sanbyaku en desu », les trois se côtoient : « kōhī » en katakana, « sanbyaku en » (trois cents yens) en kanji, « wa » et « desu » en hiragana. Mot à mot, cela donne : café, thème, trois cents yens, être poli. Pour parler, vous n'avez pas besoin de tout lire : le rōmaji est là pour vous accompagner. Une astuce pour retenir : hiragana tout rond comme un mot de chez soi, katakana pointu comme un mot venu d'ailleurs, et kanji comme une petite image.","exampleRo":"Kōhī wa sanbyaku en desu.","lit":"café · [thème] · trois-cents-yens · être (poli)","say":{"wa":"わ","desu":"です","kōhī":"コーヒー","basu":"バス","pasupōto":"パスポート","Kōhī wa sanbyaku en desu":"コーヒーは三百円です","sanbyaku en":"三百円"}}},{"title":"À la gare de Kyoto","phrases":[{"fr":"La gare de Kyoto est très grande.","tgt":"京都駅はとても大きいです。","ro":"Kyōto eki wa totemo ōkii desu.","lit":"Kyoto-gare · [thème] · très · grand · être (poli)","note":{"lit":"gare de Kyoto, petit mot du thème, très, grand, être","text":"Grand se dit « ōkii ». On commence par un o long. La gare de Kyoto, c'est Kyoto suivi du mot gare.","say":{"ōkii":"大きい"},"words":[["gare de Kyoto","京都駅"],["petit mot du thème","は"],["très","とても"],["grand","大きい"],["être","です"]]}},{"fr":"Il y a énormément de gens.","tgt":"人がたくさんいます。","ro":"Hito ga takusan imasu.","lit":"gens · [sujet] · beaucoup · il y a (vivants, poli)","note":{"lit":"gens, petit mot du sujet, beaucoup, il y a","text":"Gens ou personne se dit « hito ». Comme ce sont des êtres vivants, on prend le verbe des êtres vivants. Beaucoup se place juste avant.","say":{"hito":"人"},"words":[["gens","人"],["petit mot du sujet","が"],["beaucoup","たくさん"],["il y a","います"]]}},{"fr":"Les casiers à bagages sont au sous-sol.","tgt":"コインロッカーは地下にあります。","ro":"Koin rokkā wa chika ni arimasu.","lit":"casier-à-pièces · [thème] · sous-sol · [lieu] · se trouver (objets, poli)","note":{"lit":"casiers, petit mot du thème, sous-sol, petit mot du lieu, se trouver","text":"Sous-sol se dit « chika ». Pour dire où se trouve un objet, on emploie le verbe des objets. Le lieu se place juste avant.","say":{"chika":"地下"},"words":[["casiers","コインロッカー"],["petit mot du thème","は"],["sous-sol","地下"],["petit mot du lieu","に"],["se trouver","あります"]]}},{"fr":"Je laisse ma valise ici.","tgt":"ここにスーツケースを置きます。","ro":"Koko ni sūtsukēsu o okimasu.","lit":"ici · [lieu] · valise · [objet] · poser (poli)","note":{"lit":"ici, petit mot du lieu, valise, petit mot du complément, poser","text":"Poser ou laisser se dit « okimasu ». L'endroit où l'on pose vient en premier. Puis l'objet, avec le petit mot du complément.","say":{"okimasu":"置きます"},"words":[["ici","ここ"],["petit mot du lieu","に"],["valise","スーツケース"],["petit mot du complément","を"],["poser","置きます"]]}},{"fr":"Ça coûte sept cents yens.","tgt":"七百円です。","ro":"Nanahyaku en desu.","lit":"sept-cents-yens · être (poli)","note":{"lit":"sept cents, yen, être","text":"Sept cents se dit « nanahyaku ». Sept a deux façons de se dire. Devant cent, on prend la plus longue.","say":{"nanahyaku":"七百"},"words":[["sept cents","七百"],["yen","円"],["être","です"]]}},{"fr":"Le bus cent un va au Kinkaku-ji.","tgt":"百一番のバスは金閣寺へ行きます。","ro":"Hyakuichi ban no basu wa Kinkakuji e ikimasu.","lit":"numéro-cent-un · [possessif] · bus · [thème] · Kinkaku-ji · [direction] · aller (poli)","note":{"lit":"cent un, numéro, petit mot de liaison, bus, petit mot du thème, Kinkaku-ji, vers, aller","text":"Après le nombre, numéro se dit « ban ». Le bus cent un, c'est numéro cent un, liaison, bus.","say":{"ban":"番"},"words":[["cent un","百一"],["numéro","番"],["petit mot de liaison","の"],["bus","バス"],["petit mot du thème","は"],["Kinkaku-ji","金閣寺"],["vers","へ"],["aller","行きます"]]}},{"fr":"On prend le bus ?","tgt":"バスに乗りましょうか？","ro":"Basu ni norimashō ka?","lit":"bus · [dans] · monter (proposition) · [question]","note":{"lit":"bus, dans, monter, petit mot de question","text":"Avec la question à la fin, la proposition devient plus douce. On demande l'avis de l'autre. Prenons se dit ici « norimashō ka ».","say":{"norimashō ka":"乗りましょうか"},"words":[["bus","バス"],["dans","に"],["monter","乗りましょう"],["petit mot de question","か"]]}},{"fr":"Non, allons-y en métro.","tgt":"いいえ、地下鉄で行きましょう。","ro":"Iie, chikatetsu de ikimashō.","lit":"non · métro · [moyen] · aller (proposition)","note":{"lit":"non, métro, petit mot du moyen, aller","text":"Allons-y se dit « ikimashō ». Ici, on propose autre chose, poliment. Le métro prend le petit mot du moyen.","say":{"ikimashō":"行きましょう"},"words":[["non","いいえ"],["métro","地下鉄"],["petit mot du moyen","で"],["aller","行きましょう"]]}},{"fr":"Le métro est pratique.","tgt":"地下鉄は便利です。","ro":"Chikatetsu wa benri desu.","lit":"métro · [thème] · pratique · être (poli)","note":{"lit":"métro, petit mot du thème, pratique, être","text":"Pratique se dit « benri ». Il ne change pas de forme. On peut le dire de tout ce qui facilite la vie.","say":{"benri":"便利"},"words":[["métro","地下鉄"],["petit mot du thème","は"],["pratique","便利"],["être","です"]]}},{"fr":"Allez, on y va !","tgt":"行きましょう！","ro":"Ikimashō!","lit":"aller (proposition)","note":{"lit":"aller","text":"Pour lancer le départ, on dit juste « ikimashō ». Pas besoin de sujet. C'est l'équivalent de allez, on y va.","say":{"ikimashō":"行きましょう"},"words":[["aller","行きましょう"]]}}]},{"title":"Au guichet des billets","phrases":[{"fr":"Excusez-moi, un billet, s'il vous plaît.","tgt":"すみません、切符をください。","ro":"Sumimasen, kippu o kudasai.","lit":"excusez-moi · billet · [objet] · donnez-moi","note":{"lit":"excusez-moi, billet, petit mot du complément, donnez-moi","text":"Pour demander une chose, on dit l'objet, puis « kudasai ». C'est donnez-moi, de façon polie. Excusez-moi, au début, sert à attirer l'attention.","say":{"kudasai":"ください"},"words":[["excusez-moi","すみません"],["billet","切符"],["petit mot du complément","を"],["donnez-moi","ください"]]}},{"fr":"Deux billets pour Nara, s'il vous plaît.","tgt":"奈良の切符を二枚ください。","ro":"Nara no kippu o nimai kudasai.","lit":"Nara · [possessif] · billet · [objet] · deux-feuilles · donnez-moi","note":{"lit":"Nara, petit mot de liaison, billet, petit mot du complément, deux, donnez-moi","text":"Pour compter les billets, on emploie un petit mot de comptage. Deux billets se dit « nimai ». Ce mot sert pour les choses plates et fines.","say":{"nimai":"二枚"},"words":[["Nara","奈良"],["petit mot de liaison","の"],["billet","切符"],["petit mot du complément","を"],["deux","二枚"],["donnez-moi","ください"]]}},{"fr":"Un aller simple ?","tgt":"片道ですか？","ro":"Katamichi desu ka?","lit":"aller-simple · être (poli) · [question]","note":{"lit":"aller simple, être, petit mot de question","text":"Aller simple se dit « katamichi ». Mot à mot, c'est un seul côté du chemin. Le guichetier le demande souvent.","say":{"katamichi":"片道"},"words":[["aller simple","片道"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, un aller-retour.","tgt":"いいえ、往復です。","ro":"Iie, ōfuku desu.","lit":"non · aller-retour · être (poli)","note":{"lit":"non, aller-retour, être","text":"Aller-retour se dit « ōfuku ». Mot à mot, c'est aller et revenir. On le dit avec le petit mot poli.","say":{"ōfuku":"往復"},"words":[["non","いいえ"],["aller-retour","往復"],["être","です"]]}},{"fr":"Ça fait deux mille huit cent quatre-vingts yens.","tgt":"二千八百八十円です。","ro":"Nisen happyaku hachijū en desu.","lit":"deux-mille-huit-cent-quatre-vingts-yens · être (poli)","note":{"lit":"deux mille, huit cents, quatre-vingts, yen, être","text":"Mille se dit « sen ». Deux mille, c'est deux suivi de mille. Quatre-vingts, c'est huit fois dix.","say":{"sen":"千"},"words":[["deux mille","二千"],["huit cents","八百"],["quatre-vingts","八十"],["yen","円"],["être","です"]]}},{"fr":"Tenez, trois mille yens.","tgt":"はい、三千円です。","ro":"Hai, sanzen en desu.","lit":"oui · trois-mille-yens · être (poli)","note":{"lit":"voilà, trois mille, yen, être","text":"Trois mille se dit « sanzen ». Le mot mille change de son après trois. En tendant l'argent, oui veut dire ici tenez.","say":{"sanzen":"三千"},"words":[["voilà","はい"],["trois mille","三千"],["yen","円"],["être","です"]]}},{"fr":"Voici votre monnaie.","tgt":"おつりです。","ro":"Otsuri desu.","lit":"honorable-monnaie · être (poli)","note":{"lit":"monnaie, être","text":"La monnaie rendue se dit « otsuri ». On l'entend à chaque achat. Ici, la phrase est juste monnaie et le petit mot poli.","say":{"otsuri":"おつり"},"words":[["monnaie","おつり"],["être","です"]]}},{"fr":"Un plan du métro aussi, s'il vous plaît.","tgt":"地下鉄の地図もください。","ro":"Chikatetsu no chizu mo kudasai.","lit":"métro · [possessif] · plan · [aussi] · donnez-moi","note":{"lit":"métro, petit mot de liaison, plan, aussi, donnez-moi","text":"Plan ou carte se dit « chizu ». Aussi remplace ici le petit mot du complément. On garde donnez-moi à la fin.","say":{"chizu":"地図"},"words":[["métro","地下鉄"],["petit mot de liaison","の"],["plan","地図"],["aussi","も"],["donnez-moi","ください"]]}},{"fr":"Et deux bentō aussi, s'il vous plaît.","tgt":"お弁当も二つください。","ro":"Obentō mo futatsu kudasai.","lit":"honorable-bentō · [aussi] · deux (objets) · donnez-moi","note":{"lit":"bentō, aussi, deux, donnez-moi","text":"Pour compter les objets en général, deux se dit « futatsu ». Cette façon de compter marche pour presque tout. Le nombre se place juste avant donnez-moi.","say":{"futatsu":"二つ"},"words":[["bentō","お弁当"],["aussi","も"],["deux","二つ"],["donnez-moi","ください"]]}},{"fr":"Le train est sur la voie deux.","tgt":"電車は二番線です。","ro":"Densha wa nibansen desu.","lit":"train · [thème] · voie-numéro-deux · être (poli)","note":{"lit":"train, petit mot du thème, voie deux, être","text":"Voie se dit « sen ». Voie deux, c'est numéro deux suivi de ce mot. On l'entend dans toutes les annonces en gare.","say":{"sen":"線"},"words":[["train","電車"],["petit mot du thème","は"],["voie deux","二番線"],["être","です"]]}}],"tip":{"title":"« Kudasai » : donnez-moi, s'il vous plaît","example":"Deux billets pour Nara, s'il vous plaît. — 奈良の切符を二枚<b>ください</b>。","body":"« Kudasai » veut dire « donnez-moi, s'il vous plaît », et c'est sans doute le mot le plus utile en voyage. La construction est toute simple : on dit la chose, puis la particule « o » (objet), et on termine par « kudasai ». Comme le verbe japonais, la demande arrive à la fin de la phrase. « Nara no kippu o nimai kudasai » se dit littéralement : Nara, de, billet, objet, deux feuilles, donnez-moi. Remarquez que la quantité, « nimai » (deux, pour des objets plats comme des billets), se place juste avant « kudasai ». Quelques exemples : « Kore o kudasai » (ceci, s'il vous plaît), « Kōhī o kudasai » (un café, s'il vous plaît), « Chizu mo kudasai » (le plan aussi, s'il vous plaît). « Onegaishimasu », que vous connaissez déjà, est plus large et plus doux ; « kudasai » sert surtout à demander un objet concret qu'on vous tend. Une astuce pour retenir : imaginez votre main tendue au guichet au moment où vous prononcez « kudasai ».","exampleRo":"Nara no kippu o nimai kudasai.","lit":"Nara · [possessif] · billet · [objet] · deux-feuilles · donnez-moi","say":{"Kudasai":"ください","o":"を","kudasai":"ください","Nara no kippu o nimai kudasai":"奈良の切符を二枚ください","nimai":"二枚","Kore o kudasai":"これをください","Kōhī o kudasai":"コーヒーをください","Chizu mo kudasai":"地図もください","Onegaishimasu":"お願いします"}}},{"title":"Une nuit au ryokan","phrases":[{"fr":"Bonsoir, je suis Martin, j'ai une réservation.","tgt":"こんばんは。予約のマルタンです。","ro":"Konbanwa. Yoyaku no Marutan desu.","lit":"bonsoir · réservation · [possessif] · Martin · être (poli)","note":{"lit":"bonsoir, réservation, petit mot de liaison, Martin, être","text":"Bonsoir se dit « konbanwa ». Pour se présenter, on dit Martin de la réservation. C'est une formule très courante à l'hôtel.","say":{"konbanwa":"こんばんは"},"words":[["bonsoir","こんばんは"],["réservation","予約"],["petit mot de liaison","の"],["Martin","マルタン"],["être","です"]]}},{"fr":"Bienvenue, entrez donc.","tgt":"いらっしゃいませ。どうぞ。","ro":"Irasshaimase. Dōzo.","lit":"bienvenue (poli) · je vous en prie","note":{"lit":"bienvenue, je vous en prie","text":"Dans les magasins et les hôtels, on accueille les clients avec « irasshaimase ». Ça veut dire bienvenue. On n'y répond pas, on sourit simplement.","say":{"irasshaimase":"いらっしゃいませ"},"words":[["bienvenue","いらっしゃいませ"],["je vous en prie","どうぞ"]]}},{"fr":"Ici, on enlève ses chaussures.","tgt":"ここで靴を脱ぎます。","ro":"Koko de kutsu o nugimasu.","lit":"ici · [lieu] · chaussures · [objet] · enlever (poli)","note":{"lit":"ici, petit mot du lieu, chaussures, petit mot du complément, enlever","text":"Enlever un vêtement se dit « nugimasu ». Au ryokan, on enlève ses chaussures à l'entrée. La phrase décrit une règle, sans sujet.","say":{"nugimasu":"脱ぎます"},"words":[["ici","ここ"],["petit mot du lieu","で"],["chaussures","靴"],["petit mot du complément","を"],["enlever","脱ぎます"]]}},{"fr":"La chambre est très jolie.","tgt":"部屋はとてもきれいです。","ro":"Heya wa totemo kirei desu.","lit":"chambre · [thème] · très · joli · être (poli)","note":{"lit":"chambre, petit mot du thème, très, joli, être","text":"Chambre se dit « heya ». Joli et propre se disent avec le même mot. Ici, les deux sens vont bien.","say":{"heya":"部屋"},"words":[["chambre","部屋"],["petit mot du thème","は"],["très","とても"],["joli","きれい"],["être","です"]]}},{"fr":"Il y a des tatamis et un futon.","tgt":"畳と布団があります。","ro":"Tatami to futon ga arimasu.","lit":"tatami · [et] · futon · [sujet] · il y a (objets, poli)","note":{"lit":"tatami, et, futon, petit mot du sujet, il y a","text":"Pour relier deux noms, on dit « to ». C'est comme et en français. Il ne sert qu'entre des noms.","say":{"to":"と"},"words":[["tatami","畳"],["et","と"],["futon","布団"],["petit mot du sujet","が"],["il y a","あります"]]}},{"fr":"Le dîner est à sept heures.","tgt":"夕食は七時です。","ro":"Yūshoku wa shichiji desu.","lit":"dîner · [thème] · sept-heures · être (poli)","note":{"lit":"dîner, petit mot du thème, sept heures, être","text":"Le dîner se dit « yūshoku ». Pas besoin de verbe, le petit mot poli suffit. Le dîner, c'est sept heures.","say":{"yūshoku":"夕食"},"words":[["dîner","夕食"],["petit mot du thème","は"],["sept heures","七時"],["être","です"]]}},{"fr":"Le bain est au premier étage.","tgt":"お風呂は二階です。","ro":"Ofuro wa nikai desu.","lit":"honorable-bain · [thème] · deuxième-niveau · être (poli)","note":{"lit":"bain, petit mot du thème, premier étage, être","text":"Au Japon, le rez-de-chaussée compte déjà comme un étage. Notre premier étage se dit donc « nikai ». Mot à mot, c'est le deuxième niveau.","say":{"nikai":"二階"},"words":[["bain","お風呂"],["petit mot du thème","は"],["premier étage","二階"],["être","です"]]}},{"fr":"Au ryokan, on porte un yukata.","tgt":"旅館では浴衣を着ます。","ro":"Ryokan de wa yukata o kimasu.","lit":"ryokan · [lieu] · [thème] · yukata · [objet] · porter (poli)","note":{"lit":"ryokan, petit mot du lieu, petit mot du thème, yukata, petit mot du complément, porter","text":"Au ryokan, on porte une robe légère en coton. Cette robe se dit « yukata ». Le petit mot du thème insiste sur le lieu.","say":{"yukata":"浴衣"},"words":[["ryokan","旅館"],["petit mot du lieu","で"],["petit mot du thème","は"],["yukata","浴衣"],["petit mot du complément","を"],["porter","着ます"]]}},{"fr":"Le petit-déjeuner est japonais ?","tgt":"朝ご飯は和食ですか？","ro":"Asagohan wa washoku desu ka?","lit":"petit-déjeuner · [thème] · cuisine-japonaise · être (poli) · [question]","note":{"lit":"petit-déjeuner, petit mot du thème, cuisine japonaise, être, petit mot de question","text":"La cuisine japonaise se dit « washoku ». Son contraire désigne la cuisine occidentale. Au ryokan, le petit-déjeuner est souvent japonais.","say":{"washoku":"和食"},"words":[["petit-déjeuner","朝ご飯"],["petit mot du thème","は"],["cuisine japonaise","和食"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, du riz et une soupe miso.","tgt":"はい、ご飯とみそ汁です。","ro":"Hai, gohan to misoshiru desu.","lit":"oui · riz · [et] · soupe-miso · être (poli)","note":{"lit":"oui, riz, et, soupe miso, être","text":"Le riz cuit se dit « gohan ». Ce mot veut aussi dire repas. On le retrouve dans petit-déjeuner et déjeuner.","say":{"gohan":"ご飯"},"words":[["oui","はい"],["riz","ご飯"],["et","と"],["soupe miso","みそ汁"],["être","です"]]}}]},{"title":"À l'office du tourisme","phrases":[{"fr":"Où est l'office du tourisme ?","tgt":"観光案内所はどこですか？","ro":"Kankō annaijo wa doko desu ka?","lit":"tourisme-bureau-d'information · [thème] · où · être (poli) · [question]","note":{"lit":"office du tourisme, petit mot du thème, où, être, petit mot de question","text":"Où est se dit « doko desu ka ». On met le lieu cherché en thème juste avant. C'est la question la plus utile en voyage.","say":{"doko desu ka":"どこですか"},"words":[["office du tourisme","観光案内所"],["petit mot du thème","は"],["où","どこ"],["être","です"],["petit mot de question","か"]]}},{"fr":"Il est dans la gare.","tgt":"駅の中です。","ro":"Eki no naka desu.","lit":"gare · [possessif] · intérieur · être (poli)","note":{"lit":"gare, petit mot de liaison, intérieur, être","text":"Dans se dit mot à mot l'intérieur de. Intérieur se dit « naka ». On dit la gare, liaison, intérieur.","say":{"naka":"中"},"words":[["gare","駅"],["petit mot de liaison","の"],["intérieur","中"],["être","です"]]}},{"fr":"Qu'est-ce qu'il y a à voir à Kyoto ?","tgt":"京都には何がありますか？","ro":"Kyōto ni wa nani ga arimasu ka?","lit":"Kyoto · [lieu] · [thème] · quoi · [sujet] · il y a (objets, poli) · [question]","note":{"lit":"Kyoto, petit mot du lieu, petit mot du thème, quoi, petit mot du sujet, il y a, petit mot de question","text":"Quoi, comme sujet, se dit « nani ga ». On demande ce qui existe avec le verbe des objets. Le lieu est mis en thème au début.","say":{"nani ga":"何が"},"words":[["Kyoto","京都"],["petit mot du lieu","に"],["petit mot du thème","は"],["quoi","何"],["petit mot du sujet","が"],["il y a","あります"],["petit mot de question","か"]]}},{"fr":"Il y a beaucoup de temples.","tgt":"お寺がたくさんあります。","ro":"Otera ga takusan arimasu.","lit":"honorable-temple · [sujet] · beaucoup · il y a (objets, poli)","note":{"lit":"temple, petit mot du sujet, beaucoup, il y a","text":"Temple se dit « otera ». On l'entend presque toujours avec le petit son poli. Les temples sont partout à Kyoto.","say":{"otera":"お寺"},"words":[["temple","お寺"],["petit mot du sujet","が"],["beaucoup","たくさん"],["il y a","あります"]]}},{"fr":"Combien coûte l'entrée du Kinkaku-ji ?","tgt":"金閣寺の入場料はいくらですか？","ro":"Kinkakuji no nyūjōryō wa ikura desu ka?","lit":"Kinkaku-ji · [possessif] · droit-d'entrée · [thème] · combien · être (poli) · [question]","note":{"lit":"Kinkaku-ji, petit mot de liaison, droit d'entrée, petit mot du thème, combien, être, petit mot de question","text":"Le prix d'entrée se dit « nyūjōryō ». On l'entend devant chaque temple. Combien se place juste avant la question.","say":{"nyūjōryō":"入場料"},"words":[["Kinkaku-ji","金閣寺"],["petit mot de liaison","の"],["droit d'entrée","入場料"],["petit mot du thème","は"],["combien","いくら"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est cinq cents yens.","tgt":"五百円です。","ro":"Gohyaku en desu.","lit":"cinq-cents-yens · être (poli)","note":{"lit":"cinq cents, yen, être","text":"Cinq cents se dit « gohyaku ». Ici, le mot cent ne change pas de son. La réponse est simplement le prix et le petit mot poli.","say":{"gohyaku":"五百"},"words":[["cinq cents","五百"],["yen","円"],["être","です"]]}},{"fr":"Quand a lieu la fête de Gion ?","tgt":"祇園祭はいつですか？","ro":"Gion matsuri wa itsu desu ka?","lit":"Gion-fête · [thème] · quand · être (poli) · [question]","note":{"lit":"Gion, fête, petit mot du thème, quand, être, petit mot de question","text":"Quand se dit « itsu ». Il prend la place de la date dans la question. La fête de Gion est la plus célèbre de Kyoto.","say":{"itsu":"いつ"},"words":[["Gion","祇園"],["fête","祭"],["petit mot du thème","は"],["quand","いつ"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est en juillet.","tgt":"七月です。","ro":"Shichigatsu desu.","lit":"juillet · être (poli)","note":{"lit":"juillet, être","text":"Juillet se dit « shichigatsu ». Mot à mot, c'est le mois sept. Tous les mois se disent ainsi, avec un nombre.","say":{"shichigatsu":"七月"},"words":[["juillet","七月"],["être","です"]]}},{"fr":"Qui est la personne sur cette affiche ?","tgt":"このポスターの人は誰ですか？","ro":"Kono posutā no hito wa dare desu ka?","lit":"ce · affiche · [possessif] · personne · [thème] · qui · être (poli) · [question]","note":{"lit":"ce, affiche, petit mot de liaison, personne, petit mot du thème, qui, être, petit mot de question","text":"Qui se dit « dare ». Il se place là où viendrait le nom de la personne. La personne de l'affiche est mise en thème.","say":{"dare":"誰"},"words":[["ce","この"],["affiche","ポスター"],["petit mot de liaison","の"],["personne","人"],["petit mot du thème","は"],["qui","誰"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est une maiko de Gion.","tgt":"祇園の舞妓さんです。","ro":"Gion no maiko san desu.","lit":"Gion · [possessif] · maiko · madame · être (poli)","note":{"lit":"Gion, petit mot de liaison, maiko, madame, être","text":"Une apprentie geisha se dit « maiko ». On ajoute le petit mot de politesse après. Les maikos se voient surtout à Gion.","say":{"maiko":"舞妓"},"words":[["Gion","祇園"],["petit mot de liaison","の"],["maiko","舞妓"],["madame","さん"],["être","です"]]}}],"tip":{"title":"Les mots interrogatifs : « doko, nani, itsu, dare, ikura »","example":"Où est l'office du tourisme ? — 観光案内所は<b>どこ</b>ですか？","body":"En japonais, poser une question avec un mot interrogatif est d'une grande simplicité : on ne change pas l'ordre des mots, on met le mot interrogatif à la place de la réponse attendue, et on ajoute « ka » (question) à la fin. Voici les cinq indispensables : « doko » (où), « nani » ou « nan » (quoi), « itsu » (quand), « dare » (qui) et « ikura » (combien, pour un prix). « Kankō annaijo wa doko desu ka » se dit littéralement : office du tourisme, thème, où, être poli, question ? Pour répondre, il suffit de remplacer « doko » par le lieu : « Eki no naka desu », c'est dans la gare. De même : « Ikura desu ka ? » (c'est combien ?), « Itsu desu ka ? » (c'est quand ?), « Dare desu ka ? » (qui est-ce ?). Le schéma reste toujours le même : le sujet avec « wa », le mot interrogatif, puis « desu ka ». Une astuce pour retenir « ikura » : c'est aussi le nom des œufs de saumon, un mets plutôt cher, alors on demande toujours combien ça coûte !","exampleRo":"Kankō annaijo wa doko desu ka?","lit":"tourisme-bureau-d'information · [thème] · où · être (poli) · [question]","say":{"ka":"か","doko":"どこ","nani":"なに","nan":"なん","itsu":"いつ","dare":"誰","ikura":"いくら","Kankō annaijo wa doko desu ka":"観光案内所はどこですか","Eki no naka desu":"駅の中です","Ikura desu ka ?":"いくらですか","Itsu desu ka ?":"いつですか","Dare desu ka ?":"誰ですか","wa":"わ","desu ka":"ですか","doko, nani, itsu, dare, ikura":"どこ、なに、いつ、誰、いくら"}}},{"title":"Au Kinkaku-ji, le pavillon d'or","phrases":[{"fr":"Le Kinkaku-ji est vraiment beau.","tgt":"金閣寺は本当にきれいです。","ro":"Kinkakuji wa hontō ni kirei desu.","lit":"Kinkaku-ji · [thème] · vraiment · beau · être (poli)","note":{"lit":"Kinkaku-ji, petit mot du thème, vraiment, beau, être","text":"Vraiment se dit « hontō ni ». Il se place juste avant l'adjectif. On l'entend aussi seul, pour dire c'est vrai.","say":{"hontō ni":"本当に"},"words":[["Kinkaku-ji","金閣寺"],["petit mot du thème","は"],["vraiment","本当に"],["beau","きれい"],["être","です"]]}},{"fr":"Il est couleur or.","tgt":"金色です。","ro":"Kin'iro desu.","lit":"or-couleur · être (poli)","note":{"lit":"couleur or, être","text":"Or se dit « kin ». Couleur or se dit or suivi du mot couleur. Le nom du pavillon commence aussi par ce mot.","say":{"kin":"金"},"words":[["couleur or","金色"],["être","です"]]}},{"fr":"L'étang est très calme.","tgt":"池はとても静かです。","ro":"Ike wa totemo shizuka desu.","lit":"étang · [thème] · très · calme · être (poli)","note":{"lit":"étang, petit mot du thème, très, calme, être","text":"Calme se dit « shizuka ». Il ne change pas de forme en fin de phrase. Étang se met en thème au début.","say":{"shizuka":"静か"},"words":[["étang","池"],["petit mot du thème","は"],["très","とても"],["calme","静か"],["être","です"]]}},{"fr":"On prend une photo ?","tgt":"写真を撮りましょうか？","ro":"Shashin o torimashō ka?","lit":"photo · [objet] · prendre (proposition) · [question]","note":{"lit":"photo, petit mot du complément, prendre, petit mot de question","text":"Prendre une photo se dit « torimasu ». Avec la fin des propositions et la question, on offre de le faire. On peut le dire pour aider quelqu'un.","say":{"torimasu":"撮ります"},"words":[["photo","写真"],["petit mot du complément","を"],["prendre","撮りましょう"],["petit mot de question","か"]]}},{"fr":"Aujourd'hui, il y a beaucoup de touristes.","tgt":"今日は観光客が多いです。","ro":"Kyō wa kankōkyaku ga ōi desu.","lit":"aujourd'hui · [thème] · touristes · [sujet] · nombreux · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, touristes, petit mot du sujet, nombreux, être","text":"Touriste se dit « kankōkyaku ». C'est tourisme suivi d'un mot qui veut dire client. Il y a beaucoup se dit ici sont nombreux.","say":{"kankōkyaku":"観光客"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["touristes","観光客"],["petit mot du sujet","が"],["nombreux","多い"],["être","です"]]}},{"fr":"On n'entre pas dans le pavillon.","tgt":"建物には入りません。","ro":"Tatemono ni wa hairimasen.","lit":"bâtiment · [direction] · [thème] · entrer (négatif, poli)","note":{"lit":"bâtiment, dans, petit mot du thème, ne pas entrer","text":"Ne pas entrer se dit « hairimasen ». Le thème ajouté souligne que, dans le bâtiment, on n'entre pas. Dehors, on peut se promener.","say":{"hairimasen":"入りません"},"words":[["bâtiment","建物"],["dans","に"],["petit mot du thème","は"],["ne pas entrer","入りません"]]}},{"fr":"Le jardin aussi est magnifique.","tgt":"庭もすばらしいです。","ro":"Niwa mo subarashii desu.","lit":"jardin · [aussi] · magnifique · être (poli)","note":{"lit":"jardin, aussi, magnifique, être","text":"Magnifique se dit « subarashii ». C'est un adjectif très fort. Le jardin aussi, c'est jardin suivi du petit mot aussi.","say":{"subarashii":"すばらしい"},"words":[["jardin","庭"],["aussi","も"],["magnifique","すばらしい"],["être","です"]]}},{"fr":"Et si on achetait une amulette ?","tgt":"お守りを買いませんか？","ro":"Omamori o kaimasen ka?","lit":"honorable-protection · [objet] · acheter (négatif, poli) · [question]","note":{"lit":"amulette, petit mot du complément, ne pas acheter, petit mot de question","text":"Une amulette se dit « omamori ». On en trouve dans tous les temples et sanctuaires. Ici, on propose d'en acheter avec une question négative.","say":{"omamori":"お守り"},"words":[["amulette","お守り"],["petit mot du complément","を"],["ne pas acheter","買いません"],["petit mot de question","か"]]}},{"fr":"Cette amulette coûte huit cents yens.","tgt":"このお守りは八百円です。","ro":"Kono omamori wa happyaku en desu.","lit":"ce · honorable-protection · [thème] · huit-cents-yens · être (poli)","note":{"lit":"ce, amulette, petit mot du thème, huit cents, yen, être","text":"Ce, devant un nom, se dit « kono ». Il montre un objet tout près. Ensuite vient le prix.","say":{"kono":"この"},"words":[["ce","この"],["amulette","お守り"],["petit mot du thème","は"],["huit cents","八百"],["yen","円"],["être","です"]]}},{"fr":"C'est un joli souvenir de Kyoto.","tgt":"京都のいいお土産です。","ro":"Kyōto no ii omiyage desu.","lit":"Kyoto · [possessif] · bon · souvenir-cadeau · être (poli)","note":{"lit":"Kyoto, petit mot de liaison, bon, souvenir, être","text":"Un souvenir à offrir se dit « omiyage ». Au Japon, on en rapporte toujours à ses proches et collègues. C'est souvent une spécialité locale.","say":{"omiyage":"お土産"},"words":[["Kyoto","京都"],["petit mot de liaison","の"],["bon","いい"],["souvenir","お土産"],["être","です"]]}}]},{"title":"Les mille torii de Fushimi Inari","phrases":[{"fr":"De Kyoto à Inari, c'est à deux gares.","tgt":"京都から稲荷まで二駅です。","ro":"Kyōto kara Inari made futaeki desu.","lit":"Kyoto · [de… à… : depuis] · Inari · [de… à… : jusqu'à] · deux-gares · être (poli)","note":{"lit":"Kyoto, depuis, Inari, jusqu'à, deux gares, être","text":"Depuis se dit « kara ». Il se place après le point de départ. Jusqu'à se met de même après l'arrivée.","say":{"kara":"から"},"words":[["Kyoto","京都"],["depuis","から"],["Inari","稲荷"],["jusqu'à","まで"],["deux gares","二駅"],["être","です"]]}},{"fr":"En train, c'est cinq minutes.","tgt":"電車で五分です。","ro":"Densha de gofun desu.","lit":"train · [moyen] · cinq-minutes · être (poli)","note":{"lit":"train, petit mot du moyen, cinq minutes, être","text":"Cinq minutes se dit « gofun ». C'est cinq suivi du mot minute. En train se dit avec le petit mot du moyen.","say":{"gofun":"五分"},"words":[["train","電車"],["petit mot du moyen","で"],["cinq minutes","五分"],["être","です"]]}},{"fr":"La gare est juste devant le sanctuaire.","tgt":"駅は神社の前です。","ro":"Eki wa jinja no mae desu.","lit":"gare · [thème] · sanctuaire · [possessif] · devant · être (poli)","note":{"lit":"gare, petit mot du thème, sanctuaire, petit mot de liaison, devant, être","text":"Devant se dit « mae ». On dit le sanctuaire, liaison, devant. Mot à mot, c'est le devant du sanctuaire.","say":{"mae":"前"},"words":[["gare","駅"],["petit mot du thème","は"],["sanctuaire","神社"],["petit mot de liaison","の"],["devant","前"],["être","です"]]}},{"fr":"Il y a énormément de torii.","tgt":"鳥居がたくさんあります。","ro":"Torii ga takusan arimasu.","lit":"torii · [sujet] · beaucoup · il y a (objets, poli)","note":{"lit":"torii, petit mot du sujet, beaucoup, il y a","text":"Le portique d'un sanctuaire se dit « torii ». À Fushimi Inari, il y en a des milliers. Ce sont des objets, donc on emploie le verbe des objets.","say":{"torii":"鳥居"},"words":[["torii","鳥居"],["petit mot du sujet","が"],["beaucoup","たくさん"],["il y a","あります"]]}},{"fr":"Ils sont tous orange.","tgt":"全部オレンジ色です。","ro":"Zenbu orenji iro desu.","lit":"tout · orange-couleur · être (poli)","note":{"lit":"tout, orange, couleur, être","text":"Tout se dit « zenbu ». Il se place au début, sans article. Couleur orange se dit orange suivi du mot couleur.","say":{"zenbu":"全部"},"words":[["tout","全部"],["orange","オレンジ"],["couleur","色"],["être","です"]]}},{"fr":"On monte jusqu'en haut de la montagne ?","tgt":"山の上まで登りましょうか？","ro":"Yama no ue made noborimashō ka?","lit":"montagne · [possessif] · dessus · [de… à… : jusqu'à] · grimper (proposition) · [question]","note":{"lit":"montagne, petit mot de liaison, haut, jusqu'à, grimper, petit mot de question","text":"Jusqu'à se dit « made ». Il se place après le lieu d'arrivée. Ici, c'est le haut de la montagne.","say":{"made":"まで"},"words":[["montagne","山"],["petit mot de liaison","の"],["haut","上"],["jusqu'à","まで"],["grimper","登りましょう"],["petit mot de question","か"]]}},{"fr":"Du bas jusqu'en haut, ça prend deux heures.","tgt":"下から上まで二時間かかります。","ro":"Shita kara ue made nijikan kakarimasu.","lit":"bas · [de… à… : depuis] · haut · [de… à… : jusqu'à] · deux-heures (durée) · prendre du temps (poli)","note":{"lit":"bas, depuis, haut, jusqu'à, deux heures, prendre","text":"Pour une durée, ça prend se dit « kakarimasu ». La durée se place juste avant. Le départ et l'arrivée viennent au début.","say":{"kakarimasu":"かかります"},"words":[["bas","下"],["depuis","から"],["haut","上"],["jusqu'à","まで"],["deux heures","二時間"],["prendre","かかります"]]}},{"fr":"Les boutiques ouvrent de neuf heures à cinq heures.","tgt":"店は九時から五時までです。","ro":"Mise wa kuji kara goji made desu.","lit":"boutique · [thème] · neuf-heures · [de… à… : depuis] · cinq-heures · [de… à… : jusqu'à] · être (poli)","note":{"lit":"boutique, petit mot du thème, neuf heures, depuis, cinq heures, jusqu'à, être","text":"Pour des horaires, on dit de neuf heures jusqu'à cinq heures. Pas besoin de verbe, le petit mot poli suffit. Cinq heures se dit « goji ».","say":{"goji":"五時"},"words":[["boutique","店"],["petit mot du thème","は"],["neuf heures","九時"],["depuis","から"],["cinq heures","五時"],["jusqu'à","まで"],["être","です"]]}},{"fr":"Et si on se reposait ici ?","tgt":"ここで休みましょうか？","ro":"Koko de yasumimashō ka?","lit":"ici · [lieu] · se reposer (proposition) · [question]","note":{"lit":"ici, petit mot du lieu, se reposer, petit mot de question","text":"Se reposer se dit « yasumimasu ». Le même verbe sert aussi pour être en congé. Ici, on le propose avec la fin en question.","say":{"yasumimasu":"休みます"},"words":[["ici","ここ"],["petit mot du lieu","で"],["se reposer","休みましょう"],["petit mot de question","か"]]}},{"fr":"D'ici, la vue est superbe.","tgt":"ここからの景色はすばらしいです。","ro":"Koko kara no keshiki wa subarashii desu.","lit":"ici · [de… à… : depuis] · [possessif] · paysage · [thème] · superbe · être (poli)","note":{"lit":"ici, depuis, petit mot de liaison, vue, petit mot du thème, superbe, être","text":"Paysage ou vue se dit « keshiki ». La vue d'ici se dit ici, depuis, liaison, vue. Les petits mots s'enchaînent sans problème.","say":{"keshiki":"景色"},"words":[["ici","ここ"],["depuis","から"],["petit mot de liaison","の"],["vue","景色"],["petit mot du thème","は"],["superbe","すばらしい"],["être","です"]]}}],"tip":{"title":"« Kara » et « made » : de… à…","example":"Du bas jusqu'en haut, ça prend deux heures. — 下<b>から</b>上<b>まで</b>二時間かかります。","body":"Pour dire « de… à… », le japonais utilise deux particules : « kara », qui marque le point de départ, et « made », qui marque le point d'arrivée. Comme toutes les particules, elles se placent après le mot, et non avant comme nos prépositions. On dit donc « Kyōto kara », littéralement Kyoto depuis, et « Inari made », Inari jusqu'à. « Shita kara ue made nijikan kakarimasu » se décompose ainsi : bas, depuis, haut, jusqu'à, deux heures, ça prend. Le plus pratique, c'est que cela marche aussi bien pour les lieux que pour les heures : « Kuji kara goji made desu », c'est de neuf heures à cinq heures. On peut aussi les utiliser seuls : « Kyōto eki made onegaishimasu », jusqu'à la gare de Kyoto, s'il vous plaît, est la phrase idéale en taxi. Une astuce pour retenir l'ordre : « kara » comme un car qui démarre, « made » comme un arrêt bien marqué au bout du trajet.","exampleRo":"Shita kara ue made nijikan kakarimasu.","lit":"bas · [de… à… : depuis] · haut · [de… à… : jusqu'à] · deux-heures (durée) · prendre du temps (poli)","say":{"Kara":"から","made":"まで","kara":"から","Kyōto kara":"京都から","Inari made":"稲荷まで","Shita kara ue made nijikan kakarimasu":"下から上まで二時間かかります","Kuji kara goji made desu":"九時から五時までです","Kyōto eki made onegaishimasu":"京都駅までお願いします"}}},{"title":"Une soirée à Gion","phrases":[{"fr":"Ce soir, on va à Gion.","tgt":"今晩、祇園へ行きます。","ro":"Konban, Gion e ikimasu.","lit":"ce soir · Gion · [direction] · aller (poli)","note":{"lit":"ce soir, Gion, vers, aller","text":"Ce soir se dit « konban ». Il n'a pas besoin de petit mot après lui. On le met simplement en tête.","say":{"konban":"今晩"},"words":[["ce soir","今晩"],["Gion","祇園"],["vers","へ"],["aller","行きます"]]}},{"fr":"Les vieilles maisons sont très belles.","tgt":"古い家はとてもきれいです。","ro":"Furui ie wa totemo kirei desu.","lit":"vieux · maison · [thème] · très · beau · être (poli)","note":{"lit":"vieux, maison, petit mot du thème, très, beau, être","text":"Vieux, pour un objet, se dit « furui ». On ne l'emploie pas pour une personne. Il se place devant maison.","say":{"furui":"古い"},"words":[["vieux","古い"],["maison","家"],["petit mot du thème","は"],["très","とても"],["beau","きれい"],["être","です"]]}},{"fr":"Regarde, il y a une maiko là-bas !","tgt":"あそこに舞妓さんがいます！","ro":"Asoko ni maiko san ga imasu!","lit":"là-bas · [lieu] · maiko · madame · [sujet] · il y a (vivants, poli)","note":{"lit":"là-bas, petit mot du lieu, maiko, madame, petit mot du sujet, il y a","text":"Une maiko est une personne, donc on dit « imasu ». Pour un objet, ce serait l'autre verbe. Là-bas vient au début.","say":{"imasu":"います"},"words":[["là-bas","あそこ"],["petit mot du lieu","に"],["maiko","舞妓"],["madame","さん"],["petit mot du sujet","が"],["il y a","います"]]}},{"fr":"Dans cette rue, les photos sont interdites.","tgt":"この道では写真はだめです。","ro":"Kono michi de wa shashin wa dame desu.","lit":"ce · rue · [lieu] · [thème] · photo · [thème] · interdit · être (poli)","note":{"lit":"ce, rue, petit mot du lieu, petit mot du thème, photo, petit mot du thème, interdit, être","text":"Interdit ou pas bien se dit « dame ». C'est un mot très courant pour refuser. On l'entend aussi pour les enfants.","say":{"dame":"だめ"},"words":[["ce","この"],["rue","道"],["petit mot du lieu","で"],["petit mot du thème","は"],["photo","写真"],["petit mot du thème","は"],["interdit","だめ"],["être","です"]]}},{"fr":"On dîne dans un petit restaurant.","tgt":"小さいレストランで晩ご飯を食べます。","ro":"Chiisai resutoran de bangohan o tabemasu.","lit":"petit · restaurant · [lieu] · dîner · [objet] · manger (poli)","note":{"lit":"petit, restaurant, petit mot du lieu, dîner, petit mot du complément, manger","text":"Le repas du soir se dit « bangohan ». C'est soir suivi du mot repas. On le mange ici dans un restaurant.","say":{"bangohan":"晩ご飯"},"words":[["petit","小さい"],["restaurant","レストラン"],["petit mot du lieu","で"],["dîner","晩ご飯"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"Le tofu de Kyoto est délicieux.","tgt":"京都の豆腐はおいしいです。","ro":"Kyōto no tōfu wa oishii desu.","lit":"Kyoto · [possessif] · tofu · [thème] · délicieux · être (poli)","note":{"lit":"Kyoto, petit mot de liaison, tofu, petit mot du thème, délicieux, être","text":"Le tofu se dit « tōfu ». C'est un mot japonais passé en français. Le tofu de Kyoto est réputé pour sa finesse.","say":{"tōfu":"豆腐"},"words":[["Kyoto","京都"],["petit mot de liaison","の"],["tofu","豆腐"],["petit mot du thème","は"],["délicieux","おいしい"],["être","です"]]}},{"fr":"Le saké aussi est bon.","tgt":"お酒もおいしいです。","ro":"Osake mo oishii desu.","lit":"honorable-alcool · [aussi] · bon · être (poli)","note":{"lit":"alcool, aussi, bon, être","text":"Bon, pour une boisson ou un plat, se dit « oishii ». On l'emploie pour tout ce qui se mange ou se boit. Ici, il suit le petit mot aussi.","say":{"oishii":"おいしい"},"words":[["alcool","お酒"],["aussi","も"],["bon","おいしい"],["être","です"]]}},{"fr":"Je ne bois pas beaucoup.","tgt":"あまり飲みません。","ro":"Amari nomimasen.","lit":"pas beaucoup · boire (négatif, poli)","note":{"lit":"pas beaucoup, ne pas boire","text":"Pas beaucoup se dit « amari ». Il va toujours avec un verbe négatif. Mot à mot, je ne bois pas beaucoup.","say":{"amari":"あまり"},"words":[["pas beaucoup","あまり"],["ne pas boire","飲みません"]]}},{"fr":"La rivière Kamo est juste là.","tgt":"鴨川はすぐそこです。","ro":"Kamogawa wa sugu soko desu.","lit":"Kamo-rivière · [thème] · tout près · là · être (poli)","note":{"lit":"rivière Kamo, petit mot du thème, tout près, là, être","text":"Tout près se dit « sugu soko ». Mot à mot, c'est tout de suite là. On l'entend souvent quand on demande son chemin.","say":{"sugu soko":"すぐそこ"},"words":[["rivière Kamo","鴨川"],["petit mot du thème","は"],["tout près","すぐ"],["là","そこ"],["être","です"]]}},{"fr":"Et si on marchait un peu ?","tgt":"少し歩きませんか？","ro":"Sukoshi arukimasen ka?","lit":"un peu · marcher (négatif, poli) · [question]","note":{"lit":"un peu, ne pas marcher, petit mot de question","text":"Marcher se dit « arukimasu ». Ici, on invite avec une question négative. Un peu se place devant.","say":{"arukimasu":"歩きます"},"words":[["un peu","少し"],["ne pas marcher","歩きません"],["petit mot de question","か"]]}}]},{"title":"Une journée chez les daims de Nara","phrases":[{"fr":"Hier, je suis allé à Nara.","tgt":"昨日、奈良へ行きました。","ro":"Kinō, Nara e ikimashita.","lit":"hier · Nara · [direction] · aller (passé, poli)","note":{"lit":"hier, Nara, vers, aller","text":"Pour le passé poli, la fin du verbe devient « mashita ». Je vais devient ainsi je suis allé. Hier, au début, confirme le passé.","say":{"mashita":"ました"},"words":[["hier","昨日"],["Nara","奈良"],["vers","へ"],["aller","行きました"]]}},{"fr":"J'ai vu beaucoup de daims.","tgt":"鹿をたくさん見ました。","ro":"Shika o takusan mimashita.","lit":"daim · [objet] · beaucoup · voir (passé, poli)","note":{"lit":"daim, petit mot du complément, beaucoup, voir","text":"Daim ou cerf se dit « shika ». Il n'y a pas de pluriel en japonais. Beaucoup se place entre le complément et le verbe.","say":{"shika":"鹿"},"words":[["daim","鹿"],["petit mot du complément","を"],["beaucoup","たくさん"],["voir","見ました"]]}},{"fr":"J'ai acheté des galettes pour les daims.","tgt":"鹿せんべいを買いました。","ro":"Shika senbei o kaimashita.","lit":"daim-galette · [objet] · acheter (passé, poli)","note":{"lit":"daim, galette, petit mot du complément, acheter","text":"Une galette de riz se dit « senbei ». À Nara, on en vend spécialement pour les daims. On dit daim suivi de galette.","say":{"senbei":"せんべい"},"words":[["daim","鹿"],["galette","せんべい"],["petit mot du complément","を"],["acheter","買いました"]]}},{"fr":"Un daim a fait une révérence.","tgt":"鹿がおじぎをしました。","ro":"Shika ga ojigi o shimashita.","lit":"daim · [sujet] · révérence · [objet] · faire (passé, poli)","note":{"lit":"daim, petit mot du sujet, révérence, petit mot du complément, faire","text":"La révérence se dit « ojigi ». C'est le salut japonais, en s'inclinant. Les daims de Nara saluent pour avoir une galette.","say":{"ojigi":"おじぎ"},"words":[["daim","鹿"],["petit mot du sujet","が"],["révérence","おじぎ"],["petit mot du complément","を"],["faire","しました"]]}},{"fr":"Ensuite, j'ai vu le Tōdai-ji.","tgt":"それから、東大寺を見ました。","ro":"Sorekara, Tōdaiji o mimashita.","lit":"ensuite · Tōdai-ji · [objet] · voir (passé, poli)","note":{"lit":"ensuite, Tōdai-ji, petit mot du complément, voir","text":"J'ai vu se dit « mimashita ». C'est le verbe voir au passé poli. Ensuite permet d'enchaîner le récit.","say":{"mimashita":"見ました"},"words":[["ensuite","それから"],["Tōdai-ji","東大寺"],["petit mot du complément","を"],["voir","見ました"]]}},{"fr":"Le grand bouddha est immense.","tgt":"大仏はとても大きいです。","ro":"Daibutsu wa totemo ōkii desu.","lit":"grand-bouddha · [thème] · très · grand · être (poli)","note":{"lit":"grand bouddha, petit mot du thème, très, grand, être","text":"Le grand bouddha se dit « daibutsu ». Celui de Nara est l'un des plus grands du Japon. La phrase est au présent, car il l'est toujours.","say":{"daibutsu":"大仏"},"words":[["grand bouddha","大仏"],["petit mot du thème","は"],["très","とても"],["grand","大きい"],["être","です"]]}},{"fr":"Je n'ai pas pris de photo.","tgt":"写真は撮りませんでした。","ro":"Shashin wa torimasen deshita.","lit":"photo · [thème] · prendre (négatif passé, poli)","note":{"lit":"photo, petit mot du thème, ne pas prendre, petit mot du passé","text":"Pour le passé négatif, on ajoute après la négation « deshita ». Je ne prends pas devient je n'ai pas pris. Photo est mis en thème pour le contraste.","say":{"deshita":"でした"},"words":[["photo","写真"],["petit mot du thème","は"],["ne pas prendre","撮りません"],["petit mot du passé","でした"]]}},{"fr":"Je n'ai pas mangé à midi.","tgt":"昼ご飯は食べませんでした。","ro":"Hirugohan wa tabemasen deshita.","lit":"déjeuner · [thème] · manger (négatif passé, poli)","note":{"lit":"déjeuner, petit mot du thème, ne pas manger, petit mot du passé","text":"Je n'ai pas mangé se dit « tabemasen deshita ». C'est la négation, suivie de la marque du passé. Le déjeuner est mis en thème.","say":{"tabemasen deshita":"食べませんでした"},"words":[["déjeuner","昼ご飯"],["petit mot du thème","は"],["ne pas manger","食べません"],["petit mot du passé","でした"]]}},{"fr":"Je suis rentré à Kyoto à six heures.","tgt":"六時に京都へ帰りました。","ro":"Rokuji ni Kyōto e kaerimashita.","lit":"six-heures · [moment] · Kyoto · [direction] · rentrer (passé, poli)","note":{"lit":"six heures, petit mot du moment, Kyoto, vers, rentrer","text":"Je suis rentré se dit « kaerimashita ». C'est rentrer au passé poli. L'heure vient en premier.","say":{"kaerimashita":"帰りました"},"words":[["six heures","六時"],["petit mot du moment","に"],["Kyoto","京都"],["vers","へ"],["rentrer","帰りました"]]}},{"fr":"C'était une très bonne journée.","tgt":"とてもいい一日でした。","ro":"Totemo ii ichinichi deshita.","lit":"très · bon · une-journée · être (passé, poli)","note":{"lit":"très, bon, journée, petit mot du passé","text":"Le petit mot poli a aussi son passé, « deshita ». C'était se dit donc avec lui. Une journée se dit avec le nombre un et le mot jour.","say":{"deshita":"でした"},"words":[["très","とても"],["bon","いい"],["journée","一日"],["petit mot du passé","でした"]]}}],"tip":{"title":"Le passé poli : « -mashita » et « -masen deshita »","example":"J'ai vu beaucoup de daims. — 鹿をたくさん<b>見ました</b>。","body":"Bonne nouvelle : le passé poli japonais est très régulier. Il suffit de remplacer la terminaison « -masu » par « -mashita ». « Mimasu », je vois, devient « mimashita », j'ai vu ; « ikimasu », je vais, devient « ikimashita », je suis allé. Pour la négation, on part de « -masen » et on ajoute simplement « deshita » : « tabemasen », je ne mange pas, devient « tabemasen deshita », je n'ai pas mangé. « Shika o takusan mimashita » se dit littéralement : daim, objet, beaucoup, avoir vu poliment. Et comme en japonais le verbe ne change jamais selon la personne, « mimashita » veut dire aussi bien j'ai vu, tu as vu ou nous avons vu : c'est le contexte qui décide. Enfin, « desu » a lui aussi son passé : « deshita », c'était, comme dans « Ii ichinichi deshita », c'était une bonne journée. Une astuce pour retenir : « shita » sonne comme une porte qui se referme, l'action est terminée.","exampleRo":"Shika o takusan mimashita.","lit":"daim · [objet] · beaucoup · voir (passé, poli)","say":{"Mimasu":"見ます","mimashita":"見ました","ikimasu":"行きます","ikimashita":"行きました","deshita":"でした","tabemasen":"食べません","tabemasen deshita":"食べませんでした","Shika o takusan mimashita":"鹿をたくさん見ました","desu":"です","Ii ichinichi deshita":"いい一日でした","shita":"した","-mashita":"ました","-masen deshita":"ませんでした","-masu":"ます","-masen":"ません"}}},{"title":"Un bagage égaré","phrases":[{"fr":"Excusez-moi, ma valise n'est pas arrivée.","tgt":"すみません、スーツケースが来ませんでした。","ro":"Sumimasen, sūtsukēsu ga kimasen deshita.","lit":"excusez-moi · valise · [sujet] · venir (négatif passé, poli)","note":{"lit":"excusez-moi, valise, petit mot du sujet, ne pas venir, petit mot du passé","text":"Pour une valise qui n'arrive pas, on dit qu'elle n'est pas venue. Valise se dit « sūtsukēsu ». Elle prend le petit mot du sujet.","say":{"sūtsukēsu":"スーツケース"},"words":[["excusez-moi","すみません"],["valise","スーツケース"],["petit mot du sujet","が"],["ne pas venir","来ません"],["petit mot du passé","でした"]]}},{"fr":"Votre nom, s'il vous plaît.","tgt":"お名前をお願いします。","ro":"Onamae o onegaishimasu.","lit":"honorable-nom · [objet] · s'il vous plaît (poli)","note":{"lit":"nom, petit mot du complément, je vous le demande","text":"Le nom de quelqu'un se dit « onamae ». Le petit son poli s'ajoute quand on parle du nom de l'autre. Pour soi, on ne le met pas.","say":{"onamae":"お名前"},"words":[["nom","お名前"],["petit mot du complément","を"],["je vous le demande","お願いします"]]}},{"fr":"Je m'appelle Claire Dubois.","tgt":"クレール・デュボワです。","ro":"Kurēru Dyubowa desu.","lit":"Claire Dubois · être (poli)","note":{"lit":"Claire, Dubois, être","text":"Les noms étrangers sont adaptés aux sons japonais. Claire devient « kurēru ». Les sons r et l se confondent en japonais.","say":{"kurēru":"クレール"},"words":[["Claire","クレール"],["Dubois","デュボワ"],["être","です"]]}},{"fr":"La valise est de quelle couleur ?","tgt":"スーツケースは何色ですか？","ro":"Sūtsukēsu wa naniiro desu ka?","lit":"valise · [thème] · quelle-couleur · être (poli) · [question]","note":{"lit":"valise, petit mot du thème, quelle couleur, être, petit mot de question","text":"Quelle couleur se dit « naniiro ». C'est quoi suivi du mot couleur. On met l'objet en thème avant.","say":{"naniiro":"何色"},"words":[["valise","スーツケース"],["petit mot du thème","は"],["quelle couleur","何色"],["être","です"],["petit mot de question","か"]]}},{"fr":"Elle est bleue.","tgt":"青いです。","ro":"Aoi desu.","lit":"bleu · être (poli)","note":{"lit":"bleu, être","text":"Bleu, comme adjectif, se dit « aoi ». La valise n'est pas répétée. On comprend de quoi on parle.","say":{"aoi":"青い"},"words":[["bleu","青い"],["être","です"]]}},{"fr":"Et elle est assez grande.","tgt":"かなり大きいです。","ro":"Kanari ōkii desu.","lit":"assez · grand · être (poli)","note":{"lit":"assez, grand, être","text":"Assez, au sens de plutôt, se dit « kanari ». Il se place juste avant l'adjectif. Il ajoute une nuance.","say":{"kanari":"かなり"},"words":[["assez","かなり"],["grand","大きい"],["être","です"]]}},{"fr":"J'ai pris l'avion à Paris.","tgt":"パリで飛行機に乗りました。","ro":"Pari de hikōki ni norimashita.","lit":"Paris · [lieu] · avion · [dans] · monter (passé, poli)","note":{"lit":"Paris, petit mot du lieu, avion, dans, monter","text":"Avion se dit « hikōki ». Prendre l'avion se dit monter dans l'avion. Le même verbe sert pour le train.","say":{"hikōki":"飛行機"},"words":[["Paris","パリ"],["petit mot du lieu","で"],["avion","飛行機"],["dans","に"],["monter","乗りました"]]}},{"fr":"Nous la livrerons à votre hôtel demain.","tgt":"明日、ホテルに届けます。","ro":"Ashita, hoteru ni todokemasu.","lit":"demain · hôtel · [direction] · livrer (poli)","note":{"lit":"demain, hôtel, vers, livrer","text":"Livrer se dit « todokemasu ». Le sujet nous n'est pas dit. Le même verbe au présent sert pour le futur.","say":{"todokemasu":"届けます"},"words":[["demain","明日"],["hôtel","ホテル"],["vers","に"],["livrer","届けます"]]}},{"fr":"Voici l'adresse de mon hôtel.","tgt":"これはホテルの住所です。","ro":"Kore wa hoteru no jūsho desu.","lit":"ceci · [thème] · hôtel · [possessif] · adresse · être (poli)","note":{"lit":"ceci, petit mot du thème, hôtel, petit mot de liaison, adresse, être","text":"Adresse se dit « jūsho ». L'adresse de l'hôtel, c'est hôtel, liaison, adresse. Le possesseur vient toujours en premier.","say":{"jūsho":"住所"},"words":[["ceci","これ"],["petit mot du thème","は"],["hôtel","ホテル"],["petit mot de liaison","の"],["adresse","住所"],["être","です"]]}},{"fr":"Merci, me voilà rassurée.","tgt":"ありがとうございます。安心しました。","ro":"Arigatō gozaimasu. Anshin shimashita.","lit":"merci (très poli) · soulagement · faire (passé, poli)","note":{"lit":"merci, poliment, soulagement, faire","text":"Être soulagé se dit « anshin shimashita ». C'est soulagement suivi de faire au passé. On le dit quand un souci disparaît.","say":{"anshin shimashita":"安心しました"},"words":[["merci","ありがとう"],["poliment","ございます"],["soulagement","安心"],["faire","しました"]]}}]},{"title":"Dōtonbori, le soir","phrases":[{"fr":"Je veux voir Dōtonbori.","tgt":"道頓堀を見たいです。","ro":"Dōtonbori o mitai desu.","lit":"Dōtonbori · [objet] · voir-vouloir · être (poli)","note":{"lit":"Dōtonbori, petit mot du complément, vouloir voir, être","text":"Pour dire je veux faire, on remplace la fin du verbe par « tai ». Voir devient ainsi vouloir voir. On ajoute ensuite le petit mot poli.","say":{"tai":"たい"},"words":[["Dōtonbori","道頓堀"],["petit mot du complément","を"],["vouloir voir","見たい"],["être","です"]]}},{"fr":"Les néons sont vraiment lumineux.","tgt":"ネオンは本当に明るいです。","ro":"Neon wa hontō ni akarui desu.","lit":"néon · [thème] · vraiment · lumineux · être (poli)","note":{"lit":"néons, petit mot du thème, vraiment, lumineux, être","text":"Lumineux se dit « akarui ». C'est un adjectif en i. Son contraire veut dire sombre.","say":{"akarui":"明るい"},"words":[["néons","ネオン"],["petit mot du thème","は"],["vraiment","本当に"],["lumineux","明るい"],["être","です"]]}},{"fr":"Je veux une photo devant la grande enseigne.","tgt":"大きい看板の前で写真を撮りたいです。","ro":"Ōkii kanban no mae de shashin o toritai desu.","lit":"grand · enseigne · [possessif] · devant · [lieu] · photo · [objet] · prendre-vouloir · être (poli)","note":{"lit":"grand, enseigne, petit mot de liaison, devant, petit mot du lieu, photo, petit mot du complément, vouloir prendre, être","text":"Je veux prendre se dit « toritai ». C'est prendre, avec la fin du désir. Le lieu de la photo vient au début.","say":{"toritai":"撮りたい"},"words":[["grand","大きい"],["enseigne","看板"],["petit mot de liaison","の"],["devant","前"],["petit mot du lieu","で"],["photo","写真"],["petit mot du complément","を"],["vouloir prendre","撮りたい"],["être","です"]]}},{"fr":"J'ai un petit creux.","tgt":"おなかがすきました。","ro":"Onaka ga sukimashita.","lit":"ventre · [sujet] · se vider (passé, poli)","note":{"lit":"ventre, petit mot du sujet, se vider","text":"J'ai faim se dit mot à mot le ventre s'est vidé. Ventre se dit « onaka ». C'est la phrase à dire avant de chercher un restaurant.","say":{"onaka":"おなか"},"words":[["ventre","おなか"],["petit mot du sujet","が"],["se vider","すきました"]]}},{"fr":"Qu'est-ce que tu veux manger ?","tgt":"何を食べたいですか？","ro":"Nani o tabetai desu ka?","lit":"quoi · [objet] · manger-vouloir · être (poli) · [question]","note":{"lit":"quoi, petit mot du complément, vouloir manger, être, petit mot de question","text":"Vouloir manger se dit « tabetai ». Quoi se place avant, avec le petit mot du complément. La question vient à la fin.","say":{"tabetai":"食べたい"},"words":[["quoi","何"],["petit mot du complément","を"],["vouloir manger","食べたい"],["être","です"],["petit mot de question","か"]]}},{"fr":"Je veux manger des takoyaki.","tgt":"たこ焼きを食べたいです。","ro":"Takoyaki o tabetai desu.","lit":"takoyaki · [objet] · manger-vouloir · être (poli)","note":{"lit":"takoyaki, petit mot du complément, vouloir manger, être","text":"Les boulettes de poulpe se disent « takoyaki ». C'est la grande spécialité d'Osaka. On les mange brûlantes.","say":{"takoyaki":"たこ焼き"},"words":[["takoyaki","たこ焼き"],["petit mot du complément","を"],["vouloir manger","食べたい"],["être","です"]]}},{"fr":"Moi, je veux boire une bière.","tgt":"私はビールを飲みたいです。","ro":"Watashi wa bīru o nomitai desu.","lit":"moi · [thème] · bière · [objet] · boire-vouloir · être (poli)","note":{"lit":"moi, petit mot du thème, bière, petit mot du complément, vouloir boire, être","text":"Moi, en thème, marque le contraste avec l'autre. Lui veut manger, moi, je veux boire. Bière se dit « bīru ».","say":{"bīru":"ビール"},"words":[["moi","私"],["petit mot du thème","は"],["bière","ビール"],["petit mot du complément","を"],["vouloir boire","飲みたい"],["être","です"]]}},{"fr":"Je ne veux pas faire une longue queue.","tgt":"長い列には並びたくないです。","ro":"Nagai retsu ni wa narabitakunai desu.","lit":"long · file · [lieu] · [thème] · faire-la-queue-ne-pas-vouloir · être (poli)","note":{"lit":"long, file, dans, petit mot du thème, ne pas vouloir faire la queue, être","text":"Pour dire je ne veux pas, la fin devient « takunai ». Elle se nie comme un adjectif en i. Faire la queue se dit avec un verbe à part.","say":{"takunai":"たくない"},"words":[["long","長い"],["file","列"],["dans","に"],["petit mot du thème","は"],["ne pas vouloir faire la queue","並びたくない"],["être","です"]]}},{"fr":"Je veux monter sur le bateau.","tgt":"船に乗りたいです。","ro":"Fune ni noritai desu.","lit":"bateau · [dans] · monter-vouloir · être (poli)","note":{"lit":"bateau, dans, vouloir monter, être","text":"Bateau se dit « fune ». Comme pour le train, on dit monter dans. Le désir se met sur le verbe monter.","say":{"fune":"船"},"words":[["bateau","船"],["dans","に"],["vouloir monter","乗りたい"],["être","です"]]}},{"fr":"Osaka est vraiment animée.","tgt":"大阪は本当ににぎやかです。","ro":"Ōsaka wa hontō ni nigiyaka desu.","lit":"Osaka · [thème] · vraiment · animé · être (poli)","note":{"lit":"Osaka, petit mot du thème, vraiment, animé, être","text":"Osaka se dit avec un o long, « Ōsaka ». Les gens d'Osaka sont connus pour leur bonne humeur. Ici, vraiment renforce animé.","say":{"Ōsaka":"大阪"},"words":[["Osaka","大阪"],["petit mot du thème","は"],["vraiment","本当に"],["animé","にぎやか"],["être","です"]]}}],"tip":{"title":"« -tai desu » : dire ce qu'on veut faire","example":"Je veux manger des takoyaki. — たこ焼きを<b>食べたい</b>です。","body":"Pour dire « je veux faire quelque chose », le japonais n'utilise pas un verbe vouloir séparé : il colle l'envie directement au verbe. On prend la forme en « -masu », on enlève « -masu », et on met « -tai » à la place. « Tabemasu », manger, devient « tabetai », vouloir manger ; « mimasu », voir, devient « mitai », vouloir voir. On ajoute ensuite « desu » pour rester poli. « Takoyaki o tabetai desu » se dit littéralement : takoyaki, objet, manger-vouloir, être poli. Pour la négation, « -tai » devient « -takunai » : « Narabitakunai desu », je ne veux pas faire la queue. Et pour demander à quelqu'un ce qu'il veut, on ajoute simplement « ka » : « Nani o tabetai desu ka ? », qu'est-ce que tu veux manger ? Attention, on utilise surtout « -tai » pour parler de soi, ou dans une question directe à la personne concernée. Une astuce pour retenir : « tai » ressemble à « j'ai envie », un petit cri de désir au bout du verbe.","exampleRo":"Takoyaki o tabetai desu.","lit":"takoyaki · [objet] · manger-vouloir · être (poli)","say":{"Tabemasu":"食べます","tabetai":"食べたい","mimasu":"見ます","mitai":"見たい","desu":"です","Takoyaki o tabetai desu":"たこ焼きを食べたいです","Narabitakunai desu":"並びたくないです","ka":"か","Nani o tabetai desu ka ?":"何を食べたいですか","-masu":"ます","-takunai":"たくない"}}},{"title":"Takoyaki et okonomiyaki","phrases":[{"fr":"Deux barquettes de takoyaki, s'il vous plaît.","tgt":"たこ焼きを二つください。","ro":"Takoyaki o futatsu kudasai.","lit":"takoyaki · [objet] · deux (objets) · donnez-moi","note":{"lit":"takoyaki, petit mot du complément, deux, donnez-moi","text":"Deux, pour des objets, se dit « futatsu ». Le nombre se place après le complément, juste avant le verbe. C'est l'ordre habituel.","say":{"futatsu":"二つ"},"words":[["takoyaki","たこ焼き"],["petit mot du complément","を"],["deux","二つ"],["donnez-moi","ください"]]}},{"fr":"Attention, c'est brûlant !","tgt":"とても熱いです！","ro":"Totemo atsui desu!","lit":"très · chaud · être (poli)","note":{"lit":"très, brûlant, être","text":"Chaud, pour un objet ou un plat, se dit « atsui ». Ça se prononce comme chaud pour le temps qu'il fait. Ici, c'est un avertissement.","say":{"atsui":"熱い"},"words":[["très","とても"],["brûlant","熱い"],["être","です"]]}},{"fr":"À l'intérieur, c'est du poulpe.","tgt":"中はたこです。","ro":"Naka wa tako desu.","lit":"intérieur · [thème] · poulpe · être (poli)","note":{"lit":"intérieur, petit mot du thème, poulpe, être","text":"Poulpe se dit « tako ». On le retrouve dans le nom des boulettes. L'intérieur est mis en thème.","say":{"tako":"たこ"},"words":[["intérieur","中"],["petit mot du thème","は"],["poulpe","たこ"],["être","です"]]}},{"fr":"Ce soir, on mange des okonomiyaki.","tgt":"今晩はお好み焼きを食べます。","ro":"Konban wa okonomiyaki o tabemasu.","lit":"ce soir · [thème] · okonomiyaki · [objet] · manger (poli)","note":{"lit":"ce soir, petit mot du thème, okonomiyaki, petit mot du complément, manger","text":"L'okonomiyaki est une galette garnie. Son nom veut dire grillé comme on aime. Grillé se dit « yaki ».","say":{"yaki":"焼き"},"words":[["ce soir","今晩"],["petit mot du thème","は"],["okonomiyaki","お好み焼き"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"On les fait cuire soi-même.","tgt":"自分で焼きます。","ro":"Jibun de yakimasu.","lit":"soi-même · [moyen] · faire cuire (poli)","note":{"lit":"soi-même, petit mot du moyen, faire cuire","text":"Soi-même se dit « jibun de ». Mot à mot, c'est avec soi. Le petit mot du moyen sert ici.","say":{"jibun de":"自分で"},"words":[["soi-même","自分"],["petit mot du moyen","で"],["faire cuire","焼きます"]]}},{"fr":"Je mets du chou et du porc.","tgt":"キャベツと豚肉を入れます。","ro":"Kyabetsu to butaniku o iremasu.","lit":"chou · [et] · porc · [objet] · mettre (poli)","note":{"lit":"chou, et, porc, petit mot du complément, mettre","text":"Mettre dedans se dit « iremasu ». Chou et porc sont reliés par le petit mot et. Ils forment ensemble le complément.","say":{"iremasu":"入れます"},"words":[["chou","キャベツ"],["et","と"],["porc","豚肉"],["petit mot du complément","を"],["mettre","入れます"]]}},{"fr":"Ensuite, on verse la sauce.","tgt":"それから、ソースをかけます。","ro":"Sorekara, sōsu o kakemasu.","lit":"ensuite · sauce · [objet] · verser (poli)","note":{"lit":"ensuite, sauce, petit mot du complément, verser","text":"Verser sur un plat se dit « kakemasu ». On l'emploie pour la sauce ou la mayonnaise. Ensuite ouvre la phrase.","say":{"kakemasu":"かけます"},"words":[["ensuite","それから"],["sauce","ソース"],["petit mot du complément","を"],["verser","かけます"]]}},{"fr":"Ça sent vraiment bon.","tgt":"いいにおいです。","ro":"Ii nioi desu.","lit":"bon · odeur · être (poli)","note":{"lit":"bon, odeur, être","text":"Odeur se dit « nioi ». Ça sent bon se dit mot à mot c'est une bonne odeur. Pas besoin de verbe sentir.","say":{"nioi":"におい"},"words":[["bon","いい"],["odeur","におい"],["être","です"]]}},{"fr":"C'est la spécialité d'Osaka.","tgt":"大阪の名物です。","ro":"Ōsaka no meibutsu desu.","lit":"Osaka · [possessif] · spécialité · être (poli)","note":{"lit":"Osaka, petit mot de liaison, spécialité, être","text":"La spécialité d'une ville se dit « meibutsu ». Chaque région du Japon a les siennes. On les achète souvent en souvenir.","say":{"meibutsu":"名物"},"words":[["Osaka","大阪"],["petit mot de liaison","の"],["spécialité","名物"],["être","です"]]}},{"fr":"J'ai envie d'en remanger demain.","tgt":"明日もまた食べたいです。","ro":"Ashita mo mata tabetai desu.","lit":"demain · [aussi] · encore · manger-vouloir · être (poli)","note":{"lit":"demain, aussi, encore, vouloir manger, être","text":"Encore se dit « mata ». Demain aussi, encore, je veux manger. Les deux mots renforcent l'envie.","say":{"mata":"また"},"words":[["demain","明日"],["aussi","も"],["encore","また"],["vouloir manger","食べたい"],["être","です"]]}}]},{"title":"À la pharmacie","phrases":[{"fr":"Il y a une pharmacie près d'ici ?","tgt":"この近くに薬局がありますか？","ro":"Kono chikaku ni yakkyoku ga arimasu ka?","lit":"ce · environs · [lieu] · pharmacie · [sujet] · il y a (objets, poli) · [question]","note":{"lit":"ce, environs, petit mot du lieu, pharmacie, petit mot du sujet, il y a, petit mot de question","text":"Pharmacie se dit « yakkyoku ». Pour une chose qu'on cherche, on emploie le petit mot du sujet. Près d'ici se dit mot à mot ces environs.","say":{"yakkyoku":"薬局"},"words":[["ce","この"],["environs","近く"],["petit mot du lieu","に"],["pharmacie","薬局"],["petit mot du sujet","が"],["il y a","あります"],["petit mot de question","か"]]}},{"fr":"Oui, à côté de la gare.","tgt":"はい、駅の隣にあります。","ro":"Hai, eki no tonari ni arimasu.","lit":"oui · gare · [possessif] · à côté · [lieu] · se trouver (objets, poli)","note":{"lit":"oui, gare, petit mot de liaison, à côté, petit mot du lieu, se trouver","text":"À côté se dit « tonari ». On dit la gare, liaison, à côté. Le verbe des objets sert aussi pour les bâtiments.","say":{"tonari":"隣"},"words":[["oui","はい"],["gare","駅"],["petit mot de liaison","の"],["à côté","隣"],["petit mot du lieu","に"],["se trouver","あります"]]}},{"fr":"J'ai mal à la tête.","tgt":"頭が痛いです。","ro":"Atama ga itai desu.","lit":"tête · [sujet] · douloureux · être (poli)","note":{"lit":"tête, petit mot du sujet, douloureux, être","text":"Pour dire j'ai mal, on dit que la partie du corps est douloureuse. Douloureux se dit « itai ». La partie du corps prend le petit mot du sujet.","say":{"itai":"痛い"},"words":[["tête","頭"],["petit mot du sujet","が"],["douloureux","痛い"],["être","です"]]}},{"fr":"J'ai aussi un peu de fièvre.","tgt":"少し熱もあります。","ro":"Sukoshi netsu mo arimasu.","lit":"un peu · fièvre · [aussi] · il y a (objets, poli)","note":{"lit":"un peu, fièvre, aussi, il y a","text":"Fièvre se dit « netsu ». Pour avoir de la fièvre, on dit il y a de la fièvre. Aussi remplace ici le petit mot du sujet.","say":{"netsu":"熱"},"words":[["un peu","少し"],["fièvre","熱"],["aussi","も"],["il y a","あります"]]}},{"fr":"Depuis quand ?","tgt":"いつからですか？","ro":"Itsu kara desu ka?","lit":"quand · [de… à… : depuis] · être (poli) · [question]","note":{"lit":"quand, depuis, être, petit mot de question","text":"Depuis quand se dit « itsu kara ». C'est quand suivi de depuis. Le pharmacien le demande souvent.","say":{"itsu kara":"いつから"},"words":[["quand","いつ"],["depuis","から"],["être","です"],["petit mot de question","か"]]}},{"fr":"Depuis hier soir.","tgt":"昨日の夜からです。","ro":"Kinō no yoru kara desu.","lit":"hier · [possessif] · soir · [de… à… : depuis] · être (poli)","note":{"lit":"hier, petit mot de liaison, soir, depuis, être","text":"Soir ou nuit se dit « yoru ». Hier soir, c'est hier, liaison, soir. Depuis se place à la fin.","say":{"yoru":"夜"},"words":[["hier","昨日"],["petit mot de liaison","の"],["soir","夜"],["depuis","から"],["être","です"]]}},{"fr":"C'est ce médicament-ci qu'il vous faut.","tgt":"この薬がいいです。","ro":"Kono kusuri ga ii desu.","lit":"ce · médicament · [sujet] · bon · être (poli)","note":{"lit":"ce, médicament, petit mot du sujet, bon, être","text":"Pour désigner un choix parmi d'autres, on emploie « ga ». Ce médicament, et pas un autre, est le bon. Avec le petit mot du thème, ce serait une simple remarque.","say":{"ga":"が"},"words":[["ce","この"],["médicament","薬"],["petit mot du sujet","が"],["bon","いい"],["être","です"]]}},{"fr":"On en prend un après chaque repas.","tgt":"食後に一錠飲みます。","ro":"Shokugo ni ichijō nomimasu.","lit":"après-repas · [moment] · un-comprimé · avaler (poli)","note":{"lit":"après le repas, petit mot du moment, un comprimé, boire","text":"Pour les médicaments, on emploie le verbe boire. Boire se dit « nomimasu ». Après le repas se dit en un seul mot.","say":{"nomimasu":"飲みます"},"words":[["après le repas","食後"],["petit mot du moment","に"],["un comprimé","一錠"],["boire","飲みます"]]}},{"fr":"Mon ami, lui, a mal au ventre.","tgt":"友達はおなかが痛いです。","ro":"Tomodachi wa onaka ga itai desu.","lit":"ami · [thème] · ventre · [sujet] · douloureux · être (poli)","note":{"lit":"ami, petit mot du thème, ventre, petit mot du sujet, douloureux, être","text":"Cette phrase a les deux petits mots. Mon ami est le thème, « tomodachi wa ». Le ventre est le sujet de la douleur.","say":{"tomodachi wa":"友達は"},"words":[["ami","友達"],["petit mot du thème","は"],["ventre","おなか"],["petit mot du sujet","が"],["douloureux","痛い"],["être","です"]]}},{"fr":"Qui va à la pharmacie ?","tgt":"誰が薬局へ行きますか？","ro":"Dare ga yakkyoku e ikimasu ka?","lit":"qui · [sujet] · pharmacie · [direction] · aller (poli) · [question]","note":{"lit":"qui, petit mot du sujet, pharmacie, vers, aller, petit mot de question","text":"Qui, comme sujet, se dit toujours « dare ga ». On ne peut pas le mettre en thème. C'est une règle sûre pour les questions.","say":{"dare ga":"誰が"},"words":[["qui","誰"],["petit mot du sujet","が"],["pharmacie","薬局"],["vers","へ"],["aller","行きます"],["petit mot de question","か"]]}}],"tip":{"title":"« Ga » : la particule du sujet, et la différence avec « wa »","example":"J'ai mal à la tête. — 頭<b>が</b>痛いです。","body":"Vous connaissez « wa », qui annonce le thème, ce dont on parle, un peu comme « quant à ». « Ga », lui, désigne le sujet précis d'une action ou d'un état, souvent une information nouvelle sur laquelle on met l'accent. « Atama ga itai desu » se dit littéralement : tête, sujet, douloureux, être poli ; autrement dit, c'est la tête qui fait mal. Les deux peuvent même cohabiter : « Tomodachi wa onaka ga itai desu », quant à mon ami, c'est le ventre qui lui fait mal. Retenez trois cas où « ga » s'impose : après un mot interrogatif, comme « Dare ga ikimasu ka ? », qui y va ; avec « arimasu » et « imasu » pour dire ce qui se trouve quelque part, comme « Yakkyoku ga arimasu » ; et pour les sensations, comme « Onaka ga itai desu ». Dans le doute, pas de panique : on vous comprendra toujours, même si vous confondez. Une astuce pour retenir : « wa » allume le décor de la scène, « ga » pointe le doigt sur l'acteur.","exampleRo":"Atama ga itai desu.","lit":"tête · [sujet] · douloureux · être (poli)","say":{"Ga":"が","wa":"わ","Atama ga itai desu":"頭が痛いです","Tomodachi wa onaka ga itai desu":"友達はおなかが痛いです","ga":"が","Dare ga ikimasu ka ?":"誰が行きますか","arimasu":"あります","imasu":"います","Yakkyoku ga arimasu":"薬局があります","Onaka ga itai desu":"おなかが痛いです"}}},{"title":"Changer de l'argent","phrases":[{"fr":"Je voudrais changer des euros en yens.","tgt":"ユーロを円に両替したいです。","ro":"Yūro o en ni ryōgae shitai desu.","lit":"euro · [objet] · yen · [direction] · change · faire-vouloir · être (poli)","note":{"lit":"euros, petit mot du complément, yens, vers, change, vouloir faire, être","text":"Changer de l'argent se dit « ryōgae ». On ajoute faire pour en faire un verbe. Ici, avec la fin du désir.","say":{"ryōgae":"両替"},"words":[["euros","ユーロ"],["petit mot du complément","を"],["yens","円"],["vers","に"],["change","両替"],["vouloir faire","したい"],["être","です"]]}},{"fr":"Le bureau de change est au premier étage.","tgt":"両替所は二階です。","ro":"Ryōgaejo wa nikai desu.","lit":"bureau-de-change · [thème] · deuxième-niveau · être (poli)","note":{"lit":"bureau de change, petit mot du thème, premier étage, être","text":"Bureau de change se dit « ryōgaejo ». C'est change suivi d'un mot qui veut dire endroit. Premier étage, ici, c'est le deuxième niveau.","say":{"ryōgaejo":"両替所"},"words":[["bureau de change","両替所"],["petit mot du thème","は"],["premier étage","二階"],["être","です"]]}},{"fr":"Cent euros, ça fait combien de yens ?","tgt":"百ユーロは何円ですか？","ro":"Hyaku yūro wa nan'en desu ka?","lit":"cent-euros · [thème] · combien-de-yens · être (poli) · [question]","note":{"lit":"cent, euros, petit mot du thème, combien de yens, être, petit mot de question","text":"Combien de yens se dit « nan'en ». C'est quoi suivi de yen. On le comprend tout de suite au guichet.","say":{"nan'en":"何円"},"words":[["cent","百"],["euros","ユーロ"],["petit mot du thème","は"],["combien de yens","何円"],["être","です"],["petit mot de question","か"]]}},{"fr":"Environ seize mille yens.","tgt":"約一万六千円です。","ro":"Yaku ichiman rokusen en desu.","lit":"environ · seize-mille-yens · être (poli)","note":{"lit":"environ, dix mille, six mille, yen, être","text":"Environ se dit « yaku ». Seize mille, c'est un dix mille et six mille. Les Japonais comptent par dix mille.","say":{"yaku":"約"},"words":[["environ","約"],["dix mille","一万"],["six mille","六千"],["yen","円"],["être","です"]]}},{"fr":"Au Japon, on paie souvent en liquide.","tgt":"日本では現金をよく使います。","ro":"Nihon de wa genkin o yoku tsukaimasu.","lit":"Japon · [lieu] · [thème] · argent-liquide · [objet] · souvent · utiliser (poli)","note":{"lit":"Japon, petit mot du lieu, petit mot du thème, liquide, petit mot du complément, souvent, utiliser","text":"L'argent liquide se dit « genkin ». Utiliser se place à la fin, et souvent juste avant. Au Japon, beaucoup de petits commerces le préfèrent.","say":{"genkin":"現金"},"words":[["Japon","日本"],["petit mot du lieu","で"],["petit mot du thème","は"],["liquide","現金"],["petit mot du complément","を"],["souvent","よく"],["utiliser","使います"]]}},{"fr":"Il y a une banque près de la gare.","tgt":"駅の近くに銀行があります。","ro":"Eki no chikaku ni ginkō ga arimasu.","lit":"gare · [possessif] · environs · [lieu] · banque · [sujet] · il y a (objets, poli)","note":{"lit":"gare, petit mot de liaison, environs, petit mot du lieu, banque, petit mot du sujet, il y a","text":"Près de se dit mot à mot les environs de. Environs se dit « chikaku ». Il suit la gare et le petit mot de liaison.","say":{"chikaku":"近く"},"words":[["gare","駅"],["petit mot de liaison","の"],["environs","近く"],["petit mot du lieu","に"],["banque","銀行"],["petit mot du sujet","が"],["il y a","あります"]]}},{"fr":"Cette carte ne marche pas ?","tgt":"このカードはだめですか？","ro":"Kono kādo wa dame desu ka?","lit":"ce · carte · [thème] · pas bon · être (poli) · [question]","note":{"lit":"ce, carte, petit mot du thème, pas bon, être, petit mot de question","text":"Carte se dit « kādo ». Pour demander si elle ne marche pas, on dit pas bon. C'est une façon simple et directe.","say":{"kādo":"カード"},"words":[["ce","この"],["carte","カード"],["petit mot du thème","は"],["pas bon","だめ"],["être","です"],["petit mot de question","か"]]}},{"fr":"Alors je paie en espèces.","tgt":"じゃあ、現金で払います。","ro":"Jā, genkin de haraimasu.","lit":"alors · argent-liquide · [moyen] · payer (poli)","note":{"lit":"alors, liquide, petit mot du moyen, payer","text":"Alors, à l'oral, se dit « jā ». On l'emploie pour enchaîner sur une décision. Payer se place à la fin.","say":{"jā":"じゃあ"},"words":[["alors","じゃあ"],["liquide","現金"],["petit mot du moyen","で"],["payer","払います"]]}},{"fr":"Je n'ai pas de petite monnaie.","tgt":"小銭がありません。","ro":"Kozeni ga arimasen.","lit":"petite-monnaie · [sujet] · il y a (négatif, poli)","note":{"lit":"petite monnaie, petit mot du sujet, il n'y a pas","text":"La petite monnaie se dit « kozeni ». Je n'ai pas se dit il n'y a pas. Le japonais n'a pas besoin du verbe avoir.","say":{"kozeni":"小銭"},"words":[["petite monnaie","小銭"],["petit mot du sujet","が"],["il n'y a pas","ありません"]]}},{"fr":"Un billet de dix mille yens, ça va ?","tgt":"一万円札でいいですか？","ro":"Ichiman en satsu de ii desu ka?","lit":"dix-mille-yens-billet · [moyen] · bien · être (poli) · [question]","note":{"lit":"dix mille, yen, billet, petit mot du moyen, bien, être, petit mot de question","text":"Billet de banque se dit « satsu ». Avec ça, ça va se dit mot à mot avec, c'est bien. On le demande avant de payer avec un gros billet.","say":{"satsu":"札"},"words":[["dix mille","一万"],["yen","円"],["billet","札"],["petit mot du moyen","で"],["bien","いい"],["être","です"],["petit mot de question","か"]]}}]},{"title":"En bus ou en taxi ?","phrases":[{"fr":"Je vais à l'hôtel en bus.","tgt":"バスでホテルへ行きます。","ro":"Basu de hoteru e ikimasu.","lit":"bus · [moyen] · hôtel · [direction] · aller (poli)","note":{"lit":"bus, petit mot du moyen, hôtel, vers, aller","text":"Beaucoup de mots viennent de l'anglais. Hôtel se dit « hoteru ». On ajoute une voyelle à la fin, à la japonaise.","say":{"hoteru":"ホテル"},"words":[["bus","バス"],["petit mot du moyen","で"],["hôtel","ホテル"],["vers","へ"],["aller","行きます"]]}},{"fr":"L'arrêt de bus est en face.","tgt":"バス停は向こうです。","ro":"Basutei wa mukō desu.","lit":"bus-arrêt · [thème] · en face · être (poli)","note":{"lit":"bus, arrêt, petit mot du thème, en face, être","text":"Arrêt de bus se dit « basutei ». C'est bus suivi d'un mot qui veut dire arrêt. En face se dit avec un mot qui veut dire de l'autre côté.","say":{"basutei":"バス停"},"words":[["bus","バス"],["arrêt","停"],["petit mot du thème","は"],["en face","向こう"],["être","です"]]}},{"fr":"Le bus coûte deux cent trente yens.","tgt":"バスは二百三十円です。","ro":"Basu wa nihyaku sanjū en desu.","lit":"bus · [thème] · deux-cent-trente-yens · être (poli)","note":{"lit":"bus, petit mot du thème, deux cents, trente, yen, être","text":"Bus se dit « basu ». C'est l'anglais avec une voyelle ajoutée. Le prix suit, comme toujours avec yen.","say":{"basu":"バス"},"words":[["bus","バス"],["petit mot du thème","は"],["deux cents","二百"],["trente","三十"],["yen","円"],["être","です"]]}},{"fr":"On monte par la porte arrière.","tgt":"後ろのドアから乗ります。","ro":"Ushiro no doa kara norimasu.","lit":"arrière · [possessif] · porte · [de… à… : depuis] · monter (poli)","note":{"lit":"arrière, petit mot de liaison, porte, depuis, monter","text":"Porte se dit « doa ». On monte par se dit monter depuis. Dans beaucoup de bus, on monte à l'arrière.","say":{"doa":"ドア"},"words":[["arrière","後ろ"],["petit mot de liaison","の"],["porte","ドア"],["depuis","から"],["monter","乗ります"]]}},{"fr":"Oh non, le bus est plein.","tgt":"あ、バスは満員です。","ro":"A, basu wa man'in desu.","lit":"oh · bus · [thème] · plein · être (poli)","note":{"lit":"oh, bus, petit mot du thème, plein, être","text":"Plein, pour un transport, se dit « man'in ». Mot à mot, c'est plein de membres. On l'entend souvent aux heures de pointe.","say":{"man'in":"満員"},"words":[["oh","あ"],["bus","バス"],["petit mot du thème","は"],["plein","満員"],["être","です"]]}},{"fr":"Alors, prenons un taxi.","tgt":"じゃあ、タクシーに乗りましょう。","ro":"Jā, takushī ni norimashō.","lit":"alors · taxi · [dans] · monter (proposition)","note":{"lit":"alors, taxi, dans, monter","text":"Taxi se dit « takushī ». Prendre un taxi se dit monter dans le taxi. On le propose avec la fin du verbe en allons.","say":{"takushī":"タクシー"},"words":[["alors","じゃあ"],["taxi","タクシー"],["dans","に"],["monter","乗りましょう"]]}},{"fr":"La portière est automatique.","tgt":"ドアは自動です。","ro":"Doa wa jidō desu.","lit":"portière · [thème] · automatique · être (poli)","note":{"lit":"portière, petit mot du thème, automatique, être","text":"Automatique se dit « jidō ». Au Japon, la portière du taxi s'ouvre toute seule. Pas besoin de la toucher.","say":{"jidō":"自動"},"words":[["portière","ドア"],["petit mot du thème","は"],["automatique","自動"],["être","です"]]}},{"fr":"À la gare de Kyoto, s'il vous plaît.","tgt":"京都駅までお願いします。","ro":"Kyōto eki made onegaishimasu.","lit":"Kyoto-gare · [de… à… : jusqu'à] · s'il vous plaît (poli)","note":{"lit":"gare de Kyoto, jusqu'à, je vous le demande","text":"Pour donner une destination au taxi, on dit le lieu suivi de « made ». Puis on ajoute s'il vous plaît. C'est tout ce qu'il faut.","say":{"made":"まで"},"words":[["gare de Kyoto","京都駅"],["jusqu'à","まで"],["je vous le demande","お願いします"]]}},{"fr":"La carte de crédit, c'est possible ?","tgt":"クレジットカードは大丈夫ですか？","ro":"Kurejitto kādo wa daijōbu desu ka?","lit":"carte-de-crédit · [thème] · ça va · être (poli) · [question]","note":{"lit":"carte de crédit, petit mot du thème, ça va, être, petit mot de question","text":"Carte de crédit se dit « kurejitto kādo ». Ce sont deux mots anglais adaptés. Pour demander si c'est possible, on dit ça va.","say":{"kurejitto kādo":"クレジットカード"},"words":[["carte de crédit","クレジットカード"],["petit mot du thème","は"],["ça va","大丈夫"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, aucun problème.","tgt":"はい、大丈夫です。","ro":"Hai, daijōbu desu.","lit":"oui · ça va · être (poli)","note":{"lit":"oui, ça va, être","text":"Ça va, aucun problème, se dit « daijōbu ». C'est un mot très utile au quotidien. Il sert pour rassurer ou pour demander.","say":{"daijōbu":"大丈夫"},"words":[["oui","はい"],["ça va","大丈夫"],["être","です"]]}}],"tip":{"title":"Les mots étrangers en katakana : « hoteru, basu, takushī »","example":"Je vais à l'hôtel en bus. — <b>バス</b>で<b>ホテル</b>へ行きます。","body":"Le japonais a emprunté des milliers de mots à l'étranger, et il les écrit en katakana. C'est une excellente nouvelle pour vous : beaucoup de ces mots vous sembleront familiers, à condition de les écouter avec une oreille japonaise. En effet, une syllabe japonaise se termine presque toujours par une voyelle, alors on en ajoute une là où le mot d'origine n'en a pas. Le bus devient « basu », l'hôtel devient « hoteru », le taxi devient « takushī ». Comme le son « l » n'existe pas, il devient un « r ». « Basu de hoteru e ikimasu » se dit littéralement : bus, moyen, hôtel, direction, aller poliment. Le japonais a même emprunté quelques mots au français, comme « kurowassan », le croissant. D'autres exemples utiles en voyage : « doa » (la porte), « kādo » (la carte), « sūtsukēsu » (la valise). Une astuce : quand un mot vous manque, essayez de dire le mot français lentement en ajoutant un petit « u » ou un « o » à la fin ; ça marche étonnamment souvent.","exampleRo":"Basu de hoteru e ikimasu.","lit":"bus · [moyen] · hôtel · [direction] · aller (poli)","say":{"basu":"バス","hoteru":"ホテル","takushī":"タクシー","Basu de hoteru e ikimasu":"バスでホテルへ行きます","kurowassan":"クロワッサン","doa":"ドア","kādo":"カード","sūtsukēsu":"スーツケース","hoteru, basu, takushī":"ホテル、バス、タクシー"}}},{"title":"Un retard de shinkansen","phrases":[{"fr":"Le shinkansen est en retard.","tgt":"新幹線が遅れました。","ro":"Shinkansen ga okuremashita.","lit":"shinkansen · [sujet] · prendre du retard (passé, poli)","note":{"lit":"shinkansen, petit mot du sujet, prendre du retard","text":"Le train a pris du retard se dit « okuremashita ». Le verbe est au passé, car le retard est déjà là. Le train prend le petit mot du sujet.","say":{"okuremashita":"遅れました"},"words":[["shinkansen","新幹線"],["petit mot du sujet","が"],["prendre du retard","遅れました"]]}},{"fr":"Le vent est fort aujourd'hui.","tgt":"今日は風が強いです。","ro":"Kyō wa kaze ga tsuyoi desu.","lit":"aujourd'hui · [thème] · vent · [sujet] · fort · être (poli)","note":{"lit":"aujourd'hui, petit mot du thème, vent, petit mot du sujet, fort, être","text":"Vent se dit « kaze ». Aujourd'hui est le thème, et le vent le sujet. C'est une structure très courante.","say":{"kaze":"風"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["vent","風"],["petit mot du sujet","が"],["fort","強い"],["être","です"]]}},{"fr":"Combien de minutes de retard ?","tgt":"何分遅れますか？","ro":"Nanpun okuremasu ka?","lit":"combien-de-minutes · prendre du retard (poli) · [question]","note":{"lit":"combien de minutes, prendre du retard, petit mot de question","text":"Combien de minutes se dit « nanpun ». C'est quoi suivi du mot minute. Le son du mot minute change un peu ici.","say":{"nanpun":"何分"},"words":[["combien de minutes","何分"],["prendre du retard","遅れます"],["petit mot de question","か"]]}},{"fr":"Environ trente minutes.","tgt":"三十分ぐらいです。","ro":"Sanjuppun gurai desu.","lit":"trente-minutes · environ · être (poli)","note":{"lit":"trente minutes, environ, être","text":"Environ, après un nombre, se dit « gurai ». Il se place après la durée. C'est très courant à l'oral.","say":{"gurai":"ぐらい"},"words":[["trente minutes","三十分"],["environ","ぐらい"],["être","です"]]}},{"fr":"Au Japon, c'est rare.","tgt":"日本ではめずらしいです。","ro":"Nihon de wa mezurashii desu.","lit":"Japon · [lieu] · [thème] · rare · être (poli)","note":{"lit":"Japon, petit mot du lieu, petit mot du thème, rare, être","text":"Rare se dit « mezurashii ». Les retards sont rares au Japon. Au Japon est mis en thème pour le contraste.","say":{"mezurashii":"めずらしい"},"words":[["Japon","日本"],["petit mot du lieu","で"],["petit mot du thème","は"],["rare","めずらしい"],["être","です"]]}},{"fr":"Je vais rater ma correspondance.","tgt":"乗り換えに間に合いません。","ro":"Norikae ni maniaimasen.","lit":"correspondance · [pour] · être à temps (négatif, poli)","note":{"lit":"correspondance, pour, ne pas être à temps","text":"Ne pas être à temps se dit « maniaimasen ». C'est la négation polie du verbe. La correspondance se place avant, avec un petit mot qui veut dire pour.","say":{"maniaimasen":"間に合いません"},"words":[["correspondance","乗り換え"],["pour","に"],["ne pas être à temps","間に合いません"]]}},{"fr":"Allons au guichet.","tgt":"窓口へ行きましょう。","ro":"Madoguchi e ikimashō.","lit":"guichet · [direction] · aller (proposition)","note":{"lit":"guichet, vers, aller","text":"Le guichet se dit « madoguchi ». Mot à mot, c'est la bouche de la fenêtre. On y va pour changer un billet.","say":{"madoguchi":"窓口"},"words":[["guichet","窓口"],["vers","へ"],["aller","行きましょう"]]}},{"fr":"Le prochain train est à quelle heure ?","tgt":"次の電車は何時ですか？","ro":"Tsugi no densha wa nanji desu ka?","lit":"prochain · [possessif] · train · [thème] · quelle-heure · être (poli) · [question]","note":{"lit":"prochain, petit mot de liaison, train, petit mot du thème, quelle heure, être, petit mot de question","text":"Le prochain train se dit « tsugi no densha ». Prochain se place avant, avec le petit mot de liaison. Quelle heure vient ensuite.","say":{"tsugi no densha":"次の電車"},"words":[["prochain","次"],["petit mot de liaison","の"],["train","電車"],["petit mot du thème","は"],["quelle heure","何時"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est à quatre heures dix.","tgt":"四時十分です。","ro":"Yoji juppun desu.","lit":"quatre-heures · dix-minutes · être (poli)","note":{"lit":"quatre heures, dix minutes, être","text":"Dix minutes se dit « juppun ». Le son change un peu après dix. Les minutes se placent après l'heure.","say":{"juppun":"十分"},"words":[["quatre heures","四時"],["dix minutes","十分"],["être","です"]]}},{"fr":"Bon, j'attends au café.","tgt":"じゃあ、喫茶店で待ちます。","ro":"Jā, kissaten de machimasu.","lit":"alors · café · [lieu] · attendre (poli)","note":{"lit":"alors, café, petit mot du lieu, attendre","text":"Un café, le lieu, se dit « kissaten ». C'est un salon de thé à l'ancienne. La boisson, elle, se dit autrement.","say":{"kissaten":"喫茶店"},"words":[["alors","じゃあ"],["café","喫茶店"],["petit mot du lieu","で"],["attendre","待ちます"]]}}]},{"title":"Perdu dans Osaka","phrases":[{"fr":"Excusez-moi, je me suis perdu.","tgt":"すみません、道に迷いました。","ro":"Sumimasen, michi ni mayoimashita.","lit":"excusez-moi · chemin · [lieu] · s'égarer (passé, poli)","note":{"lit":"excusez-moi, chemin, petit mot du lieu, s'égarer","text":"Se perdre se dit mot à mot s'égarer sur le chemin. Je me suis perdu se dit « mayoimashita ». Le verbe est au passé.","say":{"mayoimashita":"迷いました"},"words":[["excusez-moi","すみません"],["chemin","道"],["petit mot du lieu","に"],["s'égarer","迷いました"]]}},{"fr":"Le château d'Osaka, c'est par où ?","tgt":"大阪城はどちらですか？","ro":"Ōsakajō wa dochira desu ka?","lit":"Osaka-château · [thème] · quelle direction · être (poli) · [question]","note":{"lit":"château d'Osaka, petit mot du thème, par où, être, petit mot de question","text":"Par où, poliment, se dit « dochira ». C'est plus poli que où. On l'emploie avec les inconnus.","say":{"dochira":"どちら"},"words":[["château d'Osaka","大阪城"],["petit mot du thème","は"],["par où","どちら"],["être","です"],["petit mot de question","か"]]}},{"fr":"Attendez un petit instant, s'il vous plaît.","tgt":"ちょっと待ってください。","ro":"Chotto matte kudasai.","lit":"un peu · attendre (forme en -te) · s'il vous plaît","note":{"lit":"un peu, attendre, s'il vous plaît","text":"Pour demander poliment, on met le verbe à une forme spéciale, puis on dit « kudasai ». Attendre devient ainsi attendez, s'il vous plaît. Un peu adoucit la demande.","say":{"kudasai":"ください"},"words":[["un peu","ちょっと"],["attendre","待って"],["s'il vous plaît","ください"]]}},{"fr":"Montrez-moi sur le plan, s'il vous plaît.","tgt":"地図で教えてください。","ro":"Chizu de oshiete kudasai.","lit":"plan · [moyen] · indiquer (forme en -te) · s'il vous plaît","note":{"lit":"plan, petit mot du moyen, montrer, s'il vous plaît","text":"Montrer ou expliquer se dit ici « oshiete ». C'est la forme du verbe qui va avec la demande polie. Le plan prend le petit mot du moyen.","say":{"oshiete":"教えて"},"words":[["plan","地図"],["petit mot du moyen","で"],["montrer","教えて"],["s'il vous plaît","ください"]]}},{"fr":"Répétez encore une fois, s'il vous plaît.","tgt":"もう一度言ってください。","ro":"Mō ichido itte kudasai.","lit":"encore · une-fois · dire (forme en -te) · s'il vous plaît","note":{"lit":"encore, une fois, dire, s'il vous plaît","text":"Dites, s'il vous plaît, se dit « itte kudasai ». Encore une fois se place devant. C'est très utile quand on n'a pas compris.","say":{"itte kudasai":"言ってください"},"words":[["encore","もう"],["une fois","一度"],["dire","言って"],["s'il vous plaît","ください"]]}},{"fr":"Parlez lentement, s'il vous plaît.","tgt":"ゆっくり話してください。","ro":"Yukkuri hanashite kudasai.","lit":"lentement · parler (forme en -te) · s'il vous plaît","note":{"lit":"lentement, parler, s'il vous plaît","text":"Lentement se dit « yukkuri ». Il se place avant le verbe. Parlez, c'est le verbe parler à la forme de la demande.","say":{"yukkuri":"ゆっくり"},"words":[["lentement","ゆっくり"],["parler","話して"],["s'il vous plaît","ください"]]}},{"fr":"Allez tout droit.","tgt":"まっすぐ行ってください。","ro":"Massugu itte kudasai.","lit":"tout droit · aller (forme en -te) · s'il vous plaît","note":{"lit":"tout droit, aller, s'il vous plaît","text":"Tout droit se dit « massugu ». On l'entend dans toutes les explications de chemin. Allez se dit avec le verbe aller, à la forme de la demande.","say":{"massugu":"まっすぐ"},"words":[["tout droit","まっすぐ"],["aller","行って"],["s'il vous plaît","ください"]]}},{"fr":"Au feu, tournez à droite.","tgt":"信号を右に曲がってください。","ro":"Shingō o migi ni magatte kudasai.","lit":"feu · [objet : lieu traversé] · droite · [direction] · tourner (forme en -te) · s'il vous plaît","note":{"lit":"feu, petit mot du complément, droite, vers, tourner, s'il vous plaît","text":"Droite se dit « migi ». Le feu prend le petit mot du complément, car on passe par là. Tourner vient à la fin, avec la demande polie.","say":{"migi":"右"},"words":[["feu","信号"],["petit mot du complément","を"],["droite","右"],["vers","に"],["tourner","曲がって"],["s'il vous plaît","ください"]]}},{"fr":"Le temple est loin d'ici ?","tgt":"お寺はここから遠いですか？","ro":"Otera wa koko kara tōi desu ka?","lit":"honorable-temple · [thème] · ici · [à partir de] · loin · être (poli) · [question]","note":{"lit":"temple, petit mot du thème, ici, depuis, loin, être, petit mot de question","text":"Loin d'ici se dit mot à mot depuis ici, loin. Depuis se dit « kara ». Il se place juste après ici.","say":{"kara":"から"},"words":[["temple","お寺"],["petit mot du thème","は"],["ici","ここ"],["depuis","から"],["loin","遠い"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, c'est à dix minutes à pied.","tgt":"いいえ、歩いて十分です。","ro":"Iie, aruite juppun desu.","lit":"non · en marchant · dix-minutes · être (poli)","note":{"lit":"non, à pied, dix minutes, être","text":"À pied se dit « aruite ». C'est le verbe marcher, à la même forme que pour la demande. Ici, il veut dire en marchant.","say":{"aruite":"歩いて"},"words":[["non","いいえ"],["à pied","歩いて"],["dix minutes","十分"],["être","です"]]}}],"tip":{"title":"La forme en « -te » + « kudasai » : demander poliment","example":"Répétez encore une fois, s'il vous plaît. — もう一度<b>言ってください</b>。","body":"Vous savez déjà demander un objet avec « kudasai ». Pour demander à quelqu'un de faire une action, on place devant « kudasai » le verbe à une forme spéciale, la forme en « -te ». Pour beaucoup de verbes, c'est facile : « tabemasu », manger, donne « tabete » ; « mimasu », regarder, donne « mite ». D'autres changent un peu : « machimasu », attendre, donne « matte » ; « iimasu », dire, donne « itte » ; « hanashimasu », parler, donne « hanashite ». « Mō ichido itte kudasai » se dit littéralement : encore, une fois, dire, s'il vous plaît. Petite curiosité : « ikimasu », aller, donne aussi « itte », d'où « Massugu itte kudasai », allez tout droit ; c'est le contexte qui fait la différence. Gardez sous la main ces trois phrases de survie : « Chotto matte kudasai », attendez un instant, « Yukkuri hanashite kudasai », parlez lentement, et « Mō ichido itte kudasai ». Une astuce pour retenir : la forme en « -te » tend la main vers l'autre, et « kudasai » dit merci d'avance.","exampleRo":"Mō ichido itte kudasai.","lit":"encore · une-fois · dire (forme en -te) · s'il vous plaît","say":{"kudasai":"ください","tabemasu":"食べます","tabete":"食べて","mimasu":"見ます","mite":"見て","machimasu":"待ちます","matte":"待って","iimasu":"言います","itte":"言って","hanashimasu":"話します","hanashite":"話して","Mō ichido itte kudasai":"もう一度言ってください","ikimasu":"行きます","Massugu itte kudasai":"まっすぐ行ってください","Chotto matte kudasai":"ちょっと待ってください","Yukkuri hanashite kudasai":"ゆっくり話してください"}}},{"title":"Des souvenirs pour la famille","phrases":[{"fr":"Je veux acheter des souvenirs.","tgt":"お土産を買いたいです。","ro":"Omiyage o kaitai desu.","lit":"souvenir-cadeau · [objet] · acheter-vouloir · être (poli)","note":{"lit":"souvenir, petit mot du complément, vouloir acheter, être","text":"Vouloir acheter se dit « kaitai ». C'est acheter avec la fin du désir. Les souvenirs sont très importants au Japon.","say":{"kaitai":"買いたい"},"words":[["souvenir","お土産"],["petit mot du complément","を"],["vouloir acheter","買いたい"],["être","です"]]}},{"fr":"Les gâteaux de Kyoto ont beaucoup de succès.","tgt":"京都のお菓子は人気があります。","ro":"Kyōto no okashi wa ninki ga arimasu.","lit":"Kyoto · [possessif] · honorable-gâteau · [thème] · popularité · [sujet] · il y a (objets, poli)","note":{"lit":"Kyoto, petit mot de liaison, gâteaux, petit mot du thème, popularité, petit mot du sujet, il y a","text":"Avoir du succès se dit mot à mot il y a de la popularité. Popularité se dit « ninki ». C'est une tournure très courante.","say":{"ninki":"人気"},"words":[["Kyoto","京都"],["petit mot de liaison","の"],["gâteaux","お菓子"],["petit mot du thème","は"],["popularité","人気"],["petit mot du sujet","が"],["il y a","あります"]]}},{"fr":"Ces yatsuhashi, s'il vous plaît.","tgt":"この八つ橋をください。","ro":"Kono yatsuhashi o kudasai.","lit":"ce · yatsuhashi · [objet] · donnez-moi","note":{"lit":"ce, yatsuhashi, petit mot du complément, donnez-moi","text":"Le yatsuhashi est un gâteau de riz à la cannelle. C'est le souvenir typique de Kyoto. Pour l'acheter, on dit ce, puis « kudasai ».","say":{"kudasai":"ください"},"words":[["ce","この"],["yatsuhashi","八つ橋"],["petit mot du complément","を"],["donnez-moi","ください"]]}},{"fr":"C'est un cadeau pour ma famille.","tgt":"家族のお土産です。","ro":"Kazoku no omiyage desu.","lit":"famille · [possessif] · souvenir-cadeau · être (poli)","note":{"lit":"famille, petit mot de liaison, souvenir, être","text":"Famille se dit « kazoku ». Un cadeau pour la famille se dit souvenir de la famille. Le petit mot de liaison suffit.","say":{"kazoku":"家族"},"words":[["famille","家族"],["petit mot de liaison","の"],["souvenir","お土産"],["être","です"]]}},{"fr":"Pouvez-vous l'emballer, s'il vous plaît ?","tgt":"包んでください。","ro":"Tsutsunde kudasai.","lit":"emballer (forme en -te) · s'il vous plaît","note":{"lit":"emballer, s'il vous plaît","text":"Emballer se dit ici « tsutsunde ». C'est la forme du verbe qui va avec la demande polie. Au Japon, l'emballage est un vrai art.","say":{"tsutsunde":"包んで"},"words":[["emballer","包んで"],["s'il vous plaît","ください"]]}},{"fr":"Un sac de plus, s'il vous plaît.","tgt":"袋をもう一枚ください。","ro":"Fukuro o mō ichimai kudasai.","lit":"sac · [objet] · encore · une-feuille · donnez-moi","note":{"lit":"sac, petit mot du complément, encore, un, donnez-moi","text":"Sac se dit « fukuro ». Un sac de plus se dit encore un. Le petit mot de comptage est celui des choses plates.","say":{"fukuro":"袋"},"words":[["sac","袋"],["petit mot du complément","を"],["encore","もう"],["un","一枚"],["donnez-moi","ください"]]}},{"fr":"Cet éventail est très joli.","tgt":"この扇子はとてもきれいです。","ro":"Kono sensu wa totemo kirei desu.","lit":"ce · éventail · [thème] · très · joli · être (poli)","note":{"lit":"ce, éventail, petit mot du thème, très, joli, être","text":"Éventail se dit « sensu ». C'est l'éventail pliant traditionnel. On en vend beaucoup à Kyoto.","say":{"sensu":"扇子"},"words":[["ce","この"],["éventail","扇子"],["petit mot du thème","は"],["très","とても"],["joli","きれい"],["être","です"]]}},{"fr":"Il coûte trois mille cinq cents yens.","tgt":"三千五百円です。","ro":"Sanzen gohyaku en desu.","lit":"trois-mille-cinq-cents-yens · être (poli)","note":{"lit":"trois mille, cinq cents, yen, être","text":"On dit trois mille, puis cinq cents. Trois mille se dit « sanzen ». Le mot mille change de son après trois.","say":{"sanzen":"三千"},"words":[["trois mille","三千"],["cinq cents","五百"],["yen","円"],["être","です"]]}},{"fr":"Hum, c'est un peu cher.","tgt":"うーん、ちょっと高いです。","ro":"Ūn, chotto takai desu.","lit":"hum · un peu · cher · être (poli)","note":{"lit":"hum, un peu, cher, être","text":"Un peu se dit « chotto ». C'est aussi une façon polie de dire non. Ici, il adoucit la critique.","say":{"chotto":"ちょっと"},"words":[["hum","うーん"],["un peu","ちょっと"],["cher","高い"],["être","です"]]}},{"fr":"Tant pis, je l'achète !","tgt":"でも、買います！","ro":"Demo, kaimasu!","lit":"mais · acheter (poli)","note":{"lit":"mais, acheter","text":"Mais se dit « demo ». Ici, il veut dire tant pis. Acheter au présent suffit.","say":{"demo":"でも"},"words":[["mais","でも"],["acheter","買います"]]}}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"C'était un beau voyage, hein ?","tgt":"いい旅行でしたね。","ro":"Ii ryokō deshita ne.","lit":"bon · voyage · être (passé, poli) · [n'est-ce pas]","note":{"lit":"bon, voyage, petit mot du passé, petit mot d'accord","text":"En fin de phrase, on cherche l'accord de l'autre avec « ne ». C'est comme hein en français. Ici, on parle d'un souvenir commun.","say":{"ne":"ね"},"words":[["bon","いい"],["voyage","旅行"],["petit mot du passé","でした"],["petit mot d'accord","ね"]]}},{"fr":"Les daims de Nara sont mignons, hein ?","tgt":"奈良の鹿はかわいいですね。","ro":"Nara no shika wa kawaii desu ne.","lit":"Nara · [possessif] · daim · [thème] · mignon · être (poli) · [n'est-ce pas]","note":{"lit":"Nara, petit mot de liaison, daim, petit mot du thème, mignon, être, petit mot d'accord","text":"Mignon se dit « kawaii ». On le dit souvent avec le petit mot d'accord. Les deux personnes ont vu les daims.","say":{"kawaii":"かわいい"},"words":[["Nara","奈良"],["petit mot de liaison","の"],["daim","鹿"],["petit mot du thème","は"],["mignon","かわいい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Et les takoyaki sont délicieux, tu sais !","tgt":"たこ焼きもおいしいですよ。","ro":"Takoyaki mo oishii desu yo.","lit":"takoyaki · [aussi] · délicieux · être (poli) · [tu sais]","note":{"lit":"takoyaki, aussi, délicieux, être, petit mot d'insistance","text":"Pour apprendre quelque chose à l'autre, on ajoute « yo ». C'est comme tu sais, ou je t'assure. Celui qui parle sait, l'autre peut-être pas.","say":{"yo":"よ"},"words":[["takoyaki","たこ焼き"],["aussi","も"],["délicieux","おいしい"],["être","です"],["petit mot d'insistance","よ"]]}},{"fr":"J'ai retenu beaucoup de mots japonais.","tgt":"日本語の言葉をたくさん覚えました。","ro":"Nihongo no kotoba o takusan oboemashita.","lit":"japonais · [possessif] · mot · [objet] · beaucoup · retenir (passé, poli)","note":{"lit":"japonais, petit mot de liaison, mots, petit mot du complément, beaucoup, retenir","text":"J'ai retenu se dit « oboemashita ». C'est retenir ou apprendre par cœur, au passé. Beaucoup se place juste avant.","say":{"oboemashita":"覚えました"},"words":[["japonais","日本語"],["petit mot de liaison","の"],["mots","言葉"],["petit mot du complément","を"],["beaucoup","たくさん"],["retenir","覚えました"]]}},{"fr":"Les katakana, maintenant, ça va.","tgt":"カタカナはもう大丈夫です。","ro":"Katakana wa mō daijōbu desu.","lit":"katakana · [thème] · désormais · ça va · être (poli)","note":{"lit":"katakana, petit mot du thème, maintenant, ça va, être","text":"Ici, désormais se dit « mō ». Il montre qu'un changement a eu lieu. Avant, ce n'était pas le cas.","say":{"mō":"もう"},"words":[["katakana","カタカナ"],["petit mot du thème","は"],["maintenant","もう"],["ça va","大丈夫"],["être","です"]]}},{"fr":"Le japonais, c'est difficile, hein ?","tgt":"日本語は難しいですね。","ro":"Nihongo wa muzukashii desu ne.","lit":"japonais · [thème] · difficile · être (poli) · [n'est-ce pas]","note":{"lit":"japonais, petit mot du thème, difficile, être, petit mot d'accord","text":"Difficile se dit « muzukashii ». Avec le petit mot d'accord, on partage un avis. L'autre va sûrement acquiescer.","say":{"muzukashii":"難しい"},"words":[["japonais","日本語"],["petit mot du thème","は"],["difficile","難しい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Mais c'est passionnant, je t'assure !","tgt":"でも、おもしろいですよ。","ro":"Demo, omoshiroi desu yo.","lit":"mais · intéressant · être (poli) · [tu sais]","note":{"lit":"mais, intéressant, être, petit mot d'insistance","text":"Pour affirmer son avis, on termine par « yo ». Ici, il rassure l'autre. Trop souvent, il peut paraître insistant.","say":{"yo":"よ"},"words":[["mais","でも"],["intéressant","おもしろい"],["être","です"],["petit mot d'insistance","よ"]]}},{"fr":"J'ai souvent utilisé « kudasai ».","tgt":"「ください」をよく使いました。","ro":"« Kudasai » o yoku tsukaimashita.","lit":"kudasai · [objet] · souvent · utiliser (passé, poli)","note":{"lit":"donnez-moi, petit mot du complément, souvent, utiliser","text":"Souvent se dit « yoku ». Il se place juste avant le verbe. Utiliser est ici au passé.","say":{"yoku":"よく"},"words":[["donnez-moi","ください"],["petit mot du complément","を"],["souvent","よく"],["utiliser","使いました"]]}},{"fr":"La prochaine fois, je veux rester plus longtemps.","tgt":"今度はもっと長くいたいです。","ro":"Kondo wa motto nagaku itai desu.","lit":"la prochaine fois · [thème] · plus · longtemps · rester-vouloir · être (poli)","note":{"lit":"la prochaine fois, petit mot du thème, plus, longtemps, vouloir rester, être","text":"Plus se dit « motto ». Il se place avant longtemps. Rester se dit avec le verbe des êtres vivants, et la fin du désir.","say":{"motto":"もっと"},"words":[["la prochaine fois","今度"],["petit mot du thème","は"],["plus","もっと"],["longtemps","長く"],["vouloir rester","いたい"],["être","です"]]}},{"fr":"On aimerait bien revenir un jour, hein ?","tgt":"またいつか来たいですね。","ro":"Mata itsuka kitai desu ne.","lit":"encore · un jour · venir-vouloir · être (poli) · [n'est-ce pas]","note":{"lit":"encore, un jour, vouloir venir, être, petit mot d'accord","text":"Un jour se dit « itsuka ». C'est quand suivi d'un petit son qui le rend vague. Avec le petit mot final, on partage cette envie.","say":{"itsuka":"いつか"},"words":[["encore","また"],["un jour","いつか"],["vouloir venir","来たい"],["être","です"],["petit mot d'accord","ね"]]}}],"tip":{"title":"« Yo » et « ne » : les petites particules de fin de phrase","example":"Mais c'est passionnant, je t'assure ! — でも、おもしろいです<b>よ</b>。","body":"Les Japonais terminent très souvent leurs phrases par une petite particule qui ajoute une émotion, un peu comme notre « hein » ou notre « tu sais ». « Ne » cherche l'accord de l'autre : on partage un sentiment, comme dans « Muzukashii desu ne », c'est difficile, hein ? « Yo », au contraire, apporte une information que l'autre ne connaît pas encore, avec une pointe d'insistance. « Demo, omoshiroi desu yo » se dit littéralement : mais, intéressant, être poli, tu sais. Vous entendrez aussi « Oishii desu yo », c'est bon, je vous assure, ou « Ii ryokō deshita ne », c'était un beau voyage, n'est-ce pas ? Attention à ne pas abuser de « yo » : trop souvent répété, il peut sonner un peu donneur de leçons. « Ne », lui, rend la conversation chaleureuse et vous fera paraître tout de suite plus naturel. Une astuce pour retenir : « ne », c'est nous deux, d'accord ensemble ; « yo », c'est moi qui te l'apprends.","exampleRo":"Demo, omoshiroi desu yo.","lit":"mais · intéressant · être (poli) · [tu sais]","say":{"Yo":"よ","ne":"ね","Ne":"ね","Muzukashii desu ne":"難しいですね","Demo, omoshiroi desu yo":"でも、おもしろいですよ","Oishii desu yo":"おいしいですよ","Ii ryokō deshita ne":"いい旅行でしたね","yo":"よ"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Se présenter à Yokohama","phrases":[{"fr":"Enchantée, je m'appelle Marie.","tgt":"はじめまして、マリーです。","ro":"Hajimemashite, Marī desu.","lit":"enchanté (première fois) · Marie · être (poli)","note":{"lit":"enchanté, Marie, être","text":"Pour se présenter, on dit d'abord enchanté, puis son nom. Pas besoin de dire je m'appelle. Il suffit du nom suivi de « desu ».","say":{"desu":"です"},"words":[["enchanté","はじめまして"],["Marie","マリー"],["être","です"]]}},{"fr":"Je suis française, je viens de Lyon.","tgt":"フランス人です。リヨンから来ました。","ro":"Furansujin desu. Riyon kara kimashita.","lit":"Français-personne · être (poli) · Lyon · [depuis] · venir (passé poli)","note":{"lit":"Français, être, Lyon, depuis, venir","text":"Pour dire d'où l'on vient, on emploie venir au passé. Mot à mot, je suis venue de Lyon. Je suis venu se dit « kimashita ».","say":{"kimashita":"来ました"},"words":[["Français","フランス人"],["être","です"],["Lyon","リヨン"],["depuis","から"],["venir","来ました"]]}},{"fr":"Moi, c'est Kenji Tanaka.","tgt":"田中健二です。","ro":"Tanaka Kenji desu.","lit":"Tanaka Kenji · être (poli)","note":{"lit":"Tanaka, Kenji, être","text":"Au Japon, on dit le nom de famille en premier. Tanaka est le nom de famille, et Kenji le prénom. Pour soi-même, on n'ajoute jamais « san ».","say":{"san":"さん"},"words":[["Tanaka","田中"],["Kenji","健二"],["être","です"]]}},{"fr":"Vous êtes de Yokohama ?","tgt":"横浜の人ですか？","ro":"Yokohama no hito desu ka?","lit":"Yokohama · [possessif] · personne · être (poli) · [question]","note":{"lit":"Yokohama, petit mot de liaison, personne, être, petit mot de question","text":"Pour demander d'où vient quelqu'un, on dit la personne de ce lieu. Personne se dit « hito ». Le lieu vient avant, avec le petit mot de liaison.","say":{"hito":"人"},"words":[["Yokohama","横浜"],["petit mot de liaison","の"],["personne","人"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, je suis né à Yokohama.","tgt":"はい、横浜生まれです。","ro":"Hai, Yokohama umare desu.","lit":"oui · Yokohama · naissance · être (poli)","note":{"lit":"oui, Yokohama, naissance, être","text":"Né à se dit « umare ». On le place juste après le nom du lieu. Mot à mot, c'est naissance de Yokohama.","say":{"umare":"生まれ"},"words":[["oui","はい"],["Yokohama","横浜"],["naissance","生まれ"],["être","です"]]}},{"fr":"Vous êtes venue au Japon pour le travail ?","tgt":"仕事で日本に来ましたか？","ro":"Shigoto de Nihon ni kimashita ka?","lit":"travail · [moyen] · Japon · [direction] · venir (passé poli) · [question]","note":{"lit":"travail, petit mot du moyen, Japon, vers, venir, petit mot de question","text":"Pour le travail se dit mot à mot par le travail. Travail se dit « shigoto ». Il prend le petit mot du moyen.","say":{"shigoto":"仕事"},"words":[["travail","仕事"],["petit mot du moyen","で"],["Japon","日本"],["vers","に"],["venir","来ました"],["petit mot de question","か"]]}},{"fr":"Oui, je travaille pour une entreprise de Yokohama.","tgt":"はい、横浜の会社員です。","ro":"Hai, Yokohama no kaishain desu.","lit":"oui · Yokohama · [possessif] · employé d'entreprise · être (poli)","note":{"lit":"oui, Yokohama, petit mot de liaison, employé de bureau, être","text":"Pour parler de son emploi, on dit simplement employé de bureau. Ce mot se dit « kaishain ». On précise la ville avec le petit mot de liaison.","say":{"kaishain":"会社員"},"words":[["oui","はい"],["Yokohama","横浜"],["petit mot de liaison","の"],["employé de bureau","会社員"],["être","です"]]}},{"fr":"C'est la première fois que je viens au Japon.","tgt":"日本は初めてです。","ro":"Nihon wa hajimete desu.","lit":"Japon · [thème] · première fois · être (poli)","note":{"lit":"Japon, petit mot du thème, première fois, être","text":"Pour dire c'est ma première fois, on met le lieu en thème. Puis on dit première fois, « hajimete ». C'est une phrase simple et très utile.","say":{"hajimete":"初めて"},"words":[["Japon","日本"],["petit mot du thème","は"],["première fois","初めて"],["être","です"]]}},{"fr":"Je parle un petit peu japonais.","tgt":"日本語を少し話します。","ro":"Nihongo o sukoshi hanashimasu.","lit":"japonais · [objet] · un peu · parler (poli)","note":{"lit":"japonais, petit mot du complément, un peu, parler","text":"Parler se dit « hanashimasu ». La langue est le complément. Un peu se place juste avant le verbe.","say":{"hanashimasu":"話します"},"words":[["japonais","日本語"],["petit mot du complément","を"],["un peu","少し"],["parler","話します"]]}},{"fr":"Je compte sur votre bienveillance.","tgt":"どうぞよろしくお願いします。","ro":"Dōzo yoroshiku onegaishimasu.","lit":"je vous en prie · bien · je vous le demande (poli)","note":{"lit":"je vous en prie, bien, je vous le demande","text":"Pour finir une présentation, on dit cette formule figée. Avec le mot du début, « dōzo ». Elle devient ainsi encore plus polie.","say":{"dōzo":"どうぞ"},"words":[["je vous en prie","どうぞ"],["bien","よろしく"],["je vous le demande","お願いします"]]}}]},{"title":"Les collègues du bureau","phrases":[{"fr":"Voici Monsieur Satō, mon chef.","tgt":"こちらは佐藤さんです。私の上司です。","ro":"Kochira wa Satō-san desu. Watashi no jōshi desu.","lit":"ce côté-ci · [thème] · Satō-monsieur · être (poli) · moi · [possessif] · chef · être (poli)","note":{"lit":"ce côté-ci, petit mot du thème, Satō, monsieur, être, moi, petit mot du possessif, chef, être","text":"Pour présenter quelqu'un, on dit « kochira ». Mot à mot, c'est ce côté-ci. C'est plus poli que de dire ceci.","say":{"kochira":"こちら"},"words":[["ce côté-ci","こちら"],["petit mot du thème","は"],["Satō","佐藤"],["monsieur","さん"],["être","です"],["moi","私"],["petit mot du possessif","の"],["chef","上司"],["être","です"]]}},{"fr":"Madame Yamada est très gentille.","tgt":"山田さんはとても親切です。","ro":"Yamada-san wa totemo shinsetsu desu.","lit":"Yamada-madame · [thème] · très · gentil · être (poli)","note":{"lit":"Yamada, madame, petit mot du thème, très, gentil, être","text":"Pour tout le monde, homme ou femme, on ajoute « san ». C'est le petit mot le plus sûr. Il n'y a rien à accorder.","say":{"san":"さん"},"words":[["Yamada","山田"],["madame","さん"],["petit mot du thème","は"],["très","とても"],["gentil","親切"],["être","です"]]}},{"fr":"Kenta, on déjeune ensemble ?","tgt":"健太くん、一緒に昼ご飯を食べませんか？","ro":"Kenta-kun, issho ni hirugohan o tabemasen ka?","lit":"Kenta-kun · ensemble · déjeuner · [objet] · manger (négatif poli) · [question]","note":{"lit":"Kenta, petit mot amical, ensemble, déjeuner, petit mot du complément, ne pas manger, petit mot de question","text":"Pour un jeune homme ou un collègue plus jeune, on dit « kun ». C'est amical, un peu familier. On ne l'emploie pas pour un supérieur.","say":{"kun":"くん"},"words":[["Kenta","健太"],["petit mot amical","くん"],["ensemble","一緒に"],["déjeuner","昼ご飯"],["petit mot du complément","を"],["ne pas manger","食べません"],["petit mot de question","か"]]}},{"fr":"Kenta vient d'entrer dans l'entreprise.","tgt":"健太くんは新入社員です。","ro":"Kenta-kun wa shinnyū shain desu.","lit":"Kenta-kun · [thème] · nouvel employé · être (poli)","note":{"lit":"Kenta, petit mot amical, petit mot du thème, nouvel employé, être","text":"Un nouvel employé se dit « shinnyū shain ». Mot à mot, c'est nouveau, entré, employé. Au Japon, les nouveaux arrivent souvent en avril.","say":{"shinnyū shain":"新入社員"},"words":[["Kenta","健太"],["petit mot amical","くん"],["petit mot du thème","は"],["nouvel employé","新入社員"],["être","です"]]}},{"fr":"La fille de Monsieur Satō s'appelle Yui.","tgt":"佐藤さんの娘さんはゆいちゃんです。","ro":"Satō-san no musume-san wa Yui-chan desu.","lit":"Satō-monsieur · [possessif] · fille-honorable · [thème] · Yui-chan · être (poli)","note":{"lit":"Satō, monsieur, petit mot de liaison, fille, madame, petit mot du thème, Yui, petit mot affectueux, être","text":"Pour les enfants, on ajoute après le prénom « chan ». C'est tendre et affectueux. On l'emploie aussi entre amies proches.","say":{"chan":"ちゃん"},"words":[["Satō","佐藤"],["monsieur","さん"],["petit mot de liaison","の"],["fille","娘"],["madame","さん"],["petit mot du thème","は"],["Yui","ゆい"],["petit mot affectueux","ちゃん"],["être","です"]]}},{"fr":"La petite Yui a cinq ans.","tgt":"ゆいちゃんは五歳です。","ro":"Yui-chan wa gosai desu.","lit":"Yui-chan · [thème] · cinq-ans · être (poli)","note":{"lit":"Yui, petit mot affectueux, petit mot du thème, cinq ans, être","text":"Pour l'âge, an se dit « sai ». On le place après le nombre. Pas besoin du verbe avoir.","say":{"sai":"歳"},"words":[["Yui","ゆい"],["petit mot affectueux","ちゃん"],["petit mot du thème","は"],["cinq ans","五歳"],["être","です"]]}},{"fr":"Le client arrive à trois heures.","tgt":"お客様は三時に来ます。","ro":"Okyakusama wa sanji ni kimasu.","lit":"honorable-client-sama · [thème] · trois-heures · [temps] · venir (poli)","note":{"lit":"client, petit mot très poli, petit mot du thème, trois heures, petit mot du moment, venir","text":"Pour un client, on emploie un mot encore plus poli, « sama ». Il montre un grand respect. On l'entend dans tous les magasins.","say":{"sama":"様"},"words":[["client","お客"],["petit mot très poli","様"],["petit mot du thème","は"],["trois heures","三時"],["petit mot du moment","に"],["venir","来ます"]]}},{"fr":"Notre directeur s'appelle Monsieur Mori.","tgt":"部長は森さんです。","ro":"Buchō wa Mori-san desu.","lit":"directeur · [thème] · Mori-monsieur · être (poli)","note":{"lit":"directeur, petit mot du thème, Mori, monsieur, être","text":"Directeur de service se dit « buchō ». Au bureau, on appelle souvent son chef par son titre. On ne dit pas son nom.","say":{"buchō":"部長"},"words":[["directeur","部長"],["petit mot du thème","は"],["Mori","森"],["monsieur","さん"],["être","です"]]}},{"fr":"Appelez-moi simplement Marie.","tgt":"マリーと呼んでください。","ro":"Marī to yonde kudasai.","lit":"Marie · [citation] · appeler (forme -te) · s'il vous plaît","note":{"lit":"Marie, petit mot de citation, appeler, s'il vous plaît","text":"Appelez-moi se dit « yonde kudasai ». Le nom est suivi d'un petit mot de citation. C'est comme des guillemets à l'oral.","say":{"yonde kudasai":"呼んでください"},"words":[["Marie","マリー"],["petit mot de citation","と"],["appeler","呼んで"],["s'il vous plaît","ください"]]}},{"fr":"Madame Yamada, merci encore pour aujourd'hui.","tgt":"山田さん、今日もありがとうございます。","ro":"Yamada-san, kyō mo arigatō gozaimasu.","lit":"Yamada-madame · aujourd'hui · [aussi] · merci (très poli)","note":{"lit":"Yamada, madame, aujourd'hui, aussi, merci, poliment","text":"Au Japon, on remercie aussi pour le quotidien. Aujourd'hui aussi se dit « kyō mo ». C'est une façon de dire merci encore.","say":{"kyō mo":"今日も"},"words":[["Yamada","山田"],["madame","さん"],["aujourd'hui","今日"],["aussi","も"],["merci","ありがとう"],["poliment","ございます"]]}}],"tip":{"title":"« San, kun, chan, sama » : les suffixes après les noms","example":"La fille de Monsieur Satō s'appelle Yui. — 佐藤<b>さん</b>の娘<b>さん</b>はゆい<b>ちゃん</b>です。","body":"En japonais, on ajoute presque toujours un petit suffixe après le nom des autres personnes. Le plus courant est « san » : il remplace à la fois monsieur, madame et mademoiselle, et il se colle au nom de famille comme au prénom. Notre phrase se dit littéralement : Satō-monsieur, de, fille-honorable, thème, Yui-petite, être. « Kun » s'emploie pour les garçons et les jeunes collègues, comme « Kenta-kun », tandis que « chan » est affectueux et va aux enfants et aux proches, comme « Yui-chan ». « Sama » est le plus respectueux : on l'entend pour les clients, « okyakusama ». Attention, on ne met jamais de suffixe à son propre nom : on dit simplement « Marī desu ». Pour retenir, imaginez une échelle : « chan » en bas pour les petits, « kun » et « san » au milieu, et « sama » tout en haut pour les clients.","exampleRo":"Satō-san no musume-san wa Yui-chan desu.","lit":"Satō-monsieur · [possessif] · fille-honorable · [thème] · Yui-chan · être (poli)","say":{"San, kun, chan, sama":"さん、くん、ちゃん、さま","san":"さん","Kun":"くん","Kenta-kun":"健太くん","chan":"ちゃん","Yui-chan":"ゆいちゃん","Sama":"さま","okyakusama":"お客様","Marī desu":"マリーです","kun":"くん","sama":"さま"}}},{"title":"Parler de son travail","phrases":[{"fr":"Quel est votre métier ?","tgt":"お仕事は何ですか？","ro":"Oshigoto wa nan desu ka?","lit":"honorable-travail · [thème] · quoi · être (poli) · [question]","note":{"lit":"travail, petit mot du thème, quoi, être, petit mot de question","text":"Pour le travail de l'autre, on dit « oshigoto ». Le petit son poli montre le respect. Pour soi, on dit le mot sans ce son.","say":{"oshigoto":"お仕事"},"words":[["travail","お仕事"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"Je suis ingénieure.","tgt":"エンジニアです。","ro":"Enjinia desu.","lit":"ingénieur · être (poli)","note":{"lit":"ingénieur, être","text":"Ingénieur se dit « enjinia ». C'est un mot anglais adapté. Il n'y a ni masculin ni féminin.","say":{"enjinia":"エンジニア"},"words":[["ingénieur","エンジニア"],["être","です"]]}},{"fr":"Moi, je suis employé de banque.","tgt":"私は銀行員です。","ro":"Watashi wa ginkōin desu.","lit":"moi · [thème] · employé de banque · être (poli)","note":{"lit":"moi, petit mot du thème, employé de banque, être","text":"Employé de banque se dit « ginkōin ». C'est banque suivi d'un mot qui veut dire membre. Moi, en thème, marque le contraste avec l'autre.","say":{"ginkōin":"銀行員"},"words":[["moi","私"],["petit mot du thème","は"],["employé de banque","銀行員"],["être","です"]]}},{"fr":"Où se trouve votre entreprise ?","tgt":"会社はどこですか？","ro":"Kaisha wa doko desu ka?","lit":"entreprise · [thème] · où · être (poli) · [question]","note":{"lit":"entreprise, petit mot du thème, où, être, petit mot de question","text":"Entreprise se dit « kaisha ». On le met en thème, puis on demande où. Le possessif votre n'est pas nécessaire.","say":{"kaisha":"会社"},"words":[["entreprise","会社"],["petit mot du thème","は"],["où","どこ"],["être","です"],["petit mot de question","か"]]}},{"fr":"Elle est près de la gare de Yokohama.","tgt":"横浜駅の近くです。","ro":"Yokohama eki no chikaku desu.","lit":"Yokohama-gare · [possessif] · proximité · être (poli)","note":{"lit":"gare de Yokohama, petit mot de liaison, proximité, être","text":"Près de se dit « chikaku ». On dit la gare, liaison, proximité. Pas besoin de répéter l'entreprise.","say":{"chikaku":"近く"},"words":[["gare de Yokohama","横浜駅"],["petit mot de liaison","の"],["proximité","近く"],["être","です"]]}},{"fr":"Je prends le train chaque matin.","tgt":"毎朝、電車に乗ります。","ro":"Maiasa, densha ni norimasu.","lit":"chaque matin · train · [dans] · monter (poli)","note":{"lit":"chaque matin, train, dans, monter","text":"Chaque matin se dit « maiasa ». C'est chaque suivi de matin. On dit de même chaque jour ou chaque soir.","say":{"maiasa":"毎朝"},"words":[["chaque matin","毎朝"],["train","電車"],["dans","に"],["monter","乗ります"]]}},{"fr":"Je commence le travail à neuf heures.","tgt":"九時から働きます。","ro":"Kuji kara hatarakimasu.","lit":"neuf-heures · [depuis] · travailler (poli)","note":{"lit":"neuf heures, depuis, travailler","text":"Travailler se dit « hatarakimasu ». Je commence à neuf heures se dit je travaille depuis neuf heures. Le petit mot depuis suffit.","say":{"hatarakimasu":"働きます"},"words":[["neuf heures","九時"],["depuis","から"],["travailler","働きます"]]}},{"fr":"Le travail finit à sept heures du soir.","tgt":"仕事は夜七時までです。","ro":"Shigoto wa yoru shichiji made desu.","lit":"travail · [thème] · soir · sept-heures · [jusqu'à] · être (poli)","note":{"lit":"travail, petit mot du thème, soir, sept heures, jusqu'à, être","text":"Le soir se dit « yoru ». On le place devant l'heure. Jusqu'à se met juste après.","say":{"yoru":"夜"},"words":[["travail","仕事"],["petit mot du thème","は"],["soir","夜"],["sept heures","七時"],["jusqu'à","まで"],["être","です"]]}},{"fr":"Votre travail est intéressant ?","tgt":"仕事はおもしろいですか？","ro":"Shigoto wa omoshiroi desu ka?","lit":"travail · [thème] · intéressant · être (poli) · [question]","note":{"lit":"travail, petit mot du thème, intéressant, être, petit mot de question","text":"Intéressant se dit « omoshiroi ». Il veut aussi dire amusant. On l'emploie pour un travail, un livre ou une personne.","say":{"omoshiroi":"おもしろい"},"words":[["travail","仕事"],["petit mot du thème","は"],["intéressant","おもしろい"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, mais c'est un peu dur.","tgt":"はい、でも少し大変です。","ro":"Hai, demo sukoshi taihen desu.","lit":"oui · mais · un peu · pénible · être (poli)","note":{"lit":"oui, mais, un peu, dur, être","text":"Dur ou pénible se dit « taihen ». C'est un mot très courant pour se plaindre gentiment. Un peu l'adoucit encore.","say":{"taihen":"大変"},"words":[["oui","はい"],["mais","でも"],["un peu","少し"],["dur","大変"],["être","です"]]}}]},{"title":"Ce qu'on aime manger","phrases":[{"fr":"Vous aimez la cuisine japonaise ?","tgt":"日本料理が好きですか？","ro":"Nihon ryōri ga suki desu ka?","lit":"Japon-cuisine · [sujet] · aimé · être (poli) · [question]","note":{"lit":"Japon, cuisine, petit mot du sujet, aimé, être, petit mot de question","text":"Aimer se dit « suki ». Ce n'est pas un verbe, mais un mot qui veut dire aimé. Ce qu'on aime prend le petit mot du sujet.","say":{"suki":"好き"},"words":[["Japon","日本"],["cuisine","料理"],["petit mot du sujet","が"],["aimé","好き"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, j'adore les sushis.","tgt":"はい、お寿司が大好きです。","ro":"Hai, osushi ga daisuki desu.","lit":"oui · honorable-sushi · [sujet] · très aimé · être (poli)","note":{"lit":"oui, sushi, petit mot du sujet, adoré, être","text":"Adorer se dit « daisuki ». C'est aimer avec un mot qui veut dire grand devant. On l'entend très souvent.","say":{"daisuki":"大好き"},"words":[["oui","はい"],["sushi","お寿司"],["petit mot du sujet","が"],["adoré","大好き"],["être","です"]]}},{"fr":"Le nattō, je déteste ça.","tgt":"納豆は嫌いです。","ro":"Nattō wa kirai desu.","lit":"nattō · [thème] · détesté · être (poli)","note":{"lit":"nattō, petit mot du thème, détesté, être","text":"Ne pas aimer se dit « kirai ». C'est un mot fort, comme détester. Les Japonais l'emploient avec prudence.","say":{"kirai":"嫌い"},"words":[["nattō","納豆"],["petit mot du thème","は"],["détesté","嫌い"],["être","です"]]}},{"fr":"Quel plat n'aimez-vous pas ?","tgt":"嫌いな料理は何ですか？","ro":"Kirai na ryōri wa nan desu ka?","lit":"détesté · [na] · plat · [thème] · quoi · être (poli) · [question]","note":{"lit":"détesté, petit mot de l'adjectif, plat, petit mot du thème, quoi, être, petit mot de question","text":"Devant un nom, aimé et détesté prennent le petit mot « na ». Ils se comportent comme des adjectifs. Un plat qu'on n'aime pas se dit donc plat détesté.","say":{"na":"な"},"words":[["détesté","嫌い"],["petit mot de l'adjectif","な"],["plat","料理"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"Je n'aime pas trop le poisson cru.","tgt":"生の魚はあまり好きじゃありません。","ro":"Nama no sakana wa amari suki ja arimasen.","lit":"cru · [possessif] · poisson · [thème] · pas tellement · aimé · ne pas être (poli)","note":{"lit":"cru, petit mot de liaison, poisson, petit mot du thème, pas tellement, aimé, ne pas être","text":"Pour dire je n'aime pas trop, on dit pas tellement aimé. C'est plus doux que détester. On dit donc « suki ja arimasen ».","say":{"suki ja arimasen":"好きじゃありません"},"words":[["cru","生"],["petit mot de liaison","の"],["poisson","魚"],["petit mot du thème","は"],["pas tellement","あまり"],["aimé","好き"],["ne pas être","じゃありません"]]}},{"fr":"Ma femme adore les douceurs.","tgt":"妻は甘いものが大好きです。","ro":"Tsuma wa amai mono ga daisuki desu.","lit":"ma femme · [thème] · sucré · chose · [sujet] · très aimé · être (poli)","note":{"lit":"ma femme, petit mot du thème, sucré, chose, petit mot du sujet, adoré, être","text":"Ma femme se dit « tsuma ». Pour sa propre famille, on emploie des mots simples. Les douceurs se disent mot à mot choses sucrées.","say":{"tsuma":"妻"},"words":[["ma femme","妻"],["petit mot du thème","は"],["sucré","甘い"],["chose","もの"],["petit mot du sujet","が"],["adoré","大好き"],["être","です"]]}},{"fr":"Quel est votre plat préféré ?","tgt":"好きな料理は何ですか？","ro":"Suki na ryōri wa nan desu ka?","lit":"aimé · [na] · plat · [thème] · quoi · être (poli) · [question]","note":{"lit":"aimé, petit mot de l'adjectif, plat, petit mot du thème, quoi, être, petit mot de question","text":"Plat préféré se dit mot à mot plat aimé. Plat ou cuisine se dit « ryōri ». C'est une question classique pour faire connaissance.","say":{"ryōri":"料理"},"words":[["aimé","好き"],["petit mot de l'adjectif","な"],["plat","料理"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"C'est la soupe miso de ma mère.","tgt":"母の味噌汁です。","ro":"Haha no misoshiru desu.","lit":"ma mère · [possessif] · soupe miso · être (poli)","note":{"lit":"ma mère, petit mot de liaison, soupe miso, être","text":"Ma mère se dit « haha ». Pour la mère de quelqu'un d'autre, on emploie un mot plus poli. La soupe miso de maman est un classique.","say":{"haha":"母"},"words":[["ma mère","母"],["petit mot de liaison","の"],["soupe miso","味噌汁"],["être","です"]]}},{"fr":"Et la bière, vous aimez ?","tgt":"ビールは好きですか？","ro":"Bīru wa suki desu ka?","lit":"bière · [thème] · aimé · être (poli) · [question]","note":{"lit":"bière, petit mot du thème, aimé, être, petit mot de question","text":"Ici, la bière est mise en thème. Mot à mot, et la bière, aimée. On demande avec « suki desu ka ».","say":{"suki desu ka":"好きですか"},"words":[["bière","ビール"],["petit mot du thème","は"],["aimé","好き"],["être","です"],["petit mot de question","か"]]}},{"fr":"Oui, une bière bien fraîche, c'est parfait !","tgt":"はい、冷たいビールは最高です！","ro":"Hai, tsumetai bīru wa saikō desu!","lit":"oui · froid · bière · [thème] · le top · être (poli)","note":{"lit":"oui, froid, bière, petit mot du thème, le top, être","text":"Le top ou génial se dit « saikō ». Mot à mot, c'est le plus haut. On l'entend très souvent.","say":{"saikō":"最高"},"words":[["oui","はい"],["froid","冷たい"],["bière","ビール"],["petit mot du thème","は"],["le top","最高"],["être","です"]]}}],"tip":{"title":"« Suki » et « kirai » : dire ce qu'on aime","example":"Oui, j'adore les sushis. — はい、お寿司が<b>大好き</b>です。","body":"En japonais, « aimer » n'est pas un verbe : « suki » est un adjectif qui veut dire « aimé », « qui plaît ». On ne dit donc pas « j'aime les sushis », mais plutôt « les sushis me plaisent ». C'est pour cela que la chose aimée prend la particule « ga », et non « o ». Notre phrase se décompose ainsi : oui, honorable sushi, sujet, très aimé, être. Le petit « dai » devant « suki » renforce le sens : « daisuki », c'est adorer. Le contraire est « kirai », détesté, un mot assez fort ; pour rester poli, on dit souvent « amari suki ja arimasen », pas tellement aimé. Quelques exemples : « Bīru ga suki desu », j'aime la bière, « Nattō wa kirai desu », je déteste le nattō, et « Suki na ryōri wa nan desu ka ? », quel est votre plat préféré ? Pour retenir, pensez à l'expression « ça me plaît » : la chose qui plaît est le sujet, donc elle prend « ga ».","exampleRo":"Hai, osushi ga daisuki desu.","lit":"oui · honorable-sushi · [sujet] · très aimé · être (poli)","say":{"Suki":"好き","kirai":"嫌い","suki":"好き","ga":"が","o":"を","daisuki":"大好き","amari suki ja arimasen":"あまり好きじゃありません","Bīru ga suki desu":"ビールが好きです","Nattō wa kirai desu":"納豆は嫌いです","Suki na ryōri wa nan desu ka ?":"好きな料理は何ですか","dai":"だい"}}},{"title":"Une soirée à l'izakaya","phrases":[{"fr":"Ce soir, on va à l'izakaya ?","tgt":"今晩、居酒屋に行きませんか？","ro":"Konban, izakaya ni ikimasen ka?","lit":"ce soir · izakaya · [direction] · aller (négatif poli) · [question]","note":{"lit":"ce soir, izakaya, vers, ne pas aller, petit mot de question","text":"Un izakaya est un bar où l'on mange de petits plats. Le nom se dit « izakaya ». On invite avec une question négative.","say":{"izakaya":"居酒屋"},"words":[["ce soir","今晩"],["izakaya","居酒屋"],["vers","に"],["ne pas aller","行きません"],["petit mot de question","か"]]}},{"fr":"Bonne idée, allons-y tous ensemble !","tgt":"いいですね。みんなで行きましょう！","ro":"Ii desu ne. Minna de ikimashō!","lit":"bien · être (poli) · [n'est-ce pas] · tout le monde · [avec] · aller (proposition)","note":{"lit":"bien, être, petit mot d'accord, tout le monde, avec, aller","text":"Tous ensemble se dit « minna de ». C'est tout le monde suivi du petit mot du moyen. On l'entend souvent pour les sorties en groupe.","say":{"minna de":"みんなで"},"words":[["bien","いい"],["être","です"],["petit mot d'accord","ね"],["tout le monde","みんな"],["avec","で"],["aller","行きましょう"]]}},{"fr":"Deux pressions, s'il vous plaît.","tgt":"生ビールを二つください。","ro":"Nama bīru o futatsu kudasai.","lit":"bière pression · [objet] · deux (objets) · donnez-moi","note":{"lit":"pression, bière, petit mot du complément, deux, donnez-moi","text":"La bière pression se dit « nama bīru ». Mot à mot, c'est bière crue. C'est la première commande classique à l'izakaya.","say":{"nama bīru":"生ビール"},"words":[["pression","生"],["bière","ビール"],["petit mot du complément","を"],["deux","二つ"],["donnez-moi","ください"]]}},{"fr":"À la santé de toute l'équipe !","tgt":"みなさん、乾杯！","ro":"Minasan, kanpai!","lit":"tout le monde · coupe vidée (santé)","note":{"lit":"tout le monde, santé","text":"Pour trinquer, on dit « kanpai ». Mot à mot, c'est verre vidé. Avant, on s'adresse poliment à tout le monde.","say":{"kanpai":"乾杯"},"words":[["tout le monde","みなさん"],["santé","乾杯"]]}},{"fr":"Les brochettes de poulet sont délicieuses.","tgt":"焼き鳥がおいしいですね。","ro":"Yakitori ga oishii desu ne.","lit":"brochettes de poulet · [sujet] · délicieux · être (poli) · [n'est-ce pas]","note":{"lit":"brochettes, petit mot du sujet, délicieux, être, petit mot d'accord","text":"Les brochettes de poulet se disent « yakitori ». Mot à mot, c'est oiseau grillé. Le petit mot final partage le plaisir.","say":{"yakitori":"焼き鳥"},"words":[["brochettes","焼き鳥"],["petit mot du sujet","が"],["délicieux","おいしい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Encore un peu d'edamame ?","tgt":"枝豆、もう少しどうですか？","ro":"Edamame, mō sukoshi dō desu ka?","lit":"edamame · encore · un peu · comment · être (poli) · [question]","note":{"lit":"edamame, encore, un peu, comment, être, petit mot de question","text":"Pour proposer, on dit « dō desu ka ». Mot à mot, c'est comment est-ce. Encore un peu se place devant.","say":{"dō desu ka":"どうですか"},"words":[["edamame","枝豆"],["encore","もう"],["un peu","少し"],["comment","どう"],["être","です"],["petit mot de question","か"]]}},{"fr":"On commande du saké chaud ?","tgt":"熱燗を頼みましょうか？","ro":"Atsukan o tanomimashō ka?","lit":"saké chaud · [objet] · commander (proposition) · [question]","note":{"lit":"saké chaud, petit mot du complément, commander, petit mot de question","text":"Commander se dit « tanomimasu ». Ici, on le propose avec la fin en question. Le saké chaud est très apprécié en hiver.","say":{"tanomimasu":"頼みます"},"words":[["saké chaud","熱燗"],["petit mot du complément","を"],["commander","頼みましょう"],["petit mot de question","か"]]}},{"fr":"Tous les collègues sont là ce soir.","tgt":"今晩は同僚がみんないます。","ro":"Konban wa dōryō ga minna imasu.","lit":"ce soir · [thème] · collègues · [sujet] · tous · être présent (poli)","note":{"lit":"ce soir, petit mot du thème, collègues, petit mot du sujet, tous, être là","text":"Collègue se dit « dōryō ». Tous se place après le sujet, juste avant le verbe. Les collègues sont vivants, d'où le verbe des êtres vivants.","say":{"dōryō":"同僚"},"words":[["ce soir","今晩"],["petit mot du thème","は"],["collègues","同僚"],["petit mot du sujet","が"],["tous","みんな"],["être là","います"]]}},{"fr":"Le patron de l'izakaya est très drôle.","tgt":"居酒屋のマスターはとてもおもしろいです。","ro":"Izakaya no masutā wa totemo omoshiroi desu.","lit":"izakaya · [possessif] · patron · [thème] · très · amusant · être (poli)","note":{"lit":"izakaya, petit mot de liaison, patron, petit mot du thème, très, drôle, être","text":"Le patron d'un bar se dit « masutā ». Le mot vient de l'anglais. Drôle se dit avec le même mot qu'intéressant.","say":{"masutā":"マスター"},"words":[["izakaya","居酒屋"],["petit mot de liaison","の"],["patron","マスター"],["petit mot du thème","は"],["très","とても"],["drôle","おもしろい"],["être","です"]]}},{"fr":"On partage l'addition ?","tgt":"割り勘にしましょうか？","ro":"Warikan ni shimashō ka?","lit":"addition partagée · [résultat] · faire (proposition) · [question]","note":{"lit":"partage, petit mot du choix, faire, petit mot de question","text":"Partager l'addition se dit « warikan ». Chacun paie sa part. Avec la proposition, on demande poliment si c'est d'accord.","say":{"warikan":"割り勘"},"words":[["partage","割り勘"],["petit mot du choix","に"],["faire","しましょう"],["petit mot de question","か"]]}}]},{"title":"Au karaoké","phrases":[{"fr":"Après, on va au karaoké ?","tgt":"このあと、カラオケに行きませんか？","ro":"Kono ato, karaoke ni ikimasen ka?","lit":"ce · après · karaoké · [direction] · aller (négatif poli) · [question]","note":{"lit":"ce, après, karaoké, vers, ne pas aller, petit mot de question","text":"Karaoké est un mot japonais, « karaoke ». Mot à mot, c'est orchestre vide. Il est passé dans le monde entier.","say":{"karaoke":"カラオケ"},"words":[["ce","この"],["après","あと"],["karaoké","カラオケ"],["vers","に"],["ne pas aller","行きません"],["petit mot de question","か"]]}},{"fr":"Je chante vraiment mal.","tgt":"歌がとても下手です。","ro":"Uta ga totemo heta desu.","lit":"chant · [sujet] · très · maladroit · être (poli)","note":{"lit":"chant, petit mot du sujet, très, maladroit, être","text":"Mal faire quelque chose se dit « heta ». Ce qu'on fait mal prend le petit mot du sujet. Mot à mot, le chant est maladroit.","say":{"heta":"下手"},"words":[["chant","歌"],["petit mot du sujet","が"],["très","とても"],["maladroit","下手"],["être","です"]]}},{"fr":"Mais non, vous chantez bien !","tgt":"いいえ、歌が上手ですよ！","ro":"Iie, uta ga jōzu desu yo!","lit":"non · chant · [sujet] · habile · être (poli) · [tu sais]","note":{"lit":"non, chant, petit mot du sujet, habile, être, petit mot d'insistance","text":"Bien faire quelque chose se dit « jōzu ». C'est le contraire de maladroit. On l'emploie surtout pour les autres.","say":{"jōzu":"上手"},"words":[["non","いいえ"],["chant","歌"],["petit mot du sujet","が"],["habile","上手"],["être","です"],["petit mot d'insistance","よ"]]}},{"fr":"Monsieur Satō chante vraiment bien.","tgt":"佐藤さんは歌がとても上手です。","ro":"Satō-san wa uta ga totemo jōzu desu.","lit":"Satō-monsieur · [thème] · chant · [sujet] · très · habile · être (poli)","note":{"lit":"Satō, monsieur, petit mot du thème, chant, petit mot du sujet, très, habile, être","text":"La personne est le thème, son talent est le sujet. Chant se dit « uta ». Mot à mot, Monsieur Satō, le chant est habile.","say":{"uta":"歌"},"words":[["Satō","佐藤"],["monsieur","さん"],["petit mot du thème","は"],["chant","歌"],["petit mot du sujet","が"],["très","とても"],["habile","上手"],["être","です"]]}},{"fr":"Vous savez jouer de la guitare ?","tgt":"ギターができますか？","ro":"Gitā ga dekimasu ka?","lit":"guitare · [sujet] · savoir faire (poli) · [question]","note":{"lit":"guitare, petit mot du sujet, savoir faire, petit mot de question","text":"Savoir faire se dit « dekimasu ». Ce qu'on sait faire prend le petit mot du sujet. On l'emploie pour un sport, un instrument ou une langue.","say":{"dekimasu":"できます"},"words":[["guitare","ギター"],["petit mot du sujet","が"],["savoir faire","できます"],["petit mot de question","か"]]}},{"fr":"Oui, je sais en jouer un peu.","tgt":"はい、少しできます。","ro":"Hai, sukoshi dekimasu.","lit":"oui · un peu · savoir faire (poli)","note":{"lit":"oui, un peu, savoir faire","text":"Pour rester modeste, on ajoute un peu. Un peu se dit « sukoshi ». Les Japonais se mettent rarement en avant.","say":{"sukoshi":"少し"},"words":[["oui","はい"],["un peu","少し"],["savoir faire","できます"]]}},{"fr":"La danse, je ne sais pas du tout.","tgt":"ダンスは全然できません。","ro":"Dansu wa zenzen dekimasen.","lit":"danse · [thème] · pas du tout · savoir faire (négatif poli)","note":{"lit":"danse, petit mot du thème, pas du tout, ne pas savoir faire","text":"Pas du tout se dit « zenzen ». Il va avec un verbe négatif. La danse est mise en thème pour le contraste.","say":{"zenzen":"全然"},"words":[["danse","ダンス"],["petit mot du thème","は"],["pas du tout","全然"],["ne pas savoir faire","できません"]]}},{"fr":"La petite Yui dessine très bien.","tgt":"ゆいちゃんは絵がとても上手です。","ro":"Yui-chan wa e ga totemo jōzu desu.","lit":"Yui-chan · [thème] · dessin · [sujet] · très · habile · être (poli)","note":{"lit":"Yui, petit mot affectueux, petit mot du thème, dessin, petit mot du sujet, très, habile, être","text":"Dessin ou tableau se dit « e ». C'est un mot d'un seul son. On retrouve la même structure, thème puis sujet.","say":{"e":"絵"},"words":[["Yui","ゆい"],["petit mot affectueux","ちゃん"],["petit mot du thème","は"],["dessin","絵"],["petit mot du sujet","が"],["très","とても"],["habile","上手"],["être","です"]]}},{"fr":"Votre japonais est vraiment bon !","tgt":"日本語が本当に上手ですね！","ro":"Nihongo ga hontō ni jōzu desu ne!","lit":"japonais · [sujet] · vraiment · habile · être (poli) · [n'est-ce pas]","note":{"lit":"japonais, petit mot du sujet, vraiment, habile, être, petit mot d'accord","text":"Les Japonais font souvent ce compliment aux étrangers. Habile se dit « jōzu ». Il ne faut pas le prendre trop au sérieux.","say":{"jōzu":"上手"},"words":[["japonais","日本語"],["petit mot du sujet","が"],["vraiment","本当に"],["habile","上手"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Oh non, j'ai encore beaucoup à apprendre.","tgt":"いいえ、まだまだです。","ro":"Iie, mada mada desu.","lit":"non · encore encore · être (poli)","note":{"lit":"non, pas encore, être","text":"Pour répondre modestement à un compliment, on dit « mada mada desu ». Mot à mot, c'est pas encore, pas encore. C'est la réponse polie attendue.","say":{"mada mada desu":"まだまだです"},"words":[["non","いいえ"],["pas encore","まだまだ"],["être","です"]]}}],"tip":{"title":"« Jōzu », « heta » et « dekimasu » : dire ce qu'on sait faire","example":"Monsieur Satō chante vraiment bien. — 佐藤さんは歌がとても<b>上手</b>です。","body":"Pour dire que quelqu'un fait bien quelque chose, le japonais utilise « jōzu », habile, et son contraire « heta », maladroit. Comme « suki », ce sont des adjectifs, et l'activité prend la particule « ga ». Notre phrase se dit mot à mot : Satō-monsieur, thème, chant, sujet, très, habile, être. On parle d'abord de la personne avec « wa », puis du domaine avec « ga ». Pour dire qu'on sait faire, ou qu'on peut faire quelque chose, on emploie « dekimasu », avec « ga » lui aussi : « Gitā ga dekimasu », je sais jouer de la guitare, et « Dansu wa dekimasen », la danse, je ne sais pas. Petit point de culture très important : on ne dit jamais de soi-même qu'on est « jōzu ». Si on vous complimente avec « Nihongo ga jōzu desu ne », répondez modestement « Iie, mada mada desu », non, pas encore. Pour retenir : « jōzu » rime avec réussi, « heta » sonne comme une petite chute.","exampleRo":"Satō-san wa uta ga totemo jōzu desu.","lit":"Satō-monsieur · [thème] · chant · [sujet] · très · habile · être (poli)","say":{"Jōzu":"上手","heta":"下手","dekimasu":"できます","jōzu":"上手","suki":"好き","ga":"が","wa":"わ","Gitā ga dekimasu":"ギターができます","Dansu wa dekimasen":"ダンスはできません","Nihongo ga jōzu desu ne":"日本語が上手ですね","Iie, mada mada desu":"いいえ、まだまだです"}}},{"title":"Parler de ses loisirs","phrases":[{"fr":"Que faites-vous le week-end, en général ?","tgt":"週末は何をしますか？","ro":"Shūmatsu wa nani o shimasu ka?","lit":"week-end · [thème] · quoi · [objet] · faire (poli) · [question]","note":{"lit":"week-end, petit mot du thème, quoi, petit mot du complément, faire, petit mot de question","text":"Pour demander les habitudes, on emploie le présent poli. Faire se dit « shimasu ». Week-end est mis en thème.","say":{"shimasu":"します"},"words":[["week-end","週末"],["petit mot du thème","は"],["quoi","何"],["petit mot du complément","を"],["faire","します"],["petit mot de question","か"]]}},{"fr":"Je joue souvent au tennis.","tgt":"よくテニスをします。","ro":"Yoku tenisu o shimasu.","lit":"souvent · tennis · [objet] · faire (poli)","note":{"lit":"souvent, tennis, petit mot du complément, faire","text":"Pour un sport, on dit le sport, puis faire. Tennis se dit « tenisu ». Souvent se place au début.","say":{"tenisu":"テニス"},"words":[["souvent","よく"],["tennis","テニス"],["petit mot du complément","を"],["faire","します"]]}},{"fr":"À la maison, je lis des mangas.","tgt":"うちで漫画を読みます。","ro":"Uchi de manga o yomimasu.","lit":"maison · [lieu] · manga · [objet] · lire (poli)","note":{"lit":"maison, petit mot du lieu, manga, petit mot du complément, lire","text":"Chez soi se dit souvent « uchi ». C'est plus chaleureux que l'autre mot pour maison. On y ajoute le petit mot du lieu.","say":{"uchi":"うち"},"words":[["maison","うち"],["petit mot du lieu","で"],["manga","漫画"],["petit mot du complément","を"],["lire","読みます"]]}},{"fr":"Le dimanche, je cours le long de la mer.","tgt":"日曜日は海のそばを走ります。","ro":"Nichiyōbi wa umi no soba o hashirimasu.","lit":"dimanche · [thème] · mer · [possessif] · bord · [parcours] · courir (poli)","note":{"lit":"dimanche, petit mot du thème, mer, petit mot de liaison, bord, petit mot du complément, courir","text":"Le long de se dit avec le petit mot du complément. Ici, il marque le chemin parcouru. Courir se dit « hashirimasu ».","say":{"hashirimasu":"走ります"},"words":[["dimanche","日曜日"],["petit mot du thème","は"],["mer","海"],["petit mot de liaison","の"],["bord","そば"],["petit mot du complément","を"],["courir","走ります"]]}},{"fr":"Vous allez parfois au cinéma ?","tgt":"ときどき映画館に行きますか？","ro":"Tokidoki eigakan ni ikimasu ka?","lit":"parfois · cinéma · [direction] · aller (poli) · [question]","note":{"lit":"parfois, cinéma, vers, aller, petit mot de question","text":"Parfois se dit « tokidoki ». Il se place au début de la phrase. Cinéma, le lieu, c'est film suivi d'un mot qui veut dire bâtiment.","say":{"tokidoki":"ときどき"},"words":[["parfois","ときどき"],["cinéma","映画館"],["vers","に"],["aller","行きます"],["petit mot de question","か"]]}},{"fr":"Je fais du yoga avec une amie.","tgt":"友達とヨガをします。","ro":"Tomodachi to yoga o shimasu.","lit":"ami · [avec] · yoga · [objet] · faire (poli)","note":{"lit":"ami, avec, yoga, petit mot du complément, faire","text":"Avec quelqu'un se dit « to ». Ce petit mot se place après la personne. C'est le même que pour et.","say":{"to":"と"},"words":[["ami","友達"],["avec","と"],["yoga","ヨガ"],["petit mot du complément","を"],["faire","します"]]}},{"fr":"Le week-end dernier, je suis allée à Kamakura.","tgt":"先週末、鎌倉に行きました。","ro":"Senshūmatsu, Kamakura ni ikimashita.","lit":"week-end dernier · Kamakura · [direction] · aller (passé poli)","note":{"lit":"week-end dernier, Kamakura, vers, aller","text":"Le week-end dernier se dit « senshūmatsu ». C'est dernier, semaine, fin. Le verbe aller est au passé poli.","say":{"senshūmatsu":"先週末"},"words":[["week-end dernier","先週末"],["Kamakura","鎌倉"],["vers","に"],["aller","行きました"]]}},{"fr":"J'ai pris plein de photos là-bas.","tgt":"そこで写真をたくさん撮りました。","ro":"Soko de shashin o takusan torimashita.","lit":"là · [lieu] · photo · [objet] · beaucoup · prendre (passé poli)","note":{"lit":"là, petit mot du lieu, photo, petit mot du complément, beaucoup, prendre","text":"J'ai pris se dit « torimashita ». Beaucoup se place juste avant. Là, avec le petit mot du lieu, renvoie à Kamakura.","say":{"torimashita":"撮りました"},"words":[["là","そこ"],["petit mot du lieu","で"],["photo","写真"],["petit mot du complément","を"],["beaucoup","たくさん"],["prendre","撮りました"]]}},{"fr":"Mon passe-temps, c'est la photo.","tgt":"趣味は写真です。","ro":"Shumi wa shashin desu.","lit":"passe-temps · [thème] · photo · être (poli)","note":{"lit":"passe-temps, petit mot du thème, photo, être","text":"Passe-temps se dit « shumi ». C'est la question classique pour faire connaissance. On répond simplement avec le petit mot poli.","say":{"shumi":"趣味"},"words":[["passe-temps","趣味"],["petit mot du thème","は"],["photo","写真"],["être","です"]]}},{"fr":"Et vous, quel est votre passe-temps ?","tgt":"ご趣味は何ですか？","ro":"Goshumi wa nan desu ka?","lit":"honorable-passe-temps · [thème] · quoi · être (poli) · [question]","note":{"lit":"passe-temps, petit mot du thème, quoi, être, petit mot de question","text":"Pour le passe-temps de l'autre, on ajoute un petit son poli devant. Votre passe-temps se dit « goshumi ». Pour soi, on ne le met jamais.","say":{"goshumi":"ご趣味"},"words":[["passe-temps","ご趣味"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}}]},{"title":"Parler de sa famille","phrases":[{"fr":"Combien êtes-vous dans votre famille ?","tgt":"何人家族ですか？","ro":"Nannin kazoku desu ka?","lit":"combien-personnes · famille · être (poli) · [question]","note":{"lit":"combien de personnes, famille, être, petit mot de question","text":"Combien de personnes se dit « nannin ». On le place devant le mot famille. C'est la façon japonaise de demander la taille d'une famille.","say":{"nannin":"何人"},"words":[["combien de personnes","何人"],["famille","家族"],["être","です"],["petit mot de question","か"]]}},{"fr":"Nous sommes quatre à la maison.","tgt":"四人家族です。","ro":"Yonin kazoku desu.","lit":"quatre-personnes · famille · être (poli)","note":{"lit":"quatre personnes, famille, être","text":"Quatre personnes se dit « yonin ». Le petit mot de comptage des personnes se met après le nombre. Puis vient le mot famille.","say":{"yonin":"四人"},"words":[["quatre personnes","四人"],["famille","家族"],["être","です"]]}},{"fr":"Ma mère est enseignante.","tgt":"母は教師です。","ro":"Haha wa kyōshi desu.","lit":"ma mère · [thème] · enseignant · être (poli)","note":{"lit":"ma mère, petit mot du thème, enseignant, être","text":"Pour sa propre mère, on dit « haha ». C'est un mot humble. On l'emploie quand on parle à quelqu'un d'extérieur.","say":{"haha":"母"},"words":[["ma mère","母"],["petit mot du thème","は"],["enseignant","教師"],["être","です"]]}},{"fr":"Et votre mère, que fait-elle ?","tgt":"お母さんのお仕事は何ですか？","ro":"Okāsan no oshigoto wa nan desu ka?","lit":"votre mère · [possessif] · honorable-travail · [thème] · quoi · être (poli) · [question]","note":{"lit":"votre mère, petit mot de liaison, travail, petit mot du thème, quoi, être, petit mot de question","text":"Pour la mère de l'autre, on dit « okāsan ». C'est plus respectueux. Devant les autres, on ne l'emploie pas pour sa propre mère.","say":{"okāsan":"お母さん"},"words":[["votre mère","お母さん"],["petit mot de liaison","の"],["travail","お仕事"],["petit mot du thème","は"],["quoi","何"],["être","です"],["petit mot de question","か"]]}},{"fr":"Mon père est salarié à Yokohama.","tgt":"父は横浜の会社員です。","ro":"Chichi wa Yokohama no kaishain desu.","lit":"mon père · [thème] · Yokohama · [possessif] · employé d'entreprise · être (poli)","note":{"lit":"mon père, petit mot du thème, Yokohama, petit mot de liaison, employé de bureau, être","text":"Mon père se dit « chichi ». C'est le mot humble, comme pour la mère. On le dit en parlant à quelqu'un d'extérieur.","say":{"chichi":"父"},"words":[["mon père","父"],["petit mot du thème","は"],["Yokohama","横浜"],["petit mot de liaison","の"],["employé de bureau","会社員"],["être","です"]]}},{"fr":"Votre père va bien ?","tgt":"お父さんはお元気ですか？","ro":"Otōsan wa ogenki desu ka?","lit":"votre père · [thème] · honorable-santé · être (poli) · [question]","note":{"lit":"votre père, petit mot du thème, en forme, être, petit mot de question","text":"Le père de l'autre se dit « otōsan ». On demande sa santé avec la formule polie. Les petits sons polis montrent le respect.","say":{"otōsan":"お父さん"},"words":[["votre père","お父さん"],["petit mot du thème","は"],["en forme","お元気"],["être","です"],["petit mot de question","か"]]}},{"fr":"J'ai un grand frère et une petite sœur.","tgt":"兄と妹がいます。","ro":"Ani to imōto ga imasu.","lit":"mon grand frère · [et] · ma petite sœur · [sujet] · il y a (êtres vivants, poli)","note":{"lit":"grand frère, et, petite sœur, petit mot du sujet, il y a","text":"Ma petite sœur se dit « imōto ». Le japonais distingue toujours grand et petit. Avoir des frères se dit il y a, avec le verbe des êtres vivants.","say":{"imōto":"妹"},"words":[["grand frère","兄"],["et","と"],["petite sœur","妹"],["petit mot du sujet","が"],["il y a","います"]]}},{"fr":"Votre grand frère est à Tokyo ?","tgt":"お兄さんは東京ですか？","ro":"Onīsan wa Tōkyō desu ka?","lit":"votre grand frère · [thème] · Tokyo · être (poli) · [question]","note":{"lit":"votre grand frère, petit mot du thème, Tokyo, être, petit mot de question","text":"Le grand frère de l'autre se dit « onīsan ». C'est le mot poli. Est à Tokyo se dit simplement Tokyo, suivi du petit mot poli.","say":{"onīsan":"お兄さん"},"words":[["votre grand frère","お兄さん"],["petit mot du thème","は"],["Tokyo","東京"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, il est à Kamakura.","tgt":"いいえ、鎌倉にいます。","ro":"Iie, Kamakura ni imasu.","lit":"non · Kamakura · [lieu] · être présent (poli)","note":{"lit":"non, Kamakura, petit mot du lieu, être","text":"Pour dire où se trouve une personne, on dit « imasu ». C'est le verbe des êtres vivants. Le lieu vient avant, avec son petit mot.","say":{"imasu":"います"},"words":[["non","いいえ"],["Kamakura","鎌倉"],["petit mot du lieu","に"],["être","います"]]}},{"fr":"Ma petite sœur a vingt ans.","tgt":"妹は二十歳です。","ro":"Imōto wa hatachi desu.","lit":"ma petite sœur · [thème] · vingt ans · être (poli)","note":{"lit":"petite sœur, petit mot du thème, vingt ans, être","text":"Vingt ans a un mot spécial, « hatachi ». Ce fut longtemps l'âge de la majorité au Japon. Les autres âges suivent la règle normale.","say":{"hatachi":"二十歳"},"words":[["petite sœur","妹"],["petit mot du thème","は"],["vingt ans","二十歳"],["être","です"]]}}],"tip":{"title":"La famille : « haha » pour ma mère, « okāsan » pour la vôtre","example":"Ma mère est enseignante. — <b>母</b>は教師です。","body":"En japonais, les mots de la famille changent selon qu'il s'agit de la vôtre ou de celle des autres. Pour parler de sa propre famille, on reste humble et on emploie des mots simples : « haha », ma mère, « chichi », mon père, « ani », mon grand frère. Pour la famille de quelqu'un d'autre, on utilise des mots plus respectueux, souvent avec « o » devant et « san » derrière : « okāsan », votre mère, « otōsan », votre père, « onīsan », votre grand frère. Notre phrase se dit littéralement : ma mère, thème, enseignant, être. Remarquez qu'il n'y a pas besoin de « ma » : le mot « haha » contient déjà l'idée que c'est la mienne. À l'inverse, « Okāsan wa ogenki desu ka ? » veut dire : votre mère va bien ? À la maison, on appelle quand même sa propre mère « okāsan ». Pour retenir : la forme courte et sèche pour les miens, la forme longue et polie, avec « san », pour les vôtres.","exampleRo":"Haha wa kyōshi desu.","lit":"ma mère · [thème] · enseignant · être (poli)","say":{"haha":"はは","okāsan":"お母さん","chichi":"ちち","ani":"あに","san":"さん","otōsan":"お父さん","onīsan":"お兄さん","Okāsan wa ogenki desu ka ?":"お母さんはお元気ですか"}}},{"title":"Parler de ses enfants","phrases":[{"fr":"Vous avez des enfants ?","tgt":"お子さんはいますか？","ro":"Okosan wa imasu ka?","lit":"honorable-enfant · [thème] · il y a (êtres vivants, poli) · [question]","note":{"lit":"enfants, petit mot du thème, il y a, petit mot de question","text":"Les enfants de l'autre se disent « okosan ». C'est le mot poli et respectueux. On demande avec le verbe des êtres vivants.","say":{"okosan":"お子さん"},"words":[["enfants","お子さん"],["petit mot du thème","は"],["il y a","います"],["petit mot de question","か"]]}},{"fr":"Oui, un garçon et une fille.","tgt":"はい、息子と娘がいます。","ro":"Hai, musuko to musume ga imasu.","lit":"oui · mon fils · [et] · ma fille · [sujet] · il y a (êtres vivants, poli)","note":{"lit":"oui, mon fils, et, ma fille, petit mot du sujet, il y a","text":"Mon fils se dit « musuko ». Ma fille se dit avec un autre mot. On les relie avec le petit mot et.","say":{"musuko":"息子"},"words":[["oui","はい"],["mon fils","息子"],["et","と"],["ma fille","娘"],["petit mot du sujet","が"],["il y a","います"]]}},{"fr":"Mon fils a sept ans.","tgt":"息子は七歳です。","ro":"Musuko wa nanasai desu.","lit":"mon fils · [thème] · sept-ans · être (poli)","note":{"lit":"mon fils, petit mot du thème, sept ans, être","text":"Sept ans se dit « nanasai ». Ici, sept prend sa forme longue. Puis vient le petit mot de l'âge.","say":{"nanasai":"七歳"},"words":[["mon fils","息子"],["petit mot du thème","は"],["sept ans","七歳"],["être","です"]]}},{"fr":"Il est fou des trains.","tgt":"電車が大好きです。","ro":"Densha ga daisuki desu.","lit":"train · [sujet] · très aimé · être (poli)","note":{"lit":"train, petit mot du sujet, adoré, être","text":"Être fou de quelque chose se dit « daisuki ». C'est adorer. Le sujet il n'est pas dit.","say":{"daisuki":"大好き"},"words":[["train","電車"],["petit mot du sujet","が"],["adoré","大好き"],["être","です"]]}},{"fr":"Ma fille est encore toute petite.","tgt":"娘はまだ小さいです。","ro":"Musume wa mada chiisai desu.","lit":"ma fille · [thème] · encore · petit · être (poli)","note":{"lit":"ma fille, petit mot du thème, encore, petit, être","text":"Encore se dit « mada ». Ici, il veut dire toujours. Il se place avant l'adjectif.","say":{"mada":"まだ"},"words":[["ma fille","娘"],["petit mot du thème","は"],["encore","まだ"],["petit","小さい"],["être","です"]]}},{"fr":"Le dimanche, nous allons tous au parc.","tgt":"日曜日はみんなで公園に行きます。","ro":"Nichiyōbi wa minna de kōen ni ikimasu.","lit":"dimanche · [thème] · tout le monde · [avec] · parc · [direction] · aller (poli)","note":{"lit":"dimanche, petit mot du thème, tout le monde, avec, parc, vers, aller","text":"Dimanche se dit « nichiyōbi ». Mis en thème, il veut dire le dimanche, en général. Tous ensemble se dit avec tout le monde.","say":{"nichiyōbi":"日曜日"},"words":[["dimanche","日曜日"],["petit mot du thème","は"],["tout le monde","みんな"],["avec","で"],["parc","公園"],["vers","に"],["aller","行きます"]]}},{"fr":"On déjeune chez mes grands-parents.","tgt":"祖父母の家で昼ご飯を食べます。","ro":"Sofubo no ie de hirugohan o tabemasu.","lit":"mes grands-parents · [possessif] · maison · [lieu] · déjeuner · [objet] · manger (poli)","note":{"lit":"grands-parents, petit mot de liaison, maison, petit mot du lieu, déjeuner, petit mot du complément, manger","text":"Mes grands-parents se dit « sofubo ». C'est grand-père et grand-mère réunis. Chez eux se dit leur maison.","say":{"sofubo":"祖父母"},"words":[["grands-parents","祖父母"],["petit mot de liaison","の"],["maison","家"],["petit mot du lieu","で"],["déjeuner","昼ご飯"],["petit mot du complément","を"],["manger","食べます"]]}},{"fr":"Ma grand-mère cuisine à merveille.","tgt":"祖母は料理がとても上手です。","ro":"Sobo wa ryōri ga totemo jōzu desu.","lit":"ma grand-mère · [thème] · cuisine · [sujet] · très · habile · être (poli)","note":{"lit":"grand-mère, petit mot du thème, cuisine, petit mot du sujet, très, habile, être","text":"Ma grand-mère se dit « sobo ». Pour sa famille, on emploie ces mots simples. Cuisiner à merveille se dit la cuisine est habile.","say":{"sobo":"祖母"},"words":[["grand-mère","祖母"],["petit mot du thème","は"],["cuisine","料理"],["petit mot du sujet","が"],["très","とても"],["habile","上手"],["être","です"]]}},{"fr":"Votre fille est vraiment mignonne.","tgt":"娘さんは本当にかわいいですね。","ro":"Musume-san wa hontō ni kawaii desu ne.","lit":"votre fille · [thème] · vraiment · mignon · être (poli) · [n'est-ce pas]","note":{"lit":"votre fille, petit mot du thème, vraiment, mignon, être, petit mot d'accord","text":"Pour la fille de l'autre, on dit « musume san ». On ajoute le petit mot de politesse. Pour la sienne, on ne le met pas.","say":{"musume san":"娘さん"},"words":[["votre fille","娘さん"],["petit mot du thème","は"],["vraiment","本当に"],["mignon","かわいい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Merci, mais elle est très bruyante !","tgt":"ありがとうございます。でも、とてもうるさいですよ。","ro":"Arigatō gozaimasu. Demo, totemo urusai desu yo.","lit":"merci (très poli) · mais · très · bruyant · être (poli) · [tu sais]","note":{"lit":"merci, poliment, mais, très, bruyant, être, petit mot d'insistance","text":"Bruyant se dit « urusai ». C'est aussi une façon de dire tais-toi. Ici, la mère reste modeste face au compliment.","say":{"urusai":"うるさい"},"words":[["merci","ありがとう"],["poliment","ございます"],["mais","でも"],["très","とても"],["bruyant","うるさい"],["être","です"],["petit mot d'insistance","よ"]]}}]},{"title":"Au téléphone : que faites-vous ?","phrases":[{"fr":"Allô, ici Marie.","tgt":"もしもし、マリーです。","ro":"Moshi moshi, Marī desu.","lit":"allô · Marie · être (poli)","note":{"lit":"allô, Marie, être","text":"Au téléphone, allô se dit « moshi moshi ». On le dit en décrochant. Puis on donne son nom.","say":{"moshi moshi":"もしもし"},"words":[["allô","もしもし"],["Marie","マリー"],["être","です"]]}},{"fr":"Qu'est-ce que vous faites en ce moment ?","tgt":"今、何をしていますか？","ro":"Ima, nani o shite imasu ka?","lit":"maintenant · quoi · [objet] · faire (forme -te) · être en train (poli) · [question]","note":{"lit":"maintenant, quoi, petit mot du complément, faire, être en train, petit mot de question","text":"Pour être en train de, on emploie une forme spéciale du verbe, puis « imasu ». Faire devient ainsi être en train de faire. Maintenant se place au début.","say":{"imasu":"います"},"words":[["maintenant","今"],["quoi","何"],["petit mot du complément","を"],["faire","して"],["être en train","います"],["petit mot de question","か"]]}},{"fr":"Je regarde la mer à Kamakura.","tgt":"鎌倉で海を見ています。","ro":"Kamakura de umi o mite imasu.","lit":"Kamakura · [lieu] · mer · [objet] · regarder (forme -te) · être en train (poli)","note":{"lit":"Kamakura, petit mot du lieu, mer, petit mot du complément, regarder, être en train","text":"Mer se dit « umi ». Je regarde en ce moment se dit regarder, à la forme en cours. Le lieu vient en premier.","say":{"umi":"海"},"words":[["Kamakura","鎌倉"],["petit mot du lieu","で"],["mer","海"],["petit mot du complément","を"],["regarder","見て"],["être en train","います"]]}},{"fr":"Mon mari est en train de cuisiner.","tgt":"夫は料理をしています。","ro":"Otto wa ryōri o shite imasu.","lit":"mon mari · [thème] · cuisine · [objet] · faire (forme -te) · être en train (poli)","note":{"lit":"mon mari, petit mot du thème, cuisine, petit mot du complément, faire, être en train","text":"Mon mari se dit « otto ». Il est en train de cuisiner se dit en train de faire la cuisine. C'est la même forme en cours.","say":{"otto":"夫"},"words":[["mon mari","夫"],["petit mot du thème","は"],["cuisine","料理"],["petit mot du complément","を"],["faire","して"],["être en train","います"]]}},{"fr":"Les enfants dorment déjà.","tgt":"子どもはもう寝ています。","ro":"Kodomo wa mō nete imasu.","lit":"enfants · [thème] · déjà · dormir (forme -te) · être en train (poli)","note":{"lit":"enfants, petit mot du thème, déjà, dormir, être en train","text":"Déjà se dit « mō ». Avec dormir à la forme en cours, on dit ils dorment. Enfant se dit sans pluriel.","say":{"mō":"もう"},"words":[["enfants","子ども"],["petit mot du thème","は"],["déjà","もう"],["dormir","寝て"],["être en train","います"]]}},{"fr":"J'habite à Yokohama.","tgt":"横浜に住んでいます。","ro":"Yokohama ni sunde imasu.","lit":"Yokohama · [lieu] · habiter (forme -te) · être (état, poli)","note":{"lit":"Yokohama, petit mot du lieu, habiter, état","text":"Habiter se dit toujours avec la forme en cours, « sunde imasu ». Mot à mot, je suis en train d'habiter. C'est un état qui dure.","say":{"sunde imasu":"住んでいます"},"words":[["Yokohama","横浜"],["petit mot du lieu","に"],["habiter","住んで"],["état","います"]]}},{"fr":"Mon grand frère est marié.","tgt":"兄は結婚しています。","ro":"Ani wa kekkon shite imasu.","lit":"mon grand frère · [thème] · mariage · faire (forme -te) · être (état, poli)","note":{"lit":"grand frère, petit mot du thème, mariage, faire, état","text":"Être marié se dit « kekkon shite imasu ». Mot à mot, il est dans l'état d'avoir fait le mariage. La forme en cours décrit ici un état.","say":{"kekkon shite imasu":"結婚しています"},"words":[["grand frère","兄"],["petit mot du thème","は"],["mariage","結婚"],["faire","して"],["état","います"]]}},{"fr":"Vous connaissez Monsieur Mori ?","tgt":"森さんを知っていますか？","ro":"Mori-san o shitte imasu ka?","lit":"Mori-monsieur · [objet] · savoir (forme -te) · être (état, poli) · [question]","note":{"lit":"Mori, monsieur, petit mot du complément, savoir, état, petit mot de question","text":"Connaître se dit « shitte imasu ». C'est aussi la forme d'un état. Pour répondre non, la forme change complètement.","say":{"shitte imasu":"知っています"},"words":[["Mori","森"],["monsieur","さん"],["petit mot du complément","を"],["savoir","知って"],["état","います"],["petit mot de question","か"]]}},{"fr":"Aujourd'hui, il pleut sur Yokohama.","tgt":"今日、横浜は雨が降っています。","ro":"Kyō, Yokohama wa ame ga futte imasu.","lit":"aujourd'hui · Yokohama · [thème] · pluie · [sujet] · tomber (forme -te) · être en train (poli)","note":{"lit":"aujourd'hui, Yokohama, petit mot du thème, pluie, petit mot du sujet, tomber, être en train","text":"Il pleut se dit mot à mot la pluie tombe. En ce moment, tomber devient « futte imasu ». Yokohama est mis en thème.","say":{"futte imasu":"降っています"},"words":[["aujourd'hui","今日"],["Yokohama","横浜"],["petit mot du thème","は"],["pluie","雨"],["petit mot du sujet","が"],["tomber","降って"],["être en train","います"]]}},{"fr":"Je vous rappelle ce soir.","tgt":"今晩、また電話します。","ro":"Konban, mata denwa shimasu.","lit":"ce soir · de nouveau · téléphone · faire (poli)","note":{"lit":"ce soir, encore, téléphone, faire","text":"Téléphoner se dit « denwa shimasu ». C'est téléphone suivi de faire. Encore, ici, veut dire de nouveau.","say":{"denwa shimasu":"電話します"},"words":[["ce soir","今晩"],["encore","また"],["téléphone","電話"],["faire","します"]]}}],"tip":{"title":"« -te imasu » : être en train de, ou un état","example":"Je regarde la mer à Kamakura. — 鎌倉で海を<b>見ています</b>。","body":"Vous connaissez déjà la forme en « -te » grâce à « -te kudasai ». En lui ajoutant « imasu », on obtient une construction très utile. Premier sens : une action en cours, comme notre « être en train de ». Notre phrase se décompose ainsi : Kamakura, lieu, mer, objet, regardant, être en train. « Mimasu », c'est « je regarde » en général, tandis que « mite imasu », c'est « je suis en train de regarder », là, maintenant. De même, « Otto wa ryōri o shite imasu » : mon mari est en train de cuisiner. Deuxième sens, plus surprenant : un état qui dure, le résultat d'une action. « Kekkon shite imasu » ne veut pas dire « il est en train de se marier », mais « il est marié ». Et « Yokohama ni sunde imasu », c'est « j'habite à Yokohama ». Pour retenir, imaginez une photo : « -te imasu » décrit ce qu'on voit sur l'image à cet instant, une action ou une situation.","exampleRo":"Kamakura de umi o mite imasu.","lit":"Kamakura · [lieu] · mer · [objet] · regarder (forme -te) · être en train (poli)","say":{"imasu":"います","Mimasu":"見ます","mite imasu":"見ています","Otto wa ryōri o shite imasu":"夫は料理をしています","Kekkon shite imasu":"結婚しています","Yokohama ni sunde imasu":"横浜に住んでいます","-te imasu":"ています"}}},{"title":"Les saisons au Japon","phrases":[{"fr":"Quelle saison aimez-vous ?","tgt":"どの季節が好きですか？","ro":"Dono kisetsu ga suki desu ka?","lit":"quel · saison · [sujet] · aimé · être (poli) · [question]","note":{"lit":"quel, saison, petit mot du sujet, aimé, être, petit mot de question","text":"Saison se dit « kisetsu ». Quel, devant un nom, ressemble au mot ce. La saison aimée prend le petit mot du sujet.","say":{"kisetsu":"季節"},"words":[["quel","どの"],["saison","季節"],["petit mot du sujet","が"],["aimé","好き"],["être","です"],["petit mot de question","か"]]}},{"fr":"J'aime le printemps et ses cerisiers.","tgt":"春と桜が好きです。","ro":"Haru to sakura ga suki desu.","lit":"printemps · [et] · cerisier · [sujet] · aimé · être (poli)","note":{"lit":"printemps, et, cerisiers, petit mot du sujet, aimé, être","text":"Printemps se dit « haru ». Les cerisiers en fleur en sont le symbole. On les admire à la fin mars et en avril.","say":{"haru":"春"},"words":[["printemps","春"],["et","と"],["cerisiers","桜"],["petit mot du sujet","が"],["aimé","好き"],["être","です"]]}},{"fr":"L'été à Kamakura est très chaud.","tgt":"鎌倉の夏はとても暑いです。","ro":"Kamakura no natsu wa totemo atsui desu.","lit":"Kamakura · [possessif] · été · [thème] · très · chaud · être (poli)","note":{"lit":"Kamakura, petit mot de liaison, été, petit mot du thème, très, chaud, être","text":"Été se dit « natsu ». L'été japonais est chaud et très humide. On dit Kamakura, liaison, été.","say":{"natsu":"夏"},"words":[["Kamakura","鎌倉"],["petit mot de liaison","の"],["été","夏"],["petit mot du thème","は"],["très","とても"],["chaud","暑い"],["être","です"]]}},{"fr":"En été, on se baigne dans la mer.","tgt":"夏は海で泳ぎます。","ro":"Natsu wa umi de oyogimasu.","lit":"été · [thème] · mer · [lieu] · nager (poli)","note":{"lit":"été, petit mot du thème, mer, petit mot du lieu, nager","text":"Nager se dit « oyogimasu ». En été, mis en thème, veut dire chaque été. La mer prend le petit mot du lieu.","say":{"oyogimasu":"泳ぎます"},"words":[["été","夏"],["petit mot du thème","は"],["mer","海"],["petit mot du lieu","で"],["nager","泳ぎます"]]}},{"fr":"L'automne, c'est la saison des feuilles rouges.","tgt":"秋は紅葉の季節です。","ro":"Aki wa kōyō no kisetsu desu.","lit":"automne · [thème] · feuilles rouges · [possessif] · saison · être (poli)","note":{"lit":"automne, petit mot du thème, feuilles rouges, petit mot de liaison, saison, être","text":"Automne se dit « aki ». C'est la saison préférée de beaucoup de Japonais. Les feuilles rouges en sont le symbole.","say":{"aki":"秋"},"words":[["automne","秋"],["petit mot du thème","は"],["feuilles rouges","紅葉"],["petit mot de liaison","の"],["saison","季節"],["être","です"]]}},{"fr":"À Kamakura, les érables rouges sont superbes.","tgt":"鎌倉の紅葉はとてもきれいです。","ro":"Kamakura no kōyō wa totemo kirei desu.","lit":"Kamakura · [possessif] · feuilles rouges · [thème] · très · beau · être (poli)","note":{"lit":"Kamakura, petit mot de liaison, feuilles rouges, petit mot du thème, très, beau, être","text":"Les feuilles rouges d'automne se disent « kōyō ». On part les admirer en novembre. C'est comme les cerisiers au printemps.","say":{"kōyō":"紅葉"},"words":[["Kamakura","鎌倉"],["petit mot de liaison","の"],["feuilles rouges","紅葉"],["petit mot du thème","は"],["très","とても"],["beau","きれい"],["être","です"]]}},{"fr":"L'hiver à Yokohama n'est pas très froid.","tgt":"横浜の冬はあまり寒くありません。","ro":"Yokohama no fuyu wa amari samuku arimasen.","lit":"Yokohama · [possessif] · hiver · [thème] · pas tellement · froid · ne pas être (poli)","note":{"lit":"Yokohama, petit mot de liaison, hiver, petit mot du thème, pas tellement, froid, ne pas être","text":"Il existe une autre négation polie des adjectifs. Pas froid se dit aussi « samuku arimasen ». C'est un peu plus soutenu.","say":{"samuku arimasen":"寒くありません"},"words":[["Yokohama","横浜"],["petit mot de liaison","の"],["hiver","冬"],["petit mot du thème","は"],["pas tellement","あまり"],["froid","寒く"],["ne pas être","ありません"]]}},{"fr":"Il fait lourd aujourd'hui, hein ?","tgt":"今日は蒸し暑いですね。","ro":"Kyō wa mushiatsui desu ne.","lit":"aujourd'hui · [thème] · chaud et humide · être (poli) · [n'est-ce pas]","note":{"lit":"aujourd'hui, petit mot du thème, lourd, être, petit mot d'accord","text":"Lourd, chaud et humide, se dit « mushiatsui ». C'est vapeur suivi de chaud. Le petit mot final cherche l'accord.","say":{"mushiatsui":"蒸し暑い"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["lourd","蒸し暑い"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"La saison des pluies commence en juin.","tgt":"梅雨は六月からです。","ro":"Tsuyu wa rokugatsu kara desu.","lit":"saison des pluies · [thème] · juin · [depuis] · être (poli)","note":{"lit":"saison des pluies, petit mot du thème, juin, depuis, être","text":"La saison des pluies se dit « tsuyu ». Elle commence en juin et dure environ un mois. Depuis juin se dit juin suivi de depuis.","say":{"tsuyu":"梅雨"},"words":[["saison des pluies","梅雨"],["petit mot du thème","は"],["juin","六月"],["depuis","から"],["être","です"]]}},{"fr":"Vivement les cerisiers en fleur !","tgt":"早く桜が見たいです。","ro":"Hayaku sakura ga mitai desu.","lit":"vite · cerisier · [objet du désir] · vouloir voir (poli)","note":{"lit":"vite, cerisiers, petit mot du sujet, vouloir voir, être","text":"Cerisier se dit « sakura ». Avec vouloir, l'objet peut prendre le petit mot du sujet. Vite exprime l'impatience.","say":{"sakura":"桜"},"words":[["vite","早く"],["cerisiers","桜"],["petit mot du sujet","が"],["vouloir voir","見たい"],["être","です"]]}}]},{"title":"Yokohama ou Kamakura ?","phrases":[{"fr":"Yokohama est plus grand que Kamakura.","tgt":"横浜は鎌倉より大きいです。","ro":"Yokohama wa Kamakura yori ōkii desu.","lit":"Yokohama · [thème] · Kamakura · [plus que] · grand · être (poli)","note":{"lit":"Yokohama, petit mot du thème, Kamakura, plus que, grand, être","text":"Plus que se dit « yori ». On le place après ce qu'on compare. L'adjectif ne change pas.","say":{"yori":"より"},"words":[["Yokohama","横浜"],["petit mot du thème","は"],["Kamakura","鎌倉"],["plus que","より"],["grand","大きい"],["être","です"]]}},{"fr":"Kamakura est plus calme que Yokohama.","tgt":"鎌倉は横浜より静かです。","ro":"Kamakura wa Yokohama yori shizuka desu.","lit":"Kamakura · [thème] · Yokohama · [plus que] · calme · être (poli)","note":{"lit":"Kamakura, petit mot du thème, Yokohama, plus que, calme, être","text":"Calme se dit « shizuka ». La comparaison se construit de la même façon. Il n'y a pas de mot pour plus.","say":{"shizuka":"静か"},"words":[["Kamakura","鎌倉"],["petit mot du thème","は"],["Yokohama","横浜"],["plus que","より"],["calme","静か"],["être","です"]]}},{"fr":"La mer ou la montagne, que préférez-vous ?","tgt":"海と山と、どちらが好きですか？","ro":"Umi to yama to, dochira ga suki desu ka?","lit":"mer · [et] · montagne · [et] · lequel · [sujet] · aimé · être (poli) · [question]","note":{"lit":"mer, et, montagne, et, lequel, petit mot du sujet, aimé, être, petit mot de question","text":"Pour choisir entre deux choses, on demande « dochira ». Ce mot veut dire lequel des deux. On cite d'abord les deux choix.","say":{"dochira":"どちら"},"words":[["mer","海"],["et","と"],["montagne","山"],["et","と"],["lequel","どちら"],["petit mot du sujet","が"],["aimé","好き"],["être","です"],["petit mot de question","か"]]}},{"fr":"Moi, je préfère la mer.","tgt":"海のほうが好きです。","ro":"Umi no hō ga suki desu.","lit":"mer · [possessif] · côté · [sujet] · aimé · être (poli)","note":{"lit":"mer, petit mot de liaison, côté, petit mot du sujet, aimé, être","text":"Pour dire je préfère, on dit « no hō ga ». Mot à mot, le côté de la mer. Puis viennent aimé et le petit mot poli.","say":{"no hō ga":"のほうが"},"words":[["mer","海"],["petit mot de liaison","の"],["côté","ほう"],["petit mot du sujet","が"],["aimé","好き"],["être","です"]]}},{"fr":"Le train est plus rapide que le bus.","tgt":"電車はバスより速いです。","ro":"Densha wa basu yori hayai desu.","lit":"train · [thème] · bus · [plus que] · rapide · être (poli)","note":{"lit":"train, petit mot du thème, bus, plus que, rapide, être","text":"Rapide se dit « hayai ». Le bus est suivi de plus que. Le train, mis en thème, gagne la comparaison.","say":{"hayai":"速い"},"words":[["train","電車"],["petit mot du thème","は"],["bus","バス"],["plus que","より"],["rapide","速い"],["être","です"]]}},{"fr":"Thé vert ou café, qu'est-ce qui vous ferait plaisir ?","tgt":"緑茶とコーヒーと、どちらがいいですか？","ro":"Ryokucha to kōhī to, dochira ga ii desu ka?","lit":"thé vert · [et] · café · [et] · lequel · [sujet] · bien · être (poli) · [question]","note":{"lit":"thé vert, et, café, et, lequel, petit mot du sujet, bien, être, petit mot de question","text":"Thé vert se dit « ryokucha ». Mot à mot, c'est thé vert. Qu'est-ce qui vous ferait plaisir se dit lequel est bien.","say":{"ryokucha":"緑茶"},"words":[["thé vert","緑茶"],["et","と"],["café","コーヒー"],["et","と"],["lequel","どちら"],["petit mot du sujet","が"],["bien","いい"],["être","です"],["petit mot de question","か"]]}},{"fr":"Plutôt du thé vert, merci.","tgt":"緑茶のほうがいいです。","ro":"Ryokucha no hō ga ii desu.","lit":"thé vert · [possessif] · côté · [sujet] · bien · être (poli)","note":{"lit":"thé vert, petit mot de liaison, côté, petit mot du sujet, bien, être","text":"Plutôt se dit avec le côté de. Bien se dit « ii ». Mot à mot, le côté du thé vert est bien.","say":{"ii":"いい"},"words":[["thé vert","緑茶"],["petit mot de liaison","の"],["côté","ほう"],["petit mot du sujet","が"],["bien","いい"],["être","です"]]}},{"fr":"Ce restaurant-ci est moins cher.","tgt":"こちらの店のほうが安いです。","ro":"Kochira no mise no hō ga yasui desu.","lit":"ce côté-ci · [possessif] · restaurant · [possessif] · côté · [sujet] · bon marché · être (poli)","note":{"lit":"ce côté-ci, petit mot de liaison, restaurant, petit mot de liaison, côté, petit mot du sujet, bon marché, être","text":"Moins cher se dit plus bon marché. Bon marché se dit « yasui ». On ne dit pas moins, on retourne la comparaison.","say":{"yasui":"安い"},"words":[["ce côté-ci","こちら"],["petit mot de liaison","の"],["restaurant","店"],["petit mot de liaison","の"],["côté","ほう"],["petit mot du sujet","が"],["bon marché","安い"],["être","です"]]}},{"fr":"J'aime mieux le printemps que l'été.","tgt":"夏より春のほうが好きです。","ro":"Natsu yori haru no hō ga suki desu.","lit":"été · [plus que] · printemps · [possessif] · côté · [sujet] · aimé · être (poli)","note":{"lit":"été, plus que, printemps, petit mot de liaison, côté, petit mot du sujet, aimé, être","text":"Les deux tournures se combinent ici. Plus que l'été, le côté du printemps. Plus que se dit « yori ».","say":{"yori":"より"},"words":[["été","夏"],["plus que","より"],["printemps","春"],["petit mot de liaison","の"],["côté","ほう"],["petit mot du sujet","が"],["aimé","好き"],["être","です"]]}},{"fr":"Finalement, les deux sont bien !","tgt":"どちらもいいですね。","ro":"Dochira mo ii desu ne.","lit":"lequel · [aussi] · bien · être (poli) · [n'est-ce pas]","note":{"lit":"lequel, aussi, bien, être, petit mot d'accord","text":"Les deux se dit « dochira mo ». C'est lequel suivi d'aussi. Mot à mot, l'un comme l'autre.","say":{"dochira mo":"どちらも"},"words":[["lequel","どちら"],["aussi","も"],["bien","いい"],["être","です"],["petit mot d'accord","ね"]]}}],"tip":{"title":"Comparer : « yori » et « no hō ga »","example":"J'aime mieux le printemps que l'été. — 夏<b>より</b>春<b>のほうが</b>好きです。","body":"Pour comparer, le japonais n'a pas de mot pour « plus » placé devant l'adjectif. Il utilise la particule « yori », qui veut dire « par rapport à », et qui se place après l'élément qu'on dépasse. « Yokohama wa Kamakura yori ōkii desu » se dit littéralement : Yokohama, thème, Kamakura, par rapport à, grand, être. Autrement dit, Yokohama est plus grand que Kamakura. Pour désigner le gagnant, on ajoute « no hō ga », qui signifie « le côté de ». Notre phrase se décompose ainsi : l'été, par rapport à, le côté du printemps, sujet, aimé, être. Pour demander une préférence, on dit « A to B to, dochira ga suki desu ka ? », A et B, lequel préférez-vous ? On répond simplement : « Umi no hō ga suki desu », je préfère la mer. Pour retenir, imaginez une balance : « yori » marque le plateau qui monte, et « no hō ga » celui qui penche, le vainqueur.","exampleRo":"Natsu yori haru no hō ga suki desu.","lit":"été · [plus que] · printemps · [possessif] · côté · [sujet] · aimé · être (poli)","say":{"yori":"より","no hō ga":"のほうが","Yokohama wa Kamakura yori ōkii desu":"横浜は鎌倉より大きいです","Umi no hō ga suki desu":"海のほうが好きです"}}},{"title":"Une invitation chez des amis","phrases":[{"fr":"Vous venez dîner à la maison samedi ?","tgt":"土曜日、うちで晩ご飯を食べませんか？","ro":"Doyōbi, uchi de bangohan o tabemasen ka?","lit":"samedi · maison · [lieu] · dîner · [objet] · manger (négatif poli) · [question]","note":{"lit":"samedi, maison, petit mot du lieu, dîner, petit mot du complément, ne pas manger, petit mot de question","text":"Pour inviter quelqu'un à dîner, on pose une question négative. Chez nous se dit « uchi de ». Le jour se place au tout début.","say":{"uchi de":"うちで"},"words":[["samedi","土曜日"],["maison","うち"],["petit mot du lieu","で"],["dîner","晩ご飯"],["petit mot du complément","を"],["ne pas manger","食べません"],["petit mot de question","か"]]}},{"fr":"Avec joie, c'est très gentil.","tgt":"ぜひ。ありがとうございます。","ro":"Zehi. Arigatō gozaimasu.","lit":"absolument · merci (très poli)","note":{"lit":"absolument, merci, poliment","text":"Pour accepter avec joie, on dit « zehi ». Ce mot veut dire absolument. Puis on remercie poliment.","say":{"zehi":"ぜひ"},"words":[["absolument","ぜひ"],["merci","ありがとう"],["poliment","ございます"]]}},{"fr":"C'est où, chez vous ?","tgt":"おうちはどこですか？","ro":"Ouchi wa doko desu ka?","lit":"honorable-maison · [thème] · où · être (poli) · [question]","note":{"lit":"maison, petit mot du thème, où, être, petit mot de question","text":"La maison de l'autre se dit « ouchi ». On ajoute le petit son poli. Puis on demande où.","say":{"ouchi":"おうち"},"words":[["maison","おうち"],["petit mot du thème","は"],["où","どこ"],["être","です"],["petit mot de question","か"]]}},{"fr":"Tout près de la gare de Kita-Kamakura.","tgt":"北鎌倉駅のすぐ近くです。","ro":"Kita-Kamakura eki no sugu chikaku desu.","lit":"Kita-Kamakura-gare · [possessif] · tout · proximité · être (poli)","note":{"lit":"gare de Kita-Kamakura, petit mot de liaison, tout, proximité, être","text":"Tout près se dit « sugu chikaku ». Mot à mot, immédiatement proche. La gare vient avant, avec le petit mot de liaison.","say":{"sugu chikaku":"すぐ近く"},"words":[["gare de Kita-Kamakura","北鎌倉駅"],["petit mot de liaison","の"],["tout","すぐ"],["proximité","近く"],["être","です"]]}},{"fr":"À quelle heure est-ce que je viens ?","tgt":"何時に行きましょうか？","ro":"Nanji ni ikimashō ka?","lit":"quelle-heure · [temps] · aller (proposition) · [question]","note":{"lit":"quelle heure, petit mot du moment, aller, petit mot de question","text":"À quelle heure se dit « nanji ni ». Avec aller en proposition, on demande l'avis de l'hôte. C'est une manière polie de s'organiser.","say":{"nanji ni":"何時に"},"words":[["quelle heure","何時"],["petit mot du moment","に"],["aller","行きましょう"],["petit mot de question","か"]]}},{"fr":"Vers six heures, ça vous va ?","tgt":"六時ごろはどうですか？","ro":"Rokuji goro wa dō desu ka?","lit":"six-heures · environ · [thème] · comment · être (poli) · [question]","note":{"lit":"six heures, environ, petit mot du thème, comment, être, petit mot de question","text":"Vers, pour une heure, se dit « goro ». Il se place juste après l'heure. Pour une durée, on dit un autre mot.","say":{"goro":"ごろ"},"words":[["six heures","六時"],["environ","ごろ"],["petit mot du thème","は"],["comment","どう"],["être","です"],["petit mot de question","か"]]}},{"fr":"Qu'est-ce que je peux apporter ?","tgt":"何を持って行きましょうか？","ro":"Nani o motte ikimashō ka?","lit":"quoi · [objet] · tenir (forme -te) · aller (proposition) · [question]","note":{"lit":"quoi, petit mot du complément, tenir, aller, petit mot de question","text":"Apporter se dit mot à mot aller en tenant. Ce verbe se dit « motte ikimasu ». On propose avec la fin en question.","say":{"motte ikimasu":"持って行きます"},"words":[["quoi","何"],["petit mot du complément","を"],["tenir","持って"],["aller","行きましょう"],["petit mot de question","か"]]}},{"fr":"Rien du tout, ce n'est pas la peine.","tgt":"何もいりませんよ。","ro":"Nani mo irimasen yo.","lit":"rien · [aussi] · être nécessaire (négatif poli) · [tu sais]","note":{"lit":"rien, aussi, ne pas falloir, petit mot d'insistance","text":"Rien se dit « nani mo ». Il va toujours avec un verbe négatif. Ici, le verbe veut dire avoir besoin.","say":{"nani mo":"何も"},"words":[["rien","何"],["aussi","も"],["ne pas falloir","いりません"],["petit mot d'insistance","よ"]]}},{"fr":"Ma femme va préparer un sukiyaki.","tgt":"妻がすき焼きを作ります。","ro":"Tsuma ga sukiyaki o tsukurimasu.","lit":"ma femme · [sujet] · sukiyaki · [objet] · préparer (poli)","note":{"lit":"ma femme, petit mot du sujet, sukiyaki, petit mot du complément, préparer","text":"Préparer ou fabriquer se dit « tsukurimasu ». On l'emploie pour un plat comme pour un objet. Le sukiyaki est une fondue de bœuf sucrée salée.","say":{"tsukurimasu":"作ります"},"words":[["ma femme","妻"],["petit mot du sujet","が"],["sukiyaki","すき焼き"],["petit mot du complément","を"],["préparer","作ります"]]}},{"fr":"Je me réjouis déjà pour samedi.","tgt":"土曜日が楽しみです。","ro":"Doyōbi ga tanoshimi desu.","lit":"samedi · [sujet] · plaisir attendu · être (poli)","note":{"lit":"samedi, petit mot du sujet, plaisir attendu, être","text":"J'ai hâte se dit « tanoshimi desu ». Ce qu'on attend prend le petit mot du sujet. C'est une phrase très chaleureuse.","say":{"tanoshimi desu":"楽しみです"},"words":[["samedi","土曜日"],["petit mot du sujet","が"],["plaisir attendu","楽しみ"],["être","です"]]}}]},{"title":"Décliner et donner une raison","phrases":[{"fr":"Désolée, samedi, ça va être difficile…","tgt":"すみません、土曜日はちょっと…。","ro":"Sumimasen, doyōbi wa chotto…","lit":"pardon · samedi · [thème] · un peu…","note":{"lit":"pardon, samedi, petit mot du thème, un peu","text":"Pour refuser poliment, on dit « chotto ». Puis on laisse la phrase en suspens. Tout le monde comprend que c'est non.","say":{"chotto":"ちょっと"},"words":[["pardon","すみません"],["samedi","土曜日"],["petit mot du thème","は"],["un peu","ちょっと"]]}},{"fr":"C'est que j'ai du travail ce jour-là.","tgt":"その日は仕事がありますから。","ro":"Sono hi wa shigoto ga arimasu kara.","lit":"ce · jour · [thème] · travail · [sujet] · il y a (poli) · [parce que]","note":{"lit":"ce, jour, petit mot du thème, travail, petit mot du sujet, il y a, parce que","text":"Parce que se dit « kara ». Il se place à la fin de la raison. Ici, la phrase s'arrête là, comme une excuse.","say":{"kara":"から"},"words":[["ce","その"],["jour","日"],["petit mot du thème","は"],["travail","仕事"],["petit mot du sujet","が"],["il y a","あります"],["parce que","から"]]}},{"fr":"Pourquoi apprenez-vous le japonais ?","tgt":"どうして日本語を勉強していますか？","ro":"Dōshite Nihongo o benkyō shite imasu ka?","lit":"pourquoi · japonais · [objet] · étude · faire (forme -te) · être en train (poli) · [question]","note":{"lit":"pourquoi, japonais, petit mot du complément, étudier, être en train, petit mot de question","text":"Pourquoi se dit « dōshite ». Il se place en début de question. Étudier est à la forme en cours, car on étudie en ce moment.","say":{"dōshite":"どうして"},"words":[["pourquoi","どうして"],["japonais","日本語"],["petit mot du complément","を"],["étudier","勉強して"],["être en train","います"],["petit mot de question","か"]]}},{"fr":"Parce que j'adore les mangas.","tgt":"漫画が大好きですから。","ro":"Manga ga daisuki desu kara.","lit":"manga · [sujet] · très aimé · être (poli) · [parce que]","note":{"lit":"manga, petit mot du sujet, adoré, être, parce que","text":"Pour répondre à pourquoi, on termine par parce que, « kara ». Il vient après le petit mot poli. Le manga est souvent la raison des étudiants.","say":{"kara":"から"},"words":[["manga","漫画"],["petit mot du sujet","が"],["adoré","大好き"],["être","です"],["parce que","から"]]}},{"fr":"Il fait froid, fermons la fenêtre.","tgt":"寒いですから、窓を閉めましょう。","ro":"Samui desu kara, mado o shimemashō.","lit":"froid · être (poli) · [parce que] · fenêtre · [objet] · fermer (proposition)","note":{"lit":"froid, être, parce que, fenêtre, petit mot du complément, fermer","text":"En japonais, la raison vient d'abord, puis la conséquence. Fenêtre se dit « mado ». Fermons se dit avec la fin des propositions.","say":{"mado":"窓"},"words":[["froid","寒い"],["être","です"],["parce que","から"],["fenêtre","窓"],["petit mot du complément","を"],["fermer","閉めましょう"]]}},{"fr":"Je me lève tôt demain, alors pas d'alcool pour moi.","tgt":"明日は早いですから、お酒は飲みません。","ro":"Ashita wa hayai desu kara, osake wa nomimasen.","lit":"demain · [thème] · tôt · être (poli) · [parce que] · alcool · [thème] · boire (négatif poli)","note":{"lit":"demain, petit mot du thème, tôt, être, parce que, alcool, petit mot du thème, ne pas boire","text":"Tôt, comme adjectif, se dit « hayai ». Mot à mot, demain est tôt. L'alcool est mis en thème, car on le refuse.","say":{"hayai":"早い"},"words":[["demain","明日"],["petit mot du thème","は"],["tôt","早い"],["être","です"],["parce que","から"],["alcool","お酒"],["petit mot du thème","は"],["ne pas boire","飲みません"]]}},{"fr":"Il est tard, alors je vais y aller.","tgt":"もう遅いですから、そろそろ失礼します。","ro":"Mō osoi desu kara, sorosoro shitsurei shimasu.","lit":"déjà · tard · être (poli) · [parce que] · bientôt · impolitesse · faire (poli)","note":{"lit":"déjà, tard, être, parce que, bientôt, partir","text":"Pour partir poliment, on dit « shitsurei shimasu ». Mot à mot, je commets une impolitesse. On l'entend aussi en entrant dans un bureau.","say":{"shitsurei shimasu":"失礼します"},"words":[["déjà","もう"],["tard","遅い"],["être","です"],["parce que","から"],["bientôt","そろそろ"],["partir","失礼します"]]}},{"fr":"Quel dommage, une autre fois alors.","tgt":"残念ですね。また今度。","ro":"Zannen desu ne. Mata kondo.","lit":"regrettable · être (poli) · [n'est-ce pas] · de nouveau · la prochaine fois","note":{"lit":"dommage, être, petit mot d'accord, encore, la prochaine fois","text":"Dommage se dit « zannen ». Avec le petit mot final, on partage la déception. Une autre fois se dit encore, la prochaine fois.","say":{"zannen":"残念"},"words":[["dommage","残念"],["être","です"],["petit mot d'accord","ね"],["encore","また"],["la prochaine fois","今度"]]}},{"fr":"Et dimanche, ça vous irait ?","tgt":"日曜日はどうですか？","ro":"Nichiyōbi wa dō desu ka?","lit":"dimanche · [thème] · comment · être (poli) · [question]","note":{"lit":"dimanche, petit mot du thème, comment, être, petit mot de question","text":"Pour proposer une autre date, on la met en thème. Comment est-ce se dit « dō desu ka ». C'est une proposition très douce.","say":{"dō desu ka":"どうですか"},"words":[["dimanche","日曜日"],["petit mot du thème","は"],["comment","どう"],["être","です"],["petit mot de question","か"]]}},{"fr":"Dimanche, pas de problème !","tgt":"日曜日は大丈夫です！","ro":"Nichiyōbi wa daijōbu desu!","lit":"dimanche · [thème] · sans problème · être (poli)","note":{"lit":"dimanche, petit mot du thème, sans problème, être","text":"Pas de problème se dit « daijōbu ». Le jour est mis en thème. Dimanche, en tout cas, ça va.","say":{"daijōbu":"大丈夫"},"words":[["dimanche","日曜日"],["petit mot du thème","は"],["sans problème","大丈夫"],["être","です"]]}}],"tip":{"title":"« Kara » : parce que, donner une raison","example":"Parce que j'adore les mangas. — 漫画が大好きです<b>から</b>。","body":"Vous connaissez déjà « kara » au sens de « depuis » ou « à partir de ». Placé à la fin d'une phrase, il prend un autre sens : « parce que ». La grande différence avec le français, c'est l'ordre : en japonais, la raison vient d'abord, puis « kara », puis la conséquence. « Samui desu kara, mado o shimemashō » se dit littéralement : froid, être, parce que, fenêtre, objet, fermons. En français, on dirait : il fait froid, donc fermons la fenêtre. Notre phrase, elle, se décompose ainsi : manga, sujet, très aimé, être, parce que. Elle répond à la question « Dōshite ? », pourquoi ? On peut aussi s'arrêter juste après « kara » pour s'excuser en douceur : « Sono hi wa shigoto ga arimasu kara », c'est que j'ai du travail ce jour-là, et l'autre comprend tout seul. Pour retenir : « kara » est comme une flèche qui part de la cause et pointe vers ce qui suit.","exampleRo":"Manga ga daisuki desu kara.","lit":"manga · [sujet] · très aimé · être (poli) · [parce que]","say":{"Kara":"から","kara":"から","Samui desu kara, mado o shimemashō":"寒いですから、窓を閉めましょう","Dōshite ?":"どうして","Sono hi wa shigoto ga arimasu kara":"その日は仕事がありますから"}}},{"title":"Le grand bouddha de Kamakura","phrases":[{"fr":"Voici le grand bouddha de Kamakura.","tgt":"これが鎌倉の大仏です。","ro":"Kore ga Kamakura no Daibutsu desu.","lit":"ceci · [sujet] · Kamakura · [possessif] · grand bouddha · être (poli)","note":{"lit":"ceci, petit mot du sujet, Kamakura, petit mot de liaison, grand bouddha, être","text":"Ici, ceci prend le petit mot du sujet. Mot à mot, c'est celui-ci qui est le grand bouddha. Ceci se dit « kore ».","say":{"kore":"これ"},"words":[["ceci","これ"],["petit mot du sujet","が"],["Kamakura","鎌倉"],["petit mot de liaison","の"],["grand bouddha","大仏"],["être","です"]]}},{"fr":"Il est vraiment immense !","tgt":"本当に大きいですね！","ro":"Hontō ni ōkii desu ne!","lit":"vraiment · grand · être (poli) · [n'est-ce pas]","note":{"lit":"vraiment, grand, être, petit mot d'accord","text":"Le sujet n'est pas répété. Grand se dit « ōkii ». Le petit mot final exprime l'admiration partagée.","say":{"ōkii":"大きい"},"words":[["vraiment","本当に"],["grand","大きい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"L'entrée coûte trois cents yens.","tgt":"入場料は三百円です。","ro":"Nyūjōryō wa sanbyaku en desu.","lit":"droit d'entrée · [thème] · trois-cents-yens · être (poli)","note":{"lit":"droit d'entrée, petit mot du thème, trois cents, yen, être","text":"Trois cents se dit « sanbyaku ». Le mot cent change de son après trois. Le prix d'entrée est mis en thème.","say":{"sanbyaku":"三百"},"words":[["droit d'entrée","入場料"],["petit mot du thème","は"],["trois cents","三百"],["yen","円"],["être","です"]]}},{"fr":"Il y a beaucoup de visiteurs aujourd'hui.","tgt":"今日は観光客が多いですね。","ro":"Kyō wa kankōkyaku ga ōi desu ne.","lit":"aujourd'hui · [thème] · touristes · [sujet] · nombreux · être (poli) · [n'est-ce pas]","note":{"lit":"aujourd'hui, petit mot du thème, touristes, petit mot du sujet, nombreux, être, petit mot d'accord","text":"Nombreux se dit « ōi ». Il y a beaucoup de visiteurs se dit les visiteurs sont nombreux. Le petit mot final partage la remarque.","say":{"ōi":"多い"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["touristes","観光客"],["petit mot du sujet","が"],["nombreux","多い"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Prenons une photo devant le bouddha.","tgt":"大仏の前で写真を撮りましょう。","ro":"Daibutsu no mae de shashin o torimashō.","lit":"grand bouddha · [possessif] · devant · [lieu] · photo · [objet] · prendre (proposition)","note":{"lit":"grand bouddha, petit mot de liaison, devant, petit mot du lieu, photo, petit mot du complément, prendre","text":"Prenons se dit « torimashō ». C'est prendre avec la fin des propositions. Devant le bouddha se dit le devant du bouddha.","say":{"torimashō":"撮りましょう"},"words":[["grand bouddha","大仏"],["petit mot de liaison","の"],["devant","前"],["petit mot du lieu","で"],["photo","写真"],["petit mot du complément","を"],["prendre","撮りましょう"]]}},{"fr":"Pardon, prenez-nous en photo, s'il vous plaît.","tgt":"すみません、写真を撮ってください。","ro":"Sumimasen, shashin o totte kudasai.","lit":"pardon · photo · [objet] · prendre (forme -te) · s'il vous plaît","note":{"lit":"pardon, photo, petit mot du complément, prendre, s'il vous plaît","text":"Pour demander à un inconnu, on commence par « sumimasen ». Puis on demande avec la forme spéciale du verbe et s'il vous plaît. C'est simple et poli.","say":{"sumimasen":"すみません"},"words":[["pardon","すみません"],["photo","写真"],["petit mot du complément","を"],["prendre","撮って"],["s'il vous plaît","ください"]]}},{"fr":"Ensuite, on va au temple Hase-dera ?","tgt":"それから、長谷寺に行きませんか？","ro":"Sore kara, Hasedera ni ikimasen ka?","lit":"ensuite · Hase-temple · [direction] · aller (négatif poli) · [question]","note":{"lit":"ensuite, Hase-dera, vers, ne pas aller, petit mot de question","text":"Ce temple se dit « Hasedera ». La fin du nom veut dire temple. On propose d'y aller avec une question négative.","say":{"Hasedera":"長谷寺"},"words":[["ensuite","それから"],["Hase-dera","長谷寺"],["vers","に"],["ne pas aller","行きません"],["petit mot de question","か"]]}},{"fr":"Le temple est à cinq minutes à pied.","tgt":"長谷寺は歩いて五分です。","ro":"Hasedera wa aruite gofun desu.","lit":"Hase-temple · [thème] · en marchant · cinq-minutes · être (poli)","note":{"lit":"Hase-dera, petit mot du thème, à pied, cinq minutes, être","text":"À pied se dit « aruite ». Mot à mot, en marchant. La durée suit directement.","say":{"aruite":"歩いて"},"words":[["Hase-dera","長谷寺"],["petit mot du thème","は"],["à pied","歩いて"],["cinq minutes","五分"],["être","です"]]}},{"fr":"En juin, les hortensias y sont magnifiques.","tgt":"六月はあじさいがとてもきれいです。","ro":"Rokugatsu wa ajisai ga totemo kirei desu.","lit":"juin · [thème] · hortensias · [sujet] · très · beau · être (poli)","note":{"lit":"juin, petit mot du thème, hortensias, petit mot du sujet, très, beau, être","text":"Hortensia se dit « ajisai ». Il fleurit pendant la saison des pluies. Juin est mis en thème.","say":{"ajisai":"あじさい"},"words":[["juin","六月"],["petit mot du thème","は"],["hortensias","あじさい"],["petit mot du sujet","が"],["très","とても"],["beau","きれい"],["être","です"]]}},{"fr":"Kamakura est vraiment une ville agréable.","tgt":"鎌倉は本当にいい町です。","ro":"Kamakura wa hontō ni ii machi desu.","lit":"Kamakura · [thème] · vraiment · bon · ville · être (poli)","note":{"lit":"Kamakura, petit mot du thème, vraiment, bon, ville, être","text":"Ville ou quartier se dit « machi ». Une ville agréable se dit une bonne ville. Bon se place devant le nom.","say":{"machi":"町"},"words":[["Kamakura","鎌倉"],["petit mot du thème","は"],["vraiment","本当に"],["bon","いい"],["ville","町"],["être","です"]]}}]},{"title":"Une journée au bord de la mer","phrases":[{"fr":"Hier, nous sommes allés à la plage de Yuigahama.","tgt":"昨日、由比ヶ浜に行きました。","ro":"Kinō, Yuigahama ni ikimashita.","lit":"hier · Yuigahama · [direction] · aller (passé poli)","note":{"lit":"hier, Yuigahama, vers, aller","text":"Hier se dit « kinō ». Il se place au début, sans petit mot. Le verbe est au passé poli.","say":{"kinō":"昨日"},"words":[["hier","昨日"],["Yuigahama","由比ヶ浜"],["vers","に"],["aller","行きました"]]}},{"fr":"Il faisait un temps splendide.","tgt":"とてもいい天気でした。","ro":"Totemo ii tenki deshita.","lit":"très · bon · temps · être (passé poli)","note":{"lit":"très, bon, temps, petit mot du passé","text":"Il faisait beau se dit c'était un bon temps. Le passé du petit mot poli se dit « deshita ». Bon ne change pas, c'est le petit mot qui passe au passé.","say":{"deshita":"でした"},"words":[["très","とても"],["bon","いい"],["temps","天気"],["petit mot du passé","でした"]]}},{"fr":"La mer était un peu froide.","tgt":"海は少し冷たかったです。","ro":"Umi wa sukoshi tsumetakatta desu.","lit":"mer · [thème] · un peu · froid (passé) · (poli)","note":{"lit":"mer, petit mot du thème, un peu, froid, être","text":"Pour le passé d'un adjectif en i, la fin devient « katta ». Froid devient ainsi était froid. On garde le petit mot poli au présent.","say":{"katta":"かった"},"words":[["mer","海"],["petit mot du thème","は"],["un peu","少し"],["froid","冷たかった"],["être","です"]]}},{"fr":"Le sable était brûlant.","tgt":"砂はとても熱かったです。","ro":"Suna wa totemo atsukatta desu.","lit":"sable · [thème] · très · brûlant (passé) · (poli)","note":{"lit":"sable, petit mot du thème, très, brûlant, être","text":"Sable se dit « suna ». Brûlant est ici au passé, avec la même fin. Le petit mot poli reste inchangé.","say":{"suna":"砂"},"words":[["sable","砂"],["petit mot du thème","は"],["très","とても"],["brûlant","熱かった"],["être","です"]]}},{"fr":"Le coucher de soleil était superbe.","tgt":"夕日はとてもきれいでした。","ro":"Yūhi wa totemo kirei deshita.","lit":"soleil couchant · [thème] · très · beau · être (passé poli)","note":{"lit":"soleil couchant, petit mot du thème, très, beau, petit mot du passé","text":"Beau ne finit pas comme les adjectifs en i, il ne change pas. C'est le petit mot poli qui passe au passé. On dit donc « kirei deshita ».","say":{"kirei deshita":"きれいでした"},"words":[["soleil couchant","夕日"],["petit mot du thème","は"],["très","とても"],["beau","きれい"],["petit mot du passé","でした"]]}},{"fr":"Le bol de shirasu était délicieux.","tgt":"しらす丼はおいしかったです。","ro":"Shirasudon wa oishikatta desu.","lit":"bol de shirasu · [thème] · délicieux (passé) · (poli)","note":{"lit":"shirasu, bol de riz, petit mot du thème, délicieux, être","text":"Délicieux au passé se dit « oishikatta ». On le dit après un bon repas. Les shirasu sont de tout petits poissons, spécialité de Kamakura.","say":{"oishikatta":"おいしかった"},"words":[["shirasu","しらす"],["bol de riz","丼"],["petit mot du thème","は"],["délicieux","おいしかった"],["être","です"]]}},{"fr":"Et ce n'était pas cher du tout.","tgt":"全然高くなかったです。","ro":"Zenzen takaku nakatta desu.","lit":"pas du tout · cher · ne pas (passé) · (poli)","note":{"lit":"pas du tout, pas cher, être","text":"Pour le passé négatif d'un adjectif en i, on dit « kunakatta ». Cher devient ainsi n'était pas cher. Pas du tout renforce la négation.","say":{"kunakatta":"くなかった"},"words":[["pas du tout","全然"],["pas cher","高くなかった"],["être","です"]]}},{"fr":"Il y avait beaucoup de monde ?","tgt":"人が多かったですか？","ro":"Hito ga ōkatta desu ka?","lit":"gens · [sujet] · nombreux (passé) · (poli) · [question]","note":{"lit":"gens, petit mot du sujet, nombreux, être, petit mot de question","text":"Nombreux au passé se dit « ōkatta ». Il y avait beaucoup de monde se dit les gens étaient nombreux. On ajoute le petit mot de question.","say":{"ōkatta":"多かった"},"words":[["gens","人"],["petit mot du sujet","が"],["nombreux","多かった"],["être","です"],["petit mot de question","か"]]}},{"fr":"Non, la plage était tranquille.","tgt":"いいえ、浜辺は静かでした。","ro":"Iie, hamabe wa shizuka deshita.","lit":"non · plage · [thème] · calme · être (passé poli)","note":{"lit":"non, plage, petit mot du thème, calme, petit mot du passé","text":"Plage se dit « hamabe ». Calme ne change pas, le petit mot poli passe au passé. La plage est mise en thème.","say":{"hamabe":"浜辺"},"words":[["non","いいえ"],["plage","浜辺"],["petit mot du thème","は"],["calme","静か"],["petit mot du passé","でした"]]}},{"fr":"On s'est vraiment bien amusés.","tgt":"本当に楽しかったです。","ro":"Hontō ni tanoshikatta desu.","lit":"vraiment · amusant (passé) · (poli)","note":{"lit":"vraiment, amusant, être","text":"On s'est bien amusés se dit c'était amusant, « tanoshikatta ». C'est la phrase parfaite pour finir une sortie. Vraiment la renforce.","say":{"tanoshikatta":"楽しかった"},"words":[["vraiment","本当に"],["amusant","楽しかった"],["être","です"]]}}],"tip":{"title":"Le passé des adjectifs : « takakatta, kirei deshita »","example":"La mer était un peu froide. — 海は少し<b>冷たかった</b>です。","body":"En japonais, ce n'est pas seulement le verbe qui se met au passé : les adjectifs en « -i » se conjuguent eux-mêmes ! On remplace le « i » final par « katta ». « Tsumetai », froid, devient « tsumetakatta », était froid. On garde ensuite « desu » juste pour la politesse, sans le mettre au passé. Notre phrase se dit donc littéralement : mer, thème, un peu, froid-passé, poli. De même, « oishii » donne « oishikatta », c'était délicieux, et « tanoshii » donne « tanoshikatta », c'était amusant. Attention à l'exception : « ii », bon, devient « yokatta ». Pour les adjectifs en « -na », comme « kirei » ou « shizuka », c'est plus simple : on met « desu » au passé, « deshita ». « Yūhi wa kirei deshita », le coucher de soleil était beau. Pour retenir : les adjectifs en « -i » portent le passé sur leur dos avec « katta », les adjectifs en « -na » le confient à « deshita ».","exampleRo":"Umi wa sukoshi tsumetakatta desu.","lit":"mer · [thème] · un peu · froid (passé) · (poli)","say":{"Tsumetai":"冷たい","tsumetakatta":"冷たかった","desu":"です","oishii":"おいしい","oishikatta":"おいしかった","tanoshii":"楽しい","tanoshikatta":"楽しかった","ii":"いい","yokatta":"よかった","kirei":"きれい","shizuka":"静か","deshita":"でした","Yūhi wa kirei deshita":"夕日はきれいでした","katta":"かった","takakatta, kirei deshita":"高かった、きれいでした"}}},{"title":"Arriver chez quelqu'un","phrases":[{"fr":"Bienvenue, entrez donc !","tgt":"いらっしゃい。どうぞ、上がってください。","ro":"Irasshai. Dōzo, agatte kudasai.","lit":"bienvenue · je vous en prie · monter (forme -te) · s'il vous plaît","note":{"lit":"bienvenue, je vous en prie, monter, s'il vous plaît","text":"Pour faire entrer chez soi, on dit « agatte kudasai ». Mot à mot, montez, s'il vous plaît. Au Japon, l'entrée de la maison est plus basse que le reste.","say":{"agatte kudasai":"上がってください"},"words":[["bienvenue","いらっしゃい"],["je vous en prie","どうぞ"],["monter","上がって"],["s'il vous plaît","ください"]]}},{"fr":"Merci, pardon de vous déranger.","tgt":"お邪魔します。","ro":"Ojama shimasu.","lit":"honorable-dérangement · faire (poli)","note":{"lit":"pardon de déranger","text":"En entrant chez quelqu'un, on dit « ojama shimasu ». Mot à mot, je vais vous déranger. C'est la formule polie obligatoire.","say":{"ojama shimasu":"お邪魔します"},"words":[["pardon de déranger","お邪魔します"]]}},{"fr":"J'enlève mes chaussures ici ?","tgt":"靴はここで脱ぎますか？","ro":"Kutsu wa koko de nugimasu ka?","lit":"chaussures · [thème] · ici · [lieu] · enlever (poli) · [question]","note":{"lit":"chaussures, petit mot du thème, ici, petit mot du lieu, enlever, petit mot de question","text":"Chaussures se dit « kutsu ». Mis en thème, il veut dire quant aux chaussures. Dans une maison, on les enlève toujours.","say":{"kutsu":"靴"},"words":[["chaussures","靴"],["petit mot du thème","は"],["ici","ここ"],["petit mot du lieu","で"],["enlever","脱ぎます"],["petit mot de question","か"]]}},{"fr":"Oui, voici des pantoufles.","tgt":"はい、スリッパをどうぞ。","ro":"Hai, surippa o dōzo.","lit":"oui · pantoufles · [objet] · je vous en prie","note":{"lit":"oui, pantoufles, petit mot du complément, je vous en prie","text":"Pantoufles se dit « surippa ». Ce mot vient de l'anglais. On les met juste après l'entrée.","say":{"surippa":"スリッパ"},"words":[["oui","はい"],["pantoufles","スリッパ"],["petit mot du complément","を"],["je vous en prie","どうぞ"]]}},{"fr":"Quelle jolie maison !","tgt":"すてきなお宅ですね。","ro":"Suteki na otaku desu ne.","lit":"charmant · [na] · honorable-maison · être (poli) · [n'est-ce pas]","note":{"lit":"charmant, petit mot de l'adjectif, maison, être, petit mot d'accord","text":"La maison de quelqu'un, poliment, se dit « otaku ». Ici, c'est un compliment. Charmant prend le petit mot des adjectifs devant le nom.","say":{"otaku":"お宅"},"words":[["charmant","すてき"],["petit mot de l'adjectif","な"],["maison","お宅"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Asseyez-vous ici, je vous en prie.","tgt":"どうぞ、こちらに座ってください。","ro":"Dōzo, kochira ni suwatte kudasai.","lit":"je vous en prie · ce côté-ci · [lieu] · s'asseoir (forme -te) · s'il vous plaît","note":{"lit":"je vous en prie, par ici, petit mot du lieu, s'asseoir, s'il vous plaît","text":"Asseyez-vous se dit « suwatte kudasai ». Par ici se dit poliment ce côté-ci. Je vous en prie au début rend l'invitation chaleureuse.","say":{"suwatte kudasai":"座ってください"},"words":[["je vous en prie","どうぞ"],["par ici","こちら"],["petit mot du lieu","に"],["s'asseoir","座って"],["s'il vous plaît","ください"]]}},{"fr":"Je vous sers un peu de thé ?","tgt":"お茶はいかがですか？","ro":"Ocha wa ikaga desu ka?","lit":"honorable-thé · [thème] · comment (poli) · être (poli) · [question]","note":{"lit":"thé, petit mot du thème, comment, être, petit mot de question","text":"Pour offrir, on dit « ikaga desu ka ». C'est une version très polie de comment est-ce. On l'emploie avec les invités.","say":{"ikaga desu ka":"いかがですか"},"words":[["thé","お茶"],["petit mot du thème","は"],["comment","いかが"],["être","です"],["petit mot de question","か"]]}},{"fr":"Merci pour ce repas, je commence.","tgt":"いただきます。","ro":"Itadakimasu.","lit":"recevoir humblement (poli)","note":{"lit":"je reçois","text":"Avant de manger, on dit toujours « itadakimasu ». Mot à mot, je reçois humblement. On remercie ainsi pour le repas.","say":{"itadakimasu":"いただきます"},"words":[["je reçois","いただきます"]]}},{"fr":"Tout est vraiment délicieux.","tgt":"全部本当においしいです。","ro":"Zenbu hontō ni oishii desu.","lit":"tout · vraiment · délicieux · être (poli)","note":{"lit":"tout, vraiment, délicieux, être","text":"Tout se dit « zenbu ». Il se place au début de la phrase. On complimente l'ensemble du repas.","say":{"zenbu":"全部"},"words":[["tout","全部"],["vraiment","本当に"],["délicieux","おいしい"],["être","です"]]}},{"fr":"C'était un vrai festin, merci.","tgt":"ごちそうさまでした。","ro":"Gochisōsama deshita.","lit":"honorable-festin · être (passé poli)","note":{"lit":"merci pour le repas","text":"Après le repas, on dit « gochisōsama deshita ». Mot à mot, c'était un festin. C'est le pendant de la formule du début.","say":{"gochisōsama deshita":"ごちそうさまでした"},"words":[["merci pour le repas","ごちそうさまでした"]]}}]},{"title":"Offrir un cadeau","phrases":[{"fr":"Voici un petit quelque chose pour vous.","tgt":"つまらないものですが、どうぞ。","ro":"Tsumaranai mono desu ga, dōzo.","lit":"sans intérêt · chose · être (poli) · [mais] · je vous en prie","note":{"lit":"sans intérêt, chose, être, mais, je vous en prie","text":"Pour offrir un cadeau, on dit traditionnellement que c'est peu de chose. Sans intérêt se dit « tsumaranai ». C'est une marque de modestie.","say":{"tsumaranai":"つまらない"},"words":[["sans intérêt","つまらない"],["chose","もの"],["être","です"],["mais","が"],["je vous en prie","どうぞ"]]}},{"fr":"Oh, il ne fallait pas, merci beaucoup !","tgt":"あ、すみません。ありがとうございます。","ro":"A, sumimasen. Arigatō gozaimasu.","lit":"ah · pardon · merci (très poli)","note":{"lit":"ah, pardon, merci, poliment","text":"En recevant un cadeau, on dit souvent « sumimasen ». Ici, il veut dire merci pour la peine. On ajoute ensuite le vrai merci.","say":{"sumimasen":"すみません"},"words":[["ah","あ"],["pardon","すみません"],["merci","ありがとう"],["poliment","ございます"]]}},{"fr":"J'ai offert du vin à Madame Yamada.","tgt":"山田さんにワインをあげました。","ro":"Yamada-san ni wain o agemashita.","lit":"Yamada-madame · [à] · vin · [objet] · donner (passé poli)","note":{"lit":"Yamada, madame, à, vin, petit mot du complément, donner","text":"Au passé, donner à quelqu'un d'autre se dit « agemashita ». Celui qui reçoit prend le petit mot à. On donne vers l'extérieur.","say":{"agemashita":"あげました"},"words":[["Yamada","山田"],["madame","さん"],["à","に"],["vin","ワイン"],["petit mot du complément","を"],["donner","あげました"]]}},{"fr":"Monsieur Satō m'a offert un éventail.","tgt":"佐藤さんが扇子をくれました。","ro":"Satō-san ga sensu o kuremashita.","lit":"Satō-monsieur · [sujet] · éventail · [objet] · donner à moi (passé poli)","note":{"lit":"Satō, monsieur, petit mot du sujet, éventail, petit mot du complément, me donner","text":"Quand on nous donne quelque chose, on dit « kuremashita ». Ce verbe montre que le cadeau vient vers moi. Celui qui donne prend le petit mot du sujet.","say":{"kuremashita":"くれました"},"words":[["Satō","佐藤"],["monsieur","さん"],["petit mot du sujet","が"],["éventail","扇子"],["petit mot du complément","を"],["me donner","くれました"]]}},{"fr":"Mon mari m'a offert des fleurs.","tgt":"夫に花をもらいました。","ro":"Otto ni hana o moraimashita.","lit":"mon mari · [de la part de] · fleurs · [objet] · recevoir (passé poli)","note":{"lit":"mon mari, de la part de, fleurs, petit mot du complément, recevoir","text":"Au passé, recevoir se dit « moraimashita ». Celui qui donne prend ici le petit mot de la part de. C'est le même fait, vu de l'autre côté.","say":{"moraimashita":"もらいました"},"words":[["mon mari","夫"],["de la part de","に"],["fleurs","花"],["petit mot du complément","を"],["recevoir","もらいました"]]}},{"fr":"Mon fils m'a fait un dessin.","tgt":"息子が絵をくれました。","ro":"Musuko ga e o kuremashita.","lit":"mon fils · [sujet] · dessin · [objet] · donner à moi (passé poli)","note":{"lit":"mon fils, petit mot du sujet, dessin, petit mot du complément, me donner","text":"Dessin se dit « e ». Le fils donne à sa mère, donc on emploie le verbe qui vient vers moi. Mon fils prend le petit mot du sujet.","say":{"e":"絵"},"words":[["mon fils","息子"],["petit mot du sujet","が"],["dessin","絵"],["petit mot du complément","を"],["me donner","くれました"]]}},{"fr":"Qu'est-ce qu'on offre à Kenta pour son anniversaire ?","tgt":"健太くんの誕生日に何をあげましょうか？","ro":"Kenta-kun no tanjōbi ni nani o agemashō ka?","lit":"Kenta-kun · [possessif] · anniversaire · [temps] · quoi · [objet] · donner (proposition) · [question]","note":{"lit":"Kenta, petit mot amical, petit mot de liaison, anniversaire, petit mot du moment, quoi, petit mot du complément, donner, petit mot de question","text":"Anniversaire se dit « tanjōbi ». Kenta est quelqu'un d'autre, donc on emploie le verbe donner vers l'extérieur. On propose avec la fin en question.","say":{"tanjōbi":"誕生日"},"words":[["Kenta","健太"],["petit mot amical","くん"],["petit mot de liaison","の"],["anniversaire","誕生日"],["petit mot du moment","に"],["quoi","何"],["petit mot du complément","を"],["donner","あげましょう"],["petit mot de question","か"]]}},{"fr":"Pourquoi pas un livre ?","tgt":"本はどうですか？","ro":"Hon wa dō desu ka?","lit":"livre · [thème] · comment · être (poli) · [question]","note":{"lit":"livre, petit mot du thème, comment, être, petit mot de question","text":"Pour suggérer une idée, on dit la chose, puis « dō desu ka ». Mot à mot, un livre, comment est-ce. C'est une suggestion douce.","say":{"dō desu ka":"どうですか"},"words":[["livre","本"],["petit mot du thème","は"],["comment","どう"],["être","です"],["petit mot de question","か"]]}},{"fr":"En France, on ouvre les cadeaux tout de suite.","tgt":"フランスではプレゼントをすぐ開けます。","ro":"Furansu de wa purezento o sugu akemasu.","lit":"France · [lieu] · [thème] · cadeau · [objet] · tout de suite · ouvrir (poli)","note":{"lit":"France, petit mot du lieu, petit mot du thème, cadeau, petit mot du complément, tout de suite, ouvrir","text":"Ouvrir quelque chose se dit « akemasu ». C'est un autre verbe que pour une boutique qui ouvre. Tout de suite se place juste avant.","say":{"akemasu":"開けます"},"words":[["France","フランス"],["petit mot du lieu","で"],["petit mot du thème","は"],["cadeau","プレゼント"],["petit mot du complément","を"],["tout de suite","すぐ"],["ouvrir","開けます"]]}},{"fr":"Au Japon, on les ouvre souvent plus tard.","tgt":"日本ではよくあとで開けます。","ro":"Nihon de wa yoku ato de akemasu.","lit":"Japon · [lieu] · [thème] · souvent · plus tard · ouvrir (poli)","note":{"lit":"Japon, petit mot du lieu, petit mot du thème, souvent, plus tard, ouvrir","text":"Plus tard se dit « ato de ». Au Japon, on ouvre souvent les cadeaux après le départ de l'invité. Le thème marque le contraste avec la France.","say":{"ato de":"あとで"},"words":[["Japon","日本"],["petit mot du lieu","で"],["petit mot du thème","は"],["souvent","よく"],["plus tard","あとで"],["ouvrir","開けます"]]}}],"tip":{"title":"Donner et recevoir : « agemasu », « kuremasu », « moraimasu »","example":"Monsieur Satō m'a offert un éventail. — 佐藤さんが扇子を<b>くれました</b>。","body":"En français, on a un seul verbe « donner ». Le japonais en a deux, selon la direction du cadeau, plus un verbe pour « recevoir ». « Agemasu » veut dire donner vers l'extérieur, de moi vers les autres : « Yamada-san ni wain o agemashita », j'ai offert du vin à Madame Yamada. « Kuremasu », au contraire, veut dire donner vers moi, ou vers ma famille. Notre phrase se décompose ainsi : Satō-monsieur, sujet, éventail, objet, donner-à-moi, passé poli. Pas besoin de dire « me » : le verbe « kuremashita » indique déjà que le cadeau est arrivé chez moi. Enfin, « moraimasu » veut dire recevoir, et la personne qui donne prend « ni » : « Otto ni hana o moraimashita », j'ai reçu des fleurs de mon mari. Pour retenir, pensez à une porte : « agemasu » sort de chez moi, « kuremasu » entre chez moi, et « moraimasu », c'est moi qui tends les mains pour recevoir.","exampleRo":"Satō-san ga sensu o kuremashita.","lit":"Satō-monsieur · [sujet] · éventail · [objet] · donner à moi (passé poli)","say":{"agemasu":"あげます","kuremasu":"くれます","moraimasu":"もらいます","Agemasu":"あげます","Yamada-san ni wain o agemashita":"山田さんにワインをあげました","Kuremasu":"くれます","kuremashita":"くれました","ni":"に","Otto ni hana o moraimashita":"夫に花をもらいました"}}},{"title":"Se dire au revoir après la soirée","phrases":[{"fr":"Oh, il est déjà onze heures !","tgt":"あ、もう十一時ですね。","ro":"A, mō jūichiji desu ne.","lit":"ah · déjà · onze-heures · être (poli) · [n'est-ce pas]","note":{"lit":"ah, déjà, onze heures, être, petit mot d'accord","text":"Déjà se dit « mō ». On le dit avec surprise en voyant l'heure. Le petit mot final partage l'étonnement.","say":{"mō":"もう"},"words":[["ah","あ"],["déjà","もう"],["onze heures","十一時"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Je rentre bientôt, à cause du dernier train.","tgt":"終電がありますから、そろそろ帰ります。","ro":"Shūden ga arimasu kara, sorosoro kaerimasu.","lit":"dernier train · [sujet] · il y a (poli) · [parce que] · bientôt · rentrer (poli)","note":{"lit":"dernier train, petit mot du sujet, il y a, parce que, bientôt, rentrer","text":"Le dernier train se dit « shūden ». C'est une excuse très courante pour partir. À Tokyo, il passe vers minuit.","say":{"shūden":"終電"},"words":[["dernier train","終電"],["petit mot du sujet","が"],["il y a","あります"],["parce que","から"],["bientôt","そろそろ"],["rentrer","帰ります"]]}},{"fr":"Merci infiniment pour aujourd'hui.","tgt":"今日は本当にありがとうございました。","ro":"Kyō wa hontō ni arigatō gozaimashita.","lit":"aujourd'hui · [thème] · vraiment · merci (passé, très poli)","note":{"lit":"aujourd'hui, petit mot du thème, vraiment, merci, poliment","text":"En partant, on met le merci au passé. On dit « arigatō gozaimashita ». On remercie pour ce qui vient de se passer.","say":{"arigatō gozaimashita":"ありがとうございました"},"words":[["aujourd'hui","今日"],["petit mot du thème","は"],["vraiment","本当に"],["merci","ありがとう"],["poliment","ございました"]]}},{"fr":"Votre cuisine était délicieuse.","tgt":"お料理、とてもおいしかったです。","ro":"Oryōri, totemo oishikatta desu.","lit":"honorable-cuisine · très · délicieux (passé) · (poli)","note":{"lit":"cuisine, très, délicieux, être","text":"Pour la cuisine de l'hôte, on ajoute le petit son poli, « oryōri ». Délicieux est au passé, car le repas est fini.","say":{"oryōri":"お料理"},"words":[["cuisine","お料理"],["très","とても"],["délicieux","おいしかった"],["être","です"]]}},{"fr":"Revenez quand vous voulez.","tgt":"またいつでも来てください。","ro":"Mata itsu demo kite kudasai.","lit":"de nouveau · n'importe quand · venir (forme -te) · s'il vous plaît","note":{"lit":"encore, n'importe quand, venir, s'il vous plaît","text":"N'importe quand se dit « itsu demo ». C'est quand suivi d'un petit mot qui veut dire même. Revenez se dit venez encore.","say":{"itsu demo":"いつでも"},"words":[["encore","また"],["n'importe quand","いつでも"],["venir","来て"],["s'il vous plaît","ください"]]}},{"fr":"La prochaine fois, venez chez nous.","tgt":"今度はうちに来てください。","ro":"Kondo wa uchi ni kite kudasai.","lit":"la prochaine fois · [thème] · maison · [direction] · venir (forme -te) · s'il vous plaît","note":{"lit":"la prochaine fois, petit mot du thème, maison, vers, venir, s'il vous plaît","text":"Venez se dit « kite kudasai ». C'est venir à la forme spéciale, puis s'il vous plaît. Chez nous se dit simplement notre maison.","say":{"kite kudasai":"来てください"},"words":[["la prochaine fois","今度"],["petit mot du thème","は"],["maison","うち"],["vers","に"],["venir","来て"],["s'il vous plaît","ください"]]}},{"fr":"Rentrez bien, soyez prudents.","tgt":"気をつけて帰ってください。","ro":"Ki o tsukete kaette kudasai.","lit":"attention · [objet] · porter (forme -te) · rentrer (forme -te) · s'il vous plaît","note":{"lit":"attention, petit mot du complément, porter, rentrer, s'il vous plaît","text":"Faites attention se dit « ki o tsukete ». On le dit toujours à quelqu'un qui part. Rentrez prudemment se dit faites attention et rentrez.","say":{"ki o tsukete":"気をつけて"},"words":[["attention","気"],["petit mot du complément","を"],["porter","つけて"],["rentrer","帰って"],["s'il vous plaît","ください"]]}},{"fr":"Mes amitiés à votre épouse.","tgt":"奥さんによろしくお伝えください。","ro":"Okusan ni yoroshiku otsutae kudasai.","lit":"votre épouse · [à] · bien · honorable-transmettre · s'il vous plaît","note":{"lit":"votre épouse, à, bien, transmettre, s'il vous plaît","text":"La femme de quelqu'un d'autre se dit « okusan ». Pour la sienne, on dit un autre mot. Transmettre ses amitiés se dit transmettre bien.","say":{"okusan":"奥さん"},"words":[["votre épouse","奥さん"],["à","に"],["bien","よろしく"],["transmettre","お伝え"],["s'il vous plaît","ください"]]}},{"fr":"Bonne nuit à tous !","tgt":"みなさん、おやすみなさい。","ro":"Minasan, oyasuminasai.","lit":"tout le monde · bonne nuit","note":{"lit":"tout le monde, bonne nuit","text":"Bonne nuit se dit « oyasuminasai ». On le dit en se quittant le soir. Avant, on s'adresse poliment à tout le monde.","say":{"oyasuminasai":"おやすみなさい"},"words":[["tout le monde","みなさん"],["bonne nuit","おやすみなさい"]]}},{"fr":"Allez, à lundi au bureau !","tgt":"じゃあ、また月曜日に会社で。","ro":"Jā, mata getsuyōbi ni kaisha de.","lit":"alors · de nouveau · lundi · [temps] · bureau · [lieu]","note":{"lit":"alors, encore, lundi, petit mot du moment, bureau, petit mot du lieu","text":"Pour dire à bientôt, on dit « mata ». Ici, la phrase s'arrête sans verbe. On comprend à lundi au bureau.","say":{"mata":"また"},"words":[["alors","じゃあ"],["encore","また"],["lundi","月曜日"],["petit mot du moment","に"],["bureau","会社"],["petit mot du lieu","で"]]}}]},{"title":"Fin du module : bilan du niveau 1","phrases":[{"fr":"Le niveau débutant est terminé !","tgt":"初級が終わりました！","ro":"Shokyū ga owarimashita!","lit":"niveau débutant · [sujet] · se terminer (passé poli)","note":{"lit":"niveau débutant, petit mot du sujet, se terminer","text":"Le niveau débutant se dit « shokyū ». Se terminer est ici au passé. C'est une belle étape.","say":{"shokyū":"初級"},"words":[["niveau débutant","初級"],["petit mot du sujet","が"],["se terminer","終わりました"]]}},{"fr":"Le japonais, c'est difficile, n'est-ce pas ?","tgt":"日本語は難しいですね。","ro":"Nihongo wa muzukashii desu ne.","lit":"japonais · [thème] · difficile · être (poli) · [n'est-ce pas]","note":{"lit":"japonais, petit mot du thème, difficile, être, petit mot d'accord","text":"Avec le petit mot final, on cherche l'accord de l'autre. C'est une invitation à répondre, avec « ne ».","say":{"ne":"ね"},"words":[["japonais","日本語"],["petit mot du thème","は"],["difficile","難しい"],["être","です"],["petit mot d'accord","ね"]]}},{"fr":"Oui, c'est vrai, mais c'est passionnant.","tgt":"そうですね。でも、おもしろいです。","ro":"Sō desu ne. Demo, omoshiroi desu.","lit":"ainsi · être (poli) · [n'est-ce pas] · mais · intéressant · être (poli)","note":{"lit":"ainsi, être, petit mot d'accord, mais, intéressant, être","text":"Pour approuver, on dit « sō desu ne ». Mot à mot, c'est ainsi, n'est-ce pas. C'est la petite réaction la plus fréquente.","say":{"sō desu ne":"そうですね"},"words":[["ainsi","そう"],["être","です"],["petit mot d'accord","ね"],["mais","でも"],["intéressant","おもしろい"],["être","です"]]}},{"fr":"Je comprends les phrases simples en japonais.","tgt":"日本語の簡単な文がわかります。","ro":"Nihongo no kantan na bun ga wakarimasu.","lit":"japonais · [possessif] · simple · [na] · phrase · [sujet] · comprendre (poli)","note":{"lit":"japonais, petit mot de liaison, simple, petit mot de l'adjectif, phrase, petit mot du sujet, comprendre","text":"Comprendre se dit « wakarimasu ». Ce qu'on comprend prend le petit mot du sujet. Simple prend le petit mot des adjectifs devant phrase.","say":{"wakarimasu":"わかります"},"words":[["japonais","日本語"],["petit mot de liaison","の"],["simple","簡単"],["petit mot de l'adjectif","な"],["phrase","文"],["petit mot du sujet","が"],["comprendre","わかります"]]}},{"fr":"Je sais me présenter en japonais.","tgt":"日本語で自己紹介ができます。","ro":"Nihongo de jiko shōkai ga dekimasu.","lit":"japonais · [moyen] · présentation de soi · [sujet] · savoir faire (poli)","note":{"lit":"japonais, petit mot du moyen, présentation de soi, petit mot du sujet, savoir faire","text":"Se présenter se dit « jiko shōkai ». Mot à mot, présentation de soi. En japonais prend le petit mot du moyen.","say":{"jiko shōkai":"自己紹介"},"words":[["japonais","日本語"],["petit mot du moyen","で"],["présentation de soi","自己紹介"],["petit mot du sujet","が"],["savoir faire","できます"]]}},{"fr":"Je connais les hiragana et les katakana.","tgt":"ひらがなとカタカナがわかります。","ro":"Hiragana to katakana ga wakarimasu.","lit":"hiragana · [et] · katakana · [sujet] · comprendre (poli)","note":{"lit":"hiragana, et, katakana, petit mot du sujet, comprendre","text":"Pour relier deux noms, on dit « to ». C'est comme et en français. Ce qu'on connaît prend le petit mot du sujet.","say":{"to":"と"},"words":[["hiragana","ひらがな"],["et","と"],["katakana","カタカナ"],["petit mot du sujet","が"],["comprendre","わかります"]]}},{"fr":"Les particules sont plus faciles qu'avant.","tgt":"助詞は前より簡単です。","ro":"Joshi wa mae yori kantan desu.","lit":"particules · [thème] · avant · [plus que] · facile · être (poli)","note":{"lit":"particules, petit mot du thème, avant, plus que, facile, être","text":"Avant, dans le temps, se dit « mae ». Plus qu'avant se dit avant suivi de plus que. Le même mot veut aussi dire devant.","say":{"mae":"前"},"words":[["particules","助詞"],["petit mot du thème","は"],["avant","前"],["plus que","より"],["facile","簡単"],["être","です"]]}},{"fr":"Ah bon ? Vraiment ?","tgt":"へえ、本当ですか？","ro":"Hē, hontō desu ka?","lit":"oh · vrai · être (poli) · [question]","note":{"lit":"oh, vrai, être, petit mot de question","text":"Pour montrer sa surprise, on dit « hē ». Puis on demande c'est vrai. Ces petites réactions rythment la conversation.","say":{"hē":"へえ"},"words":[["oh","へえ"],["vrai","本当"],["être","です"],["petit mot de question","か"]]}},{"fr":"Bientôt, le niveau intermédiaire !","tgt":"もうすぐ中級です。","ro":"Mō sugu chūkyū desu.","lit":"bientôt · niveau intermédiaire · être (poli)","note":{"lit":"bientôt, niveau intermédiaire, être","text":"Bientôt se dit « mōsugu ». Le niveau intermédiaire se dit avec le mot milieu. Pas besoin de verbe ici.","say":{"mōsugu":"もうすぐ"},"words":[["bientôt","もうすぐ"],["niveau intermédiaire","中級"],["être","です"]]}},{"fr":"Continuons nos efforts ensemble !","tgt":"これからも一緒にがんばりましょう！","ro":"Kore kara mo issho ni ganbarimashō!","lit":"à partir de maintenant · [aussi] · ensemble · faire des efforts (proposition)","note":{"lit":"à partir de maintenant, aussi, ensemble, faire des efforts","text":"Faire de son mieux se dit « ganbarimasu ». Ici, on le propose ensemble. C'est le mot d'encouragement le plus japonais.","say":{"ganbarimasu":"がんばります"},"words":[["à partir de maintenant","これから"],["aussi","も"],["ensemble","一緒に"],["faire des efforts","がんばりましょう"]]}}],"tip":{"title":"« Sō desu ne » et les petites réactions qui rythment la conversation","example":"Oui, c'est vrai, mais c'est passionnant. — <b>そうですね</b>。でも、おもしろいです。","body":"Une conversation japonaise est pleine de petites réactions qui montrent qu'on écoute. La plus célèbre est « sō desu ne ». Mot à mot, elle veut dire : ainsi, être, n'est-ce pas ? Autrement dit : oui, c'est vrai, je suis d'accord avec vous. Dans notre phrase, quelqu'un dit que le japonais est difficile, et on répond « Sō desu ne », avant d'ajouter « demo, omoshiroi desu », mais c'est passionnant. Dite lentement, en allongeant le « ne », elle sert aussi à gagner du temps, comme notre « voyons voir ». D'autres réactions sont très utiles : « Sō desu ka », ah bon, je vois, « Hē », oh, vraiment, et « Naruhodo », je comprends, c'est logique. Les Japonais en placent beaucoup plus que nous, c'est une forme de politesse. Pour retenir : en japonais, écouter, c'est aussi parler un peu. Bravo pour ce premier niveau, à très vite pour la suite !","exampleRo":"Sō desu ne. Demo, omoshiroi desu.","lit":"ainsi · être (poli) · [n'est-ce pas] · mais · intéressant · être (poli)","say":{"Sō desu ne":"そうですね","sō desu ne":"そうですね","demo, omoshiroi desu":"でも、おもしろいです","ne":"ね","Sō desu ka":"そうですか","Hē":"へえ","Naruhodo":"なるほど"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Emménager à Osaka","phrases":[{"fr":"La semaine dernière, j'ai emménagé dans un appartement à Osaka.","tgt":"先週、大阪のアパートに引っ越しました。","ro":"Senshū, Ōsaka no apāto ni hikkoshimashita."},{"fr":"La pièce est étroite, mais très lumineuse.","tgt":"部屋は狭いですが、とても明るいです。","ro":"Heya wa semai desu ga, totemo akarui desu."},{"fr":"La gare de Tennōji est à cinq minutes à pied.","tgt":"天王寺駅まで歩いて五分です。","ro":"Tennōji eki made aruite gofun desu."},{"fr":"Le loyer est de soixante-cinq mille yens par mois.","tgt":"家賃は一か月六万五千円です。","ro":"Yachin wa ikkagetsu rokuman gosen en desu."},{"fr":"Enlève tes chaussures dans l'entrée, s'il te plaît.","tgt":"靴は玄関で脱いでください。","ro":"Kutsu wa genkan de nuide kudasai."},{"fr":"Le propriétaire m'a remis deux clés.","tgt":"大家さんが鍵を二つくれました。","ro":"Ōya-san ga kagi o futatsu kuremashita."},{"fr":"Les murs sont fins, alors faites attention au bruit.","tgt":"壁が薄いですから、音に気をつけてください。","ro":"Kabe ga usui desu kara, oto ni ki o tsukete kudasai."},{"fr":"Il n'y a pas encore de rideaux aux fenêtres.","tgt":"窓にまだカーテンがありません。","ro":"Mado ni mada kāten ga arimasen."},{"fr":"Demain, j'irai acheter un frigo et un lave-linge.","tgt":"明日、冷蔵庫と洗濯機を買いに行きます。","ro":"Ashita, reizōko to sentakki o kai ni ikimasu."},{"fr":"Je m'habitue peu à peu à la vie ici.","tgt":"ここの生活にだんだん慣れてきました。","ro":"Koko no seikatsu ni dandan narete kimashita."}]},{"title":"À la mairie du quartier","phrases":[{"fr":"Demain, je passe à la mairie avant d'aller au travail.","tgt":"明日、仕事に行く前に市役所に寄ります。","ro":"Ashita, shigoto ni iku mae ni shiyakusho ni yorimasu."},{"fr":"Aujourd'hui, je compte déclarer ma nouvelle adresse.","tgt":"今日、住所の届け出をするつもりです。","ro":"Kyō, jūsho no todokede o suru tsumori desu."},{"fr":"Peut-on changer l'adresse de la carte de résident ici ?","tgt":"在留カードの住所は、ここで変えることができますか。","ro":"Zairyū kādo no jūsho wa, koko de kaeru koto ga dekimasu ka."},{"fr":"Oui, remplissez d'abord ce formulaire.","tgt":"はい、まずこの用紙に書いてください。","ro":"Hai, mazu kono yōshi ni kaite kudasai."},{"fr":"Prenez un ticket numéroté et patientez, s'il vous plaît.","tgt":"番号札を取って、お待ちください。","ro":"Bangōfuda o totte, omachi kudasai."},{"fr":"Je ne sais pas lire les kanji difficiles.","tgt":"難しい漢字を読むことができません。","ro":"Muzukashii kanji o yomu koto ga dekimasen."},{"fr":"Voulez-vous que je vous aide à écrire ?","tgt":"書くのを手伝いましょうか。","ro":"Kaku no o tetsudaimashō ka."},{"fr":"Il suffit de signer ici.","tgt":"ここにサインをするだけです。","ro":"Koko ni sain o suru dake desu."},{"fr":"L'essentiel, c'est d'avoir toujours sa carte sur soi.","tgt":"大切なのは、カードをいつも持つことです。","ro":"Taisetsu na no wa, kādo o itsumo motsu koto desu."},{"fr":"La semaine prochaine, je compte m'inscrire aussi à l'assurance santé nationale.","tgt":"来週、国民健康保険にも入るつもりです。","ro":"Raishū, kokumin kenkō hoken ni mo hairu tsumori desu."}],"tip":{"title":"La forme du dictionnaire : le verbe « nu », sans politesse","example":"Aujourd'hui, je compte déclarer ma nouvelle adresse. — 今日、住所の届け出を<b>する</b>つもりです。","body":"Jusqu'ici, vous avez toujours conjugué les verbes en « -masu ». Mais chaque verbe a aussi une forme « nue », sans politesse, celle qu'on trouve dans le dictionnaire : « suru » pour « shimasu » (faire), « iku » pour « ikimasu » (aller), « taberu » pour « tabemasu » (manger). Cette forme sert entre amis, mais surtout devant des petits mots qui la réclament, même dans une phrase polie : « tsumori desu » (j'ai l'intention de), « mae ni » (avant de), « koto ga dekimasu » (pouvoir faire). Ainsi, « todokede o suru tsumori desu » se dit littéralement : déclaration, faire, intention, c'est. Autres exemples : « neru mae ni » (avant de dormir), « yomu koto ga dekimasu » (je sais lire). Astuce : la politesse se place toujours à la toute fin de la phrase, donc le verbe du milieu peut rester nu.","exampleRo":"Kyō, jūsho no todokede o suru tsumori desu.","lit":"aujourd'hui · adresse · [possessif] · déclaration · [objet] · faire (forme du dictionnaire) · intention · être (poli)","say":{"suru":"する","shimasu":"します","iku":"行く","ikimasu":"行きます","taberu":"食べる","tabemasu":"食べます","tsumori desu":"つもりです","mae ni":"前に","koto ga dekimasu":"ことができます","todokede o suru tsumori desu":"届け出をするつもりです","neru mae ni":"寝る前に","yomu koto ga dekimasu":"読むことができます","-masu":"ます"}}},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je souhaiterais ouvrir un compte avec ma carte de résident.","tgt":"在留カードで口座を作りたいです。","ro":"Zairyū kādo de kōza o tsukuritai desu."},{"fr":"Avez-vous votre sceau personnel ?","tgt":"印鑑をお持ちですか。","ro":"Inkan o omochi desu ka."},{"fr":"Non. Est-ce qu'une signature convient aussi ?","tgt":"いいえ。サインでも大丈夫ですか。","ro":"Iie. Sain demo daijōbu desu ka."},{"fr":"Oui, mais il faut aussi un numéro de téléphone japonais.","tgt":"はい、でも日本の電話番号も必要です。","ro":"Hai, demo Nihon no denwa bangō mo hitsuyō desu."},{"fr":"Mon entreprise versera mon salaire sur ce compte.","tgt":"会社がこの口座に給料を振り込みます。","ro":"Kaisha ga kono kōza ni kyūryō o furikomimasu."},{"fr":"La carte de retrait arrivera par la poste d'ici une semaine environ.","tgt":"キャッシュカードは一週間ぐらいで郵便で届きます。","ro":"Kyasshu kādo wa isshūkan gurai de yūbin de todokimasu."},{"fr":"Peut-on retirer de l'argent au distributeur le dimanche aussi ?","tgt":"日曜日も機械でお金を下ろすことができますか。","ro":"Nichiyōbi mo kikai de okane o orosu koto ga dekimasu ka."},{"fr":"Oui, mais il y a des frais de cent dix yens.","tgt":"はい、でも手数料が百十円かかります。","ro":"Hai, demo tesūryō ga hyakujū en kakarimasu."},{"fr":"Au Japon, on paie encore souvent en liquide.","tgt":"日本ではまだよく現金で払います。","ro":"Nihon de wa mada yoku genkin de haraimasu."},{"fr":"Merci, je reviendrai avec mon sceau la prochaine fois.","tgt":"ありがとうございます。今度は印鑑を持ってきます。","ro":"Arigatō gozaimasu. Kondo wa inkan o motte kimasu."}]},{"title":"Le tri des déchets","phrases":[{"fr":"À Osaka, le tri des déchets est très strict.","tgt":"大阪はごみの分別がとても厳しいです。","ro":"Ōsaka wa gomi no bunbetsu ga totemo kibishii desu."},{"fr":"Les ordures ménagères se sortent le lundi et le jeudi.","tgt":"普通ごみは月曜日と木曜日に出します。","ro":"Futsū gomi wa getsuyōbi to mokuyōbi ni dashimasu."},{"fr":"Les bouteilles en plastique, c'est le mercredi.","tgt":"ペットボトルは水曜日です。","ro":"Petto botoru wa suiyōbi desu."},{"fr":"Enlevez le bouchon et l'étiquette, s'il vous plaît.","tgt":"キャップとラベルを取ってください。","ro":"Kyappu to raberu o totte kudasai."},{"fr":"Rince les canettes avant de les jeter.","tgt":"缶は洗ってから捨ててください。","ro":"Kan wa aratte kara sutete kudasai."},{"fr":"Les poubelles doivent être sorties avant huit heures du matin.","tgt":"ごみは朝八時までに出してください。","ro":"Gomi wa asa hachiji made ni dashite kudasai."},{"fr":"Pour les encombrants, on appelle la mairie pour faire une demande.","tgt":"大きいごみは市役所に電話して申し込みます。","ro":"Ōkii gomi wa shiyakusho ni denwa shite mōshikomimasu."},{"fr":"Le voisin m'a montré le calendrier des collectes.","tgt":"隣の人がごみの日のカレンダーを見せてくれました。","ro":"Tonari no hito ga gomi no hi no karendā o misete kuremashita."},{"fr":"Je l'ai collé sur la porte du frigo.","tgt":"冷蔵庫のドアに貼りました。","ro":"Reizōko no doa ni harimashita."},{"fr":"Au début, c'est pénible, mais on s'y habitue vite.","tgt":"最初は大変ですが、すぐ慣れます。","ro":"Saisho wa taihen desu ga, sugu naremasu."}]},{"title":"Un matin pressé","phrases":[{"fr":"Le matin, je me lève à six heures et je prends une douche.","tgt":"朝は六時に起きて、シャワーを浴びます。","ro":"Asa wa rokuji ni okite, shawā o abimasu."},{"fr":"Ensuite, je fais du café et je lis les nouvelles.","tgt":"それから、コーヒーをいれて、ニュースを読みます。","ro":"Sore kara, kōhī o irete, nyūsu o yomimasu."},{"fr":"Je sors les poubelles, puis je pars à la gare.","tgt":"ごみを出して、駅へ行きます。","ro":"Gomi o dashite, eki e ikimasu."},{"fr":"Je prends la ligne Midōsuji et je change à Umeda.","tgt":"御堂筋線に乗って、梅田で乗り換えます。","ro":"Midōsuji-sen ni notte, Umeda de norikaemasu."},{"fr":"J'achète un onigiri au konbini et je le mange au bureau.","tgt":"コンビニでおにぎりを買って、会社で食べます。","ro":"Konbini de onigiri o katte, kaisha de tabemasu."},{"fr":"Ce matin, je ne me suis pas réveillé et j'ai couru jusqu'à la gare.","tgt":"今朝は寝坊して、駅まで走りました。","ro":"Kesa wa nebō shite, eki made hashirimashita."},{"fr":"Je me suis habillé en vitesse et je suis sorti de chez moi.","tgt":"急いで着替えて、家を出ました。","ro":"Isoide kigaete, ie o demashita."},{"fr":"Heureusement, je suis arrivé juste à temps.","tgt":"幸い、時間に間に合いました。","ro":"Saiwai, jikan ni maniaimashita."},{"fr":"Le soir, je rentre, je prends un bain et je me couche tôt.","tgt":"夜は家に帰って、お風呂に入って、早く寝ます。","ro":"Yoru wa ie ni kaette, ofuro ni haitte, hayaku nemasu."},{"fr":"Demain, je vais me lever un peu plus tôt.","tgt":"明日はもう少し早く起きます。","ro":"Ashita wa mō sukoshi hayaku okimasu."}],"tip":{"title":"La forme en « -te » pour enchaîner les actions","example":"Le soir, je rentre, je prends un bain et je me couche tôt. — 夜は家に<b>帰って</b>、お風呂に<b>入って</b>、早く寝ます。","body":"Vous connaissez déjà la forme en « -te » avec « kudasai ». Elle sert aussi à enchaîner plusieurs actions, comme nos virgules et nos « puis ». Seul le dernier verbe porte le temps et la politesse : les autres restent en « -te », comme en attente. « Yoru wa ie ni kaette, ofuro ni haitte, hayaku nemasu » se dit littéralement : soir, maison vers, rentrer et, bain dans, entrer et, tôt, se coucher. Autres exemples : « okite, shawā o abimasu » (je me lève et je me douche), « katte, tabemasu » (j'achète et je mange). Astuce : imaginez des wagons en « -te » accrochés à une locomotive en « -masu », qui décide de tout le train.","exampleRo":"Yoru wa ie ni kaette, ofuro ni haitte, hayaku nemasu.","lit":"soir · [thème] · maison · [direction] · rentrer (forme -te) · bain · [dans] · entrer (forme -te) · tôt · se coucher (poli)","say":{"kudasai":"ください","Yoru wa ie ni kaette, ofuro ni haitte, hayaku nemasu":"夜は家に帰って、お風呂に入って、早く寝ます","okite, shawā o abimasu":"起きて、シャワーを浴びます","katte, tabemasu":"買って、食べます","-masu":"ます"}}},{"title":"Entre colocataires","phrases":[{"fr":"Ce soir, tu ne viens pas au sentō ?","tgt":"今夜、銭湯に行かない？","ro":"Kon'ya, sentō ni ikanai?"},{"fr":"Non, je n'y vais pas, je suis vraiment crevé.","tgt":"ううん、行かない。すごく疲れてるから。","ro":"Uun, ikanai. Sugoku tsukareteru kara."},{"fr":"Tu ne manges pas ? Il reste du curry, tu sais.","tgt":"食べないの？カレーが残ってるよ。","ro":"Tabenai no? Karē ga nokotteru yo."},{"fr":"Je n'ai pas faim, merci quand même.","tgt":"お腹すいてない。でも、ありがとう。","ro":"Onaka suitenai. Demo, arigatō."},{"fr":"Je ne comprends pas bien cette lettre de la mairie.","tgt":"市役所の手紙、よく分からない。","ro":"Shiyakusho no tegami, yoku wakaranai."},{"fr":"Ne t'inquiète pas, on va la lire ensemble.","tgt":"心配しないで。一緒に読もう。","ro":"Shinpai shinaide. Issho ni yomō."},{"fr":"N'ouvre pas la fenêtre, d'accord ? Il pleut aujourd'hui.","tgt":"窓は開けないでね。今日は雨だから。","ro":"Mado wa akenaide ne. Kyō wa ame da kara."},{"fr":"Ne fumez pas dans l'appartement, s'il vous plaît.","tgt":"部屋でたばこを吸わないでください。","ro":"Heya de tabako o suwanaide kudasai."},{"fr":"Je n'ai pas encore décidé, je te recontacte demain.","tgt":"まだ決めてない。明日連絡するね。","ro":"Mada kimetenai. Ashita renraku suru ne."},{"fr":"T'en fais pas, ce n'est pas bien grave.","tgt":"大丈夫、大したことないよ。","ro":"Daijōbu, taishita koto nai yo."}],"tip":{"title":"La forme en « -nai » : la négation familière","example":"Ce soir, tu ne viens pas au sentō ? — 今夜、銭湯に<b>行かない</b>？","body":"Entre amis, « ikimasen » (je ne vais pas) devient simplement « ikanai ». Pour les verbes en « -u », on remplace le « u » final par « anai » : « kaku » devient « kakanai », « yomu » devient « yomanai », et « kau » devient « kawanai ». Pour les verbes en « -ru » comme « taberu », on enlève « ru » et on ajoute « nai » : « tabenai ». Les deux irréguliers : « suru » donne « shinai », et « kuru » donne « konai ». Avec une intonation montante, « Sentō ni ikanai ? » se dit littéralement : bain public vers, ne pas aller ? C'est une invitation, comme notre « tu ne viendrais pas ? ». Astuce : ajoutez « -de kudasai » et vous obtenez une demande polie de ne pas faire : « suwanaide kudasai », ne fumez pas, s'il vous plaît.","exampleRo":"Kon'ya, sentō ni ikanai?","lit":"ce soir · bain public · [direction] · aller (forme -nai) · (intonation montante)","say":{"ikimasen":"行きません","ikanai":"行かない","kaku":"書く","kakanai":"書かない","yomu":"読む","yomanai":"読まない","kau":"買う","kawanai":"買わない","taberu":"食べる","nai":"ない","tabenai":"食べない","suru":"する","shinai":"しない","kuru":"くる","konai":"こない","Sentō ni ikanai ?":"銭湯に行かない？","suwanaide kudasai":"座らないでください","-ru":"る","ru":"る"}}},{"title":"À la clinique","phrases":[{"fr":"Depuis hier, j'ai de la fièvre et mal à la gorge.","tgt":"昨日から熱があって、喉が痛いです。","ro":"Kinō kara netsu ga atte, nodo ga itai desu."},{"fr":"C'est votre première visite dans cette clinique ?","tgt":"このクリニックは初めてですか。","ro":"Kono kurinikku wa hajimete desu ka."},{"fr":"Oui, voici ma carte d'assurance maladie.","tgt":"はい、これが保険証です。","ro":"Hai, kore ga hokenshō desu."},{"fr":"Remplissez ce questionnaire en attendant, s'il vous plaît.","tgt":"待っている間に、この問診票を書いてください。","ro":"Matte iru aida ni, kono monshinhyō o kaite kudasai."},{"fr":"Ouvrez la bouche et dites « a ».","tgt":"口を開けて、「あー」と言ってください。","ro":"Kuchi o akete, \"ā\" to itte kudasai."},{"fr":"C'est juste un rhume, ne vous inquiétez pas.","tgt":"ただの風邪ですね。心配ありません。","ro":"Tada no kaze desu ne. Shinpai arimasen."},{"fr":"Reposez-vous bien pendant deux ou trois jours.","tgt":"二、三日ゆっくり休んでください。","ro":"Ni-sannichi yukkuri yasunde kudasai."},{"fr":"Je vous donne une ordonnance : apportez-la à la pharmacie d'à côté.","tgt":"処方箋を出しますから、隣の薬局に持っていってください。","ro":"Shohōsen o dashimasu kara, tonari no yakkyoku ni motte itte kudasai."},{"fr":"Combien coûte la consultation ?","tgt":"診察代はいくらですか。","ro":"Shinsatsudai wa ikura desu ka."},{"fr":"Avec l'assurance, cela fait mille deux cents yens.","tgt":"保険で千二百円です。","ro":"Hoken de sen nihyaku en desu."}]},{"title":"À la pharmacie","phrases":[{"fr":"Je cherche un médicament contre le rhume.","tgt":"風邪薬を探しています。","ro":"Kazegusuri o sagashite imasu."},{"fr":"Avez-vous de la fièvre ou de la toux ?","tgt":"熱や咳がありますか。","ro":"Netsu ya seki ga arimasu ka."},{"fr":"Je tousse un peu, surtout la nuit.","tgt":"少し咳が出ます。特に夜です。","ro":"Sukoshi seki ga demasu. Toku ni yoru desu."},{"fr":"Ce sirop marche très bien, vous savez.","tgt":"このシロップはよく効きますよ。","ro":"Kono shiroppu wa yoku kikimasu yo."},{"fr":"Prenez-le trois fois par jour, après les repas.","tgt":"一日三回、食後に飲んでください。","ro":"Ichinichi sankai, shokugo ni nonde kudasai."},{"fr":"Je prends déjà un médicament pour l'estomac.","tgt":"胃の薬をもう飲んでいます。","ro":"I no kusuri o mō nonde imasu."},{"fr":"Dans ce cas, je vais demander au pharmacien.","tgt":"それなら、薬剤師に聞いてみます。","ro":"Sore nara, yakuzaishi ni kiite mimasu."},{"fr":"Cette pharmacie vend aussi des cosmétiques et des boissons.","tgt":"このドラッグストアは化粧品や飲み物も売っています。","ro":"Kono doraggu sutoa wa keshōhin ya nomimono mo utte imasu."},{"fr":"Avez-vous une carte de fidélité ?","tgt":"ポイントカードはお持ちですか。","ro":"Pointo kādo wa omochi desu ka."},{"fr":"Non, mais j'aimerais bien en faire une.","tgt":"いいえ、でも作りたいです。","ro":"Iie, demo tsukuritai desu."}]},{"title":"Au supermarché du quartier","phrases":[{"fr":"Le supermarché près de chez moi est ouvert jusqu'à vingt-deux heures.","tgt":"家の近くのスーパーは夜十時まで開いています。","ro":"Ie no chikaku no sūpā wa yoru jūji made aite imasu."},{"fr":"À partir de dix-neuf heures, les bentō deviennent moins chers.","tgt":"夜七時から、お弁当が安くなります。","ro":"Yoru shichiji kara, obentō ga yasuku narimasu."},{"fr":"On y colle des étiquettes « moitié prix ».","tgt":"半額のシールが貼ってあります。","ro":"Hangaku no shīru ga hatte arimasu."},{"fr":"Ces fraises de Nara sont sucrées et délicieuses.","tgt":"この奈良のいちごは甘くておいしいです。","ro":"Kono Nara no ichigo wa amakute oishii desu."},{"fr":"Où se trouve le rayon du tofu ?","tgt":"豆腐の売り場はどこですか。","ro":"Tōfu no uriba wa doko desu ka."},{"fr":"Au fond, à côté du lait.","tgt":"奥の、牛乳の隣です。","ro":"Oku no, gyūnyū no tonari desu."},{"fr":"Vous voulez un sac en plastique ?","tgt":"レジ袋はご利用ですか。","ro":"Rejibukuro wa goriyō desu ka."},{"fr":"Non merci, j'ai apporté mon propre sac.","tgt":"いいえ、マイバッグがあります。","ro":"Iie, mai baggu ga arimasu."},{"fr":"Est-ce qu'on peut payer avec son téléphone ?","tgt":"スマホで払うことができますか。","ro":"Sumaho de harau koto ga dekimasu ka."},{"fr":"Oui, et en plus vous cumulez des points.","tgt":"はい、ポイントもたまりますよ。","ro":"Hai, pointo mo tamarimasu yo."}]},{"title":"Le sentō du quartier","phrases":[{"fr":"Il y a un vieux sentō à deux pas de chez moi.","tgt":"家のすぐ近くに古い銭湯があります。","ro":"Ie no sugu chikaku ni furui sentō ga arimasu."},{"fr":"L'entrée coûte cinq cent vingt yens pour un adulte.","tgt":"入浴料は大人五百二十円です。","ro":"Nyūyokuryō wa otona gohyaku nijū en desu."},{"fr":"Le rideau bleu, c'est pour les hommes, le rouge pour les femmes.","tgt":"青いのれんは男湯、赤いのれんは女湯です。","ro":"Aoi noren wa otokoyu, akai noren wa onnayu desu."},{"fr":"Avant d'entrer dans l'eau, on se lave soigneusement.","tgt":"お湯に入る前に、体をよく洗います。","ro":"Oyu ni hairu mae ni, karada o yoku araimasu."},{"fr":"Ne mettez pas votre serviette dans l'eau, s'il vous plaît.","tgt":"タオルはお湯に入れないでください。","ro":"Taoru wa oyu ni irenaide kudasai."},{"fr":"L'eau est vraiment brûlante aujourd'hui !","tgt":"今日のお湯は本当に熱いですね。","ro":"Kyō no oyu wa hontō ni atsui desu ne."},{"fr":"Au mur, il y a une grande peinture du mont Fuji.","tgt":"壁に大きな富士山の絵があります。","ro":"Kabe ni ōkina Fujisan no e ga arimasu."},{"fr":"Les habitués bavardent tranquillement entre eux.","tgt":"常連さんたちがのんびり話しています。","ro":"Jōren-san-tachi ga nonbiri hanashite imasu."},{"fr":"Après le bain, on boit un lait au café bien frais.","tgt":"お風呂の後は、冷たいコーヒー牛乳を飲みます。","ro":"Ofuro no ato wa, tsumetai kōhī gyūnyū o nomimasu."},{"fr":"C'est le moment le plus heureux de ma semaine.","tgt":"これが一週間で一番幸せな時間です。","ro":"Kore ga isshūkan de ichiban shiawase na jikan desu."}]},{"title":"Un petit boulot à Kobe","phrases":[{"fr":"Je travaille à mi-temps dans un café de Kobe.","tgt":"神戸のカフェでアルバイトをしています。","ro":"Kōbe no kafe de arubaito o shite imasu."},{"fr":"Je travaille trois jours par semaine, de midi à dix-huit heures.","tgt":"週に三日、十二時から六時まで働いています。","ro":"Shū ni mikka, jūniji kara rokuji made hataraite imasu."},{"fr":"Le salaire horaire est de mille cent cinquante yens.","tgt":"時給は千百五十円です。","ro":"Jikyū wa sen hyaku gojū en desu."},{"fr":"Le gérant est exigeant, mais gentil.","tgt":"店長は厳しいですが、優しいです。","ro":"Tenchō wa kibishii desu ga, yasashii desu."},{"fr":"On dit « irasshaimase » à chaque client.","tgt":"お客さんに「いらっしゃいませ」と言います。","ro":"Okyakusan ni \"irasshaimase\" to iimasu."},{"fr":"Au début, je me trompais souvent dans les commandes.","tgt":"最初は、よく注文を間違えました。","ro":"Saisho wa, yoku chūmon o machigaemashita."},{"fr":"Maintenant, je sais préparer un bon café au lait.","tgt":"今は、おいしいカフェラテをいれることができます。","ro":"Ima wa, oishii kafe rate o ireru koto ga dekimasu."},{"fr":"Mes collègues sont tous étudiants à l'université.","tgt":"同僚はみんな大学生です。","ro":"Dōryō wa minna daigakusei desu."},{"fr":"Après le service, on mange souvent ensemble.","tgt":"仕事の後、よく一緒にご飯を食べます。","ro":"Shigoto no ato, yoku issho ni gohan o tabemasu."},{"fr":"Grâce à ce travail, mon japonais s'améliore de jour en jour.","tgt":"この仕事のおかげで、日本語がどんどん上手になります。","ro":"Kono shigoto no okage de, nihongo ga dondon jōzu ni narimasu."}]},{"title":"Le week-end dernier à Kobe","phrases":[{"fr":"Le week-end dernier, tu as fait quoi ?","tgt":"先週末、何した？","ro":"Senshūmatsu, nani shita?"},{"fr":"Je suis allé à Kobe avec des amis.","tgt":"友達と神戸に行った。","ro":"Tomodachi to Kōbe ni itta."},{"fr":"On a mangé du bœuf de Kobe à Sannomiya.","tgt":"三宮で神戸牛を食べたよ。","ro":"Sannomiya de Kōbegyū o tabeta yo."},{"fr":"C'était cher, mais vraiment délicieux.","tgt":"高かったけど、本当においしかった。","ro":"Takakatta kedo, hontō ni oishikatta."},{"fr":"Ensuite, on s'est baladés au parc Meriken, près du port.","tgt":"それから、港のメリケンパークを散歩した。","ro":"Sore kara, minato no Meriken pāku o sanpo shita."},{"fr":"Tu as vu la tour du port de Kobe ?","tgt":"神戸ポートタワー、見た？","ro":"Kōbe pōto tawā, mita?"},{"fr":"Oui, et le soir, on est allés au mont Rokkō.","tgt":"うん。夜は六甲山に行った。","ro":"Un. Yoru wa Rokkōsan ni itta."},{"fr":"La vue de nuit était superbe.","tgt":"夜景がすごくきれいだった。","ro":"Yakei ga sugoku kirei datta."},{"fr":"Moi, je ne suis allé nulle part, j'ai fait le ménage.","tgt":"僕はどこにも行かなかった。掃除をした。","ro":"Boku wa doko ni mo ikanakatta. Sōji o shita."},{"fr":"Tu n'es jamais monté au mont Rokkō ?","tgt":"六甲山に行ったことない？","ro":"Rokkōsan ni itta koto nai?"}],"tip":{"title":"La forme en « -ta » : le passé familier","example":"Je suis allé à Kobe avec des amis. — 友達と神戸に<b>行った</b>。","body":"Entre amis, « ikimashita » (je suis allé) devient « itta ». Bonne nouvelle : si vous connaissez la forme en « -te », vous connaissez déjà la forme en « -ta », il suffit de changer la dernière voyelle. « Itte » donne « itta », « tabete » donne « tabeta », « shite » donne « shita ». Ainsi, « Tomodachi to Kōbe ni itta » se dit littéralement : amis avec, Kobe vers, être allé. Pour les adjectifs, on garde « takakatta » (c'était cher), et pour les noms ou les adjectifs en « -na », on dit « datta » : « kirei datta », c'était beau. Astuce : suivi de « koto ga aru », ce passé veut dire « avoir déjà fait » : « itta koto aru ? », tu y es déjà allé ?","exampleRo":"Tomodachi to Kōbe ni itta.","lit":"amis · [avec] · Kobe · [direction] · aller (passé familier)","say":{"ikimashita":"行きました","itta":"行った","Itte":"行って","tabete":"食べて","tabeta":"食べた","shite":"して","shita":"した","Tomodachi to Kōbe ni itta":"友達と神戸に行った","takakatta":"高かった","datta":"だった","kirei datta":"きれいだった","koto ga aru":"ことがある","itta koto aru ?":"行ったことある？"}}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Pour saluer mes voisins après le déménagement, je leur ai apporté des serviettes.","tgt":"引っ越しのあいさつに、タオルを持っていきました。","ro":"Hikkoshi no aisatsu ni, taoru o motte ikimashita."},{"fr":"La dame de l'étage du dessus est très aimable.","tgt":"上の階の奥さんはとても親切です。","ro":"Ue no kai no okusan wa totemo shinsetsu desu."},{"fr":"Elle m'a donné des légumes de la campagne.","tgt":"田舎の野菜をくれました。","ro":"Inaka no yasai o kuremashita."},{"fr":"Le vieux monsieur d'en face promène son chien tous les matins.","tgt":"向かいのおじいさんは毎朝犬の散歩をしています。","ro":"Mukai no ojiisan wa maiasa inu no sanpo o shite imasu."},{"fr":"À Osaka, les gens adressent volontiers la parole aux inconnus.","tgt":"大阪の人は知らない人にもよく話しかけます。","ro":"Ōsaka no hito wa shiranai hito ni mo yoku hanashikakemasu."},{"fr":"Les commerçants disent souvent « maido » au lieu de « konnichiwa ».","tgt":"お店の人は、よく「こんにちは」の代わりに「まいど」と言います。","ro":"Omise no hito wa, yoku \"konnichiwa\" no kawari ni \"maido\" to iimasu."},{"fr":"Hier soir, la musique d'à côté était un peu forte.","tgt":"昨日の夜、隣の音楽が少しうるさかったです。","ro":"Kinō no yoru, tonari no ongaku ga sukoshi urusakatta desu."},{"fr":"Je suis allé lui en parler poliment.","tgt":"丁寧に話しに行きました。","ro":"Teinei ni hanashi ni ikimashita."},{"fr":"Il s'est excusé tout de suite.","tgt":"すぐに謝ってくれました。","ro":"Sugu ni ayamatte kuremashita."},{"fr":"Depuis, on se salue à chaque fois.","tgt":"それからは、毎回あいさつをしています。","ro":"Sore kara wa, maikai aisatsu o shite imasu."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais à la campagne en France.","tgt":"子供のころ、フランスの田舎に住んでいました。","ro":"Kodomo no koro, Furansu no inaka ni sunde imashita."},{"fr":"Je jouais dehors tous les jours avec mon grand frère.","tgt":"毎日、兄と外で遊んでいました。","ro":"Mainichi, ani to soto de asonde imashita."},{"fr":"Et vous, monsieur Tanaka, où avez-vous grandi ?","tgt":"田中さんはどこで育ちましたか。","ro":"Tanaka-san wa doko de sodachimashita ka."},{"fr":"J'ai grandi près d'une rue commerçante d'Osaka.","tgt":"大阪の商店街の近くで育ちました。","ro":"Ōsaka no shōtengai no chikaku de sodachimashita."},{"fr":"Mes parents tenaient une petite boutique de takoyaki.","tgt":"両親が小さいたこ焼き屋をやっていました。","ro":"Ryōshin ga chiisai takoyakiya o yatte imashita."},{"fr":"Après l'école, j'aidais souvent au magasin.","tgt":"学校の後、よく店を手伝いました。","ro":"Gakkō no ato, yoku mise o tetsudaimashita."},{"fr":"Enfant, je n'aimais pas du tout les légumes.","tgt":"子供のころは、野菜が全然好きじゃありませんでした。","ro":"Kodomo no koro wa, yasai ga zenzen suki ja arimasen deshita."},{"fr":"Le soir, ma grand-mère me racontait des contes d'autrefois.","tgt":"祖母は夜に昔話をしてくれました。","ro":"Sobo wa yoru ni mukashibanashi o shite kuremashita."},{"fr":"Les étés étaient longs et très chauds.","tgt":"夏は長くて、とても暑かったです。","ro":"Natsu wa nagakute, totemo atsukatta desu."},{"fr":"Que de souvenirs, ça me rend nostalgique.","tgt":"本当に懐かしいですね。","ro":"Hontō ni natsukashii desu ne."}]},{"title":"Un typhon approche","phrases":[{"fr":"Un gros typhon arrive demain soir sur le Kansai.","tgt":"明日の夜、大きい台風が関西に来ます。","ro":"Ashita no yoru, ōkii taifū ga Kansai ni kimasu."},{"fr":"Les trains vont sans doute s'arrêter.","tgt":"電車はたぶん止まるでしょう。","ro":"Densha wa tabun tomaru deshō."},{"fr":"Rentrez tout ce qui traîne sur le balcon.","tgt":"ベランダの物を中に入れてください。","ro":"Beranda no mono o naka ni irete kudasai."},{"fr":"J'ai acheté de l'eau et des piles au konbini.","tgt":"コンビニで水と電池を買いました。","ro":"Konbini de mizu to denchi o kaimashita."},{"fr":"J'ai aussi rechargé mon portable.","tgt":"スマホも充電しました。","ro":"Sumaho mo jūden shimashita."},{"fr":"L'entreprise a prévenu : demain, télétravail.","tgt":"会社から「明日は在宅勤務」と連絡がありました。","ro":"Kaisha kara \"ashita wa zaitaku kinmu\" to renraku ga arimashita."},{"fr":"Le vent souffle déjà très fort.","tgt":"もう風がとても強いです。","ro":"Mō kaze ga totemo tsuyoi desu."},{"fr":"Ne sortez pas pendant le typhon.","tgt":"台風の間は外に出ないでください。","ro":"Taifū no aida wa soto ni denaide kudasai."},{"fr":"Où se trouve le centre d'évacuation le plus proche ?","tgt":"一番近い避難所はどこですか。","ro":"Ichiban chikai hinanjo wa doko desu ka."},{"fr":"C'est l'école primaire, derrière la mairie.","tgt":"市役所の裏の小学校です。","ro":"Shiyakusho no ura no shōgakkō desu."}]},{"title":"Le lendemain du typhon","phrases":[{"fr":"Le typhon est passé dans la nuit.","tgt":"台風は夜の間に過ぎました。","ro":"Taifū wa yoru no aida ni sugimashita."},{"fr":"Ce matin, le ciel est d'un bleu parfait.","tgt":"今朝は空が真っ青です。","ro":"Kesa wa sora ga massao desu."},{"fr":"Des branches sont tombées un peu partout dans la rue.","tgt":"道のあちこちに枝が落ちています。","ro":"Michi no achikochi ni eda ga ochite imasu."},{"fr":"Il y a eu une coupure de courant d'environ trois heures.","tgt":"三時間ぐらい停電しました。","ro":"Sanjikan gurai teiden shimashita."},{"fr":"Heureusement, notre maison n'a subi aucun dégât.","tgt":"幸い、家には被害がありませんでした。","ro":"Saiwai, ie ni wa higai ga arimasen deshita."},{"fr":"Le parapluie de la voisine s'est envolé.","tgt":"隣の奥さんの傘が飛んでいきました。","ro":"Tonari no okusan no kasa ga tonde ikimashita."},{"fr":"Tout le quartier nettoie la rue ensemble.","tgt":"町内のみんなで道を掃除しています。","ro":"Chōnai no minna de michi o sōji shite imasu."},{"fr":"Je vais aider aussi, attendez-moi une seconde.","tgt":"私も手伝います。ちょっと待ってください。","ro":"Watashi mo tetsudaimasu. Chotto matte kudasai."},{"fr":"Les trains ont recommencé à circuler vers midi.","tgt":"電車は昼ごろ動き始めました。","ro":"Densha wa hiru goro ugokihajimemashita."},{"fr":"Au Japon, il est important de savoir vivre avec les typhons.","tgt":"日本では、台風とうまく付き合うことが大切です。","ro":"Nihon de wa, taifū to umaku tsukiau koto ga taisetsu desu."}]},{"title":"Une journée à Kobe","phrases":[{"fr":"Samedi prochain, je vais visiter le quartier de Kitano, à Kobe.","tgt":"今度の土曜日、神戸の北野を見に行きます。","ro":"Kondo no doyōbi, Kōbe no Kitano o mi ni ikimasu."},{"fr":"Depuis Osaka, c'est à une demi-heure de train environ.","tgt":"大阪から電車で三十分ぐらいです。","ro":"Ōsaka kara densha de sanjuppun gurai desu."},{"fr":"On y trouve beaucoup d'anciennes maisons de style occidental.","tgt":"古い洋館がたくさんあります。","ro":"Furui yōkan ga takusan arimasu."},{"fr":"Les rues montent beaucoup, venez avec de bonnes chaussures.","tgt":"坂が多いですから、歩きやすい靴で来てください。","ro":"Saka ga ōi desu kara, arukiyasui kutsu de kite kudasai."},{"fr":"Ensuite, on descendra à Nankinmachi pour grignoter dans la rue.","tgt":"それから、南京町に下りて食べ歩きをします。","ro":"Sore kara, Nankinmachi ni orite tabearuki o shimasu."},{"fr":"Le soir, les lumières du port sont magnifiques.","tgt":"夜は港の明かりがとてもきれいです。","ro":"Yoru wa minato no akari ga totemo kirei desu."},{"fr":"Après le grand séisme, la ville de Kobe a fait peau neuve.","tgt":"大震災の後、神戸の町はきれいに生まれ変わりました。","ro":"Daishinsai no ato, Kōbe no machi wa kirei ni umarekawarimashita."},{"fr":"Près de la mer, il y a un musée consacré au séisme.","tgt":"海の近くに、震災の博物館があります。","ro":"Umi no chikaku ni, shinsai no hakubutsukan ga arimasu."},{"fr":"N'oubliez pas d'acheter des gâteaux de Kobe.","tgt":"神戸のケーキを買うのを忘れないでください。","ro":"Kōbe no kēki o kau no o wasurenaide kudasai."},{"fr":"Kobe et Osaka sont proches, mais l'ambiance est complètement différente.","tgt":"神戸と大阪は近いですが、雰囲気が全然違います。","ro":"Kōbe to Ōsaka wa chikai desu ga, fun'iki ga zenzen chigaimasu."}]},{"title":"Des okonomiyaki à la maison","phrases":[{"fr":"Ce soir, on fait des okonomiyaki à la maison.","tgt":"今晩、家でお好み焼きを作ります。","ro":"Konban, ie de okonomiyaki o tsukurimasu."},{"fr":"Coupe le chou en petits morceaux, s'il te plaît.","tgt":"キャベツを細かく切ってください。","ro":"Kyabetsu o komakaku kitte kudasai."},{"fr":"On mélange la farine, l'œuf et le bouillon dashi.","tgt":"小麦粉と卵とだしを混ぜます。","ro":"Komugiko to tamago to dashi o mazemasu."},{"fr":"On chauffe la plaque et on met un peu d'huile.","tgt":"ホットプレートを温めて、油を少し引きます。","ro":"Hotto purēto o atatamete, abura o sukoshi hikimasu."},{"fr":"On pose des tranches de porc sur la pâte.","tgt":"生地の上に豚肉をのせます。","ro":"Kiji no ue ni butaniku o nosemasu."},{"fr":"Allez, c'est le moment de la retourner !","tgt":"さあ、ひっくり返しますよ！","ro":"Sā, hikkurikaeshimasu yo!"},{"fr":"À Osaka, chaque famille a sa propre recette.","tgt":"大阪では、家ごとに作り方が違います。","ro":"Ōsaka de wa, ie goto ni tsukurikata ga chigaimasu."},{"fr":"Mettez beaucoup de sauce et de mayonnaise.","tgt":"ソースとマヨネーズをたっぷりかけてください。","ro":"Sōsu to mayonēzu o tappuri kakete kudasai."},{"fr":"Les copeaux de bonite dansent avec la chaleur.","tgt":"かつお節が熱で踊っています。","ro":"Katsuobushi ga netsu de odotte imasu."},{"fr":"Franchement, c'est meilleur que celui du restaurant !","tgt":"正直、お店のよりおいしいです！","ro":"Shōjiki, omise no yori oishii desu!"}]},{"title":"Est-ce que je peux… ?","phrases":[{"fr":"Puis-je garer mon vélo devant l'immeuble ?","tgt":"マンションの前に自転車を置いてもいいですか。","ro":"Manshon no mae ni jitensha o oite mo ii desu ka."},{"fr":"Non, utilisez le parking à vélos derrière, s'il vous plaît.","tgt":"いいえ、裏の駐輪場を使ってください。","ro":"Iie, ura no chūrinjō o tsukatte kudasai."},{"fr":"Ai-je le droit d'avoir un chat dans l'appartement ?","tgt":"部屋で猫を飼ってもいいですか。","ro":"Heya de neko o katte mo ii desu ka."},{"fr":"Désolé, les animaux sont interdits ici.","tgt":"すみません、ここはペット禁止です。","ro":"Sumimasen, koko wa petto kinshi desu."},{"fr":"Aujourd'hui, est-ce que je peux finir une heure plus tôt ?","tgt":"今日、一時間早く帰ってもいいですか。","ro":"Kyō, ichijikan hayaku kaette mo ii desu ka."},{"fr":"J'ai un rendez-vous à la clinique à dix-sept heures.","tgt":"五時にクリニックの予約があります。","ro":"Goji ni kurinikku no yoyaku ga arimasu."},{"fr":"Bien sûr, vas-y, aucun souci.","tgt":"もちろん、いいですよ。","ro":"Mochiron, ii desu yo."},{"fr":"Je peux prendre un de ces prospectus ?","tgt":"このチラシを一枚もらってもいいですか。","ro":"Kono chirashi o ichimai moratte mo ii desu ka."},{"fr":"Est-ce que je peux régler le loyer par virement ?","tgt":"家賃は振り込みで払ってもいいですか。","ro":"Yachin wa furikomi de haratte mo ii desu ka."},{"fr":"Oui, mais n'oubliez pas d'indiquer votre numéro d'appartement.","tgt":"はい、でも部屋番号を書くのを忘れないでください。","ro":"Hai, demo heya bangō o kaku no o wasurenaide kudasai."}],"tip":{"title":"« -te mo ii desu ka » : demander la permission","example":"Ai-je le droit d'avoir un chat dans l'appartement ? — 部屋で猫を<b>飼ってもいいですか</b>。","body":"Pour demander la permission, le japonais utilise une petite formule très logique : la forme en « -te », puis « mo ii desu ka ». « Mo » veut dire « même si », et « ii » veut dire « bien ». « Neko o katte mo ii desu ka » se dit donc littéralement : chat, élever même si, c'est bien ? Autrement dit : est-ce que ça va si j'ai un chat ? Autres exemples : « suwatte mo ii desu ka » (puis-je m'asseoir ?), « shashin o totte mo ii desu ka » (puis-je prendre une photo ?). Pour répondre oui, on dit simplement « ii desu yo », c'est bien. Astuce : retenez « mo ii » comme un petit « ça ira ? » collé au verbe.","exampleRo":"Heya de neko o katte mo ii desu ka.","lit":"appartement · [lieu] · chat · [objet] · élever (forme -te) · même si · bien · être (poli) · [question]","say":{"mo ii desu ka":"もいいですか","Mo":"も","ii":"いい","Neko o katte mo ii desu ka":"猫を飼ってもいいですか","suwatte mo ii desu ka":"座ってもいいですか","shashin o totte mo ii desu ka":"写真を撮ってもいいですか","ii desu yo":"いいですよ","mo ii":"もいい"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait vivre le quotidien d'Osaka et de Kobe.","tgt":"このモジュールでは、大阪と神戸の毎日の生活を体験しました。","ro":"Kono mojūru de wa, Ōsaka to Kōbe no mainichi no seikatsu o taiken shimashita."},{"fr":"Nous savons désormais nous débrouiller à la mairie, à la banque et à la clinique.","tgt":"市役所や銀行やクリニックで話すことができるようになりました。","ro":"Shiyakusho ya ginkō ya kurinikku de hanasu koto ga dekiru yō ni narimashita."},{"fr":"Les formes familières du japonais ne nous font plus peur.","tgt":"日本語の普通形も、もう怖くありません。","ro":"Nihongo no futsūkei mo, mō kowaku arimasen."},{"fr":"Forme du dictionnaire, en « -te », en « -nai » et en « -ta » : quatre formes essentielles.","tgt":"辞書形、て形、ない形、た形は、とても大切な形です。","ro":"Jishokei, tekei, naikei, takei wa, totemo taisetsu na katachi desu."},{"fr":"Grâce à elles, on comprend aussi les conversations entre amis.","tgt":"これで、友達同士の会話も分かります。","ro":"Kore de, tomodachi dōshi no kaiwa mo wakarimasu."},{"fr":"Demander poliment la permission est devenu facile.","tgt":"丁寧に許可をもらうのも簡単になりました。","ro":"Teinei ni kyoka o morau no mo kantan ni narimashita."},{"fr":"Dans le prochain module, nous voyagerons à Hokkaido et dans le Tohoku.","tgt":"次のモジュールでは、北海道や東北を旅します。","ro":"Tsugi no mojūru de wa, Hokkaidō ya Tōhoku o tabi shimasu."},{"fr":"Réécoutez tranquillement les leçons difficiles.","tgt":"難しいレッスンは、もう一度ゆっくり聞いてください。","ro":"Muzukashii ressun wa, mō ichido yukkuri kiite kudasai."},{"fr":"Le secret, c'est de continuer un peu chaque jour.","tgt":"毎日少しずつ続けることが大切です。","ro":"Mainichi sukoshi zutsu tsuzukeru koto ga taisetsu desu."},{"fr":"Bravo pour ce travail, et à très vite pour la suite !","tgt":"お疲れさまでした。また次で会いましょう！","ro":"Otsukaresama deshita. Mata tsugi de aimashō!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Sapporo","phrases":[{"fr":"Nous avons atterri à l'aéroport de Shin-Chitose ce matin.","tgt":"今朝、新千歳空港に着きました。","ro":"Kesa, Shinchitose kūkō ni tsukimashita."},{"fr":"Il fait bien plus froid ici qu'à Tokyo, hein ?","tgt":"東京よりずっと寒いですね。","ro":"Tōkyō yori zutto samui desu ne."},{"fr":"Prenons le train rapide jusqu'à Sapporo.","tgt":"札幌まで快速電車に乗りましょう。","ro":"Sapporo made kaisoku densha ni norimashō."},{"fr":"Le trajet prend à peu près quarante minutes.","tgt":"四十分ぐらいかかります。","ro":"Yonjuppun gurai kakarimasu."},{"fr":"Il y a beaucoup de neige des deux côtés des voies.","tgt":"線路の両側に雪がたくさん積もっています。","ro":"Senro no ryōgawa ni yuki ga takusan tsumotte imasu."},{"fr":"J'ai oublié mes gants dans l'avion.","tgt":"飛行機に手袋を忘れました。","ro":"Hikōki ni tebukuro o wasuremashita."},{"fr":"J'en achèterai des neufs à la gare de Sapporo.","tgt":"札幌駅で新しいのを買います。","ro":"Sapporo eki de atarashii no o kaimasu."},{"fr":"Notre hôtel est tout près de la tour de télévision.","tgt":"ホテルはテレビ塔のすぐ近くです。","ro":"Hoteru wa terebitō no sugu chikaku desu."},{"fr":"Ce soir, on mange un ramen au miso.","tgt":"今晩は味噌ラーメンを食べます。","ro":"Konban wa miso rāmen o tabemasu."},{"fr":"Sapporo est la vraie patrie du ramen au miso.","tgt":"札幌は味噌ラーメンの本場です。","ro":"Sapporo wa miso rāmen no honba desu."}]},{"title":"Le festival de neige de Sapporo","phrases":[{"fr":"Le festival de neige commence demain au parc Ōdōri.","tgt":"雪まつりは明日、大通公園で始まります。","ro":"Yuki matsuri wa ashita, Ōdōri kōen de hajimarimasu."},{"fr":"D'immenses sculptures de neige bordent l'avenue.","tgt":"大きな雪像が通りに並んでいます。","ro":"Ōkina setsuzō ga tōri ni narande imasu."},{"fr":"Cette sculpture a la forme d'un château célèbre.","tgt":"この雪像は有名なお城の形です。","ro":"Kono setsuzō wa yūmei na oshiro no katachi desu."},{"fr":"Ils ont mis un mois entier à la construire.","tgt":"一か月かけて作りました。","ro":"Ikkagetsu kakete tsukurimashita."},{"fr":"Le soir, les sculptures éclairées sont superbes.","tgt":"夜は雪像にライトが当たって、とてもきれいです。","ro":"Yoru wa setsuzō ni raito ga atatte, totemo kirei desu."},{"fr":"Il y a plein de stands de nourriture chaude.","tgt":"温かい食べ物の屋台がたくさんあります。","ro":"Atatakai tabemono no yatai ga takusan arimasu."},{"fr":"J'ai bu de l'amazake pour me réchauffer.","tgt":"甘酒を飲んで、体を温めました。","ro":"Amazake o nonde, karada o atatamemashita."},{"fr":"Les enfants s'amusent sur un toboggan de glace.","tgt":"子供たちが氷の滑り台で遊んでいます。","ro":"Kodomotachi ga kōri no suberidai de asonde imasu."},{"fr":"J'ai les pieds complètement glacés.","tgt":"足がとても冷たいです。","ro":"Ashi ga totemo tsumetai desu."},{"fr":"On rentre à l'hôtel pour prendre un bain bien chaud.","tgt":"ホテルに帰って、熱いお風呂に入ります。","ro":"Hoteru ni kaette, atsui ofuro ni hairimasu."}]},{"title":"Conduire sous la neige","phrases":[{"fr":"Nous avons loué une voiture pour trois jours.","tgt":"三日間、車を借りました。","ro":"Mikkakan, kuruma o karimashita."},{"fr":"Il faut montrer le permis de conduire international.","tgt":"国際運転免許証を見せなければなりません。","ro":"Kokusai unten menkyoshō o misenakereba narimasen."},{"fr":"En hiver, on doit rouler avec des pneus neige.","tgt":"冬はスタッドレスタイヤで走らなければなりません。","ro":"Fuyu wa sutaddoresu taiya de hashiranakereba narimasen."},{"fr":"Il faut rendre la voiture avec le plein d'essence.","tgt":"ガソリンを満タンにして返さなければなりません。","ro":"Gasorin o mantan ni shite kaesanakereba narimasen."},{"fr":"Au Japon, on roule du côté gauche.","tgt":"日本では左側を走ります。","ro":"Nihon de wa hidarigawa o hashirimasu."},{"fr":"Je dois m'habituer à la conduite à gauche.","tgt":"左側通行に慣れなければなりません。","ro":"Hidarigawa tsūkō ni narenakereba narimasen."},{"fr":"La route est glissante, roulez doucement.","tgt":"道が滑りやすいので、ゆっくり走ってください。","ro":"Michi ga suberiyasui node, yukkuri hashitte kudasai."},{"fr":"À ce panneau, on doit marquer l'arrêt complet.","tgt":"この標識では必ず止まらなければなりません。","ro":"Kono hyōshiki de wa kanarazu tomaranakereba narimasen."},{"fr":"Le GPS de la voiture ne parle que japonais.","tgt":"カーナビは日本語だけです。","ro":"Kānabi wa nihongo dake desu."},{"fr":"Nous devons arriver à Furano avant la nuit.","tgt":"暗くなる前に富良野に着かなければなりません。","ro":"Kuraku naru mae ni Furano ni tsukanakereba narimasen."}],"tip":{"title":"« -nakereba narimasen » : il faut, l'obligation","example":"Il faut montrer le permis de conduire international. — 国際運転免許証を<b>見せなければなりません</b>。","body":"Pour dire « il faut » ou « je dois », le japonais utilise une tournure surprenante : « nakereba narimasen ». On part de la forme négative en « nai », on remplace le « i » final par « kereba », qui veut dire « si », puis on ajoute « narimasen », « ça ne va pas ». Ainsi « misenakereba narimasen » se dit littéralement : si je ne montre pas, ça ne va pas. Autres exemples : « ikanakereba narimasen », je dois y aller, « tabenakereba narimasen », je dois manger, « kaesanakereba narimasen », je dois rendre. Pour retenir, pensez à une double négation : ne pas le faire, ce n'est pas possible, donc il faut le faire.","exampleRo":"Kokusai unten menkyoshō o misenakereba narimasen.","lit":"international · permis de conduire · [objet] · montrer-si-ne-pas · ne-pas-aller (poli)","say":{"nakereba narimasen":"なければなりません","nai":"ない","narimasen":"なりません","misenakereba narimasen":"見せなければなりません","ikanakereba narimasen":"行かなければなりません","tabenakereba narimasen":"食べなければなりません","kaesanakereba narimasen":"返さなければなりません","-nakereba narimasen":"なければなりません","kereba":"ければ"}}},{"title":"Une journée de ski à Furano","phrases":[{"fr":"Furano est réputée pour sa neige poudreuse.","tgt":"富良野はパウダースノーで有名です。","ro":"Furano wa paudā sunō de yūmei desu."},{"fr":"J'ai loué des skis et des chaussures à l'hôtel.","tgt":"ホテルでスキー板とブーツを借りました。","ro":"Hoteru de sukī ita to būtsu o karimashita."},{"fr":"Le forfait d'une journée coûte six mille yens.","tgt":"一日券は六千円です。","ro":"Ichinichiken wa rokusen'en desu."},{"fr":"Je ne suis pas très doué à ski.","tgt":"スキーはあまり上手じゃありません。","ro":"Sukī wa amari jōzu ja arimasen."},{"fr":"Je vais skier sur les pistes pour débutants.","tgt":"初心者コースで滑ります。","ro":"Shoshinsha kōsu de suberimasu."},{"fr":"La vue depuis le télésiège est splendide.","tgt":"リフトからの景色がすばらしいです。","ro":"Rifuto kara no keshiki ga subarashii desu."},{"fr":"Je suis tombé trois fois ce matin.","tgt":"今朝、三回転びました。","ro":"Kesa, sankai korobimashita."},{"fr":"Faisons une pause au restaurant en bas des pistes.","tgt":"ふもとのレストハウスで休みましょう。","ro":"Fumoto no resuto hausu de yasumimashō."},{"fr":"La soupe au curry d'ici est un régal.","tgt":"ここのスープカレーはとてもおいしいです。","ro":"Koko no sūpu karē wa totemo oishii desu."},{"fr":"Demain, je prendrai un cours de ski.","tgt":"明日はスキーのレッスンを受けます。","ro":"Ashita wa sukī no ressun o ukemasu."}]},{"title":"Flâner à Otaru","phrases":[{"fr":"Aujourd'hui, on part à Otaru pour la journée.","tgt":"今日は小樽へ日帰り旅行です。","ro":"Kyō wa Otaru e higaeri ryokō desu."},{"fr":"À Otaru, on se promène le long du canal, on regarde les boutiques de verre…","tgt":"小樽では運河沿いを散歩したり、ガラスの店を見たりします。","ro":"Otaru de wa unga zoi o sanpo shitari, garasu no mise o mitari shimasu."},{"fr":"Le soir, on mange des sushis, on boit un peu de saké…","tgt":"夜はお寿司を食べたり、お酒を飲んだりします。","ro":"Yoru wa osushi o tabetari, osake o nondari shimasu."},{"fr":"Ces entrepôts en pierre ont plus de cent ans.","tgt":"石造りの倉庫は百年以上前のものです。","ro":"Ishizukuri no sōko wa hyakunen ijō mae no mono desu."},{"fr":"Dans cet atelier, j'ai fabriqué un petit verre.","tgt":"この工房で小さいグラスを作りました。","ro":"Kono kōbō de chiisai gurasu o tsukurimashita."},{"fr":"Dans le train, je regarde le paysage ou je fais une sieste.","tgt":"電車では景色を見たり、昼寝をしたりします。","ro":"Densha de wa keshiki o mitari, hirune o shitari shimasu."},{"fr":"Les boîtes à musique sont la spécialité du quartier.","tgt":"オルゴールはこの辺りの名物です。","ro":"Orugōru wa kono atari no meibutsu desu."},{"fr":"Rue Sakaimachi, on a goûté des pâtisseries, acheté des souvenirs…","tgt":"堺町通りでお菓子を食べたり、お土産を買ったりしました。","ro":"Sakaimachi dōri de okashi o tabetari, omiyage o kattari shimashita."},{"fr":"Le canal est encore plus joli en fin de journée.","tgt":"運河は夕方のほうがもっときれいです。","ro":"Unga wa yūgata no hō ga motto kirei desu."},{"fr":"On reprend le train pour Sapporo vers huit heures.","tgt":"八時ごろ電車で札幌に戻ります。","ro":"Hachiji goro densha de Sapporo ni modorimasu."}],"tip":{"title":"« -tari -tari shimasu » : faire des choses comme…","example":"À Otaru, on se promène le long du canal, on regarde les boutiques de verre… — 小樽では運河沿いを<b>散歩したり</b>、ガラスの店を<b>見たり</b>します。","body":"Quand on veut citer quelques activités parmi d'autres, sans faire une liste complète, on utilise « tari, tari shimasu ». On prend le verbe au passé familier en « ta », on ajoute « ri », et on termine par « shimasu », faire. « Sanpo shitari, mitari shimasu » se dit littéralement : se promener entre autres, regarder entre autres, faire. C'est l'équivalent de notre « on fait des choses comme ». Par exemple « tabetari nondari shimasu », on mange, on boit, ou « yondari netari shimasu », on lit, on dort. Pour le passé, il suffit de changer la fin en « shimashita ». Astuce : imaginez « tari » comme un petit tiroir qu'on ouvre pour sortir un exemple.","exampleRo":"Otaru de wa unga zoi o sanpo shitari, garasu no mise o mitari shimasu.","lit":"Otaru · [lieu] [thème] · canal-le long · [objet] · promenade-faire-entre autres · verre · [possessif] · boutique · [objet] · regarder-entre autres · faire (poli)","say":{"shimasu":"します","Sanpo shitari, mitari shimasu":"散歩したり、見たりします","tabetari nondari shimasu":"食べたり飲んだりします","yondari netari shimasu":"読んだり寝たりします","shimashita":"しました","-tari -tari shimasu":"たり、たりします","tari, tari shimasu":"たり、たりします","tari":"たり"}}},{"title":"Un train bloqué par la neige","phrases":[{"fr":"Notre train local est à l'arrêt à cause de la neige.","tgt":"雪のせいで、普通列車が止まっています。","ro":"Yuki no sei de, futsū ressha ga tomatte imasu."},{"fr":"Le contrôleur a annoncé un départ dans une heure.","tgt":"車掌さんは「一時間後に出発します」と言いました。","ro":"Shashō san wa \"ichijikan go ni shuppatsu shimasu\" to iimashita."},{"fr":"On n'a pas le choix, on attend.","tgt":"しかたがないので、待ちます。","ro":"Shikata ga nai node, machimasu."},{"fr":"Heureusement, le chauffage du wagon marche.","tgt":"幸い、車内の暖房はついています。","ro":"Saiwai, shanai no danbō wa tsuite imasu."},{"fr":"Une vieille dame m'a donné une mandarine.","tgt":"おばあさんがみかんをくれました。","ro":"Obāsan ga mikan o kuremashita."},{"fr":"Elle va voir sa fille qui habite à Asahikawa.","tgt":"旭川に住んでいる娘さんに会いに行きます。","ro":"Asahikawa ni sunde iru musume san ni ai ni ikimasu."},{"fr":"Je préviens l'auberge qu'on aura du retard.","tgt":"旅館に遅れると連絡します。","ro":"Ryokan ni okureru to renraku shimasu."},{"fr":"Le train est reparti avec deux heures de retard.","tgt":"列車は二時間遅れで動き出しました。","ro":"Ressha wa nijikan okure de ugokidashimashita."},{"fr":"Ici, en hiver, ce genre de chose arrive souvent.","tgt":"冬はこういうことがよくあります。","ro":"Fuyu wa kō iu koto ga yoku arimasu."},{"fr":"Au bout du compte, ce voyage au ralenti était agréable.","tgt":"結局、のんびりした旅も楽しかったです。","ro":"Kekkyoku, nonbiri shita tabi mo tanoshikatta desu."}]},{"title":"Le marché du matin de Hakodate","phrases":[{"fr":"Nous sommes descendus en train jusqu'à Hakodate.","tgt":"函館まで電車で行きました。","ro":"Hakodate made densha de ikimashita."},{"fr":"Le marché du matin ouvre dès cinq heures.","tgt":"朝市は朝五時から開いています。","ro":"Asaichi wa asa goji kara aite imasu."},{"fr":"Les crabes d'ici sont énormes.","tgt":"ここのカニはとても大きいです。","ro":"Koko no kani wa totemo ōkii desu."},{"fr":"Au petit-déjeuner, j'ai mangé un bol de riz aux oursins.","tgt":"朝ごはんにウニ丼を食べました。","ro":"Asagohan ni unidon o tabemashita."},{"fr":"Le vendeur m'a donné un petit bout de crabe à goûter.","tgt":"店の人に、カニを少しもらいました。","ro":"Mise no hito ni, kani o sukoshi moraimashita."},{"fr":"Le soir, on monte au mont Hakodate en téléphérique.","tgt":"夜はロープウェイで函館山に登ります。","ro":"Yoru wa rōpuwei de Hakodateyama ni noborimasu."},{"fr":"La vue nocturne de Hakodate est célèbre dans tout le Japon.","tgt":"函館の夜景は日本中で有名です。","ro":"Hakodate no yakei wa nihonjū de yūmei desu."},{"fr":"Il y avait un monde fou au sommet !","tgt":"山頂は人がとても多かったです。","ro":"Sanchō wa hito ga totemo ōkatta desu."},{"fr":"Là-haut, le vent était glacial.","tgt":"上は風がとても冷たかったです。","ro":"Ue wa kaze ga totemo tsumetakatta desu."},{"fr":"Demain, on passe dans le Tohoku en shinkansen.","tgt":"明日は新幹線で東北へ渡ります。","ro":"Ashita wa shinkansen de Tōhoku e watarimasu."}]},{"title":"Le village thermal de Ginzan","phrases":[{"fr":"Ginzan Onsen est un village thermal dans les montagnes de Yamagata.","tgt":"銀山温泉は山形の山の中にある温泉街です。","ro":"Ginzan onsen wa Yamagata no yama no naka ni aru onsengai desu."},{"fr":"Je pense que c'est le plus bel endroit du voyage.","tgt":"ここは今回の旅で一番きれいな所だと思います。","ro":"Koko wa konkai no tabi de ichiban kirei na tokoro da to omoimasu."},{"fr":"De vieilles auberges en bois bordent la rivière.","tgt":"古い木造の旅館が川沿いに並んでいます。","ro":"Furui mokuzō no ryokan ga kawazoi ni narande imasu."},{"fr":"À la nuit tombée, les lampes à gaz s'allument.","tgt":"夜になると、ガス灯がつきます。","ro":"Yoru ni naru to, gasutō ga tsukimasu."},{"fr":"Je pense qu'il va encore neiger cette nuit.","tgt":"今夜もまた雪が降ると思います。","ro":"Kon'ya mo mata yuki ga furu to omoimasu."},{"fr":"Je pense qu'il y aura peu de touristes demain matin.","tgt":"明日の朝は観光客が少ないと思います。","ro":"Ashita no asa wa kankōkyaku ga sukunai to omoimasu."},{"fr":"Mon ami pense qu'il vaut mieux venir en semaine.","tgt":"友達は平日に来たほうがいいと思っています。","ro":"Tomodachi wa heijitsu ni kita hō ga ii to omotte imasu."},{"fr":"Cette auberge est un peu chère, mais je pense qu'elle le vaut.","tgt":"この旅館は少し高いですが、その価値があると思います。","ro":"Kono ryokan wa sukoshi takai desu ga, sono kachi ga aru to omoimasu."},{"fr":"Le bain de pieds au bord de la rivière est gratuit.","tgt":"川沿いの足湯は無料です。","ro":"Kawazoi no ashiyu wa muryō desu."},{"fr":"Je pense qu'on reviendra un jour en été.","tgt":"いつか夏にまた来ると思います。","ro":"Itsuka natsu ni mata kuru to omoimasu."}],"tip":{"title":"« -to omoimasu » : je pense que","example":"Je pense que c'est le plus bel endroit du voyage. — ここは今回の旅で一番きれいな所<b>だと思います</b>。","body":"Pour donner son avis, on place « to omoimasu », je pense, tout à la fin de la phrase. Devant « to », la phrase se met à la forme neutre : « da » au lieu de « desu », « furu » au lieu de « furimasu ». « Kirei na tokoro da to omoimasu » se dit littéralement : bel endroit, c'est, entre guillemets, je pense. Le petit mot « to » joue le rôle de guillemets autour de votre pensée. Exemples : « yuki ga furu to omoimasu », je pense qu'il va neiger, ou « takai to omoimasu », je pense que c'est cher. Astuce : en français on commence par « je pense », en japonais on le garde pour la fin, comme une signature.","exampleRo":"Koko wa konkai no tabi de ichiban kirei na tokoro da to omoimasu.","lit":"ici · [thème] · cette fois · [possessif] · voyage · [dans] · le plus · beau · endroit · être (neutre) · [citation] · penser (poli)","say":{"to omoimasu":"と思います","to":"と","da":"だ","desu":"です","furu":"降る","furimasu":"降ります","Kirei na tokoro da to omoimasu":"きれいな所だと思います","yuki ga furu to omoimasu":"雪が降ると思います","takai to omoimasu":"高いと思います","-to omoimasu":"と思います"}}},{"title":"Le long de la mer en train local","phrases":[{"fr":"La ligne Gonō longe la mer du Japon.","tgt":"五能線は日本海沿いを走ります。","ro":"Gonōsen wa Nihonkai zoi o hashirimasu."},{"fr":"Ce train local ne passe que quelques fois par jour.","tgt":"この普通列車は一日に数本しかありません。","ro":"Kono futsū ressha wa ichinichi ni sūhon shika arimasen."},{"fr":"Surtout, ne ratez pas le suivant.","tgt":"次の列車に乗り遅れないでください。","ro":"Tsugi no ressha ni noriokurenaide kudasai."},{"fr":"Les vagues se brisent juste à côté des rails.","tgt":"線路のすぐそばで波が砕けています。","ro":"Senro no sugu soba de nami ga kudakete imasu."},{"fr":"Le train ralentit aux plus beaux endroits.","tgt":"景色のいい所では、列車がゆっくり走ります。","ro":"Keshiki no ii tokoro de wa, ressha ga yukkuri hashirimasu."},{"fr":"On s'est arrêtés dans une petite gare sans personnel.","tgt":"小さな無人駅に止まりました。","ro":"Chiisana mujin'eki ni tomarimashita."},{"fr":"Avant le départ, on a acheté un bentō au calamar.","tgt":"出発前にイカのお弁当を買いました。","ro":"Shuppatsu mae ni ika no obentō o kaimashita."},{"fr":"Le contrôleur nous a raconté l'histoire de la région.","tgt":"車掌さんがこの地方の話をしてくれました。","ro":"Shashō san ga kono chihō no hanashi o shite kuremashita."},{"fr":"Au loin, on aperçoit le mont Iwaki.","tgt":"遠くに岩木山が見えます。","ro":"Tōku ni Iwakisan ga miemasu."},{"fr":"Prendre ce train est déjà un plaisir de voyage en soi.","tgt":"この列車に乗ること自体が旅の楽しみです。","ro":"Kono ressha ni noru koto jitai ga tabi no tanoshimi desu."}]},{"title":"Les sanctuaires de Nikko","phrases":[{"fr":"Nikko est à environ deux heures de Tokyo.","tgt":"日光は東京から二時間ぐらいです。","ro":"Nikkō wa Tōkyō kara nijikan gurai desu."},{"fr":"Le sanctuaire Tōshōgū est couvert de décorations dorées.","tgt":"東照宮は金色の飾りでいっぱいです。","ro":"Tōshōgū wa kin'iro no kazari de ippai desu."},{"fr":"Voici les fameux trois singes.","tgt":"これが有名な三猿です。","ro":"Kore ga yūmei na sanzaru desu."},{"fr":"Ne pas voir, ne pas dire, ne pas entendre.","tgt":"見ざる、言わざる、聞かざる。","ro":"Mizaru, iwazaru, kikazaru."},{"fr":"Il y a une quantité de marches à grimper.","tgt":"上る階段がとても多いです。","ro":"Noboru kaidan ga totemo ōi desu."},{"fr":"Au-dessus d'une porte, il y a la sculpture du chat endormi.","tgt":"門の上に眠り猫の彫刻があります。","ro":"Mon no ue ni nemurineko no chōkoku ga arimasu."},{"fr":"À l'intérieur, les photos sont interdites.","tgt":"中で写真を撮ってはいけません。","ro":"Naka de shashin o totte wa ikemasen."},{"fr":"Ce pont rouge s'appelle le pont Shinkyō.","tgt":"この赤い橋は神橋といいます。","ro":"Kono akai hashi wa Shinkyō to iimasu."},{"fr":"Les cèdres de l'allée ont plusieurs siècles.","tgt":"杉並木の杉は何百年も前からあります。","ro":"Suginamiki no sugi wa nanbyakunen mo mae kara arimasu."},{"fr":"On a goûté au yuba, la spécialité de Nikko.","tgt":"日光名物の湯葉を食べました。","ro":"Nikkō meibutsu no yuba o tabemashita."}]},{"title":"Randonnée au lac Chūzenji","phrases":[{"fr":"Le bus grimpe la route en lacets d'Irohazaka.","tgt":"バスはいろは坂を上ります。","ro":"Basu wa Irohazaka o noborimasu."},{"fr":"Le lac Chūzenji est à presque mille trois cents mètres d'altitude.","tgt":"中禅寺湖は標高千三百メートル近くにあります。","ro":"Chūzenjiko wa hyōkō sen sanbyaku mētoru chikaku ni arimasu."},{"fr":"Aujourd'hui, on longe le lac à pied.","tgt":"今日は湖のまわりを歩きます。","ro":"Kyō wa mizuumi no mawari o arukimasu."},{"fr":"N'oubliez pas l'eau et l'imperméable.","tgt":"水とレインコートを忘れないでください。","ro":"Mizu to reinkōto o wasurenaide kudasai."},{"fr":"Après la pluie, le sentier est boueux.","tgt":"雨の後で、道がぬかるんでいます。","ro":"Ame no ato de, michi ga nukarunde imasu."},{"fr":"Attention, des panneaux signalent des ours.","tgt":"気をつけて。クマ注意の看板があります。","ro":"Ki o tsukete. Kuma chūi no kanban ga arimasu."},{"fr":"J'ai accroché une clochette à mon sac à dos.","tgt":"リュックに鈴をつけました。","ro":"Ryukku ni suzu o tsukemashita."},{"fr":"Les chutes de Kegon font presque cent mètres de haut.","tgt":"華厳の滝は高さ百メートル近くあります。","ro":"Kegon no taki wa takasa hyaku mētoru chikaku arimasu."},{"fr":"On descend en ascenseur jusqu'au pied de la cascade.","tgt":"エレベーターで滝の下まで降ります。","ro":"Erebētā de taki no shita made orimasu."},{"fr":"J'ai les jambes en compote, mais je suis comblé.","tgt":"足は疲れましたが、満足です。","ro":"Ashi wa tsukaremashita ga, manzoku desu."}]},{"title":"Hakone en une journée","phrases":[{"fr":"Avec le pass de Hakone, on peut prendre tous les transports.","tgt":"箱根フリーパスで、全部の乗り物に乗れます。","ro":"Hakone furī pasu de, zenbu no norimono ni noremasu."},{"fr":"Par beau temps, on peut voir le Fuji depuis le téléphérique.","tgt":"晴れた日は、ロープウェイから富士山が見られます。","ro":"Hareta hi wa, rōpuwei kara Fujisan ga miraremasu."},{"fr":"À Ōwakudani, on peut manger des œufs noirs.","tgt":"大涌谷では黒たまごが食べられます。","ro":"Ōwakudani de wa kuro tamago ga taberaremasu."},{"fr":"D'après la légende, un œuf noir donne sept ans de vie en plus.","tgt":"伝説では、黒たまごを一つ食べると七年長生きします。","ro":"Densetsu de wa, kuro tamago o hitotsu taberu to nananen nagaiki shimasu."},{"fr":"Je ne peux pas en manger plus de deux.","tgt":"二つ以上は食べられません。","ro":"Futatsu ijō wa taberaremasen."},{"fr":"Ici, l'odeur de soufre est assez forte.","tgt":"ここは硫黄のにおいがかなり強いです。","ro":"Koko wa iō no nioi ga kanari tsuyoi desu."},{"fr":"Est-ce qu'on peut traverser le lac Ashi en bateau pirate ?","tgt":"芦ノ湖は海賊船で渡れますか？","ro":"Ashinoko wa kaizokusen de wataremasu ka?"},{"fr":"Je n'arrive pas à lire ce panneau en kanji.","tgt":"この漢字の看板が読めません。","ro":"Kono kanji no kanban ga yomemasen."},{"fr":"Ici, on peut payer avec la carte de transport.","tgt":"ここは交通カードで払えます。","ro":"Koko wa kōtsū kādo de haraemasu."},{"fr":"Avec ce pass, on peut faire tout le tour de Hakone en une journée.","tgt":"このパスで、一日で箱根を一周できます。","ro":"Kono pasu de, ichinichi de Hakone o isshū dekimasu."}],"tip":{"title":"La forme potentielle : pouvoir faire","example":"À Ōwakudani, on peut manger des œufs noirs. — 大涌谷では黒たまごが<b>食べられます</b>。","body":"Pour dire « pouvoir faire », le japonais transforme le verbe lui-même. Pour les verbes comme « taberu », manger, on remplace « ru » par « rareru » : « taberareru », et au poli « taberaremasu ». Pour les autres verbes, le son final passe en « e » puis on ajoute « ru » : « yomu » devient « yomeru », « noru » devient « noreru », « aruku » devient « arukeru ». « Kuro tamago ga taberaremasu » se dit littéralement : œuf noir, sujet, mangeable. Remarquez que l'objet prend souvent « ga » au lieu de « o ». Et « suru », faire, devient tout simplement « dekiru ». Astuce : retenez le « e » du potentiel comme le « e » de « c'est possible ».","exampleRo":"Ōwakudani de wa kuro tamago ga taberaremasu.","lit":"Ōwakudani · [lieu] [thème] · noir · œuf · [sujet] · pouvoir manger (poli)","say":{"taberu":"食べる","rareru":"られる","taberareru":"食べられる","taberaremasu":"食べられます","yomu":"読む","yomeru":"読める","noru":"乗る","noreru":"乗れる","aruku":"歩く","arukeru":"歩ける","Kuro tamago ga taberaremasu":"黒たまごが食べられます","ga":"が","o":"を","suru":"する","dekiru":"できる","ru":"る"}}},{"title":"Une nuit dans un ryokan","phrases":[{"fr":"L'hôtesse nous accueille agenouillée dans l'entrée.","tgt":"仲居さんが玄関で正座して迎えてくれます。","ro":"Nakai san ga genkan de seiza shite mukaete kuremasu."},{"fr":"On retire ses chaussures avant de marcher sur les tatamis.","tgt":"畳に上がる前に靴を脱ぎます。","ro":"Tatami ni agaru mae ni kutsu o nugimasu."},{"fr":"De notre chambre, on voit un petit jardin.","tgt":"部屋から小さな庭が見えます。","ro":"Heya kara chiisana niwa ga miemasu."},{"fr":"Du thé vert et des douceurs nous attendent sur la table.","tgt":"テーブルに緑茶とお菓子が置いてあります。","ro":"Tēburu ni ryokucha to okashi ga oite arimasu."},{"fr":"On porte le yukata avec le pan gauche par-dessus.","tgt":"浴衣は左側を上にして着ます。","ro":"Yukata wa hidarigawa o ue ni shite kimasu."},{"fr":"À sept heures, on dîne dans la chambre.","tgt":"七時に部屋で夕食をいただきます。","ro":"Shichiji ni heya de yūshoku o itadakimasu."},{"fr":"Il y a plus de dix petits plats différents.","tgt":"小さな料理が十品以上あります。","ro":"Chiisana ryōri ga juppin ijō arimasu."},{"fr":"Pendant notre bain, on nous a préparé les futons.","tgt":"お風呂の間に、布団を敷いてくれました。","ro":"Ofuro no aida ni, futon o shiite kuremashita."},{"fr":"Le petit-déjeuner japonais comporte poisson grillé et soupe miso.","tgt":"和朝食には焼き魚と味噌汁があります。","ro":"Wachōshoku ni wa yakizakana to misoshiru ga arimasu."},{"fr":"On a dormi comme des loirs sur ces futons.","tgt":"布団でぐっすり眠れました。","ro":"Futon de gussuri nemuremashita."}]},{"title":"Les règles de l'onsen","phrases":[{"fr":"On se lave entièrement avant d'entrer dans l'eau.","tgt":"お湯に入る前に、体をきれいに洗います。","ro":"Oyu ni hairu mae ni, karada o kirei ni araimasu."},{"fr":"La serviette ne doit pas toucher l'eau du bain.","tgt":"タオルをお湯に入れてはいけません。","ro":"Taoru o oyu ni irete wa ikemasen."},{"fr":"Beaucoup de gens la posent sur leur tête.","tgt":"頭の上にタオルをのせる人が多いです。","ro":"Atama no ue ni taoru o noseru hito ga ōi desu."},{"fr":"Les bains des hommes et des femmes sont séparés.","tgt":"男湯と女湯は分かれています。","ro":"Otokoyu to onnayu wa wakarete imasu."},{"fr":"Le rideau bleu, c'est le côté des hommes.","tgt":"青いのれんが男湯です。","ro":"Aoi noren ga otokoyu desu."},{"fr":"Depuis le bain en plein air, on voit les montagnes sous la neige.","tgt":"露天風呂から雪の山が見えます。","ro":"Rotenburo kara yuki no yama ga miemasu."},{"fr":"L'eau dépasse les quarante-deux degrés.","tgt":"お湯は四十二度以上あります。","ro":"Oyu wa yonjūni do ijō arimasu."},{"fr":"Ne restez pas trop longtemps, vous risquez un malaise.","tgt":"長く入りすぎないでください。のぼせますよ。","ro":"Nagaku hairisuginaide kudasai. Nobosemasu yo."},{"fr":"Après le bain, rien de tel qu'un café au lait bien frais !","tgt":"お風呂の後は冷たいコーヒー牛乳です！","ro":"Ofuro no ato wa tsumetai kōhī gyūnyū desu!"},{"fr":"Certains onsen refusent les personnes tatouées.","tgt":"タトゥーがあると、入れない温泉もあります。","ro":"Tatū ga aru to, hairenai onsen mo arimasu."}]},{"title":"Le mont Fuji à Kawaguchiko","phrases":[{"fr":"Ce matin, le mont Fuji se voit très nettement.","tgt":"今朝は富士山がはっきり見えます。","ro":"Kesa wa Fujisan ga hakkiri miemasu."},{"fr":"Le Fuji se reflète dans le lac.","tgt":"湖に富士山が映っています。","ro":"Mizuumi ni Fujisan ga utsutte imasu."},{"fr":"Kawaguchiko est l'un des cinq lacs du Fuji.","tgt":"河口湖は富士五湖の一つです。","ro":"Kawaguchiko wa Fuji goko no hitotsu desu."},{"fr":"On a loué des vélos et fait le tour du lac.","tgt":"自転車を借りて、湖を一周しました。","ro":"Jitensha o karite, mizuumi o isshū shimashita."},{"fr":"La vue depuis la pagode Chūreitō est la plus célèbre.","tgt":"忠霊塔からの景色が一番有名です。","ro":"Chūreitō kara no keshiki ga ichiban yūmei desu."},{"fr":"Pour y arriver, on gravit presque quatre cents marches.","tgt":"四百段近くの階段を上ります。","ro":"Yonhyakudan chikaku no kaidan o noborimasu."},{"fr":"Au printemps, on voit les cerisiers et le Fuji ensemble.","tgt":"春は桜と富士山がいっしょに見えます。","ro":"Haru wa sakura to Fujisan ga issho ni miemasu."},{"fr":"J'ai pris plus de cent photos ce matin.","tgt":"今朝、写真を百枚以上撮りました。","ro":"Kesa, shashin o hyakumai ijō torimashita."},{"fr":"À midi, des nuages ont caché le sommet.","tgt":"昼に、雲が山頂を隠しました。","ro":"Hiru ni, kumo ga sanchō o kakushimashita."},{"fr":"Ce soir, on mange des hōtō, les grosses nouilles de la région.","tgt":"今晩は名物のほうとうを食べます。","ro":"Konban wa meibutsu no hōtō o tabemasu."}]},{"title":"Préparer l'ascension du Fuji","phrases":[{"fr":"La saison d'ascension du Fuji, c'est surtout juillet et août.","tgt":"富士山の登山シーズンは主に七月と八月です。","ro":"Fujisan no tozan shīzun wa omo ni shichigatsu to hachigatsu desu."},{"fr":"On commence à monter depuis la cinquième station en fin d'après-midi.","tgt":"夕方、五合目から登り始めます。","ro":"Yūgata, gogōme kara noborihajimemasu."},{"fr":"Si on arrive au refuge à huit heures du soir, on pourra dormir un peu.","tgt":"夜八時に山小屋に着いたら、少し寝られます。","ro":"Yoru hachiji ni yamagoya ni tsuitara, sukoshi neraremasu."},{"fr":"Une fois au sommet, on regardera le lever du soleil.","tgt":"頂上に着いたら、ご来光を見ます。","ro":"Chōjō ni tsuitara, goraikō o mimasu."},{"fr":"S'il pleut, on annule l'ascension.","tgt":"雨が降ったら、登山はやめます。","ro":"Ame ga futtara, tozan wa yamemasu."},{"fr":"Si vous avez mal à la tête, redescendez tout de suite.","tgt":"頭が痛くなったら、すぐに下りてください。","ro":"Atama ga itaku nattara, sugu ni orite kudasai."},{"fr":"Même en été, il fait près de zéro degré au sommet.","tgt":"夏でも頂上は零度近くになります。","ro":"Natsu demo chōjō wa reido chikaku ni narimasu."},{"fr":"J'ai acheté un bâton de marche en bois.","tgt":"木の杖を買いました。","ro":"Ki no tsue o kaimashita."},{"fr":"Dans les refuges, on peut faire marquer son bâton au fer chaud.","tgt":"山小屋で杖に焼き印を押してもらえます。","ro":"Yamagoya de tsue ni yakiin o oshite moraemasu."},{"fr":"Une fois rentrés, on file directement à l'onsen !","tgt":"帰ったら、すぐ温泉に行きましょう！","ro":"Kaettara, sugu onsen ni ikimashō!"}],"tip":{"title":"« -tara » : si, quand, la condition","example":"S'il pleut, on annule l'ascension. — 雨が<b>降ったら</b>、登山はやめます。","body":"Pour dire « si » ou « quand », on prend le verbe au passé familier en « ta » et on ajoute simplement « ra ». « Futta », il a plu, devient « futtara », s'il pleut. « Ame ga futtara, tozan wa yamemasu » se dit littéralement : pluie, sujet, si elle tombe, ascension, thème, on arrête. La même forme sert aussi pour « quand » : « tsuitara », une fois arrivés, ou « kaettara », une fois rentrés. Ça marche aussi avec les adjectifs : « itakattara », si ça fait mal. Astuce : « tara » veut dire « une fois que c'est fait », comme si l'action était déjà passée dans votre tête.","exampleRo":"Ame ga futtara, tozan wa yamemasu.","lit":"pluie · [sujet] · tomber-si · ascension · [thème] · arrêter (poli)","say":{"Futta":"降った","futtara":"降ったら","Ame ga futtara, tozan wa yamemasu":"雨が降ったら、登山はやめます","tsuitara":"着いたら","kaettara":"帰ったら","itakattara":"痛かったら"}}},{"title":"Une cheville tordue en randonnée","phrases":[{"fr":"Je me suis tordu la cheville dans la descente.","tgt":"下りで足首をひねりました。","ro":"Kudari de ashikubi o hinerimashita."},{"fr":"Tu arrives à marcher ?","tgt":"歩けますか？","ro":"Arukemasu ka?"},{"fr":"Un peu, mais ça fait vraiment mal.","tgt":"少しは歩けますが、とても痛いです。","ro":"Sukoshi wa arukemasu ga, totemo itai desu."},{"fr":"Asseyons-nous un moment sur ce rocher.","tgt":"ちょっとこの岩に座りましょう。","ro":"Chotto kono iwa ni suwarimashō."},{"fr":"J'ai une bande dans mon sac à dos.","tgt":"リュックに包帯があります。","ro":"Ryukku ni hōtai ga arimasu."},{"fr":"Un autre randonneur est venu nous aider.","tgt":"ほかの登山者が手伝ってくれました。","ro":"Hoka no tozansha ga tetsudatte kuremashita."},{"fr":"On redescend doucement jusqu'au parking.","tgt":"駐車場までゆっくり下ります。","ro":"Chūshajō made yukkuri orimasu."},{"fr":"Y a-t-il un médecin ouvert le dimanche près d'ici ?","tgt":"この近くに日曜日もやっている病院はありますか？","ro":"Kono chikaku ni nichiyōbi mo yatte iru byōin wa arimasu ka?"},{"fr":"Le médecin a dit que ce n'était pas cassé.","tgt":"お医者さんは骨折ではないと言いました。","ro":"Oishasan wa kossetsu de wa nai to iimashita."},{"fr":"Je dois me reposer deux ou trois jours.","tgt":"二、三日休まなければなりません。","ro":"Ni, sannichi yasumanakereba narimasen."}]},{"title":"Un sac oublié dans le train","phrases":[{"fr":"J'ai laissé mon sac dans le train local.","tgt":"普通電車にかばんを忘れました。","ro":"Futsū densha ni kaban o wasuremashita."},{"fr":"Je m'en suis aperçu sur le quai.","tgt":"ホームで気がつきました。","ro":"Hōmu de ki ga tsukimashita."},{"fr":"Allons tout de suite au bureau de la gare.","tgt":"すぐ駅の事務室に行きましょう。","ro":"Sugu eki no jimushitsu ni ikimashō."},{"fr":"Dans quelle voiture étiez-vous ?","tgt":"何号車に乗っていましたか？","ro":"Nangōsha ni notte imashita ka?"},{"fr":"Dans la voiture trois, près de la porte.","tgt":"三号車の、ドアの近くです。","ro":"Sangōsha no, doa no chikaku desu."},{"fr":"Il ressemble à quoi, votre sac ?","tgt":"どんなかばんですか？","ro":"Donna kaban desu ka?"},{"fr":"C'est un sac à dos noir avec un porte-clés en forme d'ours.","tgt":"クマのキーホルダーがついた黒いリュックです。","ro":"Kuma no kīhorudā ga tsuita kuroi ryukku desu."},{"fr":"L'employé téléphone à la gare du terminus.","tgt":"駅員さんが終点の駅に電話します。","ro":"Ekiin san ga shūten no eki ni denwa shimasu."},{"fr":"Il a été retrouvé ! Vous pourrez le récupérer en gare d'Otaru.","tgt":"見つかりました！小樽駅で受け取れます。","ro":"Mitsukarimashita! Otaru eki de uketoremasu."},{"fr":"Au Japon, les objets perdus réapparaissent presque toujours.","tgt":"日本では、なくした物がたいてい見つかります。","ro":"Nihon de wa, nakushita mono ga taitei mitsukarimasu."}]},{"title":"Les derniers souvenirs","phrases":[{"fr":"Je dois acheter des souvenirs pour mes collègues.","tgt":"同僚にお土産を買わなければなりません。","ro":"Dōryō ni omiyage o kawanakereba narimasen."},{"fr":"Ces biscuits blancs sont le grand classique de Hokkaido.","tgt":"この白いクッキーは北海道の名物です。","ro":"Kono shiroi kukkī wa Hokkaidō no meibutsu desu."},{"fr":"Chaque boîte contient douze biscuits emballés un par un.","tgt":"一箱に十二枚入っていて、一枚ずつ包んであります。","ro":"Hitohako ni jūnimai haitte ite, ichimai zutsu tsutsunde arimasu."},{"fr":"Ma mère adore le fromage de Furano.","tgt":"母は富良野のチーズが大好きです。","ro":"Haha wa Furano no chīzu ga daisuki desu."},{"fr":"Il faut le garder au frais pendant le voyage.","tgt":"旅行中は冷やしておかなければなりません。","ro":"Ryokōchū wa hiyashite okanakereba narimasen."},{"fr":"Pourriez-vous me faire un paquet cadeau ?","tgt":"プレゼント用に包んでもらえますか？","ro":"Purezento yō ni tsutsunde moraemasu ka?"},{"fr":"La valise est déjà presque pleine.","tgt":"スーツケースはもうほとんどいっぱいです。","ro":"Sūtsukēsu wa mō hotondo ippai desu."},{"fr":"On envoie un carton jusqu'à l'aéroport par livraison.","tgt":"段ボールを一つ空港まで宅配便で送ります。","ro":"Danbōru o hitotsu kūkō made takuhaibin de okurimasu."},{"fr":"Ce service de livraison est vraiment pratique.","tgt":"この宅配サービスはとても便利です。","ro":"Kono takuhai sābisu wa totemo benri desu."},{"fr":"Je pense que ce voyage dans le nord va me manquer.","tgt":"北の旅がなつかしくなると思います。","ro":"Kita no tabi ga natsukashiku naru to omoimasu."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce voyage nous a menés de Hokkaido jusqu'au pied du Fuji.","tgt":"この旅で、北海道から富士山のふもとまで行きました。","ro":"Kono tabi de, Hokkaidō kara Fujisan no fumoto made ikimashita."},{"fr":"Je sais maintenant exprimer l'obligation en japonais.","tgt":"日本語で「〜なければなりません」が言えるようになりました。","ro":"Nihongo de \"nakereba narimasen\" ga ieru yō ni narimashita."},{"fr":"La forme potentielle nous a beaucoup servi en voyage.","tgt":"可能形は旅行でとても役に立ちました。","ro":"Kanōkei wa ryokō de totemo yaku ni tachimashita."},{"fr":"Avec « tara », on peut parler de ce qui arrivera si…","tgt":"「〜たら」で、もしもの話ができます。","ro":"\"Tara\" de, moshimo no hanashi ga dekimasu."},{"fr":"Je pense que mon japonais a vraiment progressé.","tgt":"私の日本語はかなり上手になったと思います。","ro":"Watashi no nihongo wa kanari jōzu ni natta to omoimasu."},{"fr":"Les imprévus ne me font plus peur.","tgt":"もう予定外のことも怖くありません。","ro":"Mō yoteigai no koto mo kowaku arimasen."},{"fr":"J'ai envie de retourner dans un onsen du Tohoku.","tgt":"また東北の温泉に行きたいです。","ro":"Mata Tōhoku no onsen ni ikitai desu."},{"fr":"Le prochain module parlera de conversation entre amis.","tgt":"次は友達との会話を勉強します。","ro":"Tsugi wa tomodachi to no kaiwa o benkyō shimasu."},{"fr":"Prenons le temps de souffler un peu avant la suite.","tgt":"次に進む前に、少し休みましょう。","ro":"Tsugi ni susumu mae ni, sukoshi yasumimashō."},{"fr":"Bravo pour ce beau voyage, et à très bientôt !","tgt":"おつかれさまでした。またすぐに会いましょう！","ro":"Otsukaresama deshita. Mata sugu ni aimashō!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles à Fukuoka","phrases":[{"fr":"Ça fait vraiment longtemps, Kenta !","tgt":"健太さん、本当にお久しぶりです。","ro":"Kenta-san, hontō ni ohisashiburi desu."},{"fr":"Je suis arrivé à Fukuoka hier soir.","tgt":"昨日の夜、福岡に着きました。","ro":"Kinō no yoru, Fukuoka ni tsukimashita."},{"fr":"Tu n'as pas changé du tout.","tgt":"全然変わっていませんね。","ro":"Zenzen kawatte imasen ne."},{"fr":"Tu habites toujours près de la gare de Hakata ?","tgt":"まだ博多駅の近くに住んでいますか？","ro":"Mada Hakata eki no chikaku ni sunde imasu ka?"},{"fr":"Non, j'ai déménagé à Tenjin l'année dernière.","tgt":"いいえ、去年天神に引っ越しました。","ro":"Iie, kyonen Tenjin ni hikkoshimashita."},{"fr":"Tenjin, c'est pratique pour sortir le soir.","tgt":"天神は夜出かけるのに便利です。","ro":"Tenjin wa yoru dekakeru no ni benri desu."},{"fr":"Tu as le temps de prendre un café maintenant ?","tgt":"今、コーヒーを飲む時間がありますか？","ro":"Ima, kōhī o nomu jikan ga arimasu ka?"},{"fr":"Bien sûr, je connais un bon café près d'ici.","tgt":"もちろんです。この近くにいい喫茶店を知っています。","ro":"Mochiron desu. Kono chikaku ni ii kissaten o shitte imasu."},{"fr":"On a tellement de choses à se raconter.","tgt":"話したいことがたくさんあります。","ro":"Hanashitai koto ga takusan arimasu."},{"fr":"Je suis vraiment content de te revoir.","tgt":"また会えて本当にうれしいです。","ro":"Mata aete hontō ni ureshii desu."}]},{"title":"Parler comme entre amis","phrases":[{"fr":"Salut Yui, tu vas bien ?","tgt":"ゆい、元気？","ro":"Yui, genki?"},{"fr":"Ouais, ça va. J'ai fini le boulot.","tgt":"うん、元気。仕事が終わったよ。","ro":"Un, genki. Shigoto ga owatta yo."},{"fr":"Ça te dit d'aller manger des ramen ce soir ?","tgt":"今晩、ラーメン食べに行かない？","ro":"Konban, rāmen tabe ni ikanai?"},{"fr":"Bonne idée, j'ai trop faim !","tgt":"いいね、おなかすいた！","ro":"Ii ne, onaka suita!"},{"fr":"Tu connais une bonne adresse à Nakasu ?","tgt":"中洲でおいしい店、知ってる？","ro":"Nakasu de oishii mise, shitte ru?"},{"fr":"Oui, il y a un super stand de ramen tonkotsu.","tgt":"うん、すごくおいしい豚骨ラーメンの屋台があるよ。","ro":"Un, sugoku oishii tonkotsu rāmen no yatai ga aru yo."},{"fr":"On se retrouve à sept heures devant la gare ?","tgt":"七時に駅の前で待ち合わせる？","ro":"Shichiji ni eki no mae de machiawaseru?"},{"fr":"Ça marche, je ne serai pas en retard.","tgt":"了解、遅れないよ。","ro":"Ryōkai, okurenai yo."},{"fr":"Avec toi, pas besoin de parler poliment.","tgt":"ゆいとは丁寧に話さなくてもいいね。","ro":"Yui to wa teinei ni hanasanakute mo ii ne."},{"fr":"Bon, à plus tard alors !","tgt":"じゃあ、またあとでね！","ro":"Jā, mata ato de ne!"}],"tip":{"title":"Le registre familier entre amis","example":"Ça te dit d'aller manger des ramen ce soir ? — 今晩、ラーメン食べに<b>行かない</b>？","body":"Entre amis ou en famille, les Japonais abandonnent les terminaisons polies « desu » et « masu » et parlent avec les formes simples que vous connaissez déjà : forme du dictionnaire, forme en « -nai », forme en « -ta ». Ainsi « ikimasen ka », on n'y va pas, devient simplement « ikanai », dit avec une intonation montante et sans le « ka » de la question. « Konban, rāmen tabe ni ikanai » se décompose ainsi : ce soir, ramen, manger, pour, ne pas aller ? Les particules comme « o » disparaissent souvent, « desu » saute ou devient « da », et on ajoute volontiers « yo » ou « ne » : « genki » pour ça va, « un, genki da yo » pour ouais, ça va, « oishii ne » pour c'est bon, hein. Attention, ce registre est réservé aux proches : avec un collègue plus âgé ou un inconnu, restez à la forme polie. Pour retenir : plus on est proche, plus la phrase raccourcit.","exampleRo":"Konban, rāmen tabe ni ikanai?","lit":"ce soir · ramen · manger · [but] · aller-pas · [question montante]","say":{"desu":"です","masu":"ます","ikimasen ka":"行きませんか","ikanai":"行かない","ka":"か","o":"を","da":"だ","yo":"よ","ne":"ね","genki":"元気","un, genki da yo":"うん、元気だよ","oishii ne":"おいしいね","Konban, rāmen tabe ni ikanai":"今晩、ラーメン食べに行かない？"}}},{"title":"Une soirée au yatai","phrases":[{"fr":"Les yatai de Nakasu sont alignés le long de la rivière.","tgt":"中洲の屋台は川沿いに並んでいます。","ro":"Nakasu no yatai wa kawazoi ni narande imasu."},{"fr":"Il n'y a que huit places, serrons-nous un peu.","tgt":"席は八つしかありませんから、詰めて座りましょう。","ro":"Seki wa yattsu shika arimasen kara, tsumete suwarimashō."},{"fr":"Le patron est bavard et très gentil.","tgt":"店の主人はおしゃべりで、とても親切です。","ro":"Mise no shujin wa oshaberi de, totemo shinsetsu desu."},{"fr":"Pour moi, des yakitori et une bière pression.","tgt":"私は焼き鳥と生ビールにします。","ro":"Watashi wa yakitori to nama bīru ni shimasu."},{"fr":"On a discuté avec des employés de bureau assis à côté.","tgt":"隣に座っていた会社員と話しました。","ro":"Tonari ni suwatte ita kaishain to hanashimashita."},{"fr":"Ils nous ont recommandé les ramen d'un yatai voisin.","tgt":"近くの屋台のラーメンを勧めてくれました。","ro":"Chikaku no yatai no rāmen o susumete kuremashita."},{"fr":"Ici, le bouillon tonkotsu est très épais.","tgt":"ここの豚骨スープはとても濃いです。","ro":"Koko no tonkotsu sūpu wa totemo koi desu."},{"fr":"On peut commander une portion de nouilles en plus.","tgt":"替え玉を頼むことができます。","ro":"Kaedama o tanomu koto ga dekimasu."},{"fr":"Je n'avais jamais mangé dehors comme ça.","tgt":"こんなふうに外で食べたことはありませんでした。","ro":"Konna fū ni soto de tabeta koto wa arimasen deshita."},{"fr":"C'était une soirée vraiment inoubliable.","tgt":"本当に忘れられない夜でした。","ro":"Hontō ni wasurerarenai yoru deshita."}]},{"title":"Le hanami au parc Maizuru","phrases":[{"fr":"Les cerisiers du parc Maizuru sont en pleine floraison.","tgt":"舞鶴公園の桜が満開です。","ro":"Maizuru kōen no sakura ga mankai desu."},{"fr":"Faisons un hanami samedi avec les collègues.","tgt":"土曜日に同僚とお花見をしましょう。","ro":"Doyōbi ni dōryō to ohanami o shimashō."},{"fr":"Si on n'arrive pas tôt, on n'aura pas de bonne place.","tgt":"早く行かなかったら、いい場所が取れません。","ro":"Hayaku ikanakattara, ii basho ga toremasen."},{"fr":"J'apporte une bâche bleue et des boissons.","tgt":"ブルーシートと飲み物を持っていきます。","ro":"Burū shīto to nomimono o motte ikimasu."},{"fr":"Qui s'occupe des bentō ?","tgt":"お弁当はだれが用意しますか？","ro":"Obentō wa dare ga yōi shimasu ka?"},{"fr":"Mme Tanaka a dit qu'elle ferait des onigiri.","tgt":"田中さんがおにぎりを作ると言っていました。","ro":"Tanaka-san ga onigiri o tsukuru to itte imashita."},{"fr":"Les pétales tombent comme de la neige.","tgt":"花びらが雪のように散っています。","ro":"Hanabira ga yuki no yō ni chitte imasu."},{"fr":"Le soir, les cerisiers sont illuminés.","tgt":"夜は桜のライトアップがあります。","ro":"Yoru wa sakura no raitoappu ga arimasu."},{"fr":"Le hanami, c'est une bonne excuse pour boire entre amis.","tgt":"お花見は友達と飲むいい口実です。","ro":"Ohanami wa tomodachi to nomu ii kōjitsu desu."},{"fr":"N'oubliez pas de remporter vos déchets en partant.","tgt":"帰るとき、ごみを持って帰るのを忘れないでください。","ro":"Kaeru toki, gomi o motte kaeru no o wasurenaide kudasai."}]},{"title":"Un week-end incertain","phrases":[{"fr":"Demain, il pleuvra peut-être sur Fukuoka.","tgt":"明日、福岡は雨が降るかもしれません。","ro":"Ashita, Fukuoka wa ame ga furu kamoshiremasen."},{"fr":"Dans ce cas, le hanami sera peut-être annulé.","tgt":"そうしたら、お花見は中止かもしれません。","ro":"Sō shitara, ohanami wa chūshi kamoshiremasen."},{"fr":"Kenta arrivera peut-être un peu en retard.","tgt":"健太さんは少し遅れるかもしれません。","ro":"Kenta-san wa sukoshi okureru kamoshiremasen."},{"fr":"Il a peut-être oublié notre rendez-vous.","tgt":"約束を忘れたかもしれません。","ro":"Yakusoku o wasureta kamoshiremasen."},{"fr":"Je ne pourrai peut-être pas venir dimanche.","tgt":"日曜日は行けないかもしれません。","ro":"Nichiyōbi wa ikenai kamoshiremasen."},{"fr":"J'aurai peut-être du travail dimanche aussi.","tgt":"日曜日も仕事があるかもしれません。","ro":"Nichiyōbi mo shigoto ga aru kamoshiremasen."},{"fr":"Ce restaurant est peut-être fermé le lundi.","tgt":"あのレストランは月曜日、休みかもしれません。","ro":"Ano resutoran wa getsuyōbi, yasumi kamoshiremasen."},{"fr":"Je vais d'abord leur téléphoner.","tgt":"先に電話してみます。","ro":"Saki ni denwa shite mimasu."},{"fr":"L'après-midi, ce sera peut-être plus calme.","tgt":"午後のほうが静かかもしれません。","ro":"Gogo no hō ga shizuka kamoshiremasen."},{"fr":"Décidons ensemble ce soir, d'accord ?","tgt":"今晩、一緒に決めましょうか。","ro":"Konban, issho ni kimemashō ka."}],"tip":{"title":"« -kamoshiremasen » : peut-être","example":"Kenta arrivera peut-être un peu en retard. — 健太さんは少し遅れる<b>かもしれません</b>。","body":"Pour dire « peut-être », le japonais ajoute « kamoshiremasen » à la fin de la phrase, après un verbe à la forme simple, un adjectif ou un nom. « Kenta-san wa sukoshi okureru kamoshiremasen » se lit mot à mot : Kenta, thème, un peu, être en retard, peut-être. En français, « peut-être » se promène dans la phrase ; en japonais, il arrive toujours tout à la fin, comme un petit doute qu'on ajoute au dernier moment. Il marche avec tous les temps et avec la négation : « furu kamoshiremasen », il pleuvra peut-être, « ikenai kamoshiremasen », je ne pourrai peut-être pas y aller, « wasureta kamoshiremasen », il a peut-être oublié. Avec un nom, on le colle directement : « yasumi kamoshiremasen », c'est peut-être fermé. Astuce : les Japonais l'adorent pour adoucir un refus, alors pensez-y chaque fois que vous hésitez.","exampleRo":"Kenta-san wa sukoshi okureru kamoshiremasen.","lit":"Kenta-monsieur · [thème] · un peu · être en retard · peut-être (poli)","say":{"kamoshiremasen":"かもしれません","furu kamoshiremasen":"降るかもしれません","ikenai kamoshiremasen":"行けないかもしれません","wasureta kamoshiremasen":"忘れたかもしれません","yasumi kamoshiremasen":"休みかもしれません","Kenta-san wa sukoshi okureru kamoshiremasen":"健太さんは少し遅れるかもしれません"}}},{"title":"Le festival Hakata Gion Yamakasa","phrases":[{"fr":"En juillet, Fukuoka fête le Hakata Gion Yamakasa.","tgt":"七月に、福岡で博多祇園山笠があります。","ro":"Shichigatsu ni, Fukuoka de Hakata Gion Yamakasa ga arimasu."},{"fr":"Des hommes portent d'énormes chars en courant dans les rues.","tgt":"男の人たちが大きな山笠を担いで町を走ります。","ro":"Otoko no hitotachi ga ōkina yamakasa o katsuide machi o hashirimasu."},{"fr":"La course finale commence à quatre heures cinquante-neuf du matin.","tgt":"最後のレースは朝四時五十九分に始まります。","ro":"Saigo no rēsu wa asa yoji gojūkyūfun ni hajimarimasu."},{"fr":"Si tu veux la voir, il faut te lever très tôt.","tgt":"それを見たかったら、とても早く起きなければなりません。","ro":"Sore o mitakattara, totemo hayaku okinakereba narimasen."},{"fr":"Les spectateurs jettent de l'eau sur les porteurs.","tgt":"見物人が担ぎ手に水をかけます。","ro":"Kenbutsunin ga katsugite ni mizu o kakemasu."},{"fr":"Mon collègue y participe depuis qu'il est enfant.","tgt":"同僚は子どものころから参加しています。","ro":"Dōryō wa kodomo no koro kara sanka shite imasu."},{"fr":"Les participants portent une tenue traditionnelle.","tgt":"参加者は伝統的な衣装を着ています。","ro":"Sankasha wa dentōteki na ishō o kite imasu."},{"fr":"Pendant deux semaines, l'ambiance du quartier est incroyable.","tgt":"二週間、町の雰囲気がすごいです。","ro":"Nishūkan, machi no fun'iki ga sugoi desu."},{"fr":"Je l'ai vu une fois, il y a trois ans.","tgt":"三年前に一度見ました。","ro":"Sannen mae ni ichido mimashita."},{"fr":"Cette année aussi, je veux absolument y aller.","tgt":"今年もぜひ見に行きたいです。","ro":"Kotoshi mo zehi mi ni ikitai desu."}]},{"title":"Porter un yukata","phrases":[{"fr":"Pour le feu d'artifice, on y va en yukata.","tgt":"花火大会には浴衣を着ていきます。","ro":"Hanabi taikai ni wa yukata o kite ikimasu."},{"fr":"Je n'ai jamais porté de yukata.","tgt":"浴衣を着たことがありません。","ro":"Yukata o kita koto ga arimasen."},{"fr":"Ma collègue va m'aider à l'enfiler.","tgt":"同僚が着るのを手伝ってくれます。","ro":"Dōryō ga kiru no o tetsudatte kuremasu."},{"fr":"Le côté gauche se met par-dessus le droit.","tgt":"左側を右側の上に重ねます。","ro":"Hidarigawa o migigawa no ue ni kasanemasu."},{"fr":"L'inverse, c'est la façon d'habiller les défunts.","tgt":"逆は亡くなった人の着方です。","ro":"Gyaku wa nakunatta hito no kikata desu."},{"fr":"Cette ceinture rouge te va très bien.","tgt":"この赤い帯、よく似合っていますね。","ro":"Kono akai obi, yoku niatte imasu ne."},{"fr":"Les sandales en bois font un peu mal aux pieds.","tgt":"下駄は少し足が痛くなります。","ro":"Geta wa sukoshi ashi ga itaku narimasu."},{"fr":"On peut louer un yukata près de la gare.","tgt":"駅の近くで浴衣を借りることができます。","ro":"Eki no chikaku de yukata o kariru koto ga dekimasu."},{"fr":"Prenons une photo ensemble avant de partir.","tgt":"出かける前に、一緒に写真を撮りましょう。","ro":"Dekakeru mae ni, issho ni shashin o torimashō."},{"fr":"Quand on porte un yukata, on se sent vraiment en été.","tgt":"浴衣を着たら、本当に夏の気分になります。","ro":"Yukata o kitara, hontō ni natsu no kibun ni narimasu."}]},{"title":"Parler baseball","phrases":[{"fr":"Tu es supporter de quelle équipe de baseball ?","tgt":"どの野球チームのファンですか？","ro":"Dono yakyū chīmu no fan desu ka?"},{"fr":"Moi, je soutiens les Hawks de Fukuoka.","tgt":"私は福岡のホークスを応援しています。","ro":"Watashi wa Fukuoka no Hōkusu o ōen shite imasu."},{"fr":"Mon collègue de Hiroshima est fan des Carp.","tgt":"広島出身の同僚はカープのファンです。","ro":"Hiroshima shusshin no dōryō wa Kāpu no fan desu."},{"fr":"Hier soir, les Hawks ont gagné cinq à trois.","tgt":"昨日の夜、ホークスが五対三で勝ちました。","ro":"Kinō no yoru, Hōkusu ga go tai san de kachimashita."},{"fr":"Le stade était plein à craquer.","tgt":"球場は満員でした。","ro":"Kyūjō wa man'in deshita."},{"fr":"À la septième manche, tout le monde lâche des ballons.","tgt":"七回に、みんなで風船を飛ばします。","ro":"Nanakai ni, minna de fūsen o tobashimasu."},{"fr":"Les supporters chantent pendant tout le match.","tgt":"ファンは試合中ずっと歌っています。","ro":"Fan wa shiaichū zutto utatte imasu."},{"fr":"Les places au premier rang coûtent cher.","tgt":"一列目の席は高いです。","ro":"Ichiretsume no seki wa takai desu."},{"fr":"Tu veux venir voir un match avec moi le mois prochain ?","tgt":"来月、一緒に試合を見に行きませんか？","ro":"Raigetsu, issho ni shiai o mi ni ikimasen ka?"},{"fr":"Avec plaisir, mais je porterai la casquette des Carp !","tgt":"いいですね。でも、カープの帽子をかぶっていきます！","ro":"Ii desu ne. Demo, Kāpu no bōshi o kabutte ikimasu!"}]},{"title":"Le sumō, un sujet de conversation","phrases":[{"fr":"En novembre, le tournoi de sumō a lieu à Fukuoka.","tgt":"十一月に、福岡で大相撲の九州場所があります。","ro":"Jūichigatsu ni, Fukuoka de ōzumō no Kyūshū basho ga arimasu."},{"fr":"Tu as regardé le combat d'hier à la télé ?","tgt":"昨日の取組をテレビで見ましたか？","ro":"Kinō no torikumi o terebi de mimashita ka?"},{"fr":"Oui, le combat a duré moins de dix secondes.","tgt":"はい、十秒もかかりませんでした。","ro":"Hai, jūbyō mo kakarimasen deshita."},{"fr":"Avant le combat, les lutteurs jettent du sel.","tgt":"取組の前に、力士は塩をまきます。","ro":"Torikumi no mae ni, rikishi wa shio o makimasu."},{"fr":"Avec le sel, ils purifient le cercle de combat.","tgt":"塩で土俵を清めます。","ro":"Shio de dohyō o kiyomemasu."},{"fr":"Le lutteur qui sort du cercle a perdu.","tgt":"土俵から出た力士が負けです。","ro":"Dohyō kara deta rikishi ga make desu."},{"fr":"Ma grand-mère connaît le nom de tous les lutteurs.","tgt":"祖母は力士の名前を全部知っています。","ro":"Sobo wa rikishi no namae o zenbu shitte imasu."},{"fr":"Je ne comprends pas encore toutes les règles.","tgt":"まだルールが全部わかりません。","ro":"Mada rūru ga zenbu wakarimasen."},{"fr":"Le grade le plus élevé s'appelle « yokozuna ».","tgt":"一番上の位は横綱といいます。","ro":"Ichiban ue no kurai wa yokozuna to iimasu."},{"fr":"Le sumō, c'est un bon sujet pour lancer la conversation.","tgt":"相撲の話は、会話のきっかけになります。","ro":"Sumō no hanashi wa, kaiwa no kikkake ni narimasu."}]},{"title":"L'anniversaire d'une collègue","phrases":[{"fr":"Vendredi, c'est l'anniversaire de Mme Mori.","tgt":"金曜日は森さんの誕生日です。","ro":"Kin'yōbi wa Mori-san no tanjōbi desu."},{"fr":"Et si on lui faisait une surprise ?","tgt":"サプライズをしませんか？","ro":"Sapuraizu o shimasen ka?"},{"fr":"Pour le cadeau, c'est mille yens par personne.","tgt":"プレゼント代は一人千円ずつです。","ro":"Purezento dai wa hitori sen'en zutsu desu."},{"fr":"À ton avis, qu'est-ce qu'elle aime ?","tgt":"森さんは何が好きだと思いますか？","ro":"Mori-san wa nani ga suki da to omoimasu ka?"},{"fr":"Je crois qu'elle adore les fleurs et le thé.","tgt":"花とお茶が大好きだと思います。","ro":"Hana to ocha ga daisuki da to omoimasu."},{"fr":"J'ai commandé un gâteau à la pâtisserie d'en face.","tgt":"向かいのケーキ屋さんにケーキを注文しました。","ro":"Mukai no kēkiya-san ni kēki o chūmon shimashita."},{"fr":"Cache la carte, elle arrive !","tgt":"カードを隠してください。森さんが来ます！","ro":"Kādo o kakushite kudasai. Mori-san ga kimasu!"},{"fr":"Joyeux anniversaire, madame Mori !","tgt":"森さん、お誕生日おめでとうございます！","ro":"Mori-san, otanjōbi omedetō gozaimasu!"},{"fr":"Elle a été très touchée par la surprise.","tgt":"サプライズにとても感動していました。","ro":"Sapuraizu ni totemo kandō shite imashita."},{"fr":"Ça fait combien d'années que vous travaillez ensemble ?","tgt":"一緒に働いて何年になりますか？","ro":"Issho ni hataraite nannen ni narimasu ka?"}]},{"title":"Les séries du moment","phrases":[{"fr":"Tu regardes une série en ce moment ?","tgt":"今、何かドラマを見ていますか？","ro":"Ima, nanika dorama o mite imasu ka?"},{"fr":"Je regarde une série policière très populaire.","tgt":"人気の刑事ドラマを見ています。","ro":"Ninki no keiji dorama o mite imasu."},{"fr":"Justement, l'histoire se passe à Hiroshima.","tgt":"ちょうど広島が舞台です。","ro":"Chōdo Hiroshima ga butai desu."},{"fr":"Tu en as déjà vu combien d'épisodes ?","tgt":"もう何話見ましたか？","ro":"Mō nanwa mimashita ka?"},{"fr":"J'ai tout regardé le week-end dernier.","tgt":"先週末に全部見ました。","ro":"Senshūmatsu ni zenbu mimashita."},{"fr":"Ne me raconte pas la fin, s'il te plaît !","tgt":"最後は言わないでください！","ro":"Saigo wa iwanaide kudasai!"},{"fr":"L'acteur principal joue vraiment bien.","tgt":"主役の俳優は演技が本当に上手です。","ro":"Shuyaku no haiyū wa engi ga hontō ni jōzu desu."},{"fr":"La deuxième saison commence en avril.","tgt":"第二シーズンは四月に始まります。","ro":"Dai ni shīzun wa shigatsu ni hajimarimasu."},{"fr":"Je préfère les séries courtes, d'une dizaine d'épisodes.","tgt":"十話ぐらいの短いドラマのほうが好きです。","ro":"Jūwa gurai no mijikai dorama no hō ga suki desu."},{"fr":"Tu veux la regarder avec moi samedi, chez moi ?","tgt":"土曜日にうちで一緒に見ませんか？","ro":"Doyōbi ni uchi de issho ni mimasen ka?"}]},{"title":"Impressions et rumeurs","phrases":[{"fr":"Ce mentaiko a l'air délicieux.","tgt":"この明太子、おいしそうですね。","ro":"Kono mentaiko, oishisō desu ne."},{"fr":"Tu as l'air d'avoir sommeil aujourd'hui.","tgt":"今日は眠そうですね。","ro":"Kyō wa nemusō desu ne."},{"fr":"Il paraît que Kenta va se marier.","tgt":"健太さんは結婚するそうです。","ro":"Kenta-san wa kekkon suru sō desu."},{"fr":"D'après la météo, il fera beau ce week-end.","tgt":"天気予報によると、週末は晴れるそうです。","ro":"Tenki yohō ni yoru to, shūmatsu wa hareru sō desu."},{"fr":"On dirait qu'il va pleuvoir d'un moment à l'autre.","tgt":"今にも雨が降りそうです。","ro":"Ima ni mo ame ga furisō desu."},{"fr":"Il paraît qu'un nouveau café a ouvert à Tenjin.","tgt":"天神に新しいカフェができたそうです。","ro":"Tenjin ni atarashii kafe ga dekita sō desu."},{"fr":"Ce match s'annonce serré.","tgt":"この試合は接戦になりそうです。","ro":"Kono shiai wa sessen ni narisō desu."},{"fr":"Mme Mori a l'air ravie de son cadeau.","tgt":"森さんはプレゼントがとてもうれしそうです。","ro":"Mori-san wa purezento ga totemo ureshisō desu."},{"fr":"Il paraît que le directeur est muté à Hiroshima.","tgt":"部長は広島に転勤するそうです。","ro":"Buchō wa Hiroshima ni tenkin suru sō desu."},{"fr":"Ah bon ? Je n'en savais rien.","tgt":"そうですか。全然知りませんでした。","ro":"Sō desu ka. Zenzen shirimasen deshita."}],"tip":{"title":"« -sō desu » : on dirait que, et j'ai entendu dire que","example":"Il paraît que Kenta va se marier. — 健太さんは結婚する<b>そうです</b>。","body":"« Sō desu » a deux usages, et c'est la forme placée juste avant qui permet de les distinguer. Collé au radical d'un verbe, ou à un adjectif privé de son « i » final, il exprime une impression : « oishisō desu », ça a l'air bon, « furisō desu », on dirait qu'il va pleuvoir. Placé après une forme complète, il rapporte une information entendue : « Kenta-san wa kekkon suru sō desu » se décompose en Kenta, thème, se marier, il paraît. C'est notre « il paraît que », mais placé tout à la fin de la phrase. Comparez « furisō desu », je vois des nuages, il va pleuvoir, et « furu sō desu », la météo annonce de la pluie. Astuce : forme raccourcie, je le vois ; forme entière, on me l'a dit.","exampleRo":"Kenta-san wa kekkon suru sō desu.","lit":"Kenta-monsieur · [thème] · se marier · il paraît (poli)","say":{"Sō desu":"そうです","oishisō desu":"おいしそうです","furisō desu":"降りそうです","furu sō desu":"降るそうです","Kenta-san wa kekkon suru sō desu":"健太さんは結婚するそうです"}}},{"title":"Une journée à Hiroshima","phrases":[{"fr":"De Fukuoka à Hiroshima, il faut environ une heure en shinkansen.","tgt":"福岡から広島まで新幹線で一時間ぐらいです。","ro":"Fukuoka kara Hiroshima made shinkansen de ichijikan gurai desu."},{"fr":"Nous sommes d'abord allés au parc du Mémorial pour la paix.","tgt":"まず平和記念公園に行きました。","ro":"Mazu Heiwa Kinen Kōen ni ikimashita."},{"fr":"En voyant le Dôme de la bombe atomique, j'ai eu le cœur serré.","tgt":"原爆ドームを見て、とても胸が痛くなりました。","ro":"Genbaku dōmu o mite, totemo mune ga itaku narimashita."},{"fr":"Au musée, il y avait beaucoup d'élèves en voyage scolaire.","tgt":"資料館には修学旅行の学生がたくさんいました。","ro":"Shiryōkan ni wa shūgaku ryokō no gakusei ga takusan imashita."},{"fr":"Chaque année, des milliers de grues en papier sont envoyées ici.","tgt":"毎年、何千羽もの折り鶴が届きます。","ro":"Maitoshi, nanzenba mo no orizuru ga todokimasu."},{"fr":"À midi, on a mangé un okonomiyaki à la mode de Hiroshima.","tgt":"昼は広島風お好み焼きを食べました。","ro":"Hiru wa Hiroshimafū okonomiyaki o tabemashita."},{"fr":"Ici, on met des nouilles au milieu.","tgt":"ここでは、麺を間に入れます。","ro":"Koko de wa, men o aida ni iremasu."},{"fr":"Le cuisinier prépare tout devant nous, sur une plaque chauffante.","tgt":"店の人が目の前の鉄板で焼きます。","ro":"Mise no hito ga me no mae no teppan de yakimasu."},{"fr":"Je trouve celui de Hiroshima plus copieux que celui d'Osaka.","tgt":"大阪のより広島のほうがボリュームがあると思います。","ro":"Ōsaka no yori Hiroshima no hō ga boryūmu ga aru to omoimasu."},{"fr":"Ce soir, on dort près de l'embarcadère pour Miyajima.","tgt":"今晩は宮島行きの船乗り場の近くに泊まります。","ro":"Konban wa Miyajima iki no funanoriba no chikaku ni tomarimasu."}]},{"title":"L'île de Miyajima","phrases":[{"fr":"Le ferry pour Miyajima ne met que dix minutes.","tgt":"宮島行きのフェリーは十分しかかかりません。","ro":"Miyajima iki no ferī wa juppun shika kakarimasen."},{"fr":"On a regardé le grand torii pendant la traversée.","tgt":"船に乗りながら、大鳥居を見ました。","ro":"Fune ni norinagara, ōtorii o mimashita."},{"fr":"À marée haute, le torii semble flotter sur la mer.","tgt":"満潮のとき、鳥居は海に浮いているように見えます。","ro":"Manchō no toki, torii wa umi ni uite iru yō ni miemasu."},{"fr":"Des cerfs se promènent librement dans les rues.","tgt":"鹿が自由に町を歩いています。","ro":"Shika ga jiyū ni machi o aruite imasu."},{"fr":"Les huîtres grillées sont la spécialité de l'île.","tgt":"焼き牡蠣は島の名物です。","ro":"Yakigaki wa shima no meibutsu desu."},{"fr":"Mon ami prend des photos tout en marchant.","tgt":"友達は歩きながら写真を撮っています。","ro":"Tomodachi wa arukinagara shashin o totte imasu."},{"fr":"On a parlé de nos souvenirs en buvant un thé.","tgt":"お茶を飲みながら、思い出を話しました。","ro":"Ocha o nominagara, omoide o hanashimashita."},{"fr":"Nous sommes montés au mont Misen en téléphérique.","tgt":"ロープウェーで弥山に登りました。","ro":"Rōpuwē de Misen ni noborimashita."},{"fr":"J'aime regarder la mer en écoutant de la musique.","tgt":"音楽を聞きながら、海を見るのが好きです。","ro":"Ongaku o kikinagara, umi o miru no ga suki desu."},{"fr":"En fin de journée, l'île devient très calme.","tgt":"夕方、島はとても静かになります。","ro":"Yūgata, shima wa totemo shizuka ni narimasu."}],"tip":{"title":"« -nagara » : faire deux choses en même temps","example":"On a parlé de nos souvenirs en buvant un thé. — お茶を<b>飲みながら</b>、思い出を話しました。","body":"Pour dire qu'on fait deux choses à la fois, on prend le verbe à la forme en « masu », on enlève « masu » et on ajoute « nagara » : « nomimasu » devient « nominagara », en buvant. « Ocha o nominagara, omoide o hanashimashita » se décompose ainsi : thé, objet, tout en buvant, souvenirs, objet, nous avons parlé. Le verbe avec « nagara » décrit l'action d'arrière-plan, et c'est le dernier verbe, l'action principale, qui porte le temps et la politesse. Quelques exemples : « arukinagara », en marchant, « kikinagara », en écoutant, « minagara », en regardant. Attention, les deux actions doivent être faites par la même personne. Astuce : pensez au gérondif français « en faisant », mais placé avant l'action principale.","exampleRo":"Ocha o nominagara, omoide o hanashimashita.","lit":"honorable-thé · [objet] · boire-tout en · souvenirs · [objet] · avoir parlé (poli)","say":{"masu":"ます","nagara":"ながら","nomimasu":"飲みます","nominagara":"飲みながら","arukinagara":"歩きながら","kikinagara":"聞きながら","minagara":"見ながら","Ocha o nominagara, omoide o hanashimashita":"お茶を飲みながら、思い出を話しました","-nagara":"ながら"}}},{"title":"Un onsen entre amis","phrases":[{"fr":"Ce week-end, je pars à l'onsen avec des amis.","tgt":"今週末、友達と温泉に行きます。","ro":"Konshūmatsu, tomodachi to onsen ni ikimasu."},{"fr":"On a réservé un ryokan à Futsukaichi, près de Fukuoka.","tgt":"福岡の近くの二日市温泉の旅館を予約しました。","ro":"Fukuoka no chikaku no Futsukaichi onsen no ryokan o yoyaku shimashita."},{"fr":"Il faut se laver avant d'entrer dans le bain.","tgt":"お風呂に入る前に、体を洗わなければなりません。","ro":"Ofuro ni hairu mae ni, karada o arawanakereba narimasen."},{"fr":"On ne met pas sa serviette dans l'eau.","tgt":"タオルをお湯に入れてはいけません。","ro":"Taoru o oyu ni irete wa ikemasen."},{"fr":"L'eau est un peu trop chaude pour moi.","tgt":"お湯が私には少し熱すぎます。","ro":"Oyu ga watashi ni wa sukoshi atsusugimasu."},{"fr":"La nuit, le bain en plein air est magnifique.","tgt":"夜の露天風呂はすばらしいです。","ro":"Yoru no rotenburo wa subarashii desu."},{"fr":"Après le bain, on boit du lait bien froid.","tgt":"お風呂のあとで、冷たい牛乳を飲みます。","ro":"Ofuro no ato de, tsumetai gyūnyū o nomimasu."},{"fr":"On a joué au ping-pong en yukata.","tgt":"浴衣で卓球をしました。","ro":"Yukata de takkyū o shimashita."},{"fr":"On a dîné dans notre chambre.","tgt":"晩ご飯は部屋で食べました。","ro":"Bangohan wa heya de tabemashita."},{"fr":"J'ai pu bien me détendre, merci de m'avoir invité.","tgt":"本当にリラックスできました。誘ってくれてありがとうございます。","ro":"Hontō ni rirakkusu dekimashita. Sasotte kurete arigatō gozaimasu."}]},{"title":"Donner son opinion","phrases":[{"fr":"Que penses-tu du nouveau stade ?","tgt":"新しいスタジアムについてどう思いますか？","ro":"Atarashii sutajiamu ni tsuite dō omoimasu ka?"},{"fr":"Je pense que c'est une bonne chose pour la ville.","tgt":"町にとっていいことだと思います。","ro":"Machi ni totte ii koto da to omoimasu."},{"fr":"Moi, je ne suis pas vraiment d'accord.","tgt":"私は、あまり賛成できません。","ro":"Watashi wa, amari sansei dekimasen."},{"fr":"À mon avis, les billets sont devenus trop chers.","tgt":"チケットが高くなりすぎたと思います。","ro":"Chiketto ga takaku narisugita to omoimasu."},{"fr":"C'est vrai, mais l'ambiance s'est améliorée.","tgt":"それはそうですが、雰囲気はよくなりました。","ro":"Sore wa sō desu ga, fun'iki wa yoku narimashita."},{"fr":"Au Japon, on évite souvent de dire non directement.","tgt":"日本では、はっきり「いいえ」と言わないことが多いです。","ro":"Nihon de wa, hakkiri « iie » to iwanai koto ga ōi desu."},{"fr":"On dit plutôt « c'est un peu difficile ».","tgt":"「ちょっと難しいですね」と言います。","ro":"« Chotto muzukashii desu ne » to iimasu."},{"fr":"Chacun a un avis différent, et je trouve ça bien.","tgt":"人それぞれ意見が違って、いいと思います。","ro":"Hito sorezore iken ga chigatte, ii to omoimasu."},{"fr":"Je comprends aussi ce point de vue.","tgt":"その考え方もわかります。","ro":"Sono kangaekata mo wakarimasu."},{"fr":"Parlons-en encore autour d'un verre.","tgt":"飲みながら、もっと話しましょう。","ro":"Nominagara, motto hanashimashō."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, je vivais près de la mer à Itoshima.","tgt":"子どものころ、糸島の海の近くに住んでいました。","ro":"Kodomo no koro, Itoshima no umi no chikaku ni sunde imashita."},{"fr":"L'été, je nageais tous les jours.","tgt":"夏は毎日泳いでいました。","ro":"Natsu wa mainichi oyoide imashita."},{"fr":"Le dimanche, mon grand-père m'emmenait souvent pêcher.","tgt":"祖父は日曜日によく釣りに連れていってくれました。","ro":"Sofu wa nichiyōbi ni yoku tsuri ni tsurete itte kuremashita."},{"fr":"On allait aussi au matsuri du quartier en yukata.","tgt":"近所のお祭りにも浴衣で行きました。","ro":"Kinjo no omatsuri ni mo yukata de ikimashita."},{"fr":"J'adorais pêcher des poissons rouges sur les stands.","tgt":"金魚すくいが大好きでした。","ro":"Kingyo sukui ga daisuki deshita."},{"fr":"À l'école primaire, je jouais au baseball avec mes amis.","tgt":"小学校で友達と野球をしていました。","ro":"Shōgakkō de tomodachi to yakyū o shite imashita."},{"fr":"Je n'étais pas très doué, mais je m'amusais beaucoup.","tgt":"あまり上手ではありませんでしたが、とても楽しかったです。","ro":"Amari jōzu de wa arimasen deshita ga, totemo tanoshikatta desu."},{"fr":"Quel est ton meilleur souvenir d'enfance ?","tgt":"子どものころの一番の思い出は何ですか？","ro":"Kodomo no koro no ichiban no omoide wa nan desu ka?"},{"fr":"Je me souviens encore de l'odeur des feux d'artifice.","tgt":"花火のにおいを今でも覚えています。","ro":"Hanabi no nioi o ima demo oboete imasu."},{"fr":"Ces souvenirs me rendent un peu nostalgique.","tgt":"その思い出は、ちょっと懐かしいです。","ro":"Sono omoide wa, chotto natsukashii desu."}]},{"title":"Chez les parents d'un collègue","phrases":[{"fr":"Les parents de M. Yamada nous ont invités chez eux.","tgt":"山田さんのご両親が家に招待してくださいました。","ro":"Yamada-san no goryōshin ga ie ni shōtai shite kudasaimashita."},{"fr":"Votre père est-il là ?","tgt":"お父さんはいらっしゃいますか？","ro":"Otōsan wa irasshaimasu ka?"},{"fr":"Mon père rentre tout de suite, entrez donc.","tgt":"父はすぐ帰ってきます。どうぞ、お上がりください。","ro":"Chichi wa sugu kaette kimasu. Dōzo, oagari kudasai."},{"fr":"Vous allez souvent à Miyajima, madame ?","tgt":"お母さんは、よく宮島にいらっしゃいますか？","ro":"Okāsan wa, yoku Miyajima ni irasshaimasu ka?"},{"fr":"Je vous en prie, goûtez ces huîtres.","tgt":"どうぞ、この牡蠣を召し上がってください。","ro":"Dōzo, kono kaki o meshiagatte kudasai."},{"fr":"Votre père boit-il du saké ?","tgt":"お父さんはお酒を召し上がりますか？","ro":"Otōsan wa osake o meshiagarimasu ka?"},{"fr":"Que faites-vous le week-end, monsieur ?","tgt":"週末は何をなさいますか？","ro":"Shūmatsu wa nani o nasaimasu ka?"},{"fr":"Mon père regarde toujours les matchs des Carp.","tgt":"父はいつもカープの試合を見ています。","ro":"Chichi wa itsumo Kāpu no shiai o mite imasu."},{"fr":"Hier, le professeur est venu au matsuri, lui aussi.","tgt":"先生も昨日お祭りにいらっしゃいました。","ro":"Sensei mo kinō omatsuri ni irasshaimashita."},{"fr":"Merci pour cet accueil si chaleureux.","tgt":"温かく迎えてくださって、ありがとうございました。","ro":"Atatakaku mukaete kudasatte, arigatō gozaimashita."}],"tip":{"title":"Le langage respectueux : « irasshaimasu », « meshiagarimasu »","example":"Votre père boit-il du saké ? — お父さんはお酒を<b>召し上がります</b>か？","body":"Quand on parle d'une personne à qui l'on doit du respect, un aîné, un client ou les parents d'un ami, le japonais remplace certains verbes ordinaires par des verbes spéciaux qui l'élèvent. « Irasshaimasu » remplace à la fois « imasu », être là, « ikimasu », aller, et « kimasu », venir ; « meshiagarimasu » remplace « tabemasu », manger, et « nomimasu », boire. « Otōsan wa osake o meshiagarimasu ka » se décompose ainsi : honorable père, thème, honorable saké, objet, boire avec respect, question ? En revanche, on n'utilise jamais ces verbes pour soi-même ni pour sa propre famille : on dit simplement « chichi wa mite imasu », mon père regarde. Vous connaissez déjà « irasshaimase », le mot d'accueil des magasins : c'est le même verbe. Astuce : on élève les autres, jamais soi-même.","exampleRo":"Otōsan wa osake o meshiagarimasu ka?","lit":"honorable-père · [thème] · honorable-saké · [objet] · boire (respectueux) · [question]","say":{"irasshaimasu":"いらっしゃいます","meshiagarimasu":"召し上がります","Irasshaimasu":"いらっしゃいます","imasu":"います","ikimasu":"行きます","kimasu":"来ます","tabemasu":"食べます","nomimasu":"飲みます","chichi wa mite imasu":"父は見ています","irasshaimase":"いらっしゃいませ","Otōsan wa osake o meshiagarimasu ka":"お父さんはお酒を召し上がりますか"}}},{"title":"Se dire au revoir","phrases":[{"fr":"Je rentre en France la semaine prochaine.","tgt":"来週、フランスに帰ります。","ro":"Raishū, Furansu ni kaerimasu."},{"fr":"Ces mois à Fukuoka sont passés si vite.","tgt":"福岡での数か月は、あっという間でした。","ro":"Fukuoka de no sūkagetsu wa, atto iu ma deshita."},{"fr":"Faisons une petite fête d'adieu.","tgt":"送別会をしましょう。","ro":"Sōbetsukai o shimashō."},{"fr":"Tout le monde a écrit un mot sur une carte pour toi.","tgt":"みんなでカードに寄せ書きをしました。","ro":"Minna de kādo ni yosegaki o shimashita."},{"fr":"Écris-moi quand tu seras arrivé.","tgt":"着いたら、連絡してください。","ro":"Tsuitara, renraku shite kudasai."},{"fr":"Si tu viens en France, je te ferai visiter Paris.","tgt":"フランスに来たら、パリを案内します。","ro":"Furansu ni kitara, Pari o annai shimasu."},{"fr":"On pourra se parler en visio le dimanche.","tgt":"日曜日にビデオ通話で話せます。","ro":"Nichiyōbi ni bideo tsūwa de hanasemasu."},{"fr":"Je reviendrai peut-être pour le Yamakasa.","tgt":"山笠のときに、また来るかもしれません。","ro":"Yamakasa no toki ni, mata kuru kamoshiremasen."},{"fr":"Fais attention à ta santé, d'accord ?","tgt":"体に気をつけてくださいね。","ro":"Karada ni ki o tsukete kudasai ne."},{"fr":"Merci pour tout, on se revoit bientôt.","tgt":"いろいろありがとうございました。また会いましょう。","ro":"Iroiro arigatō gozaimashita. Mata aimashō."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à bavarder en japonais.","tgt":"このモジュールで、日本語でおしゃべりすることを学びました。","ro":"Kono mojūru de, nihongo de oshaberi suru koto o manabimashita."},{"fr":"Maintenant, on peut parler familièrement avec des amis.","tgt":"今は友達とくだけた日本語で話せます。","ro":"Ima wa tomodachi to kudaketa nihongo de hanasemasu."},{"fr":"Avec nos aînés, on sait aussi utiliser le langage respectueux.","tgt":"目上の人には尊敬語も使えます。","ro":"Meue no hito ni wa sonkeigo mo tsukaemasu."},{"fr":"Avec « kamoshiremasen », on peut nuancer ses phrases.","tgt":"「かもしれません」を使って、やわらかく話せます。","ro":"« Kamoshiremasen » o tsukatte, yawarakaku hanasemasu."},{"fr":"Avec « sō desu », on rapporte ce qu'on a entendu dire.","tgt":"「そうです」で、聞いた話を伝えられます。","ro":"« Sō desu » de, kiita hanashi o tsutaeraremasu."},{"fr":"Fukuoka et Hiroshima ont été des villes très chaleureuses.","tgt":"福岡も広島も、とても温かい町でした。","ro":"Fukuoka mo Hiroshima mo, totemo atatakai machi deshita."},{"fr":"Notre japonais devient peu à peu plus naturel.","tgt":"日本語がだんだん自然になってきました。","ro":"Nihongo ga dandan shizen ni natte kimashita."},{"fr":"Le deuxième niveau se termine ici.","tgt":"これで、レベル二が終わります。","ro":"Kore de, reberu ni ga owarimasu."},{"fr":"Au niveau trois, on apprendra le keigo et les nuances.","tgt":"レベル三では、敬語や細かいニュアンスを学びます。","ro":"Reberu san de wa, keigo ya komakai nyuansu o manabimasu."},{"fr":"Bravo pour vos efforts, rendez-vous au niveau suivant !","tgt":"お疲れさまでした。また次のレベルで会いましょう！","ro":"Otsukaresama deshita. Mata tsugi no reberu de aimashō!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée au Japon, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Premier jour dans une entreprise japonaise","phrases":[{"fr":"Le premier jour, j'ai été présenté à toute l'équipe.","tgt":"初日に、チーム全員に紹介されました。","ro":"Shonichi ni, chīmu zen'in ni shōkai saremashita."},{"fr":"Le directeur m'a chargé de préparer les documents de demain.","tgt":"部長に明日の資料の準備を頼まれました。","ro":"Buchō ni ashita no shiryō no junbi o tanomaremashita."},{"fr":"Ce bâtiment a été construit il y a trente ans.","tgt":"このビルは三十年前に建てられました。","ro":"Kono biru wa sanjūnen mae ni tateraremashita."},{"fr":"Hier, je suis arrivé en retard et je me suis fait gronder par mon supérieur.","tgt":"昨日、遅刻して上司に怒られました。","ro":"Kinō, chikoku shite jōshi ni okoraremashita."},{"fr":"Un collègue m'a invité à déjeuner avec lui.","tgt":"同僚に昼ご飯に誘われました。","ro":"Dōryō ni hirugohan ni sasowaremashita."},{"fr":"Dans le train, quelqu'un m'a marché sur le pied.","tgt":"電車で足を踏まれました。","ro":"Densha de ashi o fumaremashita."},{"fr":"Le nouveau règlement a été annoncé par e-mail ce matin.","tgt":"新しい規則は今朝、メールで発表されました。","ro":"Atarashii kisoku wa kesa, mēru de happyō saremashita."},{"fr":"À l'accueil, on m'a demandé mon numéro d'employé.","tgt":"受付で社員番号を聞かれました。","ro":"Uketsuke de shain bangō o kikaremashita."},{"fr":"En rentrant, je me suis fait surprendre par la pluie.","tgt":"帰りに雨に降られました。","ro":"Kaeri ni ame ni furaremashita."},{"fr":"Au final, j'ai été accueilli très chaleureusement par tout le monde.","tgt":"結局、みんなにとても温かく迎えられました。","ro":"Kekkyoku, minna ni totemo atatakaku mukaeraremashita."}],"tip":{"title":"Le passif : « -rareru », subir une action","example":"Dans le train, quelqu'un m'a marché sur le pied. — 電車で足を<b>踏まれました</b>。","body":"Le passif japonais se forme en ajoutant « -rareru » ou « -areru » au verbe : « taberu » (manger) devient « taberareru » (être mangé), et « fumu » (marcher sur) devient « fumareru ». La personne qui fait l'action est marquée par « ni » : « jōshi ni okoraremashita » se dit littéralement : supérieur, par, avoir été grondé. Contrairement au français, le japonais l'emploie très souvent pour dire qu'on a subi quelque chose de désagréable, même avec un verbe comme pleuvoir : « ame ni furaremashita », la pluie m'est tombée dessus. Notre exemple, « ashi o fumaremashita », se lit : pied, objet, avoir été marché dessus. Astuce pour retenir : quand vous entendez « -areru » à la fin d'un verbe, pensez « ça m'est tombé dessus ».","exampleRo":"Densha de ashi o fumaremashita.","lit":"train · [lieu] · pied · [objet] · avoir été marché dessus (poli, passé)","say":{"taberu":"食べる","taberareru":"食べられる","fumu":"踏む","fumareru":"踏まれる","ni":"に","jōshi ni okoraremashita":"上司に怒られました","ame ni furaremashita":"雨に降られました","ashi o fumaremashita":"足を踏まれました","-rareru":"られる"}}},{"title":"La réunion du lundi matin","phrases":[{"fr":"La réunion commence à neuf heures pile, ne soyez pas en retard.","tgt":"会議は九時ちょうどに始まるので、遅れないでください。","ro":"Kaigi wa kuji chōdo ni hajimaru node, okurenaide kudasai."},{"fr":"Avant la réunion, il faut imprimer l'ordre du jour.","tgt":"会議の前に、議題を印刷しておかなければなりません。","ro":"Kaigi no mae ni, gidai o insatsu shite okanakereba narimasen."},{"fr":"Chacun résume rapidement l'avancement de son projet.","tgt":"それぞれが自分のプロジェクトの進み具合を簡単に報告します。","ro":"Sorezore ga jibun no purojekuto no susumiguai o kantan ni hōkoku shimasu."},{"fr":"Au Japon, on décide souvent les choses avant la réunion, en coulisses.","tgt":"日本では、会議の前に根回しで物事を決めることが多いです。","ro":"Nihon de wa, kaigi no mae ni nemawashi de monogoto o kimeru koto ga ōi desu."},{"fr":"Personne n'ose contredire ouvertement le directeur.","tgt":"部長にはっきり反対する人はいません。","ro":"Buchō ni hakkiri hantai suru hito wa imasen."},{"fr":"Excusez-moi, me permettez-vous de poser une question ?","tgt":"すみません、一つ質問してもよろしいでしょうか。","ro":"Sumimasen, hitotsu shitsumon shite mo yoroshii deshō ka."},{"fr":"Je pense que ce délai est un peu trop court.","tgt":"この締め切りは少し短すぎると思います。","ro":"Kono shimekiri wa sukoshi mijikasugiru to omoimasu."},{"fr":"Réfléchissons-y, et on en reparle la semaine prochaine.","tgt":"検討して、来週また話し合いましょう。","ro":"Kentō shite, raishū mata hanashiaimashō."},{"fr":"Le compte rendu sera envoyé à tout le monde cet après-midi.","tgt":"議事録は今日の午後、全員に送ります。","ro":"Gijiroku wa kyō no gogo, zen'in ni okurimasu."},{"fr":"Entre nous, cette réunion aurait pu tenir dans un seul e-mail.","tgt":"この会議、メール一通で済んだと思うけど。","ro":"Kono kaigi, mēru ittsū de sunda to omou kedo."}]},{"title":"Former un nouvel employé","phrases":[{"fr":"Cette année, on m'a confié la formation d'un nouvel employé.","tgt":"今年、新入社員の指導を任されました。","ro":"Kotoshi, shinnyū shain no shidō o makasaremashita."},{"fr":"D'abord, je lui fais observer notre façon de travailler.","tgt":"まず、仕事のやり方を見学させます。","ro":"Mazu, shigoto no yarikata o kengaku sasemasu."},{"fr":"Ensuite, je lui fais faire les photocopies et le classement.","tgt":"次に、コピーや書類の整理をさせます。","ro":"Tsugi ni, kopī ya shorui no seiri o sasemasu."},{"fr":"Chaque jour, avant qu'il parte, je lui fais écrire un court compte rendu.","tgt":"毎日、帰る前に短い報告を書かせています。","ro":"Mainichi, kaeru mae ni mijikai hōkoku o kakasete imasu."},{"fr":"Le directeur ne laisse pas encore les nouveaux s'occuper seuls des clients.","tgt":"部長は、新人にはまだ一人でお客様の対応をさせません。","ro":"Buchō wa, shinjin ni wa mada hitori de okyakusama no taiō o sasemasen."},{"fr":"Laissez-moi m'occuper de ce travail, s'il vous plaît.","tgt":"その仕事、私にやらせてください。","ro":"Sono shigoto, watashi ni yarasete kudasai."},{"fr":"Désolé de t'avoir fait attendre si longtemps devant la gare.","tgt":"駅の前で長い間待たせてごめんね。","ro":"Eki no mae de nagai aida matasete gomen ne."},{"fr":"J'ai fait rire toute l'équipe avec une blague.","tgt":"冗談を言って、チームのみんなを笑わせました。","ro":"Jōdan o itte, chīmu no minna o warawasemashita."},{"fr":"Je ne veux pas l'inquiéter pour rien.","tgt":"余計な心配をさせたくないです。","ro":"Yokei na shinpai o sasetaku nai desu."},{"fr":"Laissez-moi y réfléchir jusqu'à demain.","tgt":"明日まで考えさせてください。","ro":"Ashita made kangaesasete kudasai."}],"tip":{"title":"Le causatif : faire faire, laisser faire","example":"Laissez-moi m'occuper de ce travail, s'il vous plaît. — その仕事、私に<b>やらせて</b>ください。","body":"Pour dire qu'on fait faire ou qu'on laisse faire quelque chose à quelqu'un, on ajoute « -saseru » ou « -aseru » au verbe : « taberu » devient « tabesaseru », « kaku » (écrire) devient « kakaseru », et « suru » devient « saseru ». La personne qu'on fait agir est suivie de « ni » : « shinjin ni kopī o sasemasu », je fais faire les photocopies au nouveau. Le même verbe veut dire faire faire ou laisser faire, et seul le contexte tranche. Suivi de « kudasai », il devient une demande très polie : « yarasete kudasai » se dit littéralement : faire-laisser, s'il vous plaît, donc laissez-moi le faire. Retenez aussi « kangaesasete kudasai », laissez-moi réfléchir, parfait pour gagner du temps en réunion. Astuce : quand vous entendez « -sase- » au milieu d'un verbe, c'est que quelqu'un tire les ficelles.","exampleRo":"Sono shigoto, watashi ni yarasete kudasai.","lit":"ce · travail · moi · [à] · laisser faire · s'il vous plaît","say":{"taberu":"食べる","tabesaseru":"食べさせる","kaku":"書く","kakaseru":"書かせる","suru":"する","saseru":"させる","ni":"に","shinjin ni kopī o sasemasu":"新人にコピーをさせます","kudasai":"ください","yarasete kudasai":"やらせてください","kangaesasete kudasai":"考えさせてください","-saseru":"させる"}}},{"title":"Le nomikai de l'équipe","phrases":[{"fr":"Vendredi soir, il y a un nomikai avec toute l'équipe.","tgt":"金曜日の夜、チームの飲み会があります。","ro":"Kin'yōbi no yoru, chīmu no nomikai ga arimasu."},{"fr":"Au début, on attend que tout le monde soit servi pour trinquer.","tgt":"最初は、全員の飲み物がそろうまで乾杯を待ちます。","ro":"Saisho wa, zen'in no nomimono ga sorou made kanpai o machimasu."},{"fr":"On ne se sert pas soi-même, on remplit le verre des autres.","tgt":"自分のグラスには注がないで、ほかの人のグラスに注ぎます。","ro":"Jibun no gurasu ni wa tsuganaide, hoka no hito no gurasu ni tsugimasu."},{"fr":"Quand le verre du directeur est vide, il faut le remarquer tout de suite.","tgt":"部長のグラスが空になったら、すぐに気づかないといけません。","ro":"Buchō no gurasu ga kara ni nattara, sugu ni kizukanai to ikemasen."},{"fr":"Ce soir, on oublie la hiérarchie, alors parlons sans gêne.","tgt":"今夜は無礼講だから、気楽に話そう。","ro":"Kon'ya wa bureikō dakara, kiraku ni hanasō."},{"fr":"Je ne peux pas boire d'alcool, je prendrai un thé oolong.","tgt":"お酒は飲めないので、ウーロン茶にします。","ro":"Osake wa nomenai node, ūroncha ni shimasu."},{"fr":"Tu viens au karaoké pour la deuxième partie de soirée ?","tgt":"二次会のカラオケ、来る？","ro":"Nijikai no karaoke, kuru?"},{"fr":"Désolé, il faut que j'attrape le dernier train.","tgt":"ごめん、終電に乗らなきゃ。","ro":"Gomen, shūden ni noranakya."},{"fr":"Le lendemain, personne ne reparle de ce qui s'est dit à table.","tgt":"次の日は、飲み会で言ったことをだれも話題にしません。","ro":"Tsugi no hi wa, nomikai de itta koto o dare mo wadai ni shimasen."},{"fr":"Chef, merci de nous avoir invités hier soir.","tgt":"部長、昨日はごちそうさまでした。","ro":"Buchō, kinō wa gochisōsama deshita."}]},{"title":"Chercher un appartement","phrases":[{"fr":"Si on s'éloigne un peu du centre, les loyers baissent beaucoup.","tgt":"都心から少し離れれば、家賃がずいぶん安くなります。","ro":"Toshin kara sukoshi hanarereba, yachin ga zuibun yasuku narimasu."},{"fr":"Plus c'est près de la gare, mieux c'est.","tgt":"駅から近ければ近いほどいいです。","ro":"Eki kara chikakereba chikai hodo ii desu."},{"fr":"Si possible, j'aimerais un logement orienté au sud.","tgt":"できれば、南向きの部屋がいいです。","ro":"Dekireba, minamimuki no heya ga ii desu."},{"fr":"Si vous avez un garant, les formalités sont plus simples.","tgt":"保証人がいれば、手続きが簡単になります。","ro":"Hoshōnin ga ireba, tetsuzuki ga kantan ni narimasu."},{"fr":"Avec la caution et le « reikin », combien dois-je payer au départ ?","tgt":"敷金と礼金を合わせると、最初にいくら払えばいいですか。","ro":"Shikikin to reikin o awaseru to, saisho ni ikura haraeba ii desu ka."},{"fr":"Le « reikin » est un remerciement au propriétaire, et il n'est jamais rendu.","tgt":"礼金は大家さんへのお礼で、返ってきません。","ro":"Reikin wa ōya-san e no orei de, kaette kimasen."},{"fr":"Tant qu'on n'a pas visité, on ne peut rien savoir.","tgt":"実際に見なければ、わかりません。","ro":"Jissai ni minakereba, wakarimasen."},{"fr":"Si tu veux, je t'accompagne à l'agence immobilière samedi.","tgt":"よければ、土曜日に不動産屋に一緒に行くよ。","ro":"Yokereba, doyōbi ni fudōsan'ya ni issho ni iku yo."},{"fr":"Ce studio est petit, mais il suffit pour vivre seul.","tgt":"この部屋は狭いけど、一人暮らしなら十分です。","ro":"Kono heya wa semai kedo, hitorigurashi nara jūbun desu."},{"fr":"Si on signe cette semaine, on pourra emménager le mois prochain.","tgt":"今週契約すれば、来月引っ越せます。","ro":"Konshū keiyaku sureba, raigetsu hikkosemasu."}],"tip":{"title":"« -ba » : la condition, si","example":"Si vous avez un garant, les formalités sont plus simples. — 保証人が<b>いれば</b>、手続きが簡単になります。","body":"Pour dire si, le japonais a plusieurs outils, et « -ba » exprime une condition logique : si A se réalise, alors B suit naturellement. On le forme en remplaçant le « u » final du verbe par « eba » : « iku » devient « ikeba », « iru » devient « ireba », et « suru » devient « sureba ». Pour les adjectifs en « -i », on utilise « -kereba » : « yasui » devient « yasukereba », si c'est bon marché. Notre exemple, « hoshōnin ga ireba », se lit : garant, sujet, s'il y a. Retenez deux formules très utiles au quotidien : « dō sureba ii desu ka », que dois-je faire, et « dekireba », si possible. Astuce : « -ba » regarde vers la suite, on l'emploie quand la condition ouvre la porte au résultat.","exampleRo":"Hoshōnin ga ireba, tetsuzuki ga kantan ni narimasu.","lit":"garant · [sujet] · s'il y a · formalités · [sujet] · simple · devenir (poli)","say":{"iku":"行く","ikeba":"行けば","iru":"いる","ireba":"いれば","suru":"する","sureba":"すれば","yasui":"安い","yasukereba":"安ければ","hoshōnin ga ireba":"保証人がいれば","dō sureba ii desu ka":"どうすればいいですか","dekireba":"できれば","-kereba":"ければ"}}},{"title":"Signer le contrat de location","phrases":[{"fr":"Avant de signer, lisez bien tout le contrat.","tgt":"契約する前に、契約書の内容をよく読んでください。","ro":"Keiyaku suru mae ni, keiyakusho no naiyō o yoku yonde kudasai."},{"fr":"Les animaux sont interdits dans cette résidence.","tgt":"このマンションはペット禁止です。","ro":"Kono manshon wa petto kinshi desu."},{"fr":"Le contrat dure deux ans, et le renouvellement entraîne des frais.","tgt":"契約は二年で、更新するときに更新料がかかります。","ro":"Keiyaku wa ninen de, kōshin suru toki ni kōshinryō ga kakarimasu."},{"fr":"Il faut aussi souscrire une assurance incendie.","tgt":"火災保険にも入らなければなりません。","ro":"Kasai hoken ni mo hairanakereba narimasen."},{"fr":"Où dois-je apposer mon sceau ?","tgt":"どこにはんこを押せばいいですか。","ro":"Doko ni hanko o oseba ii desu ka."},{"fr":"Si vous n'avez pas de sceau, une signature suffit.","tgt":"はんこがなければ、サインでも大丈夫です。","ro":"Hanko ga nakereba, sain demo daijōbu desu."},{"fr":"Pour partir, il faut prévenir un mois à l'avance.","tgt":"退去するときは、一か月前に連絡する必要があります。","ro":"Taikyo suru toki wa, ikkagetsu mae ni renraku suru hitsuyō ga arimasu."},{"fr":"Les réparations des murs abîmés seront retenues sur la caution.","tgt":"壁の傷の修理代は、敷金から引かれます。","ro":"Kabe no kizu no shūridai wa, shikikin kara hikaremasu."},{"fr":"Les charges communes sont-elles comprises dans le loyer ?","tgt":"共益費は家賃に含まれていますか。","ro":"Kyōekihi wa yachin ni fukumarete imasu ka."},{"fr":"Nous vous remettrons les clés le jour de l'emménagement.","tgt":"鍵は入居日にお渡しします。","ro":"Kagi wa nyūkyobi ni owatashi shimasu."}]},{"title":"Le jour du déménagement","phrases":[{"fr":"Les déménageurs arrivent à huit heures du matin.","tgt":"引っ越し業者は朝八時に来ます。","ro":"Hikkoshi gyōsha wa asa hachiji ni kimasu."},{"fr":"J'ai écrit le nom de la pièce sur chaque carton.","tgt":"段ボールには全部、部屋の名前を書いておきました。","ro":"Danbōru ni wa zenbu, heya no namae o kaite okimashita."},{"fr":"Attention, ce carton-là contient de la vaisselle fragile.","tgt":"気をつけて。その箱には割れやすい食器が入っています。","ro":"Ki o tsukete. Sono hako ni wa wareyasui shokki ga haitte imasu."},{"fr":"Le frigo ne passe pas par la porte d'entrée.","tgt":"冷蔵庫が玄関から入りません。","ro":"Reizōko ga genkan kara hairimasen."},{"fr":"Il n'y a plus qu'à le hisser par la fenêtre avec une corde.","tgt":"窓からロープでつり上げるしかないですね。","ro":"Mado kara rōpu de tsuriageru shika nai desu ne."},{"fr":"N'oublie pas de faire couper le gaz dans l'ancien logement.","tgt":"前の部屋のガスを止めるのを忘れないで。","ro":"Mae no heya no gasu o tomeru no o wasurenaide."},{"fr":"Pour ouvrir le gaz, il faut être là quand le technicien passe.","tgt":"ガスの開栓には、係の人の立ち会いが必要です。","ro":"Gasu no kaisen ni wa, kakari no hito no tachiai ga hitsuyō desu."},{"fr":"Pour se présenter, on offre une petite serviette aux voisins.","tgt":"近所の人に、あいさつの品としてタオルを渡します。","ro":"Kinjo no hito ni, aisatsu no shina to shite taoru o watashimasu."},{"fr":"Bonjour, je viens d'emménager juste au-dessus de chez vous.","tgt":"こんにちは。真上の部屋に引っ越してきた者です。","ro":"Konnichiwa. Maue no heya ni hikkoshite kita mono desu."},{"fr":"Le soir, on a mangé des soba de déménagement, comme le veut la tradition.","tgt":"夜は、伝統どおり引っ越しそばを食べました。","ro":"Yoru wa, dentō dōri hikkoshi soba o tabemashita."}]},{"title":"Une semaine de maladresses","phrases":[{"fr":"J'ai encore oublié mon parapluie dans le train ce matin.","tgt":"今朝、また電車に傘を忘れてしまいました。","ro":"Kesa, mata densha ni kasa o wasurete shimaimashita."},{"fr":"Je me suis trompé et j'ai sorti les bouteilles en plastique le mauvais jour.","tgt":"間違えて、違う日にペットボトルを出してしまいました。","ro":"Machigaete, chigau hi ni pettobotoru o dashite shimaimashita."},{"fr":"On a collé un papier d'avertissement sur mon sac poubelle.","tgt":"ごみ袋に注意の紙を貼られてしまいました。","ro":"Gomibukuro ni chūi no kami o hararete shimaimashita."},{"fr":"Je me suis endormi dans le train et j'ai dépassé ma station.","tgt":"電車で寝てしまって、駅を乗り過ごしました。","ro":"Densha de nete shimatte, eki o norisugoshimashita."},{"fr":"J'ai mangé tout le gâteau à moi tout seul.","tgt":"ケーキを一人で全部食べちゃった。","ro":"Kēki o hitori de zenbu tabechatta."},{"fr":"Zut, j'ai effacé le fichier sans l'enregistrer.","tgt":"しまった、保存しないでファイルを消しちゃった。","ro":"Shimatta, hozon shinaide fairu o keshichatta."},{"fr":"Je suis vraiment désolé d'avoir cassé votre précieuse tasse.","tgt":"大切なカップを割ってしまって、本当に申し訳ありません。","ro":"Taisetsu na kappu o watte shimatte, hontō ni mōshiwake arimasen."},{"fr":"Au nomikai, j'ai fini par dire des choses que j'aurais dû taire.","tgt":"飲み会で、言わなくてもいいことを言ってしまいました。","ro":"Nomikai de, iwanakute mo ii koto o itte shimaimashita."},{"fr":"J'ai liquidé tous mes dossiers avant midi.","tgt":"昼までに、書類を全部片付けてしまいました。","ro":"Hiru made ni, shorui o zenbu katazukete shimaimashita."},{"fr":"À force de vivre ici, j'ai fini par m'habituer aux trains bondés.","tgt":"ここに住んでいるうちに、満員電車に慣れてしまいました。","ro":"Koko ni sunde iru uchi ni, man'in densha ni narete shimaimashita."}],"tip":{"title":"« -te shimau » : finir par, le regret","example":"J'ai encore oublié mon parapluie dans le train ce matin. — 今朝、また電車に傘を<b>忘れてしまいました</b>。","body":"En ajoutant « shimau » après la forme en « -te », on dit qu'une action est complètement terminée, ou qu'elle est arrivée malgré nous, avec une pointe de regret. « Wasureru » (oublier) devient ainsi « wasurete shimaimashita », j'ai bel et bien oublié, et zut. Notre exemple se décompose ainsi : ce matin, encore, train, dans, parapluie, objet, oublier pour de bon. Entre amis, la forme se contracte en « -chau » : « tabechatta », j'ai tout mangé, ou « keshichatta », je l'ai effacé par erreur. Le même outil sert aussi à dire qu'on a fini quelque chose d'un coup : « zenbu katazukete shimaimashita », j'ai tout liquidé. Astuce : pensez au cri « shimatta », oups, c'est exactement le même verbe.","exampleRo":"Kesa, mata densha ni kasa o wasurete shimaimashita.","lit":"ce matin · encore · train · [lieu] · parapluie · [objet] · oublier-finir par (poli, passé)","say":{"shimau":"しまう","Wasureru":"忘れる","wasurete shimaimashita":"忘れてしまいました","tabechatta":"食べちゃった","keshichatta":"消しちゃった","zenbu katazukete shimaimashita":"全部片付けてしまいました","shimatta":"しまった","-te shimau":"てしまう"}}},{"title":"L'assurance santé nationale","phrases":[{"fr":"Toute personne qui vit au Japon doit s'affilier à une assurance santé.","tgt":"日本に住む人は全員、健康保険に入らなければなりません。","ro":"Nihon ni sumu hito wa zen'in, kenkō hoken ni hairanakereba narimasen."},{"fr":"Avec l'assurance, on ne paie que trente pour cent des frais médicaux.","tgt":"保険があれば、医療費は三割負担で済みます。","ro":"Hoken ga areba, iryōhi wa sanwari futan de sumimasu."},{"fr":"Les salariés sont couverts par l'assurance de leur entreprise.","tgt":"会社員は会社の健康保険に加入しています。","ro":"Kaishain wa kaisha no kenkō hoken ni kanyū shite imasu."},{"fr":"Les indépendants, eux, cotisent à l'assurance santé nationale.","tgt":"自営業の人は国民健康保険に入ります。","ro":"Jieigyō no hito wa kokumin kenkō hoken ni hairimasu."},{"fr":"Ma carte d'assuré est arrivée par la poste.","tgt":"保険証が郵便で届きました。","ro":"Hokenshō ga yūbin de todokimashita."},{"fr":"N'oubliez pas de montrer votre carte d'assuré à l'accueil.","tgt":"受付で保険証を見せるのを忘れないでください。","ro":"Uketsuke de hokenshō o miseru no o wasurenaide kudasai."},{"fr":"La cotisation est calculée d'après les revenus de l'année précédente.","tgt":"保険料は前の年の収入をもとに計算されます。","ro":"Hokenryō wa mae no toshi no shūnyū o moto ni keisan saremasu."},{"fr":"Si les frais médicaux deviennent très élevés, une partie est remboursée.","tgt":"医療費が高額になったら、一部が戻ってきます。","ro":"Iryōhi ga kōgaku ni nattara, ichibu ga modotte kimasu."},{"fr":"Est-ce que ce traitement est pris en charge par l'assurance ?","tgt":"この治療は保険がききますか。","ro":"Kono chiryō wa hoken ga kikimasu ka."},{"fr":"Grâce à ce système, on peut aller à l'hôpital l'esprit tranquille.","tgt":"この制度のおかげで、安心して病院に行けます。","ro":"Kono seido no okage de, anshin shite byōin ni ikemasu."}]},{"title":"Les déchets et la vie de voisinage","phrases":[{"fr":"Dans mon quartier, on trie les déchets en cinq catégories.","tgt":"私の地域では、ごみを五種類に分けます。","ro":"Watashi no chiiki de wa, gomi o goshurui ni wakemasu."},{"fr":"Les déchets combustibles sont ramassés le mardi et le vendredi.","tgt":"燃えるごみは火曜日と金曜日に回収されます。","ro":"Moeru gomi wa kayōbi to kin'yōbi ni kaishū saremasu."},{"fr":"Il faut sortir les poubelles avant huit heures et demie du matin.","tgt":"ごみは朝八時半までに出さなければなりません。","ro":"Gomi wa asa hachiji han made ni dasanakereba narimasen."},{"fr":"Pour jeter un gros objet, il faut acheter un autocollant payant.","tgt":"粗大ごみを出すには、有料のシールが必要です。","ro":"Sodai gomi o dasu ni wa, yūryō no shīru ga hitsuyō desu."},{"fr":"La personne d'en dessous m'a dit que mes pas faisaient trop de bruit.","tgt":"下の階の人から、足音がうるさいと言われました。","ro":"Shita no kai no hito kara, ashioto ga urusai to iwaremashita."},{"fr":"Depuis, je fais attention à marcher doucement le soir.","tgt":"それからは、夜は静かに歩くようにしています。","ro":"Sore kara wa, yoru wa shizuka ni aruku yō ni shite imasu."},{"fr":"Les annonces du quartier circulent sur un carnet que les voisins se passent.","tgt":"回覧板で、町内のお知らせが回ってきます。","ro":"Kairanban de, chōnai no oshirase ga mawatte kimasu."},{"fr":"Une fois que je l'ai lu, je le passe à la maison d'à côté.","tgt":"読んだら、隣の家に回します。","ro":"Yondara, tonari no ie ni mawashimasu."},{"fr":"Dimanche prochain, il y a un grand nettoyage du quartier.","tgt":"今度の日曜日、町内の清掃活動があります。","ro":"Kondo no nichiyōbi, chōnai no seisō katsudō ga arimasu."},{"fr":"On se salue toujours quand on se croise dans l'ascenseur, c'est agréable.","tgt":"エレベーターで会うと、いつもあいさつし合うので気持ちがいいです。","ro":"Erebētā de au to, itsumo aisatsu shiau node kimochi ga ii desu."}]},{"title":"Se préparer aux séismes","phrases":[{"fr":"Au Japon, il y a un séisme quelque part presque chaque jour.","tgt":"日本ではほぼ毎日、どこかで地震が起きています。","ro":"Nihon de wa hobo mainichi, doko ka de jishin ga okite imasu."},{"fr":"Fixez les grands meubles au mur pour qu'ils ne tombent pas.","tgt":"大きな家具は倒れないように壁に固定してください。","ro":"Ōkina kagu wa taorenai yō ni kabe ni kotei shite kudasai."},{"fr":"Gardons à la maison de l'eau et de la nourriture pour trois jours.","tgt":"家に三日分の水と食料を用意しておきましょう。","ro":"Ie ni mikkabun no mizu to shokuryō o yōi shite okimashō."},{"fr":"Je garde un sac d'urgence près de l'entrée.","tgt":"玄関の近くに非常用持ち出し袋を置いています。","ro":"Genkan no chikaku ni hijōyō mochidashi bukuro o oite imasu."},{"fr":"Si ça secoue, protège d'abord ta tête sous une table.","tgt":"揺れたら、まず机の下で頭を守って。","ro":"Yuretara, mazu tsukue no shita de atama o mamotte."},{"fr":"Pendant que ça tremble, ne te précipite pas dehors.","tgt":"揺れている間は、慌てて外に出ないで。","ro":"Yurete iru aida wa, awatete soto ni denaide."},{"fr":"Où se trouve le lieu d'évacuation de ce quartier ?","tgt":"この地域の避難場所はどこですか。","ro":"Kono chiiki no hinan basho wa doko desu ka."},{"fr":"Le portable reçoit une alerte quelques secondes avant la secousse.","tgt":"揺れる数秒前に、携帯に緊急地震速報が届きます。","ro":"Yureru sūbyō mae ni, keitai ni kinkyū jishin sokuhō ga todokimasu."},{"fr":"Au bureau, il y a un exercice d'évacuation chaque année en septembre.","tgt":"会社では毎年九月に避難訓練があります。","ro":"Kaisha de wa maitoshi kugatsu ni hinan kunren ga arimasu."},{"fr":"Si l'on s'est préparé, on ne panique pas le moment venu.","tgt":"準備しておけば、いざというときも慌てずに済みます。","ro":"Junbi shite okeba, iza to iu toki mo awatezu ni sumimasu."}]},{"title":"Recevoir un client au bureau","phrases":[{"fr":"Je m'appelle Martin, du service commercial.","tgt":"営業部のマルタンと申します。","ro":"Eigyōbu no Marutan to mōshimasu."},{"fr":"Nous vous attendions, merci d'être venu de si loin.","tgt":"お待ちしておりました。遠いところをありがとうございます。","ro":"Omachi shite orimashita. Tōi tokoro o arigatō gozaimasu."},{"fr":"Je vous conduis à la salle de réunion.","tgt":"会議室へご案内いたします。","ro":"Kaigishitsu e goannai itashimasu."},{"fr":"Je vais chercher le responsable tout de suite.","tgt":"ただいま担当者を呼んでまいります。","ro":"Tadaima tantōsha o yonde mairimasu."},{"fr":"Je vous apporte du thé.","tgt":"お茶をお持ちいたします。","ro":"Ocha o omochi itashimasu."},{"fr":"Je vous enverrai le devis demain sans faute.","tgt":"明日、必ず見積書をお送りいたします。","ro":"Ashita, kanarazu mitsumorisho o ookuri itashimasu."},{"fr":"La semaine prochaine, c'est moi qui viendrai dans vos locaux.","tgt":"来週、御社へまいります。","ro":"Raishū, onsha e mairimasu."},{"fr":"Je viens de France, et je travaille ici depuis trois ans.","tgt":"フランスからまいりました。こちらで三年働いております。","ro":"Furansu kara mairimashita. Kochira de sannen hataraite orimasu."},{"fr":"Merci de toujours nous faire confiance.","tgt":"いつもお世話になっております。","ro":"Itsumo osewa ni natte orimasu."},{"fr":"Je compte sur vous pour la suite de notre collaboration.","tgt":"今後ともよろしくお願いいたします。","ro":"Kongo tomo yoroshiku onegai itashimasu."}],"tip":{"title":"Le langage humble : « itashimasu », « mairimasu »","example":"Je vais chercher le responsable tout de suite. — ただいま担当者を呼んで<b>まいります</b>。","body":"Au niveau 2, vous avez vu le langage de respect, qui élève l'autre ; le langage humble fait l'inverse : on s'abaisse soi-même pour honorer son interlocuteur. On l'utilise uniquement pour ses propres actions, ou celles de son entreprise face à un client. « Suru » (faire) devient « itasu », d'où « itashimasu », et « iku » ou « kuru » (aller, venir) deviennent « mairu », d'où « mairimasu ». Notre exemple, « yonde mairimasu », se lit : appeler, aller humblement, autrement dit je vais le chercher. Avec « o » ou « go » devant un nom d'action, on obtient des formules toutes faites : « goannai itashimasu », je vous guide, ou « ookuri itashimasu », je vous l'envoie. Astuce : si c'est vous qui agissez face à un client, pensez humble ; si c'est lui, pensez respect.","exampleRo":"Tadaima tantōsha o yonde mairimasu.","lit":"à l'instant · responsable · [objet] · appeler · aller (humble, poli)","say":{"itashimasu":"いたします","mairimasu":"まいります","Suru":"する","itasu":"いたす","iku":"行く","kuru":"くる","mairu":"まいる","yonde mairimasu":"呼んでまいります","goannai itashimasu":"ご案内いたします","ookuri itashimasu":"お送りいたします"}}},{"title":"Les trains bondés aux heures de pointe","phrases":[{"fr":"Entre huit et neuf heures, les trains sont pleins à craquer.","tgt":"八時から九時の間は、電車がぎゅうぎゅう詰めです。","ro":"Hachiji kara kuji no aida wa, densha ga gyūgyūzume desu."},{"fr":"Il arrive que le personnel pousse les passagers pour fermer les portes.","tgt":"駅員が乗客を押して、ドアを閉めることもあります。","ro":"Ekiin ga jōkyaku o oshite, doa o shimeru koto mo arimasu."},{"fr":"Porte ton sac à dos devant toi, s'il te plaît.","tgt":"リュックは前に抱えてね。","ro":"Ryukku wa mae ni kakaete ne."},{"fr":"Dans le train, la règle est de ne pas téléphoner.","tgt":"電車の中では電話で話さないのがマナーです。","ro":"Densha no naka de wa denwa de hanasanai no ga manā desu."},{"fr":"Le matin, il y a des voitures réservées aux femmes.","tgt":"朝は、女性専用車両があります。","ro":"Asa wa, josei sen'yō sharyō ga arimasu."},{"fr":"Le train est en retard à cause d'un accident de personne.","tgt":"人身事故で電車が遅れています。","ro":"Jinshin jiko de densha ga okurete imasu."},{"fr":"Dans ce cas, on peut obtenir un certificat de retard à la gare.","tgt":"その場合、駅で遅延証明書がもらえます。","ro":"Sono baai, eki de chien shōmeisho ga moraemasu."},{"fr":"Si je le montre à mon chef, mon retard n'est pas compté.","tgt":"それを上司に見せれば、遅刻扱いになりません。","ro":"Sore o jōshi ni misereba, chikoku atsukai ni narimasen."},{"fr":"Comme je veux être assis, je m'efforce de partir un peu plus tôt.","tgt":"座りたいので、少し早く家を出るようにしています。","ro":"Suwaritai node, sukoshi hayaku ie o deru yō ni shite imasu."},{"fr":"Avec le temps, on finit par savoir dormir debout dans le train.","tgt":"そのうち、立ったまま電車で寝られるようになります。","ro":"Sono uchi, tatta mama densha de nerareru yō ni narimasu."}]},{"title":"Le télétravail","phrases":[{"fr":"Depuis cette année, je travaille de chez moi deux jours par semaine.","tgt":"今年から、週に二日在宅勤務をしています。","ro":"Kotoshi kara, shū ni futsuka zaitaku kinmu o shite imasu."},{"fr":"Je gagne près de deux heures de trajet par jour.","tgt":"通勤時間が一日二時間近く浮きます。","ro":"Tsūkin jikan ga ichinichi nijikan chikaku ukimasu."},{"fr":"Mais mon logement est trop petit pour un vrai coin bureau.","tgt":"でも、部屋が狭くて、ちゃんとした仕事スペースがありません。","ro":"Demo, heya ga semakute, chanto shita shigoto supēsu ga arimasen."},{"fr":"Parfois, je travaille dans un café près de chez moi.","tgt":"時々、近所のカフェで仕事をします。","ro":"Tokidoki, kinjo no kafe de shigoto o shimasu."},{"fr":"Ta caméra est éteinte, on ne voit pas ton visage.","tgt":"カメラがオフになってるよ。顔が見えない。","ro":"Kamera ga ofu ni natteru yo. Kao ga mienai."},{"fr":"Pardon, il semble que mon micro était coupé.","tgt":"すみません、マイクがミュートになっていたみたいです。","ro":"Sumimasen, maiku ga myūto ni natte ita mitai desu."},{"fr":"La connexion est instable, je vous rappelle.","tgt":"接続が不安定なので、かけ直します。","ro":"Setsuzoku ga fuantei na node, kakenaoshimasu."},{"fr":"Il paraît que le directeur veut nous voir au bureau le lundi.","tgt":"部長は、月曜日は出社してほしいそうです。","ro":"Buchō wa, getsuyōbi wa shussha shite hoshii sō desu."},{"fr":"Pour bien séparer travail et repos, je m'habille comme pour aller au bureau.","tgt":"メリハリをつけるために、出社するときと同じ服を着ます。","ro":"Merihari o tsukeru tame ni, shussha suru toki to onaji fuku o kimasu."},{"fr":"Le plus difficile, c'est d'arrêter de travailler le soir.","tgt":"一番難しいのは、夜に仕事をやめることです。","ro":"Ichiban muzukashii no wa, yoru ni shigoto o yameru koto desu."}]},{"title":"Les démarches à la mairie","phrases":[{"fr":"Après un déménagement, il faut déclarer son arrivée sous quatorze jours.","tgt":"引っ越したら、十四日以内に転入届を出さなければなりません。","ro":"Hikkoshitara, jūyokka inai ni tennyū todoke o dasanakereba narimasen."},{"fr":"J'ai pris un ticket et j'attends qu'on appelle mon numéro.","tgt":"番号札を取って、呼ばれるのを待っています。","ro":"Bangōfuda o totte, yobareru no o matte imasu."},{"fr":"Remplissez ce formulaire et déposez-le au guichet numéro trois.","tgt":"この用紙に記入して、三番の窓口に出してください。","ro":"Kono yōshi ni kinyū shite, sanban no madoguchi ni dashite kudasai."},{"fr":"La banque me demande un certificat de résidence.","tgt":"銀行に出すので、住民票が必要です。","ro":"Ginkō ni dasu node, jūminhyō ga hitsuyō desu."},{"fr":"Avec la carte My Number, on peut aussi l'imprimer au konbini.","tgt":"マイナンバーカードがあれば、コンビニでも印刷できます。","ro":"Mai nanbā kādo ga areba, konbini demo insatsu dekimasu."},{"fr":"Il faut aussi faire changer l'adresse sur la carte de séjour.","tgt":"在留カードの住所も変えてもらう必要があります。","ro":"Zairyū kādo no jūsho mo kaete morau hitsuyō ga arimasu."},{"fr":"Qu'est-ce que je dois apporter, exactement ?","tgt":"何を持ってくればいいですか。","ro":"Nani o motte kureba ii desu ka."},{"fr":"Ce guichet ferme à cinq heures et quart de l'après-midi.","tgt":"この窓口は午後五時十五分に閉まります。","ro":"Kono madoguchi wa gogo goji jūgofun ni shimarimasu."},{"fr":"Il manquait un tampon, alors j'ai dû revenir une deuxième fois.","tgt":"はんこが足りなくて、もう一度来なければなりませんでした。","ro":"Hanko ga tarinakute, mō ichido konakereba narimasen deshita."},{"fr":"Les démarches sont longues, mais les agents sont très aimables.","tgt":"手続きは時間がかかりますが、職員の方はとても親切です。","ro":"Tetsuzuki wa jikan ga kakarimasu ga, shokuin no kata wa totemo shinsetsu desu."}]},{"title":"Le bilan de santé annuel","phrases":[{"fr":"Chaque année, l'entreprise fait passer un bilan de santé à ses employés.","tgt":"毎年、会社が社員に健康診断を受けさせます。","ro":"Maitoshi, kaisha ga shain ni kenkō shindan o ukesasemasu."},{"fr":"La veille, il ne faut rien manger après neuf heures du soir.","tgt":"前の日の夜九時以降は、何も食べてはいけません。","ro":"Mae no hi no yoru kuji ikō wa, nani mo tabete wa ikemasen."},{"fr":"On mesure la taille, le poids et le tour de ventre.","tgt":"身長と体重と腹囲を測ります。","ro":"Shinchō to taijū to fukui o hakarimasu."},{"fr":"La prise de sang m'a fait un peu peur.","tgt":"採血がちょっと怖かったです。","ro":"Saiketsu ga chotto kowakatta desu."},{"fr":"Pour l'examen de l'estomac, il faut avaler du baryum.","tgt":"胃の検査では、バリウムを飲まなければなりません。","ro":"I no kensa de wa, bariumu o nomanakereba narimasen."},{"fr":"Les résultats nous sont envoyés un mois plus tard.","tgt":"結果は一か月後に送られてきます。","ro":"Kekka wa ikkagetsu go ni okurarete kimasu."},{"fr":"Le médecin m'a dit de faire davantage de sport.","tgt":"医者に、もっと運動するように言われました。","ro":"Isha ni, motto undō suru yō ni iwaremashita."},{"fr":"Mon taux de cholestérol est un peu élevé.","tgt":"コレステロールの値が少し高いです。","ro":"Koresuterōru no atai ga sukoshi takai desu."},{"fr":"Si rien ne change, il faudra peut-être refaire un examen.","tgt":"このままだと、再検査が必要になるかもしれません。","ro":"Kono mama da to, saikensa ga hitsuyō ni naru kamoshiremasen."},{"fr":"À partir de demain, j'irai à pied jusqu'à la gare suivante.","tgt":"明日から、一つ先の駅まで歩くことにします。","ro":"Ashita kara, hitotsu saki no eki made aruku koto ni shimasu."}]},{"title":"La banque et les factures","phrases":[{"fr":"Pour ouvrir un compte, il faut une adresse et un numéro de téléphone.","tgt":"口座を開くには、住所と電話番号が必要です。","ro":"Kōza o hiraku ni wa, jūsho to denwa bangō ga hitsuyō desu."},{"fr":"Certaines banques refusent d'ouvrir un compte avant six mois de résidence.","tgt":"日本に住んで六か月たたないと、口座を作れない銀行もあります。","ro":"Nihon ni sunde rokkagetsu tatanai to, kōza o tsukurenai ginkō mo arimasu."},{"fr":"Mon salaire est versé le vingt-cinq de chaque mois.","tgt":"給料は毎月二十五日に振り込まれます。","ro":"Kyūryō wa maitsuki nijūgonichi ni furikomaremasu."},{"fr":"On peut régler la facture d'électricité au konbini.","tgt":"電気代はコンビニで払えます。","ro":"Denkidai wa konbini de haraemasu."},{"fr":"J'ai choisi le prélèvement automatique, c'est plus pratique.","tgt":"口座振替のほうが楽なので、そうしています。","ro":"Kōza furikae no hō ga raku na node, sō shite imasu."},{"fr":"Au Japon, beaucoup de gens paient encore en liquide.","tgt":"日本では、まだ現金を使う人が多いです。","ro":"Nihon de wa, mada genkin o tsukau hito ga ōi desu."},{"fr":"Mais les magasins qui acceptent le paiement par smartphone se multiplient.","tgt":"でも、スマホ決済が使える店もどんどん増えています。","ro":"Demo, sumaho kessai ga tsukaeru mise mo dondon fuete imasu."},{"fr":"En juin, l'avis de l'impôt local arrive dans la boîte aux lettres.","tgt":"六月になると、住民税の通知がポストに届きます。","ro":"Rokugatsu ni naru to, jūminzei no tsūchi ga posuto ni todokimasu."},{"fr":"Pour les salariés, cet impôt est prélevé directement sur le salaire.","tgt":"会社員の場合、この税金は給料から天引きされます。","ro":"Kaishain no baai, kono zeikin wa kyūryō kara tenbiki saremasu."},{"fr":"J'ai enfin compris comment lire ma fiche de paie.","tgt":"やっと給与明細の見方がわかりました。","ro":"Yatto kyūyo meisai no mikata ga wakarimashita."}]},{"title":"La fête du sanctuaire du quartier","phrases":[{"fr":"Ce week-end, il y a une fête au sanctuaire du quartier.","tgt":"今週末、近所の神社でお祭りがあります。","ro":"Konshūmatsu, kinjo no jinja de omatsuri ga arimasu."},{"fr":"Les habitants portent le palanquin sacré à travers les rues.","tgt":"町内の人たちがみこしを担いで、通りを練り歩きます。","ro":"Chōnai no hitotachi ga mikoshi o katsuide, tōri o neriarukimasu."},{"fr":"Cette année, on m'a proposé de le porter avec eux.","tgt":"今年は一緒に担がないかと誘われました。","ro":"Kotoshi wa issho ni katsuganai ka to sasowaremashita."},{"fr":"Il faut porter la veste « happi » du quartier.","tgt":"町内のはっぴを着なければなりません。","ro":"Chōnai no happi o kinakereba narimasen."},{"fr":"Les stands vendent des yakisoba et des pommes d'amour.","tgt":"屋台で焼きそばやりんごあめを売っています。","ro":"Yatai de yakisoba ya ringoame o utte imasu."},{"fr":"Les enfants s'amusent à pêcher des poissons rouges.","tgt":"子どもたちは金魚すくいをしています。","ro":"Kodomotachi wa kingyo sukui o shite imasu."},{"fr":"Tu as mis un yukata ! Il te va vraiment bien.","tgt":"浴衣、着たんだ。よく似合ってるね。","ro":"Yukata, kita n da. Yoku niatteru ne."},{"fr":"C'est l'occasion de parler aux voisins qu'on ne fait que croiser.","tgt":"いつもすれ違うだけの近所の人と話すいい機会です。","ro":"Itsumo surechigau dake no kinjo no hito to hanasu ii kikai desu."},{"fr":"Après la fête, tout le monde aide à ranger.","tgt":"お祭りの後は、みんなで片付けを手伝います。","ro":"Omatsuri no ato wa, minna de katazuke o tetsudaimasu."},{"fr":"J'ai enfin l'impression d'être un vrai habitant de ce quartier.","tgt":"やっと、この町の住人になれた気がします。","ro":"Yatto, kono machi no jūnin ni nareta ki ga shimasu."}]},{"title":"Le pot de départ d'un collègue","phrases":[{"fr":"Monsieur Tanaka est muté à l'agence de Fukuoka.","tgt":"田中さんが福岡支店に転勤することになりました。","ro":"Tanaka-san ga Fukuoka shiten ni tenkin suru koto ni narimashita."},{"fr":"Vendredi soir, nous organisons une soirée d'adieu.","tgt":"金曜日の夜、送別会を開きます。","ro":"Kin'yōbi no yoru, sōbetsukai o hirakimasu."},{"fr":"Chacun a donné mille yens pour lui acheter un cadeau.","tgt":"みんなで千円ずつ出して、プレゼントを買いました。","ro":"Minna de sen'en zutsu dashite, purezento o kaimashita."},{"fr":"On m'a chargé de rassembler les messages pour la carte collective.","tgt":"寄せ書きのメッセージを集める係になりました。","ro":"Yosegaki no messēji o atsumeru kakari ni narimashita."},{"fr":"Grâce à vous, monsieur Tanaka, j'ai appris énormément de choses.","tgt":"田中さんのおかげで、たくさんのことを学びました。","ro":"Tanaka-san no okage de, takusan no koto o manabimashita."},{"fr":"On va vraiment se sentir seuls sans vous.","tgt":"本当に寂しくなります。","ro":"Hontō ni sabishiku narimasu."},{"fr":"Là-bas aussi, prenez bien soin de votre santé.","tgt":"向こうでも体に気をつけてください。","ro":"Mukō demo karada ni ki o tsukete kudasai."},{"fr":"Si jamais vous repassez par Tokyo, faites-nous signe.","tgt":"東京に来ることがあれば、ぜひ連絡してください。","ro":"Tōkyō ni kuru koto ga areba, zehi renraku shite kudasai."},{"fr":"À la fin, monsieur Tanaka a fait un discours très émouvant.","tgt":"最後に、田中さんが感動的なスピーチをしました。","ro":"Saigo ni, Tanaka-san ga kandōteki na supīchi o shimashita."},{"fr":"Au Japon, les mutations font partie de la vie d'un salarié.","tgt":"日本では、転勤は会社員の生活の一部です。","ro":"Nihon de wa, tenkin wa kaishain no seikatsu no ichibu desu."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait entrer dans la vie d'adulte à Tokyo.","tgt":"このモジュールでは、東京での大人の生活を体験しました。","ro":"Kono mojūru de wa, Tōkyō de no otona no seikatsu o taiken shimashita."},{"fr":"On sait maintenant parler du travail, du logement et des démarches.","tgt":"仕事や住まい、手続きについて話せるようになりました。","ro":"Shigoto ya sumai, tetsuzuki ni tsuite hanaseru yō ni narimashita."},{"fr":"Avec le passif, on peut dire ce qu'on a subi, comme la pluie ou un reproche.","tgt":"受け身を使えば、雨や注意など、自分が受けたことを表せます。","ro":"Ukemi o tsukaeba, ame ya chūi nado, jibun ga uketa koto o arawasemasu."},{"fr":"Avec le causatif, on peut faire faire ou laisser faire quelque chose.","tgt":"使役を使うと、人に何かをさせたり、許したりできます。","ro":"Shieki o tsukau to, hito ni nanika o sasetari, yurushitari dekimasu."},{"fr":"On sait maintenant exprimer une condition avec « -ba ».","tgt":"「ば」を使って、条件を言えるようになりました。","ro":"« Ba » o tsukatte, jōken o ieru yō ni narimashita."},{"fr":"« Shimatta » est peut-être le mot le plus utile au quotidien.","tgt":"「しまった」は、毎日いちばん役に立つ言葉かもしれません。","ro":"« Shimatta » wa, mainichi ichiban yaku ni tatsu kotoba kamoshiremasen."},{"fr":"Le langage humble ne s'apprend pas en un jour.","tgt":"謙譲語は一日で覚えられるものではありません。","ro":"Kenjōgo wa ichinichi de oboerareru mono de wa arimasen."},{"fr":"Le prochain module nous emmènera en voyage à travers le Japon.","tgt":"次のモジュールでは、日本各地を旅します。","ro":"Tsugi no mojūru de wa, Nihon kakuchi o tabi shimasu."},{"fr":"Prenez le temps de réécouter les leçons qui vous ont paru difficiles.","tgt":"難しかったレッスンは、ゆっくり聞き直してください。","ro":"Muzukashikatta ressun wa, yukkuri kikinaoshite kudasai."},{"fr":"Beau travail, on se retrouve dans le prochain module.","tgt":"お疲れさまでした。また次のモジュールで会いましょう。","ro":"Otsukaresama deshita. Mata tsugi no mojūru de aimashō."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Okinawa","phrases":[{"fr":"L'avion vient d'atterrir à Naha, et il fait déjà très chaud.","tgt":"飛行機が那覇に着いたばかりですが、もうとても暑いです。","ro":"Hikōki ga Naha ni tsuita bakari desu ga, mō totemo atsui desu."},{"fr":"Dès la sortie de l'aéroport, l'air sent la mer.","tgt":"空港を出たとたん、海の匂いがします。","ro":"Kūkō o deta totan, umi no nioi ga shimasu."},{"fr":"Okinawa était autrefois un royaume indépendant appelé Ryūkyū.","tgt":"沖縄はかつて琉球という独立した王国でした。","ro":"Okinawa wa katsute Ryūkyū to iu dokuritsu shita ōkoku deshita."},{"fr":"C'est pourquoi la culture locale diffère tant du reste du Japon.","tgt":"だから、地元の文化は日本のほかの地域とずいぶん違います。","ro":"Dakara, jimoto no bunka wa Nihon no hoka no chiiki to zuibun chigaimasu."},{"fr":"Les toits des maisons sont gardés par des lions en terre cuite, les shīsā.","tgt":"家の屋根は、シーサーという焼き物の獅子に守られています。","ro":"Ie no yane wa, shīsā to iu yakimono no shishi ni mamorarete imasu."},{"fr":"On a loué une voiture en se disant qu'on ferait le tour de l'île principale.","tgt":"本島を回ろうと思って、レンタカーを借りました。","ro":"Hontō o mawarō to omotte, rentakā o karimashita."},{"fr":"Au début, la conduite à gauche demande un peu d'attention.","tgt":"左側通行には、最初は少し注意が必要です。","ro":"Hidarigawa tsūkō ni wa, saisho wa sukoshi chūi ga hitsuyō desu."},{"fr":"Les gens d'ici sont connus pour vivre très longtemps.","tgt":"この辺りの人は長生きすることで知られています。","ro":"Kono atari no hito wa nagaiki suru koto de shirarete imasu."},{"fr":"Le rythme de vie semble bien plus lent qu'à Tokyo.","tgt":"生活のリズムは東京よりずっとゆっくりしているようです。","ro":"Seikatsu no rizumu wa Tōkyō yori zutto yukkuri shite iru yō desu."},{"fr":"Ce soir, on dîne dans une petite gargote au bord de la plage.","tgt":"今夜は浜辺の小さな食堂で夕食を食べます。","ro":"Kon'ya wa hamabe no chiisana shokudō de yūshoku o tabemasu."}]},{"title":"Le marché de Makishi","phrases":[{"fr":"Le marché où je suis allé ce matin s'appelle Makishi.","tgt":"今朝行った市場は牧志市場といいます。","ro":"Kesa itta ichiba wa Makishi ichiba to iimasu."},{"fr":"Les poissons qu'on vend ici ont des couleurs incroyables.","tgt":"ここで売っている魚は、信じられないほど色鮮やかです。","ro":"Koko de utte iru sakana wa, shinjirarenai hodo iroazayaka desu."},{"fr":"À l'étage, on peut faire cuisiner le poisson acheté en bas.","tgt":"下の階で買った魚を、上の階で料理してもらえます。","ro":"Shita no kai de katta sakana o, ue no kai de ryōri shite moraemasu."},{"fr":"Le plat que je préfère, c'est le gōyā chanpurū.","tgt":"私がいちばん好きな料理はゴーヤーチャンプルーです。","ro":"Watashi ga ichiban suki na ryōri wa gōyā chanpurū desu."},{"fr":"La dame qui tient ce stand nous a fait goûter du sucre noir.","tgt":"この店をやっているおばさんが、黒糖を味見させてくれました。","ro":"Kono mise o yatte iru obasan ga, kokutō o ajimi sasete kuremashita."},{"fr":"Le vendeur qui parlait vite était difficile à comprendre.","tgt":"早口で話す店員さんの言葉は、聞き取りにくかったです。","ro":"Hayakuchi de hanasu ten'in san no kotoba wa, kikitorinikukatta desu."},{"fr":"Voici la boutique qui vend les meilleurs souvenirs.","tgt":"ここが一番いいお土産を売っている店です。","ro":"Koko ga ichiban ii omiyage o utte iru mise desu."},{"fr":"Les gens qui viennent ici le matin sont surtout des habitants.","tgt":"朝ここに来る人は、ほとんどが地元の人です。","ro":"Asa koko ni kuru hito wa, hotondo ga jimoto no hito desu."},{"fr":"Le restaurant que tu m'avais recommandé était complet.","tgt":"君が勧めてくれた店は満席でした。","ro":"Kimi ga susumete kureta mise wa manseki deshita."},{"fr":"Je n'oublierai jamais le goût de ce que j'ai mangé ici.","tgt":"ここで食べたものの味は、一生忘れません。","ro":"Koko de tabeta mono no aji wa, isshō wasuremasen."}],"tip":{"title":"Les relatives : le verbe placé devant le nom","example":"Les poissons qu'on vend ici ont des couleurs incroyables. — ここで<b>売っている魚</b>は、信じられないほど色鮮やかです。","body":"En japonais, il n'existe pas de mot comme « qui » ou « que » : pour décrire un nom, on place simplement le verbe juste devant lui. « Koko de utte iru sakana » se dit littéralement : ici, en train de vendre, poisson, c'est-à-dire le poisson qu'on vend ici. Le verbe se met à la forme neutre, au présent ou au passé : « kinō katta hon », le livre acheté hier, ou « Naha ni sumu tomodachi », l'ami qui habite à Naha. Si la relative a son propre sujet, il prend « ga » et non « wa » : « watashi ga tsukutta ryōri », le plat que j'ai préparé. Pour retenir, imaginez une étiquette collée devant le nom : tout ce qui décrit vient avant, et le nom arrive toujours en dernier.","exampleRo":"Koko de utte iru sakana wa, shinjirarenai hodo iroazayaka desu.","lit":"ici [lieu] · être en train de vendre · poisson [thème] · incroyable-au point de · coloré · être (poli)","say":{"Koko de utte iru sakana":"ここで売っている魚","kinō katta hon":"昨日買った本","Naha ni sumu tomodachi":"那覇に住む友達","ga":"が","wa":"わ","watashi ga tsukutta ryōri":"私が作った料理"}}},{"title":"Le château de Shuri et les îles Kerama","phrases":[{"fr":"Le château de Shuri domine toute la ville de Naha.","tgt":"首里城は那覇の町全体を見下ろしています。","ro":"Shurijō wa Naha no machi zentai o mioroshite imasu."},{"fr":"Il a malheureusement brûlé en deux mille dix-neuf.","tgt":"残念ながら、二〇一九年に焼けてしまいました。","ro":"Zannen nagara, nisen jūkyū nen ni yakete shimaimashita."},{"fr":"Les travaux de reconstruction se poursuivent encore aujourd'hui.","tgt":"再建工事は今も続いています。","ro":"Saiken kōji wa ima mo tsuzuite imasu."},{"fr":"On peut même regarder les artisans pendant qu'ils travaillent.","tgt":"職人さんが作業しているところも見学できます。","ro":"Shokunin san ga sagyō shite iru tokoro mo kengaku dekimasu."},{"fr":"Le soir, on a écouté un concert de sanshin.","tgt":"夜は三線の演奏を聴きました。","ro":"Yoru wa sanshin no ensō o kikimashita."},{"fr":"Cet instrument à trois cordes est tendu de peau de serpent.","tgt":"この三本弦の楽器には、蛇の皮が張られています。","ro":"Kono sanbongen no gakki ni wa, hebi no kawa ga hararete imasu."},{"fr":"Le musicien nous a appris quelques mots du dialecte d'Okinawa.","tgt":"演奏者が沖縄の方言をいくつか教えてくれました。","ro":"Ensōsha ga Okinawa no hōgen o ikutsu ka oshiete kuremashita."},{"fr":"Ici, « mensōre » veut dire « bienvenue ».","tgt":"「めんそーれ」は、ここでは「ようこそ」という意味です。","ro":"« Mensōre » wa, koko de wa « yōkoso » to iu imi desu."},{"fr":"Le lendemain, on a pris le bateau pour les îles Kerama.","tgt":"翌日、船で慶良間諸島へ渡りました。","ro":"Yokujitsu, fune de Kerama shotō e watarimashita."},{"fr":"L'eau est si claire qu'on voit les tortues depuis le bateau.","tgt":"海がとても透明で、船の上からウミガメが見えます。","ro":"Umi ga totemo tōmei de, fune no ue kara umigame ga miemasu."}]},{"title":"Préparer le Kumano Kodō","phrases":[{"fr":"Pour marcher sur le Kumano Kodō, il faut de bonnes chaussures.","tgt":"熊野古道を歩くためには、いい靴が必要です。","ro":"Kumano Kodō o aruku tame ni wa, ii kutsu ga hitsuyō desu."},{"fr":"Je m'entraîne tous les week-ends pour me faire de l'endurance.","tgt":"体力をつけるために、毎週末トレーニングしています。","ro":"Tairyoku o tsukeru tame ni, maishūmatsu torēningu shite imasu."},{"fr":"On part tôt pour pouvoir arriver avant la nuit.","tgt":"暗くなる前に着けるように、早く出発します。","ro":"Kuraku naru mae ni tsukeru yō ni, hayaku shuppatsu shimasu."},{"fr":"J'emporte une lampe pour ne pas me perdre dans la forêt.","tgt":"森で迷わないように、ライトを持っていきます。","ro":"Mori de mayowanai yō ni, raito o motte ikimasu."},{"fr":"Les pèlerins venaient ici pour prier dans les trois grands sanctuaires.","tgt":"巡礼者たちは三つの大社にお参りするために、ここへ来ていました。","ro":"Junreishatachi wa mittsu no taisha ni omairi suru tame ni, koko e kite imashita."},{"fr":"On fait suivre nos bagages pour pouvoir marcher léger.","tgt":"身軽に歩けるように、荷物を宅配便で送ります。","ro":"Migaru ni arukeru yō ni, nimotsu o takuhaibin de okurimasu."},{"fr":"J'économise depuis un an pour faire ce voyage.","tgt":"この旅行をするために、一年前から貯金しています。","ro":"Kono ryokō o suru tame ni, ichinen mae kara chokin shite imasu."},{"fr":"Écrivez l'adresse en gros pour que le chauffeur puisse la lire.","tgt":"運転手さんが読めるように、住所を大きく書いてください。","ro":"Untenshu san ga yomeru yō ni, jūsho o ōkiku kaite kudasai."},{"fr":"Buvez souvent pour ne pas vous déshydrater.","tgt":"脱水にならないように、こまめに水を飲んでください。","ro":"Dassui ni naranai yō ni, komame ni mizu o nonde kudasai."},{"fr":"Tout ça, on le fait pour savourer pleinement l'ancien chemin.","tgt":"古道を心から楽しむために、これを全部しています。","ro":"Kodō o kokoro kara tanoshimu tame ni, kore o zenbu shite imasu."}],"tip":{"title":"« Tame ni » et « yō ni » : pour, afin de","example":"On part tôt pour pouvoir arriver avant la nuit. — 暗くなる前に<b>着けるように</b>、早く出発します。","body":"« Tame ni » et « yō ni » traduisent tous les deux « pour » ou « afin de », mais pas dans les mêmes cas. « Tame ni » suit une action que l'on contrôle et que l'on veut accomplir : « aruku tame ni », pour marcher, ou « chokin suru tame ni », pour économiser. « Yō ni » suit plutôt un résultat qu'on ne maîtrise pas complètement, souvent un verbe de possibilité ou une négation : « tsukeru yō ni », pour pouvoir arriver, ou « mayowanai yō ni », pour ne pas se perdre. Notre exemple se dit littéralement : devenir sombre, avant, pouvoir arriver, de façon à, tôt, partir. Astuce : si vous pouvez glisser « pouvoir » ou « ne pas » dans la phrase française, pensez à « yō ni ».","exampleRo":"Kuraku naru mae ni tsukeru yō ni, hayaku shuppatsu shimasu.","lit":"sombre · devenir · avant [temps] · pouvoir arriver · de façon à · tôt · départ-faire (poli)","say":{"Tame ni":"ために","yō ni":"ように","aruku tame ni":"歩くために","chokin suru tame ni":"貯金するために","Yō ni":"ように","tsukeru yō ni":"着けるように","mayowanai yō ni":"迷わないように"}}},{"title":"Sur le Kumano Kodō","phrases":[{"fr":"Le chemin traverse des forêts de cèdres plus que centenaires.","tgt":"道は樹齢百年を超える杉の森を通っています。","ro":"Michi wa jurei hyakunen o koeru sugi no mori o tōtte imasu."},{"fr":"Les pavés couverts de mousse glissent après la pluie.","tgt":"苔に覆われた石畳は、雨のあとは滑りやすいです。","ro":"Koke ni ōwareta ishidatami wa, ame no ato wa suberiyasui desu."},{"fr":"Le long du sentier, on trouve beaucoup de petits bouddhas de pierre.","tgt":"道沿いには小さな石仏がたくさんあります。","ro":"Michizoi ni wa chiisana sekibutsu ga takusan arimasu."},{"fr":"Les pèlerins empruntent ce chemin depuis plus de mille ans.","tgt":"この道は千年以上前から巡礼者に歩かれてきました。","ro":"Kono michi wa sennen ijō mae kara junreisha ni arukarete kimashita."},{"fr":"Après six heures de marche, on a enfin aperçu le grand torii.","tgt":"六時間歩いて、やっと大鳥居が見えてきました。","ro":"Rokujikan aruite, yatto ōtorii ga miete kimashita."},{"fr":"Ce torii compte parmi les plus grands du Japon.","tgt":"この鳥居は日本で最も大きいもののひとつです。","ro":"Kono torii wa Nihon de mottomo ōkii mono no hitotsu desu."},{"fr":"Le soir, on s'est baignés dans une source chaude au bord de la rivière.","tgt":"夜は川辺の温泉に入りました。","ro":"Yoru wa kawabe no onsen ni hairimashita."},{"fr":"À Kawayu, on peut creuser son propre bain dans le lit de la rivière.","tgt":"川湯では、川原を掘って自分だけの温泉を作れます。","ro":"Kawayu de wa, kawara o hotte jibun dake no onsen o tsukuremasu."},{"fr":"L'aubergiste nous a servi un repas de plantes sauvages de montagne.","tgt":"宿の主人が山菜料理を出してくれました。","ro":"Yado no shujin ga sansai ryōri o dashite kuremashita."},{"fr":"J'avais mal aux jambes, mais j'étais profondément heureux.","tgt":"足は痛かったけれど、心から幸せでした。","ro":"Ashi wa itakatta keredo, kokoro kara shiawase deshita."}]},{"title":"Kanazawa, la ville préservée","phrases":[{"fr":"Pendant la guerre, Kanazawa a été épargnée par les bombardements.","tgt":"金沢は戦争中、空襲の被害を受けませんでした。","ro":"Kanazawa wa sensōchū, kūshū no higai o ukemasen deshita."},{"fr":"C'est pour cette raison que les vieux quartiers sont si bien conservés.","tgt":"そのため、古い町並みがよく残っています。","ro":"Sono tame, furui machinami ga yoku nokotte imasu."},{"fr":"Le Kenroku-en est considéré comme l'un des trois plus beaux jardins du pays.","tgt":"兼六園は日本三名園のひとつとされています。","ro":"Kenrokuen wa Nihon sanmeien no hitotsu to sarete imasu."},{"fr":"En hiver, on soutient les branches des pins avec des cordes pour qu'elles ne cassent pas sous la neige.","tgt":"冬には、雪の重さで折れないように松の枝を縄で吊ります。","ro":"Fuyu ni wa, yuki no omosa de orenai yō ni matsu no eda o nawa de tsurimasu."},{"fr":"Dans le quartier de Higashi Chaya, les maisons de thé sont tout en bois.","tgt":"ひがし茶屋街の茶屋は木造です。","ro":"Higashi chayagai no chaya wa mokuzō desu."},{"fr":"On a bu un matcha décoré d'une feuille d'or.","tgt":"金箔をのせた抹茶を飲みました。","ro":"Kinpaku o noseta matcha o nomimashita."},{"fr":"Presque toute la feuille d'or du Japon est fabriquée ici.","tgt":"日本の金箔のほとんどは、ここで作られています。","ro":"Nihon no kinpaku no hotondo wa, koko de tsukurarete imasu."},{"fr":"Au marché d'Ōmichō, les crabes d'hiver sont énormes.","tgt":"近江町市場では、冬になるとカニがとても大きいです。","ro":"Ōmichō ichiba de wa, fuyu ni naru to kani ga totemo ōkii desu."},{"fr":"Le musée d'art contemporain a une étonnante forme ronde.","tgt":"現代美術館は、驚くほど丸い形をしています。","ro":"Gendai bijutsukan wa, odoroku hodo marui katachi o shite imasu."},{"fr":"Kanazawa mérite qu'on y consacre au moins deux jours.","tgt":"金沢は少なくとも二日かけて見る価値があります。","ro":"Kanazawa wa sukunaku tomo futsuka kakete miru kachi ga arimasu."}]},{"title":"Préparer une traversée en ferry","phrases":[{"fr":"J'ai réservé les billets de ferry une semaine à l'avance.","tgt":"フェリーの切符を一週間前に予約しておきました。","ro":"Ferī no kippu o isshūkan mae ni yoyaku shite okimashita."},{"fr":"Les horaires changent selon la saison, vérifie-les avant de partir.","tgt":"季節によって変わるから、出発前に時刻表を確認しておいてね。","ro":"Kisetsu ni yotte kawaru kara, shuppatsu mae ni jikokuhyō o kakunin shite oite ne."},{"fr":"J'ai pris un médicament contre le mal de mer avant d'embarquer.","tgt":"乗る前に酔い止めを飲んでおきました。","ro":"Noru mae ni yoidome o nonde okimashita."},{"fr":"Comme la boutique du bateau est petite, mieux vaut acheter à manger au port.","tgt":"船の売店は小さいので、港で食べ物を買っておいたほうがいいです。","ro":"Fune no baiten wa chiisai node, minato de tabemono o katte oita hō ga ii desu."},{"fr":"J'ai rechargé mon téléphone pendant la nuit.","tgt":"夜のうちにスマホを充電しておきました。","ro":"Yoru no uchi ni sumaho o jūden shite okimashita."},{"fr":"On laisse les grosses valises dans une consigne de la gare.","tgt":"大きいスーツケースは駅のロッカーに入れておきます。","ro":"Ōkii sūtsukēsu wa eki no rokkā ni irete okimasu."},{"fr":"Je note le numéro de la compagnie, au cas où.","tgt":"念のため、フェリー会社の電話番号をメモしておきます。","ro":"Nen no tame, ferī gaisha no denwa bangō o memo shite okimasu."},{"fr":"J'ai prévenu l'auberge qu'on arriverait tard.","tgt":"遅く着くことを、宿に伝えておきました。","ro":"Osoku tsuku koto o, yado ni tsutaete okimashita."},{"fr":"Il fait trop chaud, laisse la porte de la cabine ouverte.","tgt":"暑いから、船室のドアを開けておいて。","ro":"Atsui kara, senshitsu no doa o akete oite."},{"fr":"Tout est prêt, il ne reste plus qu'à monter à bord.","tgt":"準備は全部しておいたので、あとは乗るだけです。","ro":"Junbi wa zenbu shite oita node, ato wa noru dake desu."}],"tip":{"title":"« -te oku » : faire à l'avance","example":"J'ai réservé les billets de ferry une semaine à l'avance. — フェリーの切符を一週間前に<b>予約しておきました</b>。","body":"« -te oku » se forme avec la forme en « te » du verbe, suivie de « oku », qui veut dire poser. L'idée est de faire quelque chose maintenant en prévision de plus tard, comme si l'on posait l'action de côté pour s'en servir ensuite. « Yoyaku shite okimashita » se dit littéralement : réserver, et poser, au passé poli, c'est-à-dire j'ai réservé à l'avance. On l'emploie aussi pour laisser une chose dans un certain état : « doa o akete oku », laisser la porte ouverte. À l'oral, on contracte souvent en « -toku » : « kattoku », je l'achète d'avance. Retenez l'image du sac posé près de la porte la veille du départ.","exampleRo":"Ferī no kippu o isshūkan mae ni yoyaku shite okimashita.","lit":"ferry [possessif] · billet [objet] · une semaine · avant [temps] · réserver · mettre de côté (poli, passé)","say":{"oku":"おく","Yoyaku shite okimashita":"予約しておきました","doa o akete oku":"ドアを開けておく","kattoku":"買っとく","-toku":"とく"}}},{"title":"Le ferry pour Naoshima","phrases":[{"fr":"Le ferry pour Naoshima part du port d'Uno.","tgt":"直島行きのフェリーは宇野港から出ます。","ro":"Naoshima iki no ferī wa Uno kō kara demasu."},{"fr":"La traversée ne prend qu'une vingtaine de minutes.","tgt":"船で二十分ほどしかかかりません。","ro":"Fune de nijuppun hodo shika kakarimasen."},{"fr":"La mer intérieure de Seto est parsemée de centaines d'îles.","tgt":"瀬戸内海には何百もの島が点在しています。","ro":"Setonaikai ni wa nanbyaku mo no shima ga tenzai shite imasu."},{"fr":"Depuis le pont, on voit les îles défiler lentement.","tgt":"デッキから、島々がゆっくり過ぎていくのが見えます。","ro":"Dekki kara, shimajima ga yukkuri sugite iku no ga miemasu."},{"fr":"Des mouettes suivent le bateau dans l'espoir d'un peu de nourriture.","tgt":"カモメが餌をもらおうと船を追いかけてきます。","ro":"Kamome ga esa o moraō to fune o oikakete kimasu."},{"fr":"À l'arrivée, une grande citrouille rouge à pois nous accueille.","tgt":"着くと、水玉模様の大きな赤いかぼちゃが迎えてくれます。","ro":"Tsuku to, mizutama moyō no ōkina akai kabocha ga mukaete kuremasu."},{"fr":"Sur l'île, on se déplace surtout en vélo électrique.","tgt":"島では、主に電動自転車で移動します。","ro":"Shima de wa, omo ni dendō jitensha de idō shimasu."},{"fr":"En été, les vélos de location partent très vite.","tgt":"夏はレンタサイクルがすぐになくなってしまいます。","ro":"Natsu wa rentasaikuru ga sugu ni nakunatte shimaimasu."},{"fr":"Les habitants vivent surtout de la pêche et du tourisme.","tgt":"住民は主に漁業と観光で暮らしています。","ro":"Jūmin wa omo ni gyogyō to kankō de kurashite imasu."},{"fr":"Pour rentrer, on a pris le dernier bateau du soir.","tgt":"帰りは夜の最終便に乗りました。","ro":"Kaeri wa yoru no saishūbin ni norimashita."}]},{"title":"Naoshima, l'île de l'art","phrases":[{"fr":"Le musée Chichū est presque entièrement construit sous terre.","tgt":"地中美術館は、ほとんど地下に造られています。","ro":"Chichū bijutsukan wa, hotondo chika ni tsukurarete imasu."},{"fr":"Selon l'heure, la lumière naturelle change l'aspect des œuvres.","tgt":"時間によって、自然光が作品の見え方を変えます。","ro":"Jikan ni yotte, shizenkō ga sakuhin no miekata o kaemasu."},{"fr":"Pour y entrer, il faut réserver un créneau horaire.","tgt":"入るには、時間指定の予約が必要です。","ro":"Hairu ni wa, jikan shitei no yoyaku ga hitsuyō desu."},{"fr":"Dans le quartier de Honmura, de vieilles maisons sont devenues des œuvres d'art.","tgt":"本村地区では、古い家がアート作品に生まれ変わっています。","ro":"Honmura chiku de wa, furui ie ga āto sakuhin ni umarekawatte imasu."},{"fr":"Dans l'une d'elles, on avance dans une obscurité totale.","tgt":"そのひとつでは、真っ暗な中に入っていきます。","ro":"Sono hitotsu de wa, makkura na naka ni haitte ikimasu."},{"fr":"Peu à peu, nos yeux s'habituent et distinguent une faible lueur.","tgt":"だんだん目が慣れて、かすかな光が見えてきます。","ro":"Dandan me ga narete, kasuka na hikari ga miete kimasu."},{"fr":"Même le bain public de l'île est une œuvre d'art.","tgt":"島の銭湯さえもアート作品です。","ro":"Shima no sentō sae mo āto sakuhin desu."},{"fr":"Dans la plupart des musées, les photos sont interdites.","tgt":"ほとんどの美術館の中では、撮影が禁止されています。","ro":"Hotondo no bijutsukan no naka de wa, satsuei ga kinshi sarete imasu."},{"fr":"C'est justement parce qu'on ne peut pas photographier qu'on regarde vraiment.","tgt":"撮影できないからこそ、本当によく見るようになります。","ro":"Satsuei dekinai kara koso, hontō ni yoku miru yō ni narimasu."},{"fr":"Naoshima prouve qu'une petite île peut renaître grâce à l'art.","tgt":"直島は、小さな島がアートで生まれ変われることを示しています。","ro":"Naoshima wa, chiisana shima ga āto de umarekawareru koto o shimeshite imasu."}]},{"title":"Takayama, au cœur des montagnes","phrases":[{"fr":"On surnomme Takayama le « petit Kyōto » de Hida.","tgt":"高山は「飛騨の小京都」と呼ばれています。","ro":"Takayama wa « Hida no shōkyōto » to yobarete imasu."},{"fr":"Les rues de Sanmachi sont bordées de maisons marchandes en bois sombre.","tgt":"三町の通りには、黒っぽい木の町家が並んでいます。","ro":"Sanmachi no tōri ni wa, kuroppoi ki no machiya ga narande imasu."},{"fr":"Plusieurs brasseries de saké proposent des dégustations.","tgt":"いくつかの酒蔵で試飲ができます。","ro":"Ikutsu ka no sakagura de shiin ga dekimasu."},{"fr":"Une boule de cèdre suspendue signale que le saké nouveau est prêt.","tgt":"杉玉が吊るされていると、新酒ができた印です。","ro":"Sugidama ga tsurusarete iru to, shinshu ga dekita shirushi desu."},{"fr":"Le marché du matin se tient au bord de la rivière Miyagawa.","tgt":"朝市は宮川沿いで開かれます。","ro":"Asaichi wa Miyagawa zoi de hirakaremasu."},{"fr":"De vieilles dames y vendent des légumes et des pickles maison.","tgt":"おばあさんたちが野菜や手作りの漬物を売っています。","ro":"Obāsantachi ga yasai ya tezukuri no tsukemono o utte imasu."},{"fr":"Le bœuf de Hida fond littéralement dans la bouche.","tgt":"飛騨牛は口の中でとろけるようです。","ro":"Hidagyū wa kuchi no naka de torokeru yō desu."},{"fr":"On a mangé des brochettes grillées sous nos yeux.","tgt":"目の前で焼いてくれた串焼きを食べました。","ro":"Me no mae de yaite kureta kushiyaki o tabemashita."},{"fr":"La fête de Takayama attire des foules au printemps et en automne.","tgt":"高山祭は春と秋に大勢の人を集めます。","ro":"Takayama matsuri wa haru to aki ni ōzei no hito o atsumemasu."},{"fr":"En dehors de la fête, la ville est paisible le soir.","tgt":"祭り以外の時期は、夜の町は静かです。","ro":"Matsuri igai no jiki wa, yoru no machi wa shizuka desu."}]},{"title":"Les maisons de Shirakawa-gō","phrases":[{"fr":"Le bus pour Shirakawa-gō met une cinquantaine de minutes.","tgt":"白川郷行きのバスは五十分ぐらいかかります。","ro":"Shirakawagō iki no basu wa gojuppun gurai kakarimasu."},{"fr":"Les toits de chaume ressemblent à des mains jointes.","tgt":"かやぶき屋根は、合わせた手のように見えます。","ro":"Kayabuki yane wa, awaseta te no yō ni miemasu."},{"fr":"C'est pour ça que ce style s'appelle « gasshō-zukuri ».","tgt":"それで、この様式は「合掌造り」と呼ばれています。","ro":"Sorede, kono yōshiki wa « gasshō zukuri » to yobarete imasu."},{"fr":"Grâce à la pente raide, la neige s'accumule difficilement.","tgt":"急な傾斜のおかげで、雪が積もりにくいです。","ro":"Kyū na keisha no okage de, yuki ga tsumorinikui desu."},{"fr":"Tout le village refait le chaume tous les trente ou quarante ans.","tgt":"屋根のふき替えは、三、四十年ごとに村人全員で行います。","ro":"Yane no fukikae wa, san, yonjū nen goto ni murabito zen'in de okonaimasu."},{"fr":"Cette entraide porte le nom de « yui ».","tgt":"この助け合いは「結」と呼ばれています。","ro":"Kono tasukeai wa « yui » to yobarete imasu."},{"fr":"Certaines maisons sont encore habitées aujourd'hui.","tgt":"今でも人が住んでいる家もあります。","ro":"Ima demo hito ga sunde iru ie mo arimasu."},{"fr":"On a dormi dans l'une d'elles, autour du foyer creusé dans le sol.","tgt":"そのひとつに泊まって、囲炉裏を囲みました。","ro":"Sono hitotsu ni tomatte, irori o kakomimashita."},{"fr":"La fumée du foyer protège la charpente des insectes.","tgt":"囲炉裏の煙が、木を虫から守ります。","ro":"Irori no kemuri ga, ki o mushi kara mamorimasu."},{"fr":"En hiver, le village illuminé sous la neige a quelque chose de magique.","tgt":"冬、雪の中でライトアップされた村は幻想的です。","ro":"Fuyu, yuki no naka de raitoappu sareta mura wa gensōteki desu."}]},{"title":"Un typhon bloque les bateaux","phrases":[{"fr":"Normalement, le ferry doit partir à dix heures.","tgt":"フェリーは十時に出るはずです。","ro":"Ferī wa jūji ni deru hazu desu."},{"fr":"Mais un typhon s'approche de l'archipel.","tgt":"でも、台風が諸島に近づいています。","ro":"Demo, taifū ga shotō ni chikazuite imasu."},{"fr":"Avec ce vent, le bateau ne devrait pas pouvoir quitter le port.","tgt":"この風では、船は出られないはずです。","ro":"Kono kaze de wa, fune wa derarenai hazu desu."},{"fr":"La compagnie devrait annoncer sa décision avant huit heures.","tgt":"フェリー会社は八時までに判断を発表するはずです。","ro":"Ferī gaisha wa hachiji made ni handan o happyō suru hazu desu."},{"fr":"L'auberge devrait bien nous laisser rester une nuit de plus.","tgt":"宿はもう一泊させてくれるはずです。","ro":"Yado wa mō ippaku sasete kureru hazu desu."},{"fr":"Et pourtant, j'avais bien vérifié la météo hier soir.","tgt":"昨日の夜、ちゃんと天気予報を確認したはずなのに。","ro":"Kinō no yoru, chanto tenki yohō o kakunin shita hazu na no ni."},{"fr":"Les magasins devraient rester fermés toute la journée.","tgt":"店は一日中閉まっているはずです。","ro":"Mise wa ichinichijū shimatte iru hazu desu."},{"fr":"Le bâtiment est solide, il ne devrait pas y avoir de souci.","tgt":"建物は丈夫だから、心配はいらないはずです。","ro":"Tatemono wa jōbu da kara, shinpai wa iranai hazu desu."},{"fr":"Demain matin, la tempête devrait être passée.","tgt":"明日の朝には、嵐は過ぎているはずです。","ro":"Ashita no asa ni wa, arashi wa sugite iru hazu desu."},{"fr":"Encore une annulation ? Ce n'est pas possible !","tgt":"またキャンセルなんて、そんなはずはありません！","ro":"Mata kyanseru nante, sonna hazu wa arimasen!"}],"tip":{"title":"« Hazu desu » : normalement, ça devrait","example":"Normalement, le ferry doit partir à dix heures. — フェリーは十時に<b>出るはずです</b>。","body":"« Hazu desu » s'ajoute après un verbe à la forme neutre pour dire ce qui devrait logiquement se passer, d'après ce que l'on sait. « Jūji ni deru hazu desu » se dit littéralement : dix heures, partir, attente logique, être, soit il devrait partir à dix heures. Ce n'est pas un simple peut-être : on s'appuie sur un horaire, une règle ou une information fiable. Au négatif, « derarenai hazu desu » signifie il ne devrait pas pouvoir sortir, et « sonna hazu wa arimasen » veut dire ce n'est pas possible. Astuce : pensez au mot « normalement » en français, c'est presque toujours la bonne traduction.","exampleRo":"Ferī wa jūji ni deru hazu desu.","lit":"ferry [thème] · dix heures [temps] · sortir · attente logique · être (poli)","say":{"Hazu desu":"はずです","Jūji ni deru hazu desu":"十時に出るはずです","derarenai hazu desu":"出られないはずです","sonna hazu wa arimasen":"そんなはずはありません"}}},{"title":"Le pèlerinage de Shikoku","phrases":[{"fr":"Le pèlerinage de Shikoku relie quatre-vingt-huit temples.","tgt":"四国遍路は八十八か所の寺を結んでいます。","ro":"Shikoku henro wa hachijūhakkasho no tera o musunde imasu."},{"fr":"Le parcours complet fait environ mille deux cents kilomètres.","tgt":"全行程はおよそ千二百キロあります。","ro":"Zenkōtei wa oyoso sen nihyaku kiro arimasu."},{"fr":"La plupart des gens le font en car ou en voiture.","tgt":"ほとんどの人はバスや車で回ります。","ro":"Hotondo no hito wa basu ya kuruma de mawarimasu."},{"fr":"Ceux qui le font à pied mettent une quarantaine de jours.","tgt":"歩いて回る人は、四十日ほどかかります。","ro":"Aruite mawaru hito wa, yonjūnichi hodo kakarimasu."},{"fr":"Les pèlerins portent une veste blanche et un chapeau de paille conique.","tgt":"お遍路さんは白衣を着て、すげ笠をかぶります。","ro":"Ohenro san wa hakui o kite, sugegasa o kaburimasu."},{"fr":"Sur le chapeau est écrit « dōgyō ninin » : nous marchons à deux.","tgt":"笠には「同行二人」と書いてあります。","ro":"Kasa ni wa « dōgyō ninin » to kaite arimasu."},{"fr":"Cela signifie que Kōbō Daishi marche toujours à vos côtés.","tgt":"弘法大師がいつも一緒に歩いてくれるという意味です。","ro":"Kōbō Daishi ga itsumo issho ni aruite kureru to iu imi desu."},{"fr":"Les habitants offrent souvent des fruits ou du thé aux marcheurs.","tgt":"地元の人は、よく歩き遍路に果物やお茶をくれます。","ro":"Jimoto no hito wa, yoku aruki henro ni kudamono ya ocha o kuremasu."},{"fr":"Cette tradition d'accueil s'appelle « osettai ».","tgt":"このおもてなしの伝統は「お接待」と呼ばれます。","ro":"Kono omotenashi no dentō wa « osettai » to yobaremasu."},{"fr":"Refuser une offrande est considéré comme impoli.","tgt":"お接待を断るのは失礼だとされています。","ro":"Osettai o kotowaru no wa shitsurei da to sarete imasu."}]},{"title":"Une nuit dans un temple","phrases":[{"fr":"Ce soir, nous logeons dans un temple du pèlerinage.","tgt":"今夜は札所のお寺の宿坊に泊まります。","ro":"Kon'ya wa fudasho no otera no shukubō ni tomarimasu."},{"fr":"Le dîner est de la cuisine bouddhique, sans viande ni poisson.","tgt":"夕食は精進料理なので、肉も魚も使いません。","ro":"Yūshoku wa shōjin ryōri na node, niku mo sakana mo tsukaimasen."},{"fr":"Le tofu au sésame avait un goût d'une finesse étonnante.","tgt":"ごま豆腐は驚くほど上品な味でした。","ro":"Gomadōfu wa odoroku hodo jōhin na aji deshita."},{"fr":"Le moine nous a demandé de venir au pavillon principal à six heures.","tgt":"お坊さんに、六時に本堂に来るように言われました。","ro":"Obōsan ni, rokuji ni hondō ni kuru yō ni iwaremashita."},{"fr":"La prière du matin dure environ une demi-heure.","tgt":"朝のお勤めは三十分ぐらいです。","ro":"Asa no otsutome wa sanjuppun gurai desu."},{"fr":"Même sans comprendre les sutras, on est touché par leur rythme.","tgt":"お経の意味がわからなくても、そのリズムに心を打たれます。","ro":"Okyō no imi ga wakaranakute mo, sono rizumu ni kokoro o utaremasu."},{"fr":"Ensuite, on s'est essayés à recopier un sutra au pinceau.","tgt":"そのあと、写経に挑戦しました。","ro":"Sono ato, shakyō ni chōsen shimashita."},{"fr":"Il faut se concentrer sur chaque trait sans se presser.","tgt":"急がずに、一画一画に集中しなければなりません。","ro":"Isogazu ni, ikkaku ikkaku ni shūchū shinakereba narimasen."},{"fr":"Dans chaque temple, on reçoit un sceau calligraphié sur son carnet.","tgt":"札所ごとに納経帳に御朱印をいただきます。","ro":"Fudasho goto ni nōkyōchō ni goshuin o itadakimasu."},{"fr":"Ce calme absolu m'a fait un bien immense.","tgt":"この静けさに、本当に心が癒されました。","ro":"Kono shizukesa ni, hontō ni kokoro ga iyasaremashita."}]},{"title":"Yakushima, l'île de la pluie","phrases":[{"fr":"Yakushima est une île couverte de forêts, au sud de Kyūshū.","tgt":"屋久島は九州の南にある、森に覆われた島です。","ro":"Yakushima wa Kyūshū no minami ni aru, mori ni ōwareta shima desu."},{"fr":"On dit qu'il y pleut trente-cinq jours par mois.","tgt":"「ひと月に三十五日雨が降る」と言われています。","ro":"« Hitotsuki ni sanjūgonichi ame ga furu » to iwarete imasu."},{"fr":"C'est exagéré, bien sûr, mais il pleut vraiment beaucoup.","tgt":"もちろん大げさですが、本当によく雨が降ります。","ro":"Mochiron ōgesa desu ga, hontō ni yoku ame ga furimasu."},{"fr":"Certains cèdres ont plus de mille ans.","tgt":"樹齢千年を超える杉もあります。","ro":"Jurei sennen o koeru sugi mo arimasu."},{"fr":"Le plus célèbre, le Jōmon-sugi, aurait plusieurs milliers d'années.","tgt":"一番有名な縄文杉は、樹齢数千年とも言われています。","ro":"Ichiban yūmei na Jōmon sugi wa, jurei sūsennen to mo iwarete imasu."},{"fr":"Il faut une dizaine d'heures pour faire l'aller-retour jusqu'à lui.","tgt":"往復で十時間ぐらいかかります。","ro":"Ōfuku de jūjikan gurai kakarimasu."},{"fr":"La forêt de Shiratani a servi de modèle à un célèbre film d'animation.","tgt":"白谷雲水峡の森は、有名なアニメ映画のモデルになりました。","ro":"Shiratani Unsuikyō no mori wa, yūmei na anime eiga no moderu ni narimashita."},{"fr":"Au bord du chemin, des cerfs et des singes nous observaient.","tgt":"道ばたからシカやサルがこちらを見ていました。","ro":"Michibata kara shika ya saru ga kochira o mite imashita."},{"fr":"Ils sont plus petits que ceux du reste du Japon.","tgt":"本土のシカやサルより小柄です。","ro":"Hondo no shika ya saru yori kogara desu."},{"fr":"Après la pluie, toute la mousse brillait d'un vert intense.","tgt":"雨上がりには、苔が一面あざやかな緑に輝いていました。","ro":"Ameagari ni wa, koke ga ichimen azayaka na midori ni kagayaite imashita."}]},{"title":"Avec un guide de l'île","phrases":[{"fr":"Pour la randonnée, on a fait appel à un guide local.","tgt":"登山のために、地元のガイドさんを頼みました。","ro":"Tozan no tame ni, jimoto no gaido san o tanomimashita."},{"fr":"Il a grandi sur l'île et connaît chaque sentier.","tgt":"島で生まれ育ったので、どの道もよく知っています。","ro":"Shima de umaresodatta node, dono michi mo yoku shitte imasu."},{"fr":"Il nous a appris à reconnaître les arbres à leur écorce.","tgt":"樹皮で木を見分ける方法を教えてくれました。","ro":"Juhi de ki o miwakeru hōhō o oshiete kuremashita."},{"fr":"Grâce à lui, on a remarqué des détails qu'on aurait manqués seuls.","tgt":"彼のおかげで、自分たちでは見逃していた細かいところに気づけました。","ro":"Kare no okage de, jibuntachi de wa minogashite ita komakai tokoro ni kizukemashita."},{"fr":"Il nous a laissés faire une pause à chaque point d'eau.","tgt":"水場ごとに休憩させてくれました。","ro":"Mizuba goto ni kyūkei sasete kuremashita."},{"fr":"D'après lui, en montagne, le temps change en quelques minutes.","tgt":"彼によると、山の天気は数分で変わるそうです。","ro":"Kare ni yoru to, yama no tenki wa sūfun de kawaru sō desu."},{"fr":"Il nous a demandé de ne rien laisser derrière nous.","tgt":"何も残さないようにと言われました。","ro":"Nani mo nokosanai yō ni to iwaremashita."},{"fr":"Même une peau de fruit peut nuire aux animaux.","tgt":"果物の皮でさえ、動物に悪い影響を与えることがあります。","ro":"Kudamono no kawa de sae, dōbutsu ni warui eikyō o ataeru koto ga arimasu."},{"fr":"À la fin, il nous a offert un verre de shōchū de l'île.","tgt":"最後に、地元の焼酎をごちそうしてくれました。","ro":"Saigo ni, jimoto no shōchū o gochisō shite kuremashita."},{"fr":"Avec un bon guide, l'expérience devient tout autre.","tgt":"いいガイドがいると、体験がまったく変わります。","ro":"Ii gaido ga iru to, taiken ga mattaku kawarimasu."}]},{"title":"Voyager de façon responsable","phrases":[{"fr":"Dans certaines zones de Yakushima, le nombre de randonneurs est limité.","tgt":"屋久島の一部では、入山者の数が制限されています。","ro":"Yakushima no ichibu de wa, nyūzansha no kazu ga seigen sarete imasu."},{"fr":"Chaque randonneur verse une petite contribution pour protéger la forêt.","tgt":"森を守るために、登山者は協力金を払います。","ro":"Mori o mamoru tame ni, tozansha wa kyōryokukin o haraimasu."},{"fr":"À Shirakawa-gō, les habitants souffrent parfois du trop grand nombre de touristes.","tgt":"白川郷では、観光客が多すぎて住民が困ることもあります。","ro":"Shirakawagō de wa, kankōkyaku ga ōsugite jūmin ga komaru koto mo arimasu."},{"fr":"Il ne faut pas entrer dans les maisons privées sans autorisation.","tgt":"許可なく民家に入ってはいけません。","ro":"Kyoka naku minka ni haitte wa ikemasen."},{"fr":"On essaie de voyager hors saison pour éviter la foule.","tgt":"混雑を避けるために、オフシーズンに旅行するようにしています。","ro":"Konzatsu o sakeru tame ni, ofushīzun ni ryokō suru yō ni shite imasu."},{"fr":"Il y a peu de poubelles au Japon, alors on garde toujours ses déchets.","tgt":"日本はゴミ箱が少ないので、ゴミはいつも持ち帰ります。","ro":"Nihon wa gomibako ga sukunai node, gomi wa itsumo mochikaerimasu."},{"fr":"Dormir dans une pension familiale fait vivre l'économie locale.","tgt":"民宿に泊まると、地元の経済が潤います。","ro":"Minshuku ni tomaru to, jimoto no keizai ga uruoimasu."},{"fr":"Acheter de l'artisanat local soutient aussi les artisans.","tgt":"地元の工芸品を買うことも、職人さんの支えになります。","ro":"Jimoto no kōgeihin o kau koto mo, shokunin san no sasae ni narimasu."},{"fr":"Le train et le ferry pèsent bien moins sur l'environnement que l'avion.","tgt":"電車やフェリーは、飛行機より環境への負担がずっと少ないです。","ro":"Densha ya ferī wa, hikōki yori kankyō e no futan ga zutto sukunai desu."},{"fr":"Voyager lentement permet aussi de mieux comprendre un lieu.","tgt":"ゆっくり旅をすると、その土地をもっと深く理解できます。","ro":"Yukkuri tabi o suru to, sono tochi o motto fukaku rikai dekimasu."}]},{"title":"Expliquer un imprévu","phrases":[{"fr":"Excusez-moi, en fait, j'ai raté le dernier bus.","tgt":"すみません、実は最終バスに乗り遅れたんです。","ro":"Sumimasen, jitsu wa saishū basu ni noriokureta n desu."},{"fr":"Qu'est-ce qui se passe ? Pourquoi le train est-il arrêté ?","tgt":"どうしたんですか？どうして電車が止まっているんですか？","ro":"Dō shita n desu ka? Dōshite densha ga tomatte iru n desu ka?"},{"fr":"Un arbre est tombé sur la voie à cause du vent.","tgt":"風で木が線路に倒れたんです。","ro":"Kaze de ki ga senro ni taoreta n desu."},{"fr":"Si je suis en retard, c'est que le ferry a été annulé.","tgt":"フェリーが欠航になったので、遅れたんです。","ro":"Ferī ga kekkō ni natta node, okureta n desu."},{"fr":"Je cherche une pharmacie, ma fille a de la fièvre.","tgt":"娘が熱を出したので、薬局を探しているんです。","ro":"Musume ga netsu o dashita node, yakkyoku o sagashite iru n desu."},{"fr":"Tu ne manges pas ? Tu n'as pas faim ?","tgt":"食べないの？お腹すいてないの？","ro":"Tabenai no? Onaka suitenai no?"},{"fr":"Non, c'est que j'ai trop mangé au marché ce matin.","tgt":"ううん、今朝市場で食べすぎちゃったんだ。","ro":"Uun, kesa ichiba de tabesugichatta n da."},{"fr":"En fait, c'est mon premier voyage seul au Japon.","tgt":"実は、日本を一人で旅するのは初めてなんです。","ro":"Jitsu wa, Nihon o hitori de tabi suru no wa hajimete na n desu."},{"fr":"Je voudrais modifier ma réservation, c'est possible ?","tgt":"予約を変更したいんですが、できますか？","ro":"Yoyaku o henkō shitai n desu ga, dekimasu ka?"},{"fr":"Je ne trouve plus mon passeport, que dois-je faire ?","tgt":"パスポートが見つからないんですが、どうすればいいでしょうか？","ro":"Pasupōto ga mitsukaranai n desu ga, dō sureba ii deshō ka?"}],"tip":{"title":"« -n desu » : expliquer, donner le contexte","example":"Un arbre est tombé sur la voie à cause du vent. — 風で木が線路に<b>倒れたんです</b>。","body":"En ajoutant « n desu » après un verbe ou un adjectif à la forme neutre, on présente sa phrase comme une explication, un peu comme « c'est que » ou « en fait » en français. « Taoreta n desu » se dit littéralement : être tombé, c'est que, être, ce qui sonne comme c'est qu'un arbre est tombé. Les Japonais l'utilisent sans cesse pour donner le contexte, par exemple « jitsu wa noriokureta n desu », en fait, j'ai raté le bus. En question, « dō shita n desu ka » demande ce qui se passe avec plus d'intérêt qu'une question neutre. Entre amis, on dit simplement « n da » ou « no ». Retenez que sans « n desu », une explication paraît souvent sèche, presque froide.","exampleRo":"Kaze de ki ga senro ni taoreta n desu.","lit":"vent [moyen] · arbre [sujet] · voie ferrée [direction] · être tombé · c'est que · être (poli)","say":{"n desu":"んです","Taoreta n desu":"倒れたんです","jitsu wa noriokureta n desu":"実は乗り遅れたんです","dō shita n desu ka":"どうしたんですか","n da":"んだ","no":"の"}}},{"title":"De retour à Tokyo","phrases":[{"fr":"De retour à Tokyo, on a du mal à quitter le rythme des îles.","tgt":"東京に戻っても、島のリズムからなかなか抜けられません。","ro":"Tōkyō ni modotte mo, shima no rizumu kara nakanaka nukeraremasen."},{"fr":"Mes collègues m'ont demandé quel endroit j'avais préféré.","tgt":"同僚に、どこが一番よかったかと聞かれました。","ro":"Dōryō ni, doko ga ichiban yokatta ka to kikaremashita."},{"fr":"C'est difficile de choisir entre la forêt et la mer.","tgt":"森と海のどちらかを選ぶのは難しいです。","ro":"Mori to umi no dochira ka o erabu no wa muzukashii desu."},{"fr":"J'ai rapporté des gâteaux de Kanazawa pour tout le bureau.","tgt":"職場のみんなに金沢のお菓子を買ってきました。","ro":"Shokuba no minna ni Kanazawa no okashi o katte kimashita."},{"fr":"Au Japon, rapporter des souvenirs à ses collègues est presque une obligation.","tgt":"日本では、同僚へのお土産はほとんど義務のようなものです。","ro":"Nihon de wa, dōryō e no omiyage wa hotondo gimu no yō na mono desu."},{"fr":"Ce week-end, j'ai trié des centaines de photos.","tgt":"週末に何百枚もの写真を整理しました。","ro":"Shūmatsu ni nanbyakumai mo no shashin o seiri shimashita."},{"fr":"Celles de Shirakawa-gō sous la neige sont mes préférées.","tgt":"雪の白川郷の写真が一番のお気に入りです。","ro":"Yuki no Shirakawagō no shashin ga ichiban no okiniiri desu."},{"fr":"Ce voyage m'a appris à prendre mon temps.","tgt":"この旅で、ゆっくり過ごすことを覚えました。","ro":"Kono tabi de, yukkuri sugosu koto o oboemashita."},{"fr":"Je rêve déjà de faire tout le pèlerinage de Shikoku à pied.","tgt":"もう四国遍路を全部歩くことを夢見ています。","ro":"Mō Shikoku henro o zenbu aruku koto o yumemite imasu."},{"fr":"Pour cela, il me faudra au moins un an de préparation.","tgt":"そのために、少なくとも一年は準備しないといけません。","ro":"Sono tame ni, sukunaku tomo ichinen wa junbi shinai to ikemasen."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a menés d'Okinawa jusqu'aux montagnes de Hida.","tgt":"この単元で、沖縄から飛騨の山まで旅しました。","ro":"Kono tangen de, Okinawa kara Hida no yama made tabi shimashita."},{"fr":"On sait désormais décrire un lieu avec des propositions relatives.","tgt":"今では、関係節を使って場所を説明できます。","ro":"Ima de wa, kankeisetsu o tsukatte basho o setsumei dekimasu."},{"fr":"Avec « tame ni » et « yō ni », on sait exprimer un but.","tgt":"「ために」と「ように」で、目的を説明できるようになりました。","ro":"« Tame ni » to « yō ni » de, mokuteki o setsumei dekiru yō ni narimashita."},{"fr":"Grâce à « te oku », on peut dire qu'on prépare les choses à l'avance.","tgt":"「ておく」で、前もって準備することが言えます。","ro":"« Te oku » de, maemotte junbi suru koto ga iemasu."},{"fr":"« Hazu desu » exprime ce qui devrait normalement arriver.","tgt":"「はずです」で、当然そうなるはずのことが言えます。","ro":"« Hazu desu » de, tōzen sō naru hazu no koto ga iemasu."},{"fr":"Et avec « n desu », nos explications sonnent bien plus naturelles.","tgt":"そして「んです」を使うと、説明がもっと自然になります。","ro":"Soshite « n desu » o tsukau to, setsumei ga motto shizen ni narimasu."},{"fr":"Le japonais du voyage ne nous fait presque plus peur.","tgt":"旅行の日本語は、もうほとんど怖くありません。","ro":"Ryokō no nihongo wa, mō hotondo kowaku arimasen."},{"fr":"Chaque phrase apprise ici nous rapproche des gens que l'on rencontre.","tgt":"ここで覚えた一文一文が、出会う人との距離を縮めてくれます。","ro":"Koko de oboeta ichibun ichibun ga, deau hito to no kyori o chijimete kuremasu."},{"fr":"Le prochain module sera consacré à des conversations plus personnelles.","tgt":"次の単元では、もっと個人的な会話を学びます。","ro":"Tsugi no tangen de wa, motto kojinteki na kaiwa o manabimasu."},{"fr":"Bravo pour ce beau voyage, et à très vite pour la suite !","tgt":"お疲れさまでした。また次回お会いしましょう！","ro":"Otsukaresama deshita. Mata jikai oai shimashō!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le cœur qui bat : émotions et onomatopées","phrases":[{"fr":"Avant l'entretien, mon cœur battait à tout rompre.","tgt":"面接の前、心臓がドキドキしていました。","ro":"Mensetsu no mae, shinzō ga dokidoki shite imashita."},{"fr":"Mon collègue parle le français couramment, c'est impressionnant.","tgt":"同僚はフランス語がペラペラで、すごいです。","ro":"Dōryō wa furansugo ga perapera de, sugoi desu."},{"fr":"Le dimanche, je traîne à la maison sans rien faire.","tgt":"日曜日は家でゴロゴロしています。","ro":"Nichiyōbi wa ie de gorogoro shite imasu."},{"fr":"Le voyage du mois prochain me rend tout excité.","tgt":"来月の旅行が楽しみで、ワクワクしています。","ro":"Raigetsu no ryokō ga tanoshimi de, wakuwaku shite imasu."},{"fr":"Le train n'arrivait pas et je commençais à m'énerver.","tgt":"電車が来なくて、イライラしてきました。","ro":"Densha ga konakute, iraira shite kimashita."},{"fr":"En sortant du bain, j'ai la peau toute douce.","tgt":"お風呂上がりで、肌がすべすべです。","ro":"Ofuro agari de, hada ga subesube desu."},{"fr":"Devant le feu d'artifice, les yeux de l'enfant brillaient.","tgt":"花火を見て、子供の目がキラキラ輝いていました。","ro":"Hanabi o mite, kodomo no me ga kirakira kagayaite imashita."},{"fr":"Je n'ai rien mangé depuis ce matin, je meurs de faim.","tgt":"朝から何も食べていないので、お腹がペコペコです。","ro":"Asa kara nani mo tabete inai node, onaka ga pekopeko desu."},{"fr":"Il pleut des cordes sur Tokyo depuis ce matin.","tgt":"東京は朝から雨がザーザー降っています。","ro":"Tōkyō wa asa kara ame ga zāzā futte imasu."},{"fr":"Grâce aux onomatopées, le japonais paraît vraiment vivant.","tgt":"オノマトペのおかげで、日本語はとても生き生きしています。","ro":"Onomatope no okage de, nihongo wa totemo ikiiki shite imasu."}],"tip":{"title":"Les onomatopées japonaises : « doki doki, pera pera, goro goro »","example":"Le dimanche, je traîne à la maison sans rien faire. — 日曜日は家で<b>ゴロゴロ</b>しています。","body":"Le japonais adore les onomatopées, bien plus que le français, et elles ne servent pas seulement à imiter des bruits : elles décrivent aussi des états et des émotions. « Doki doki » évoque le cœur qui bat d'émotion, « pera pera » une parole fluide, et « goro goro » le fait de se prélasser sans rien faire. On les emploie très souvent avec le verbe « suru » (faire) : « gorogoro shite imasu » se dit littéralement « goro goro », faire, être en train, c'est-à-dire « je traîne ». Vous entendrez aussi « wakuwaku suru » pour l'impatience joyeuse et « iraira suru » pour l'agacement. Astuce : prononcez-les à voix haute, leur son vous aide à sentir leur sens.","exampleRo":"Nichiyōbi wa ie de gorogoro shite imasu.","lit":"dimanche · [thème] · maison · [lieu] · goro goro (se prélasser) · faire, être en train (poli)","say":{"Doki doki":"ドキドキ","pera pera":"ペラペラ","goro goro":"ゴロゴロ","suru":"する","gorogoro shite imasu":"ゴロゴロしています","wakuwaku suru":"ワクワクする","iraira suru":"イライラする","doki doki, pera pera, goro goro":"ドキドキ、ペラペラ、ゴロゴロ"}}},{"title":"Travail et équilibre de vie","phrases":[{"fr":"Au Japon, beaucoup de gens font encore des heures supplémentaires tous les soirs.","tgt":"日本では、今でも毎晩残業する人が多いです。","ro":"Nihon de wa, ima demo maiban zangyō suru hito ga ōi desu."},{"fr":"Pour certains, rentrer après le dernier train n'a rien d'exceptionnel.","tgt":"終電の後に帰るのが珍しくない人もいます。","ro":"Shūden no ato ni kaeru no ga mezurashiku nai hito mo imasu."},{"fr":"On parle de plus en plus d'équilibre entre travail et vie privée.","tgt":"ワークライフバランスについて話すことが増えてきました。","ro":"Wāku raifu baransu ni tsuite hanasu koto ga fuete kimashita."},{"fr":"Mon entreprise a enfin accepté le télétravail deux jours par semaine.","tgt":"うちの会社は、やっと週に二日の在宅勤務を認めてくれました。","ro":"Uchi no kaisha wa, yatto shū ni futsuka no zaitaku kinmu o mitomete kuremashita."},{"fr":"Dans certains bureaux, prendre tous ses congés payés reste mal vu.","tgt":"有給休暇を全部取るのを、まだ嫌がる職場もあります。","ro":"Yūkyū kyūka o zenbu toru no o, mada iyagaru shokuba mo arimasu."},{"fr":"Le mot « karōshi » désigne la mort causée par l'excès de travail.","tgt":"「過労死」という言葉は、働きすぎによる死を意味します。","ro":"\"Karōshi\" to iu kotoba wa, hatarakisugi ni yoru shi o imi shimasu."},{"fr":"Même avec un salaire plus bas, je veux du temps pour ma famille.","tgt":"給料が少なくても、家族との時間がほしいです。","ro":"Kyūryō ga sukunakute mo, kazoku to no jikan ga hoshii desu."},{"fr":"Les jeunes n'acceptent plus de tout sacrifier pour leur entreprise.","tgt":"今の若者は、会社のためにすべてを犠牲にしなくなりました。","ro":"Ima no wakamono wa, kaisha no tame ni subete o gisei ni shinaku narimashita."},{"fr":"Personne ne devrait culpabiliser de quitter le bureau à l'heure.","tgt":"定時に帰ることに、罪悪感を持つ必要はないはずです。","ro":"Teiji ni kaeru koto ni, zaiakukan o motsu hitsuyō wa nai hazu desu."},{"fr":"À ton avis, on vit pour travailler ou on travaille pour vivre ?","tgt":"働くために生きるのか、生きるために働くのか、どう思う？","ro":"Hataraku tame ni ikiru no ka, ikiru tame ni hataraku no ka, dō omou?"}]},{"title":"Les petites formules du quotidien","phrases":[{"fr":"Je m'appelle Yamada et je commence aujourd'hui ; ravi de travailler avec vous.","tgt":"今日から入りました山田です。どうぞよろしくお願いいたします。","ro":"Kyō kara hairimashita Yamada desu. Dōzo yoroshiku onegai itashimasu."},{"fr":"Merci pour ton travail aujourd'hui, à demain !","tgt":"今日もお疲れさま。また明日！","ro":"Kyō mo otsukaresama. Mata ashita!"},{"fr":"Bon courage pour la réunion de cet après-midi.","tgt":"午後の会議、頑張ってください。","ro":"Gogo no kaigi, ganbatte kudasai."},{"fr":"Avant de manger, on joint les mains et on dit « itadakimasu ».","tgt":"食べる前は、手を合わせて「いただきます」と言います。","ro":"Taberu mae wa, te o awasete \"itadakimasu\" to iimasu."},{"fr":"Après le repas, n'oublie pas de dire « gochisōsama ».","tgt":"食べ終わったら、「ごちそうさま」と言うのを忘れないでね。","ro":"Tabeowattara, \"gochisōsama\" to iu no o wasurenaide ne."},{"fr":"Excusez-moi, je me permets de partir avant vous.","tgt":"お先に失礼します。","ro":"Osaki ni shitsurei shimasu."},{"fr":"En rentrant, je lance toujours « tadaima » depuis l'entrée.","tgt":"家に帰ると、いつも玄関で「ただいま」と言います。","ro":"Ie ni kaeru to, itsumo genkan de \"tadaima\" to iimasu."},{"fr":"Ma mère me répond « okaeri » depuis la cuisine.","tgt":"母は台所から「おかえり」と答えます。","ro":"Haha wa daidokoro kara \"okaeri\" to kotaemasu."},{"fr":"Désolé de vous avoir fait attendre si longtemps.","tgt":"長い間お待たせしました。","ro":"Nagai aida omatase shimashita."},{"fr":"Ces petites formules donnent le rythme de toute une journée au Japon.","tgt":"こういう短い挨拶が、日本の一日のリズムを作っています。","ro":"Kō iu mijikai aisatsu ga, Nihon no ichinichi no rizumu o tsukutte imasu."}],"tip":{"title":"Les expressions de tous les jours : « yoroshiku onegaishimasu, otsukaresama, itadakimasu »","example":"Merci pour ton travail aujourd'hui, à demain ! — 今日も<b>お疲れさま</b>。また明日！","body":"Certaines formules japonaises n'ont pas d'équivalent exact en français, et pourtant on les entend partout. « Yoroshiku onegaishimasu » se dit en se présentant ou en demandant un service : littéralement bien, je vous en prie, soit à peu près « je compte sur votre bienveillance ». « Otsukaresama » (merci pour vos efforts) salue le travail de quelqu'un, le soir en quittant le bureau comme en croisant un collègue dans le couloir. « Itadakimasu » (je reçois humblement) se prononce avant de manger, et « gochisōsama » (merci pour ce festin) après. Astuce : voyez ces formules comme des rituels plutôt que des traductions ; on les retient en les disant au bon moment.","exampleRo":"Kyō mo otsukaresama. Mata ashita!","lit":"aujourd'hui · [aussi] · honorable-fatigue (merci pour tes efforts) · encore · demain","say":{"Yoroshiku onegaishimasu":"よろしくお願いします","Otsukaresama":"お疲れさま","Itadakimasu":"いただきます","gochisōsama":"ごちそうさま","yoroshiku onegaishimasu, otsukaresama, itadakimasu":"よろしくお願いします、お疲れさま、いただきます"}}},{"title":"Le vieillissement de la population","phrases":[{"fr":"Le Japon compte parmi les pays où l'espérance de vie est la plus longue.","tgt":"日本は、世界でも平均寿命が特に長い国の一つです。","ro":"Nihon wa, sekai demo heikin jumyō ga toku ni nagai kuni no hitotsu desu."},{"fr":"Dans mon village natal, presque tous les habitants ont plus de soixante-dix ans.","tgt":"私のふるさとの村では、ほとんどの住民が七十歳を超えています。","ro":"Watashi no furusato no mura de wa, hotondo no jūmin ga nanajissai o koete imasu."},{"fr":"Faute d'enfants, les écoles ferment les unes après les autres.","tgt":"子供が少なくて、学校が次々と閉校しています。","ro":"Kodomo ga sukunakute, gakkō ga tsugitsugi to heikō shite imasu."},{"fr":"Qui s'occupera des personnes âgées dans vingt ans ?","tgt":"二十年後、誰がお年寄りの世話をするのでしょうか。","ro":"Nijūnen go, dare ga otoshiyori no sewa o suru no deshō ka."},{"fr":"À quatre-vingt-dix ans, mon grand-père travaille encore aux champs tous les matins.","tgt":"九十歳の祖父は、今でも毎朝畑仕事をしています。","ro":"Kyūjussai no sofu wa, ima demo maiasa hatakeshigoto o shite imasu."},{"fr":"Dans certaines maisons de retraite, des robots aident déjà le personnel.","tgt":"介護施設では、もうロボットが職員を手伝っています。","ro":"Kaigo shisetsu de wa, mō robotto ga shokuin o tetsudatte imasu."},{"fr":"Lors de la Journée du respect des aînés, on remercie les personnes âgées.","tgt":"敬老の日には、お年寄りに感謝の気持ちを伝えます。","ro":"Keirō no hi ni wa, otoshiyori ni kansha no kimochi o tsutaemasu."},{"fr":"Beaucoup de personnes âgées vivent seules et souffrent de solitude.","tgt":"一人暮らしで寂しい思いをしているお年寄りも多いです。","ro":"Hitorigurashi de sabishii omoi o shite iru otoshiyori mo ōi desu."},{"fr":"Si les jeunes ne reviennent pas, le village finira peut-être par disparaître.","tgt":"若者が戻ってこなければ、村はなくなってしまうかもしれません。","ro":"Wakamono ga modotte konakereba, mura wa nakunatte shimau kamo shiremasen."},{"fr":"Vieillir au Japon, c'est aussi voir son expérience valorisée.","tgt":"日本で年を取るということは、経験が大切にされることでもあります。","ro":"Nihon de toshi o toru to iu koto wa, keiken ga taisetsu ni sareru koto demo arimasu."}]},{"title":"Tradition et modernité","phrases":[{"fr":"Avec ses maisons en bois alignées, ce coin est typiquement japonais.","tgt":"木の家が並んでいて、この辺りは本当に日本らしいですね。","ro":"Ki no ie ga narande ite, kono atari wa hontō ni Nihon rashii desu ne."},{"fr":"Un temple coincé entre des gratte-ciel, c'est tellement Tokyo.","tgt":"高層ビルの間にお寺があるなんて、いかにも東京らしい。","ro":"Kōsō biru no aida ni otera ga aru nante, ikanimo Tōkyō rashii."},{"fr":"Cette nouvelle boutique a un petit air rétro.","tgt":"この新しい店は、ちょっとレトロっぽい感じです。","ro":"Kono atarashii mise wa, chotto retoroppoi kanji desu."},{"fr":"Ma grand-mère porte encore le kimono pour les grandes occasions.","tgt":"祖母は今でも、特別な日には着物を着ます。","ro":"Sobo wa ima demo, tokubetsu na hi ni wa kimono o kimasu."},{"fr":"Dès qu'il parle de trains, il redevient un vrai gamin.","tgt":"電車の話になると、彼は子供っぽくなります。","ro":"Densha no hanashi ni naru to, kare wa kodomoppoku narimasu."},{"fr":"Le ciel est grisâtre ; il paraît qu'il va pleuvoir.","tgt":"空が灰色っぽいですね。雨が降るらしいですよ。","ro":"Sora ga haiiroppoi desu ne. Ame ga furu rashii desu yo."},{"fr":"Les jeunes louent des kimonos pour se promener dans Kyoto.","tgt":"若者が着物をレンタルして、京都を散歩しています。","ro":"Wakamono ga kimono o rentaru shite, Kyōto o sanpo shite imasu."},{"fr":"Dans ce restaurant de sushis, on commande sur tablette, mais le comptoir est resté en bois ancien.","tgt":"この寿司屋はタブレットで注文するのに、カウンターは昔ながらの木のままです。","ro":"Kono sushiya wa taburetto de chūmon suru noni, kauntā wa mukashi nagara no ki no mama desu."},{"fr":"Rester poli même dans un train bondé, c'est très japonais.","tgt":"満員電車でも礼儀正しいのは、とても日本人らしいです。","ro":"Man'in densha demo reigi tadashii no wa, totemo nihonjin rashii desu."},{"fr":"La tradition et la modernité ne s'opposent pas forcément.","tgt":"伝統と現代は、必ずしも対立するものではありません。","ro":"Dentō to gendai wa, kanarazushimo tairitsu suru mono de wa arimasen."}],"tip":{"title":"« -ppoi » et « -rashii » : avoir l'air, typique de","example":"Cette nouvelle boutique a un petit air rétro. — この新しい店は、ちょっと<b>レトロっぽい</b>感じです。","body":"Le suffixe « -ppoi » signifie avoir l'air de, tirer sur, avec une idée d'approximation : « kodomoppoi » (un peu gamin), « haiiroppoi » (grisâtre), « retoroppoi » (dans un style rétro). Le suffixe « -rashii » a deux emplois : après un nom, il veut dire typique de, digne de, comme « Nihon rashii » (typiquement japonais) ; après un verbe, il signale une information entendue, comme « ame ga furu rashii » (il paraît qu'il va pleuvoir). Ainsi « retoroppoi kanji desu » se dit littéralement rétro-genre, impression, être, soit « ça donne une impression rétro ». En résumé, « -ppoi » décrit une ressemblance, tandis que « -rashii » souligne ce qui correspond vraiment à l'essence d'une chose. Astuce : « otona rashii » est un compliment (vraiment adulte, mature), alors que « kodomoppoi » est plutôt un reproche.","exampleRo":"Kono atarashii mise wa, chotto retoroppoi kanji desu.","lit":"ce · nouveau · boutique · [thème] · un peu · rétro-genre · impression · être (poli)","say":{"kodomoppoi":"子どもっぽい","haiiroppoi":"灰色っぽい","retoroppoi":"レトロっぽい","Nihon rashii":"日本らしい","ame ga furu rashii":"雨が降るらしい","retoroppoi kanji desu":"レトロっぽい感じです","otona rashii":"大人らしい","-ppoi":"っぽい","-rashii":"らしい"}}},{"title":"Le manga comme sujet de débat","phrases":[{"fr":"Au Japon, des adultes lisent des mangas dans le train sans la moindre gêne.","tgt":"日本では、大人が電車で堂々と漫画を読んでいます。","ro":"Nihon de wa, otona ga densha de dōdō to manga o yonde imasu."},{"fr":"Certains parents croient que leurs enfants n'étudient pas à cause des mangas.","tgt":"漫画のせいで子供が勉強しないと思っている親もいます。","ro":"Manga no sei de kodomo ga benkyō shinai to omotte iru oya mo imasu."},{"fr":"Pourtant, il existe des mangas sur l'histoire, la médecine ou la cuisine.","tgt":"でも、歴史や医療や料理についての漫画もあります。","ro":"Demo, rekishi ya iryō ya ryōri ni tsuite no manga mo arimasu."},{"fr":"C'est grâce à un manga que j'ai découvert le monde du shōgi.","tgt":"将棋の世界を知ったのは、ある漫画のおかげです。","ro":"Shōgi no sekai o shitta no wa, aru manga no okage desu."},{"fr":"Les mangakas travaillent souvent jusqu'à l'épuisement, paraît-il.","tgt":"漫画家は、倒れるまで働くことが多いそうです。","ro":"Mangaka wa, taoreru made hataraku koto ga ōi sō desu."},{"fr":"Les magazines de manga hebdomadaires se vendent dans tous les konbini.","tgt":"週刊の漫画雑誌は、どのコンビニでも売っています。","ro":"Shūkan no manga zasshi wa, dono konbini demo utte imasu."},{"fr":"Je trouve que la fin de cette série a été bâclée.","tgt":"このシリーズの終わり方は、急ぎすぎだったと思います。","ro":"Kono shirīzu no owarikata wa, isogisugi datta to omoimasu."},{"fr":"On lit un manga en une heure, mais il faut des mois pour le dessiner.","tgt":"漫画は一時間で読めるけど、描くには何か月もかかります。","ro":"Manga wa ichijikan de yomeru kedo, kaku ni wa nankagetsu mo kakarimasu."},{"fr":"Le manga, est-ce de l'art ou un simple divertissement ?","tgt":"漫画は芸術なのか、ただの娯楽なのか。","ro":"Manga wa geijutsu na no ka, tada no goraku na no ka."},{"fr":"Pour moi, une bonne histoire reste une bonne histoire, quel que soit son format.","tgt":"私にとって、いい物語は形に関係なく、いい物語です。","ro":"Watashi ni totte, ii monogatari wa katachi ni kankei naku, ii monogatari desu."}]},{"title":"L'anime et la culture populaire","phrases":[{"fr":"Certains films d'animation attirent des millions de spectateurs au cinéma.","tgt":"アニメ映画が何百万人もの観客を集めることもあります。","ro":"Anime eiga ga nanbyakuman nin mo no kankyaku o atsumeru koto mo arimasu."},{"fr":"Des fans visitent les lieux réels qui apparaissent dans les anime.","tgt":"アニメに出てくる実際の場所を訪れるファンもいます。","ro":"Anime ni dete kuru jissai no basho o otozureru fan mo imasu."},{"fr":"On appelle cela un « pèlerinage en terre sacrée ».","tgt":"それは「聖地巡礼」と呼ばれています。","ro":"Sore wa \"seichi junrei\" to yobarete imasu."},{"fr":"Grâce à ces fans, une petite ville de campagne a retrouvé de la vie.","tgt":"そのファンのおかげで、田舎の小さな町が元気を取り戻しました。","ro":"Sono fan no okage de, inaka no chiisana machi ga genki o torimodoshimashita."},{"fr":"À Akihabara, il y a des boutiques de figurines à chaque coin de rue.","tgt":"秋葉原には、あちこちにフィギュアの店があります。","ro":"Akihabara ni wa, achikochi ni figyua no mise ga arimasu."},{"fr":"Au Japon, les comédiens de doublage sont de véritables stars.","tgt":"日本では、声優は本物のスターです。","ro":"Nihon de wa, seiyū wa honmono no sutā desu."},{"fr":"Petit, je me levais tôt le dimanche pour regarder des dessins animés.","tgt":"子供の頃、日曜日はアニメを見るために早起きしていました。","ro":"Kodomo no koro, nichiyōbi wa anime o miru tame ni hayaoki shite imashita."},{"fr":"Les génériques d'anime font partie des chansons les plus chantées au karaoké.","tgt":"アニメの主題歌は、カラオケでよく歌われます。","ro":"Anime no shudaika wa, karaoke de yoku utawaremasu."},{"fr":"Certains disent que l'anime donne une image faussée du Japon.","tgt":"アニメは日本の間違ったイメージを与えると言う人もいます。","ro":"Anime wa Nihon no machigatta imēji o ataeru to iu hito mo imasu."},{"fr":"Mais beaucoup ont justement commencé le japonais grâce aux anime.","tgt":"でも、まさにアニメがきっかけで日本語を始めた人も多いです。","ro":"Demo, masa ni anime ga kikkake de nihongo o hajimeta hito mo ōi desu."}]},{"title":"Ce qu'on nous a obligés à faire","phrases":[{"fr":"Enfant, on m'obligeait à prendre des cours de piano.","tgt":"子供の頃、ピアノを習わされていました。","ro":"Kodomo no koro, piano o narawasarete imashita."},{"fr":"Au club de sport, les élèves de première année devaient ramasser les balles.","tgt":"部活では、一年生はボールを拾わされました。","ro":"Bukatsu de wa, ichinensei wa bōru o hirowasaremashita."},{"fr":"Hier soir, mon directeur m'a obligé à boire jusqu'à minuit.","tgt":"昨日の夜、部長に十二時まで飲まされました。","ro":"Kinō no yoru, buchō ni jūniji made nomasaremashita."},{"fr":"On m'a fait attendre une heure entière devant le restaurant de ramen.","tgt":"ラーメン屋の前で一時間も待たされました。","ro":"Rāmen'ya no mae de ichijikan mo matasaremashita."},{"fr":"À l'école, on nous faisait nettoyer les salles de classe nous-mêmes.","tgt":"学校では、自分たちで教室を掃除させられました。","ro":"Gakkō de wa, jibuntachi de kyōshitsu o sōji saseraremashita."},{"fr":"Je suis obligé de faire des heures supplémentaires presque tous les jours.","tgt":"ほとんど毎日、残業させられています。","ro":"Hotondo mainichi, zangyō saserarete imasu."},{"fr":"Au mariage de mon ami, on m'a fait chanter devant tout le monde.","tgt":"友達の結婚式で、みんなの前で歌わされました。","ro":"Tomodachi no kekkonshiki de, minna no mae de utawasaremashita."},{"fr":"Ma mère me forçait à manger les légumes que je détestais.","tgt":"母に嫌いな野菜を食べさせられました。","ro":"Haha ni kirai na yasai o tabesaseraremashita."},{"fr":"Ce film m'a vraiment fait réfléchir.","tgt":"この映画には、本当に考えさせられました。","ro":"Kono eiga ni wa, hontō ni kangaesaseraremashita."},{"fr":"Avec le recul, je suis content qu'on m'ait obligé à apprendre le piano.","tgt":"今思えば、ピアノを習わされてよかったです。","ro":"Ima omoeba, piano o narawasarete yokatta desu."}],"tip":{"title":"Le causatif-passif : être obligé de","example":"Ma mère me forçait à manger les légumes que je détestais. — 母<b>に</b>嫌いな野菜を<b>食べさせられました</b>。","body":"Le causatif-passif combine deux formes que vous connaissez déjà : le causatif (faire faire) et le passif (subir). Ensemble, ils expriment une action qu'on a été obligé de faire contre son gré. On part du causatif « tabesaseru » (faire manger), puis on ajoute le passif pour obtenir « tabesaserareru » (être forcé de manger). « Haha ni kirai na yasai o tabesaseraremashita » se dit littéralement mère, par, détesté, légume, objet, être forcé de manger, soit « ma mère m'a forcé à manger des légumes que je détestais ». Pour les verbes en « -u », on utilise souvent une forme courte : « nomasareru » (être forcé de boire), « matasareru » (devoir attendre). Astuce : avec « kangaesaserareta » (cela m'a fait réfléchir), la forme décrit aussi une émotion qu'on n'a pas choisie mais qu'on a ressentie.","exampleRo":"Haha ni kirai na yasai o tabesaseraremashita.","lit":"mère · [par] · détesté · légume · [objet] · être forcé de manger (passé poli)","say":{"tabesaseru":"食べさせる","tabesaserareru":"食べさせられる","Haha ni kirai na yasai o tabesaseraremashita":"母に嫌いな野菜を食べさせられました","nomasareru":"飲まされる","matasareru":"待たされる","kangaesaserareta":"考えさせられた"}}},{"title":"Le wabi-sabi : la beauté de l'imparfait","phrases":[{"fr":"Le wabi-sabi est difficile à traduire en un seul mot.","tgt":"「わびさび」は一言で訳すのが難しいです。","ro":"\"Wabisabi\" wa hitokoto de yakusu no ga muzukashii desu."},{"fr":"C'est la beauté de ce qui est simple, imparfait et éphémère.","tgt":"それは、シンプルで不完全で、はかないものの美しさです。","ro":"Sore wa, shinpuru de fukanzen de, hakanai mono no utsukushisa desu."},{"fr":"Les fissures de ce vieux bol ont été réparées avec de l'or.","tgt":"この古いお茶碗は、ひびを金で直してあります。","ro":"Kono furui ochawan wa, hibi o kin de naoshite arimasu."},{"fr":"Cette technique de réparation s'appelle le kintsugi.","tgt":"この技法は「金継ぎ」と言います。","ro":"Kono gihō wa \"kintsugi\" to iimasu."},{"fr":"Les cicatrices font partie de l'histoire de l'objet.","tgt":"傷も、その器の歴史の一部です。","ro":"Kizu mo, sono utsuwa no rekishi no ichibu desu."},{"fr":"Dans le jardin de ce temple, la mousse recouvre les vieilles pierres.","tgt":"このお寺の庭では、苔が古い石を覆っています。","ro":"Kono otera no niwa de wa, koke ga furui ishi o ōtte imasu."},{"fr":"Je préfère une maison un peu usée à un appartement neuf sans âme.","tgt":"新しくて味気ないマンションより、少し古びた家のほうが好きです。","ro":"Atarashikute ajikenai manshon yori, sukoshi furubita ie no hō ga suki desu."},{"fr":"Dans la cérémonie du thé, chaque geste est simple mais mûrement pensé.","tgt":"茶道では、一つ一つの動作がシンプルですが、よく考えられています。","ro":"Sadō de wa, hitotsu hitotsu no dōsa ga shinpuru desu ga, yoku kangaerarete imasu."},{"fr":"Accepter l'imperfection est peut-être une forme de sagesse.","tgt":"不完全さを受け入れることは、一種の知恵かもしれません。","ro":"Fukanzensa o ukeireru koto wa, isshu no chie kamo shiremasen."},{"fr":"Depuis que je connais le wabi-sabi, je regarde les vieux objets autrement.","tgt":"わびさびを知ってから、古い物の見方が変わりました。","ro":"Wabisabi o shitte kara, furui mono no mikata ga kawarimashita."}]},{"title":"L'omotenashi : l'art de recevoir","phrases":[{"fr":"L'omotenashi, c'est l'art de recevoir sans rien attendre en retour.","tgt":"おもてなしとは、見返りを求めずに人をもてなす心です。","ro":"Omotenashi to wa, mikaeri o motomezu ni hito o motenasu kokoro desu."},{"fr":"Dans ce ryokan, la patronne nous a accueillis agenouillée dans l'entrée.","tgt":"この旅館では、女将さんが玄関で正座して迎えてくれました。","ro":"Kono ryokan de wa, okamisan ga genkan de seiza shite mukaete kuremashita."},{"fr":"Le personnel a remarqué que j'étais gaucher et a posé mes baguettes à gauche.","tgt":"スタッフは私が左利きだと気づいて、お箸を左側に置いてくれました。","ro":"Sutaffu wa watashi ga hidarikiki da to kizuite, ohashi o hidarigawa ni oite kuremashita."},{"fr":"Les vendeurs s'inclinent même quand on n'achète rien.","tgt":"何も買わなくても、店員さんはお辞儀をしてくれます。","ro":"Nani mo kawanakute mo, ten'insan wa ojigi o shite kuremasu."},{"fr":"Dans le shinkansen, le contrôleur s'incline chaque fois qu'il entre dans une voiture.","tgt":"新幹線では、車掌さんが車両に入るたびにお辞儀をします。","ro":"Shinkansen de wa, shashōsan ga sharyō ni hairu tabi ni ojigi o shimasu."},{"fr":"Les serviettes chaudes servies avant le repas s'appellent des oshibori.","tgt":"食事の前に出される温かいタオルは「おしぼり」と言います。","ro":"Shokuji no mae ni dasareru atatakai taoru wa \"oshibori\" to iimasu."},{"fr":"On ne laisse pas de pourboire, car un bon service va de soi.","tgt":"チップは要りません。いいサービスは当たり前だからです。","ro":"Chippu wa irimasen. Ii sābisu wa atarimae da kara desu."},{"fr":"Certains trouvent cette politesse parfois un peu excessive.","tgt":"この丁寧さを、ちょっとやりすぎだと感じる人もいます。","ro":"Kono teineisa o, chotto yarisugi da to kanjiru hito mo imasu."},{"fr":"Moi, j'ai été profondément touché par tant d'attentions.","tgt":"私は、そこまでの気配りに深く感動しました。","ro":"Watashi wa, soko made no kikubari ni fukaku kandō shimashita."},{"fr":"Quand mes amis viendront en France, je voudrais les recevoir de la même façon.","tgt":"友達がフランスに来たら、同じようにもてなしたいです。","ro":"Tomodachi ga Furansu ni kitara, onaji yō ni motenashitai desu."}]},{"title":"Les quatre saisons","phrases":[{"fr":"Les Japonais sont très attachés aux quatre saisons.","tgt":"日本人は四季をとても大切にしています。","ro":"Nihonjin wa shiki o totemo taisetsu ni shite imasu."},{"fr":"Au printemps, on pique-nique sous les cerisiers en fleurs.","tgt":"春は桜の下でお花見をします。","ro":"Haru wa sakura no shita de ohanami o shimasu."},{"fr":"La saison des pluies de juin est moite et un peu déprimante.","tgt":"六月の梅雨は、じめじめしていて気分が沈みます。","ro":"Rokugatsu no tsuyu wa, jimejime shite ite kibun ga shizumimasu."},{"fr":"En été, on mange de la glace pilée en écoutant les cigales.","tgt":"夏はセミの声を聞きながら、かき氷を食べます。","ro":"Natsu wa semi no koe o kikinagara, kakigōri o tabemasu."},{"fr":"Les feux d'artifice d'été rassemblent des foules en yukata.","tgt":"夏の花火大会には、浴衣姿の人がたくさん集まります。","ro":"Natsu no hanabi taikai ni wa, yukata sugata no hito ga takusan atsumarimasu."},{"fr":"En automne, les érables rougissent dans les montagnes autour de Kyoto.","tgt":"秋になると、京都の山のもみじが赤く色づきます。","ro":"Aki ni naru to, Kyōto no yama no momiji ga akaku irozukimasu."},{"fr":"Un bain chaud en plein air un jour de neige, c'est le paradis.","tgt":"雪の日の露天風呂は最高です。","ro":"Yuki no hi no rotenburo wa saikō desu."},{"fr":"Même les gâteaux et les menus changent selon la saison.","tgt":"お菓子やメニューまで、季節によって変わります。","ro":"Okashi ya menyū made, kisetsu ni yotte kawarimasu."},{"fr":"Une lettre commence souvent par quelques mots sur la saison.","tgt":"手紙は、よく季節の挨拶から始めます。","ro":"Tegami wa, yoku kisetsu no aisatsu kara hajimemasu."},{"fr":"Au Japon, quelle saison préfères-tu, et pourquoi ?","tgt":"日本の季節で、どれが一番好き？どうして？","ro":"Nihon no kisetsu de, dore ga ichiban suki? Dōshite?"}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Il existe un proverbe japonais pour presque chaque situation.","tgt":"日本には、ほとんどどんな場面にも合うことわざがあります。","ro":"Nihon ni wa, hotondo donna bamen ni mo au kotowaza ga arimasu."},{"fr":"Même un singe tombe de l'arbre : tout le monde peut se tromper.","tgt":"猿も木から落ちる。誰でも間違えることがあります。","ro":"Saru mo ki kara ochiru. Dare demo machigaeru koto ga arimasu."},{"fr":"Sept fois à terre, huit fois debout : il ne faut jamais abandonner.","tgt":"七転び八起き。決してあきらめてはいけません。","ro":"Nanakorobi yaoki. Kesshite akiramete wa ikemasen."},{"fr":"Des boulettes plutôt que des fleurs : on préfère manger que contempler.","tgt":"花より団子。きれいなものより、おいしいものです。","ro":"Hana yori dango. Kirei na mono yori, oishii mono desu."},{"fr":"Trois ans sur un rocher : la patience finit toujours par payer.","tgt":"石の上にも三年。我慢すれば、いつか報われます。","ro":"Ishi no ue ni mo sannen. Gaman sureba, itsuka mukuwaremasu."},{"fr":"La poussière accumulée finit par former une montagne.","tgt":"塵も積もれば山となる。","ro":"Chiri mo tsumoreba yama to naru."},{"fr":"Ce proverbe m'encourage à réviser un peu de japonais chaque jour.","tgt":"このことわざのおかげで、毎日少しずつ日本語を復習しています。","ro":"Kono kotowaza no okage de, mainichi sukoshi zutsu nihongo o fukushū shite imasu."},{"fr":"La grenouille au fond du puits ne connaît pas l'océan.","tgt":"井の中の蛙、大海を知らず。","ro":"I no naka no kawazu, taikai o shirazu."},{"fr":"Pour moi, ce proverbe est une excellente raison de voyager.","tgt":"私にとって、このことわざは旅をするいい理由です。","ro":"Watashi ni totte, kono kotowaza wa tabi o suru ii riyū desu."},{"fr":"Si tu places bien un proverbe, les Japonais seront souvent impressionnés.","tgt":"ことわざをうまく使うと、日本人によく感心されます。","ro":"Kotowaza o umaku tsukau to, nihonjin ni yoku kanshin saremasu."}],"tip":{"title":"Les proverbes japonais : « kotowaza »","example":"Même un singe tombe de l'arbre : tout le monde peut se tromper. — <b>猿も木から落ちる</b>。誰でも間違えることがあります。","body":"Les « kotowaza », les proverbes japonais, sont bien vivants dans la conversation, et en placer un au bon moment fait toujours son effet. « Saru mo ki kara ochiru » se dit littéralement singe, même, arbre, depuis, tomber : même un singe tombe de l'arbre, autrement dit, tout le monde peut se tromper, même les experts. « Hana yori dango », des boulettes plutôt que des fleurs, se moque gentiment de ceux qui, sous les cerisiers, pensent surtout au pique-nique. « Nanakorobi yaoki », sept chutes, huit relevés, encourage à ne jamais abandonner. Remarquez que les proverbes sont à la forme neutre et souvent très courts, parfois sans verbe. Astuce : associez chaque proverbe à une image mentale, comme ce singe qui glisse de sa branche.","exampleRo":"Saru mo ki kara ochiru. Dare demo machigaeru koto ga arimasu.","lit":"singe · [même] · arbre · [depuis] · tomber · n'importe qui · [même] · se tromper · chose · [sujet] · il y a (poli)","say":{"kotowaza":"ことわざ","Saru mo ki kara ochiru":"猿も木から落ちる","Hana yori dango":"花より団子","Nanakorobi yaoki":"七転び八起き"}}},{"title":"Campagne ou grande ville ?","phrases":[{"fr":"J'ai grandi à Tokyo, mais je rêve de vivre à la campagne.","tgt":"東京で育ちましたが、田舎暮らしに憧れています。","ro":"Tōkyō de sodachimashita ga, inakagurashi ni akogarete imasu."},{"fr":"En ville, tout est pratique, mais on n'a jamais le temps de souffler.","tgt":"都会は便利だけど、ほっとする暇がありません。","ro":"Tokai wa benri da kedo, hotto suru hima ga arimasen."},{"fr":"À la campagne, les voisins déposent des légumes devant votre porte.","tgt":"田舎では、近所の人が玄関の前に野菜を置いていってくれます。","ro":"Inaka de wa, kinjo no hito ga genkan no mae ni yasai o oite itte kuremasu."},{"fr":"Sans voiture, la vie dans les villages est presque impossible.","tgt":"車がないと、村での生活はほとんど無理です。","ro":"Kuruma ga nai to, mura de no seikatsu wa hotondo muri desu."},{"fr":"Les loyers de Tokyo sont si chers que beaucoup habitent loin du centre.","tgt":"東京は家賃が高すぎて、中心から離れて住む人が多いです。","ro":"Tōkyō wa yachin ga takasugite, chūshin kara hanarete sumu hito ga ōi desu."},{"fr":"Avec le télétravail, certains jeunes s'installent dans la campagne de Nagano.","tgt":"在宅勤務が広まってから、長野の田舎に移住する若者もいます。","ro":"Zaitaku kinmu ga hiromatte kara, Nagano no inaka ni ijū suru wakamono mo imasu."},{"fr":"La nuit, on n'entend que les grenouilles dans les rizières.","tgt":"夜は田んぼのカエルの声しか聞こえません。","ro":"Yoru wa tanbo no kaeru no koe shika kikoemasen."},{"fr":"Ici, tout le monde se connaît, pour le meilleur et pour le pire.","tgt":"ここでは、良くも悪くもみんな知り合いです。","ro":"Koko de wa, yoku mo waruku mo minna shiriai desu."},{"fr":"Les grandes villes offrent davantage d'emplois et de culture.","tgt":"大都市のほうが、仕事も文化も多いです。","ro":"Daitoshi no hō ga, shigoto mo bunka mo ōi desu."},{"fr":"Idéalement, je travaillerais en ville et passerais mes week-ends à la campagne.","tgt":"理想を言えば、平日は都会で働いて、週末は田舎で過ごしたいです。","ro":"Risō o ieba, heijitsu wa tokai de hataraite, shūmatsu wa inaka de sugoshitai desu."}]},{"title":"Une amitié née au Japon","phrases":[{"fr":"J'ai rencontré Kenta dans un petit bar de Shinjuku il y a dix ans.","tgt":"健太とは、十年前に新宿の小さなバーで出会いました。","ro":"Kenta to wa, jūnen mae ni Shinjuku no chiisana bā de deaimashita."},{"fr":"Le courant est tout de suite passé, comme si on se connaissait depuis toujours.","tgt":"まるで昔からの知り合いのように、すぐ気が合いました。","ro":"Marude mukashi kara no shiriai no yō ni, sugu ki ga aimashita."},{"fr":"Il corrigeait mon japonais avec une patience infinie.","tgt":"彼は根気よく私の日本語を直してくれました。","ro":"Kare wa konki yoku watashi no nihongo o naoshite kuremashita."},{"fr":"En échange, je lui ai appris à faire des crêpes.","tgt":"その代わりに、私はクレープの作り方を教えてあげました。","ro":"Sono kawari ni, watashi wa kurēpu no tsukurikata o oshiete agemashita."},{"fr":"Au Japon, il faut parfois du temps avant de devenir vraiment proches.","tgt":"日本では、本当に仲良くなるまで時間がかかることもあります。","ro":"Nihon de wa, hontō ni nakayoku naru made jikan ga kakaru koto mo arimasu."},{"fr":"Le jour où il m'a parlé sans formules de politesse, j'ai compris qu'on était amis.","tgt":"彼がタメ口で話してくれた日、友達になれたと分かりました。","ro":"Kare ga tameguchi de hanashite kureta hi, tomodachi ni nareta to wakarimashita."},{"fr":"Même loin l'un de l'autre, on s'écrit presque chaque semaine.","tgt":"離れていても、ほとんど毎週連絡を取り合っています。","ro":"Hanarete ite mo, hotondo maishū renraku o toriatte imasu."},{"fr":"Un vrai ami, c'est quelqu'un avec qui le silence n'est jamais gênant.","tgt":"本当の友達とは、黙っていても気まずくならない人です。","ro":"Hontō no tomodachi to wa, damatte ite mo kimazuku naranai hito desu."},{"fr":"Il m'a dit qu'il viendrait à Paris l'année prochaine.","tgt":"来年パリに来ると言っていました。","ro":"Rainen Pari ni kuru to itte imashita."},{"fr":"Cette amitié est peut-être le plus beau trésor que m'a offert le Japon.","tgt":"この友情は、日本での一番の宝物かもしれません。","ro":"Kono yūjō wa, Nihon de no ichiban no takaramono kamo shiremasen."}]},{"title":"Les non-dits : honne et tatemae","phrases":[{"fr":"Au Japon, on dit rarement non de manière directe.","tgt":"日本では、はっきり「いいえ」と言わないことが多いです。","ro":"Nihon de wa, hakkiri \"iie\" to iwanai koto ga ōi desu."},{"fr":"« C'est un peu difficile » veut souvent dire tout simplement non.","tgt":"「ちょっと難しいですね」は、たいてい断りの意味です。","ro":"\"Chotto muzukashii desu ne\" wa, taitei kotowari no imi desu."},{"fr":"On jongle entre ce qu'on pense vraiment, le honne, et ce qu'on montre, le tatemae.","tgt":"本音と建前を使い分けます。","ro":"Honne to tatemae o tsukaiwakemasu."},{"fr":"Comme disent les Japonais, il faut savoir lire l'air.","tgt":"日本人がよく言うように、空気を読むことが大切です。","ro":"Nihonjin ga yoku iu yō ni, kūki o yomu koto ga taisetsu desu."},{"fr":"Au début, je ne comprenais pas pourquoi mes collègues restaient si vagues.","tgt":"最初は、同僚がなぜあんなにあいまいなのか分かりませんでした。","ro":"Saisho wa, dōryō ga naze anna ni aimai na no ka wakarimasen deshita."},{"fr":"Peu à peu, j'ai appris à deviner ce que les gens ne disent pas.","tgt":"今は、言葉にしない気持ちが少しずつ分かるようになりました。","ro":"Ima wa, kotoba ni shinai kimochi ga sukoshi zutsu wakaru yō ni narimashita."},{"fr":"Cette retenue évite les conflits, mais elle peut aussi fatiguer.","tgt":"この遠慮は争いを避けるけれど、疲れることもあります。","ro":"Kono enryo wa arasoi o sakeru keredo, tsukareru koto mo arimasu."},{"fr":"Entre amis proches, on se parle beaucoup plus franchement.","tgt":"親しい友達の間では、もっと本音で話します。","ro":"Shitashii tomodachi no aida de wa, motto honne de hanashimasu."},{"fr":"Les Français, eux, adorent débattre ouvertement à table.","tgt":"フランス人は、食事中に堂々と議論するのが好きです。","ro":"Furansujin wa, shokujichū ni dōdō to giron suru no ga suki desu."},{"fr":"La politesse ne prend pas la même forme d'un pays à l'autre.","tgt":"礼儀の形は、国によって違います。","ro":"Reigi no katachi wa, kuni ni yotte chigaimasu."}]},{"title":"Les fêtes de fin d'année","phrases":[{"fr":"En décembre, on se retrouve entre collègues pour la fête de fin d'année.","tgt":"十二月には、同僚と忘年会をします。","ro":"Jūnigatsu ni wa, dōryō to bōnenkai o shimasu."},{"fr":"Le bōnenkai sert littéralement à oublier l'année écoulée.","tgt":"忘年会は、文字通りその年を忘れるための会です。","ro":"Bōnenkai wa, mojidōri sono toshi o wasureru tame no kai desu."},{"fr":"Le grand ménage de fin d'année se fait en famille.","tgt":"年末の大掃除は、家族みんなでします。","ro":"Nenmatsu no ōsōji wa, kazoku minna de shimasu."},{"fr":"Le soir du réveillon, on mange des soba pour souhaiter une longue vie.","tgt":"大晦日の夜は、長生きを願って年越しそばを食べます。","ro":"Ōmisoka no yoru wa, nagaiki o negatte toshikoshi soba o tabemasu."},{"fr":"Cette nuit-là, les cloches des temples sonnent cent huit fois.","tgt":"その夜、お寺の鐘が百八回鳴らされます。","ro":"Sono yoru, otera no kane ga hyakuhachikai narasaremasu."},{"fr":"Le premier janvier, on va prier au sanctuaire pour la nouvelle année.","tgt":"一月一日には、神社へ初詣に行きます。","ro":"Ichigatsu tsuitachi ni wa, jinja e hatsumōde ni ikimasu."},{"fr":"Les enfants reçoivent de l'argent dans de petites enveloppes, l'otoshidama.","tgt":"子供たちは、小さな袋に入ったお年玉をもらいます。","ro":"Kodomotachi wa, chiisana fukuro ni haitta otoshidama o moraimasu."},{"fr":"Les cartes de vœux arrivent toutes ensemble le matin du jour de l'an.","tgt":"年賀状は、元日の朝にまとめて届きます。","ro":"Nengajō wa, ganjitsu no asa ni matomete todokimasu."},{"fr":"Pour beaucoup, le Nouvel An est l'occasion de rentrer chez ses parents.","tgt":"多くの人にとって、お正月は実家に帰るチャンスです。","ro":"Ōku no hito ni totte, oshōgatsu wa jikka ni kaeru chansu desu."},{"fr":"Merci pour tout cette année, et je compte sur vous l'an prochain !","tgt":"今年もお世話になりました。来年もよろしくお願いします。","ro":"Kotoshi mo osewa ni narimashita. Rainen mo yoroshiku onegai shimasu."}]},{"title":"Un au revoir à la gare","phrases":[{"fr":"Je rentre en France demain, alors c'est notre dernier dîner ensemble.","tgt":"明日フランスに帰るから、これが一緒に食べる最後の晩ご飯だね。","ro":"Ashita Furansu ni kaeru kara, kore ga issho ni taberu saigo no bangohan da ne."},{"fr":"Tous mes amis sont venus me dire au revoir à la gare de Tokyo.","tgt":"友達がみんな、東京駅まで見送りに来てくれました。","ro":"Tomodachi ga minna, Tōkyō eki made miokuri ni kite kuremashita."},{"fr":"Ils ont agité la main jusqu'à ce que le train disparaisse.","tgt":"電車が見えなくなるまで、手を振ってくれました。","ro":"Densha ga mienaku naru made, te o futte kuremashita."},{"fr":"Au Japon, on dit rarement « sayōnara » à ses amis.","tgt":"日本では、友達にはあまり「さようなら」と言いません。","ro":"Nihon de wa, tomodachi ni wa amari \"sayōnara\" to iimasen."},{"fr":"Il est plus naturel de dire « mata ne », à la prochaine.","tgt":"「またね」と言うほうが自然です。","ro":"\"Mata ne\" to iu hō ga shizen desu."},{"fr":"« Sayōnara » sonne un peu comme un adieu pour toujours.","tgt":"「さようなら」は、ちょっと永遠の別れみたいに聞こえます。","ro":"\"Sayōnara\" wa, chotto eien no wakare mitai ni kikoemasu."},{"fr":"Elle m'a acheté un porte-bonheur au sanctuaire pour le voyage.","tgt":"彼女は、旅のお守りを神社で買ってくれました。","ro":"Kanojo wa, tabi no omamori o jinja de katte kuremashita."},{"fr":"J'ai essayé de ne pas pleurer, mais c'était impossible.","tgt":"泣かないようにしたけど、無理でした。","ro":"Nakanai yō ni shita kedo, muri deshita."},{"fr":"Prends soin de toi, et préviens-moi quand tu seras arrivé.","tgt":"元気でね。着いたら連絡してね。","ro":"Genki de ne. Tsuitara renraku shite ne."},{"fr":"Ce n'est pas un adieu, c'est juste un « à la prochaine ».","tgt":"これはお別れじゃなくて、ただの「またね」だよ。","ro":"Kore wa owakare ja nakute, tada no \"mata ne\" da yo."}]},{"title":"Ichigo ichie : chaque rencontre est unique","phrases":[{"fr":"« Ichigo ichie » désigne une rencontre qui n'arrive qu'une fois dans une vie.","tgt":"「一期一会」とは、一生に一度の出会いという意味です。","ro":"\"Ichigo ichie\" to wa, isshō ni ichido no deai to iu imi desu."},{"fr":"Cette idée vient de la cérémonie du thé.","tgt":"この考え方は、茶道から来ています。","ro":"Kono kangaekata wa, sadō kara kite imasu."},{"fr":"On sert chaque tasse de thé avec soin, comme si c'était la dernière.","tgt":"一杯のお茶を、最後の一杯のように心を込めて出します。","ro":"Ippai no ocha o, saigo no ippai no yō ni kokoro o komete dashimasu."},{"fr":"En repensant à mon séjour, je revois toutes les personnes croisées.","tgt":"日本での日々を振り返ると、出会った人たちのことを思い出します。","ro":"Nihon de no hibi o furikaeru to, deatta hitotachi no koto o omoidashimasu."},{"fr":"Ce vieux monsieur qui m'a guidé sous la pluie jusqu'à mon hôtel.","tgt":"雨の中、ホテルまで案内してくれたおじいさん。","ro":"Ame no naka, hoteru made annai shite kureta ojiisan."},{"fr":"Cette étudiante qui m'a aidé à déchiffrer un menu sans photos.","tgt":"写真のないメニューを読むのを手伝ってくれた学生さん。","ro":"Shashin no nai menyū o yomu no o tetsudatte kureta gakuseisan."},{"fr":"Je ne les reverrai sans doute jamais, mais je ne les oublierai pas.","tgt":"もう二度と会えないかもしれないけど、決して忘れません。","ro":"Mō nido to aenai kamo shirenai kedo, kesshite wasuremasen."},{"fr":"Grâce à eux, je me suis senti chez moi loin de chez moi.","tgt":"その人たちのおかげで、遠い国でも自分の家にいるように感じました。","ro":"Sono hitotachi no okage de, tōi kuni demo jibun no ie ni iru yō ni kanjimashita."},{"fr":"Je voudrais leur dire merci du fond du cœur.","tgt":"心から「ありがとう」と伝えたいです。","ro":"Kokoro kara \"arigatō\" to tsutaetai desu."},{"fr":"Désormais, je chéris chaque rencontre comme un ichigo ichie.","tgt":"これからは、すべての出会いを一期一会だと思って大切にします。","ro":"Kore kara wa, subete no deai o ichigo ichie da to omotte taisetsu ni shimasu."}]},{"title":"Regarder en arrière sur ce parcours en japonais","phrases":[{"fr":"Au début, je ne savais même pas dire « konnichiwa » correctement.","tgt":"最初は、「こんにちは」さえちゃんと言えませんでした。","ro":"Saisho wa, \"konnichiwa\" sae chanto iemasen deshita."},{"fr":"La différence entre « wa » et « ga » m'a longtemps donné mal à la tête.","tgt":"「は」と「が」の違いは、本当に頭が痛い問題でした。","ro":"\"Wa\" to \"ga\" no chigai wa, hontō ni atama ga itai mondai deshita."},{"fr":"Puis j'ai appris les formes neutres, et j'ai progressé d'un coup.","tgt":"それから普通形を覚えて、一気に上達しました。","ro":"Sore kara futsūkei o oboete, ikki ni jōtatsu shimashita."},{"fr":"Le keigo m'a donné des sueurs froides plus d'une fois.","tgt":"敬語には、何度も冷や汗をかかされました。","ro":"Keigo ni wa, nando mo hiyaase o kakasaremashita."},{"fr":"Aujourd'hui, je peux parler de wabi-sabi avec un ami japonais.","tgt":"今では、日本人の友達とわびさびについて話せます。","ro":"Ima de wa, nihonjin no tomodachi to wabisabi ni tsuite hanasemasu."},{"fr":"Le japonais m'a appris à écouter avant de parler.","tgt":"日本語のおかげで、話す前に聞くことを覚えました。","ro":"Nihongo no okage de, hanasu mae ni kiku koto o oboemashita."},{"fr":"Je ne comprends pas encore tout, mais je ne panique plus.","tgt":"まだ全部は分からないけど、もう慌てません。","ro":"Mada zenbu wa wakaranai kedo, mō awatemasen."},{"fr":"Dans le train, j'ai pris l'habitude de répéter des phrases à voix basse.","tgt":"電車の中で、小さな声でフレーズを繰り返すのが習慣になりました。","ro":"Densha no naka de, chiisana koe de furēzu o kurikaesu no ga shūkan ni narimashita."},{"fr":"Chaque trajet est devenu une petite leçon de japonais.","tgt":"毎日の移動が、小さな日本語のレッスンになりました。","ro":"Mainichi no idō ga, chiisana nihongo no ressun ni narimashita."},{"fr":"Depuis la première leçon, j'ai fait un sacré bout de chemin.","tgt":"最初のレッスンから、ずいぶん遠くまで来ました。","ro":"Saisho no ressun kara, zuibun tōku made kimashita."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a fait voyager du wabi-sabi jusqu'aux proverbes.","tgt":"この最後のモジュールでは、わびさびからことわざまで旅をしました。","ro":"Kono saigo no mojūru de wa, wabisabi kara kotowaza made tabi o shimashita."},{"fr":"Nous avons parlé de travail, de vieillesse, de manga et d'amitié en japonais.","tgt":"仕事や高齢化、漫画や友情について、日本語で話しました。","ro":"Shigoto ya kōreika, manga ya yūjō ni tsuite, nihongo de hanashimashita."},{"fr":"Les onomatopées et le causatif-passif ne nous font plus peur.","tgt":"オノマトペも使役受身も、もう怖くありません。","ro":"Onomatope mo shieki ukemi mo, mō kowaku arimasen."},{"fr":"Après trois niveaux, notre parcours en japonais arrive à son terme.","tgt":"三つのレベルを終えて、日本語の旅はここで一区切りです。","ro":"Mittsu no reberu o oete, nihongo no tabi wa koko de hitokugiri desu."},{"fr":"Des premières phrases en « desu » jusqu'au keigo, quelle aventure !","tgt":"最初の「です」から敬語まで、なんという冒険でしょう！","ro":"Saisho no \"desu\" kara keigo made, nan to iu bōken deshō!"},{"fr":"Une langue, c'est un voyage sans véritable fin.","tgt":"言葉は、終わりのない旅のようなものです。","ro":"Kotoba wa, owari no nai tabi no yō na mono desu."},{"fr":"Continuez à écouter, à lire et surtout à parler japonais.","tgt":"これからも、日本語を聞いて、読んで、そして何より話し続けてください。","ro":"Kore kara mo, nihongo o kiite, yonde, soshite nani yori hanashitsuzukete kudasai."},{"fr":"Le jour où vous partirez au Japon, vous serez prêts.","tgt":"日本に行く日が来たら、もう準備はできています。","ro":"Nihon ni iku hi ga kitara, mō junbi wa dekite imasu."},{"fr":"Merci d'avoir partagé avec nous tous ces trajets.","tgt":"すべての移動の時間に付き合ってくれて、ありがとうございました。","ro":"Subete no idō no jikan ni tsukiatte kurete, arigatō gozaimashita."},{"fr":"Pour tout ce chemin parcouru, du fond du cœur : otsukaresama deshita !","tgt":"ここまで、本当にお疲れさまでした！","ro":"Koko made, hontō ni otsukaresama deshita!"}]}]}]}];
